// Define the structure to store the hostname and IP address information
struct HostInfo {
    char *hostname;
    char *ip_address;
};

// Define the function to retrieve the DNS for a given hostname
void get_dns(char *hostname, struct HostInfo *host_info) {
    // Initialize the CURL handle and set the URL for the remote CSV file
    CURL *curl = curl_easy_init();
    char url[1024];
    sprintf(url, "http://example.com/hosts.csv");
    curl_easy_setopt(curl, CURLOPT_URL, url);

    // Set the timeout for network operations in seconds
    long timeout = 5;
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, timeout);

    // Set the maximum number of redirects to follow
    int max_redirects = 10;
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, max_redirects);

    // Perform the HTTP GET request and check for errors
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: %s\n", curl_easy_strerror(res));
        return;
    }

    // Get the response code and check for errors
    long response_code = 0;
    res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: %s\n", curl_easy_strerror(res));
        return;
    }

    // Check the response code and handle errors appropriately
    if (response_code != 200) {
        fprintf(stderr, "Error: HTTP response code %ld\n", response_code);
        return;
    }

    // Get the contents of the remote CSV file and check for errors
    char *contents = NULL;
    res = curl_easy_getinfo(curl, CURLINFO_CONTENT_STRING, &contents);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: %s\n", curl_easy_strerror(res));
        return;
    }

    // Parse the contents of the remote CSV file line by line
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, contents)) != -1) {
        // Check if the line is a comment or empty
        if (line[0] == '#' || line[0] == '\n') {
            continue;
        }

        // Split the line into hostname and IP address using a comma as delimiter
        char *hostname = strtok(line, ",");
        char *ip_address = strtok(NULL, "\n");

        // Check if the hostname is valid and has an IP address
        if (hostname && ip_address) {
            // Add the hostname and IP address to the list of hosts
            struct HostInfo *host_info = malloc(sizeof(struct HostInfo));
            host_info->hostname = strdup(hostname);
            host_info->ip_address = strdup(ip_address);
            // Add the host information to the linked list
            add_host_info(host_info);
        }
    }

    // Clean up memory allocated for the line and contents of the remote CSV file
    free(line);
    curl_free(contents);
}

// Define the function to add host information to a linked list
void add_host_info(struct HostInfo *host_info) {
    // Create a new node for the host information
    struct Node *node = malloc(sizeof(struct Node));
    node->host_info = host_info;
    node->next = NULL;

    // Add the node to the linked list
    if (head == NULL) {
        head = node;
    } else {
        struct Node *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
}

// Define the function to retrieve the IP address for a given hostname
