}

// Define the function to calculate the average of the last two fields in a line
double calculate_average(char *line) {
    // Split the line into fields using a comma as delimiter
    char *field1 = strtok(line, ",");
    char *field2 = strtok(NULL, "\n");

    // Check if both fields are valid and convert them to integers
