// Define the supported algorithms and modes of operation
enum Algorithm { AES_128, AES_192, AES_256, ChaCha20 };
enum Mode { CBC, GCM, CTR };

// Define a structure to hold the encryption context
struct EncryptionContext {
    enum Algorithm algorithm;
    enum Mode mode;
    unsigned char key[32]; // 256-bit key for AES and ChaCha20
    unsigned char iv[16]; // Initialization vector for CBC and GCM modes
};

// Define a function to generate a random key
void generate_key(unsigned char *key, size_t len) {
    if (len > 32) {
        len = 32;
    }
    for (size_t i = 0; i < len; i++) {
        key[i] = rand() & 0xFF;
    }
}

// Define a function to encrypt data using the selected algorithm and mode
int encrypt(struct EncryptionContext *ctx, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    // Check if the input parameters are valid
    if (ctx == NULL || plaintext == NULL || ciphertext == NULL) {
        return -1;
    }

    // Select the appropriate encryption function based on the algorithm and mode
    switch (ctx->algorithm) {
        case AES_128:
            switch (ctx->mode) {
                case CBC:
                    return AES_cbc_encrypt(plaintext, ciphertext, plaintext_len, ctx->key, ctx->iv, AES_ENCRYPT);
                case GCM:
                    return AES_gcm_encrypt(plaintext, ciphertext, plaintext_len, ctx->key, ctx->iv, AES_ENCRYPT);
