import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class PokemonReport {
    private static final Logger logger = Logger.getLogger(PokemonReport.class.getName());

    public static Map<String, List<String>> getWeaknessesAndResistances(List<Pokemon> pokemons) {
        // Initialize the cache with default values for each Pokemon type
        Map<String, List<String>> weaknessesAndResistances = new HashMap<>();
        for (PokemonType type : PokemonType.values()) {
            weaknessesAndResistances.put(type.name(), Collections.emptyList());
        }

        // Process each Pokemon and update the cache accordingly
        for (Pokemon pokemon : pokemons) {
            try {
                String type = getPokemonType(pokemon);
                List<String> weaknessesAndResistancesForType = weaknessesAndResistances.get(type);
                if (weaknessesAndResistancesForType == null) {
                    weaknessesAndResistancesForType = new ArrayList<>();
                    weaknessesAndResistances.put(type, weaknessesAndResistancesForType);
                }
                weaknessesAndResistancesForType.addAll(getWeaknessesAndResistancesForPokemon(pokemon));
            } catch (Exception e) {
                logger.log(Level.WARNING, "Error processing Pokemon: " + pokemon, e);
            }
        }

        // Return the cache
        return weaknessesAndResistances;
    }

    private static String getPokemonType(Pokemon pokemon) {
        try {
            return PokemonType.valueOf(pokemon.getType()).name();
        } catch (IllegalArgumentException e) {
            logger.log(Level.WARNING, "Invalid Pokemon type: " + pokemon.getType(), e);
            return null;
