using System;
using System.IO;
using System.Xml;
using System.Xml.XPath;

public static void ParseConfigFile(string configFilePath)
{
    // Create a new XPathDocument object to parse the XML file
    XPathDocument doc = new XPathDocument(configFilePath);

    // Define an XPath expression to locate the first instance of a specific node name
    string xpathExpression = "//node[@name='specificNodeName']";

    // Create an XPathNavigator object to navigate the XML document
    XPathNavigator nav = doc.CreateNavigator();

    // Evaluate the XPath expression and get the first matching node
    XPathNodeIterator iterator = nav.Select(xpathExpression);

    if (iterator.Count == 0)
    {
        // If no matching node is found, create a new directory named "ConfigStore" in the user's home directory
        string configStoreDir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "ConfigStore");
        Directory.CreateDirectory(configStoreDir);

        // Set an environment variable `CONFIG_PATH` to its absolute path
        Environment.SetEnvironmentVariable("CONFIG_PATH", configStoreDir, EnvironmentVariableTarget.Process);

        // Log the action to a system event log
        EventLog.WriteEntry("ConfigFileParser", $"Created new directory {configStoreDir} for storing configuration files.", EventLogEntryType.Information);
    }
    else if (iterator.Count > 1)
    {
        // If multiple nodes are found, update the `CONFIG_PATH` to point to a newly created subdirectory within the existing "ConfigStore" directory
        string configStoreDir = Environment.GetEnvironmentVariable("CONFIG_PATH");
        Directory.CreateDirectory(Path.Combine(configStoreDir, "specificNodeName"));

        // Set an environment variable `CONFIG_PATH` to its absolute path
        Environment.SetEnvironmentVariable("CONFIG_PATH", Path.Combine(configStoreDir, "specificNodeName"), EnvironmentVariableTarget.Process);
    }
}
