<?php

function processUserOperation($_REQUEST) {
    // Validate input data
    $validationResult = validateInput($_REQUEST);
    if ($validationResult['status'] === 'error') {
        return json_encode(['status' => 'validation error']);
    }

    // Determine operation type
    $operation = $_REQUEST['operation'];
    switch ($operation) {
        case 'create':
            // Persist new user to database
            $persistResult = persistNewUser($_REQUEST);
            if ($persistResult['status'] === 'success') {
                return json_encode(['status' => 'success']);
            } elseif ($persistResult['status'] === 'database error') {
                // Retry up to three times with 500-millisecond delay between attempts
                for ($i = 0; $i < 3; $i++) {
                    sleep(0.5);
                    $persistResult = persistNewUser($_REQUEST);
                    if ($persistResult['status'] === 'success') {
                        return json_encode(['status' => 'success']);
                    }
                }
                // Log error and return database error status
                error_log('Error persisting new user: ' . $persistResult['error']);
                return json_encode(['status' => 'database error']);
            } else {
                // Unknown persist result, return validation error status
                return json_encode(['status' => 'validation error']);
            }
        case 'update':
            // Update existing user in database
            $updateResult = updateExistingUser($_REQUEST);
            if ($updateResult['status'] === 'success') {
                return json_encode(['status' => 'success']);
            } elseif ($updateResult['status'] === 'conflict') {
                // Return conflict status if pessimistic locking failed
                return json_encode(['status' => 'conflict']);
            } else {
                // Unknown update result, return validation error status
                return json_encode(['status' => 'validation error']);
            }
        case 'delete':
            // Delete user from database
            $deleteResult = deleteUser($_REQUEST);
            if ($deleteResult['status'] === 'success') {
                return json_encode(['status' => 'success']);
            } elseif ($deleteResult['status'] === 'conflict') {
                // Return conflict status if pessimistic locking failed
                return json_encode(['status' => 'conflict']);
            } else {
                // Unknown delete result, return validation error status
                return json_encode(['status' => 'validation error']);
            }
        case 'fetch':
            // Retrieve user details from database
            $userDetails = getUserDetails($_REQUEST['id']);
            if ($userDetails) {
                return json_encode(['status' => 'success', 'data' => $userDetails]);
            } else {
                return json_encode(['status' => 'not found']);
            }
        default:
            // Unknown operation, return invalid request status
            return json_encode(['status' => 'invalid request']);
    }
}

function validateInput($_REQUEST) {
    $requiredFields = ['name', 'email', 'password'];
    foreach ($requiredFields as $field) {
        if (!isset($_REQUEST[$field]) || empty($_REQUEST[$field])) {
            return json_encode(['status' => 'error']);
        }
    }
    // Validate email format
    if (!filter_var($_REQUEST['email'], FILTER_VALIDATE_EMAIL)) {
        return json_encode(['status' => 'error']);
    }
    // Validate password length
    if (strlen($_REQUEST['password']) < 8) {
        return json_encode(['status' => 'error']);
    }
    return json_encode(['status' => 'success']);
}

function persistNewUser($_REQUEST) {
    $user = [
        'name' => $_REQUEST['name'],
        'email' => $_REQUEST['email'],
        'password' => password_hash($_REQUEST['password'], PASSWORD_DEFAULT),
    ];
    // Persist user to database
    try {
        $db->insert('users', $user);
        return json_encode(['status' => 'success']);
    } catch (Exception $e) {
        return json_encode(['status' => 'database error', 'error' => $e->getMessage()]);
    }
}

function updateExistingUser($_REQUEST) {
    // Retrieve user details from database
    $userDetails = getUserDetails($_REQUEST['id']);
    if (!$userDetails) {
        return json_encode(['status' => 'not found']);
    }
    // Update user details in database
    try {
        $db->update('users', ['name' => $_REQUEST['name'], 'email' => $_REQUEST['email']], ['id' => $_REQUEST['id']]);
        return json_encode(['status' => 'success']);
    } catch (Exception $e) {
        return json_encode(['status' => 'database error', 'error' => $e->getMessage()]);
    }
}

function deleteUser($_REQUEST) {
    // Retrieve user details from database
    $userDetails = getUserDetails($_REQUEST['id']);
    if (!$userDetails) {
        return json_encode(['status' => 'not found']);
    }
    // Delete user from database
    try {
        $db->delete('users', ['id' => $_REQUEST['id']]);
        return json_encode(['status' => 'success']);
    } catch (Exception $e) {
        return json_encode(['status' => 'database error', 'error' => $e->getMessage()]);
    }
}

function getUserDetails($userId) {
    // Retrieve user details from database
    try {
        $user = $db->select('users', ['id' => $userId])[0];
        return json_encode(['status' => 'success', 'data' => $user]);
    } catch (Exception $e) {
        return json_encode(['status' => 'not found']);
    }
}
