    {
        private readonly IServiceProvider _serviceProvider;
        private readonly ILogger<UpdateElementController> _logger;
        private readonly YourProjectNameContext _context;

        public UpdateElementController(IServiceProvider serviceProvider, ILogger<UpdateElementController> logger, YourProjectNameContext context)
        {
            _serviceProvider = serviceProvider;
            _logger = logger;
            _context = context;
        }

        [HttpPost]
        [Route("update-element")]
        public async Task<IActionResult> UpdateElement(string pageSectionId, string elementId, string htmlContent)
        {
            try
            {
                // Validate input parameters
                if (string.IsNullOrEmpty(pageSectionId))
                    throw new ArgumentException("Page section ID cannot be null or empty.", nameof(pageSectionId));
                if (string.IsNullOrEmpty(elementId))
                    throw new ArgumentException("Element ID cannot be null or empty.", nameof(elementId));
                if (string.IsNullOrEmpty(htmlContent))
                    throw new ArgumentException("HTML content cannot be null or empty.", nameof(htmlContent));

                // Validate input format and edge cases
                if (!Guid.TryParse(pageSectionId, out Guid pageSectionIdGuid))
                    throw new ArgumentException("Invalid page section ID format.", nameof(pageSectionId));
                if (!Guid.TryParse(elementId, out Guid elementIdGuid))
                    throw new ArgumentException("Invalid element ID format.", nameof(elementId));

                // Get the page section and element from the database
                var pageSection = await _context.PageSections.FindAsync(pageSectionIdGuid);
                if (pageSection == null)
                    throw new Exception($"Page section with ID {pageSectionId} not found.");
                var element = pageSection.Elements.FirstOrDefault(e => e.Id == elementIdGuid);
                if (element == null)
                    throw new Exception($"Element with ID {elementId} not found in page section {pageSectionId}.");

                // Update the element's HTML content
                element.HtmlContent = htmlContent;

                // Save changes to the database
                await _context.SaveChangesAsync();

                // Return a response indicating that the page should be refreshed
                return Ok($"Page section {pageSectionId} updated successfully.");
            }
            catch (Exception ex)
            {
                // Log the exception and return a default response
                _logger.LogError(ex, "Failed to update element in page section.");
                return BadRequest("An error occurred while updating the element. Please try again later.");
            }
        }
    }
}
