public class MoSTState {
    private static final int DEFAULT_THEME_DIRECTORY = "themes";
    private static final long THEME_RECYCLING_PERIOD = TimeUnit.MINUTES.toMillis(30);

    public static MoSTState loadMoSTStateFromFile(String filePath) throws IOException {
        FileInputStream fis = null;
        ObjectInputStream ois = null;
        try {
            fis = new FileInputStream(filePath);
            ois = new ObjectInputStream(fis);
            MoSTState state = (MoSTState) ois.readObject();
            if (!(state instanceof MoSTState)) {
                return null;
            }
            return state;
        } catch (IOException | ClassNotFoundException e) {
            throw new IOException("Failed to load MoSTState from file", e);
        } finally {
            if (ois != null) {
                try {
                    ois.close();
                } catch (IOException ex) {
                    // ignore
                }
            }
            if (fis != null) {
                try {
                    fis.close();
                } catch (IOException ex) {
                    // ignore
                }
            }
        }
    }
}
