function collectData(stream) {
  const data = [];
  let buffer = "";

  stream.on("data", (chunk) => {
    buffer += chunk;
    if (buffer.length > 1024 * 1024) { // 1 MB
      data.push(buffer);
      buffer = "";
    }
  });

  stream.on("end", () => {
    data.push(buffer);
    saveData(data);
  });
}

