@Controller
public class ServiceLifecycleController {
  private static final Logger LOGGER = Logger.getLogger(ServiceLifecycleController.class.getName());

  @Autowired
  private Service service;

  @PostMapping("/start")
  public void start() {
    service.start();
  }

  @PostMapping("/stop")
  public void stop() {
    service.stop();
  }

  @GetMapping("/status")
  public String status() {
    return service.getStatus().toString();
  }

  @GetMapping("/health-check")
  public String healthCheck() {
    return service.getHealthCheck();
  }

  @PostMapping("/log")
  public void log(@RequestBody String message) {
    service.log(message);
  }
}

class Service {
  private static final Logger LOGGER = Logger.getLogger(Service.class.getName());

  private enum State {
    STARTING, RUNNING, STOPPING
  }

  private State state;
  private int startups;
  private long startupDelay;
  private long lastStartupTime;
  private long lastStopTime;
  private RestTemplate restTemplate;
  private String monitoringUrl;

  public Service() {
    this.state = State.STOPPING;
    this.startups = 0;
    this.startupDelay = 5;
    this.lastStartupTime = System.currentTimeMillis();
    this.lastStopTime = System.currentTimeMillis();
    this.restTemplate = new RestTemplate();
    this.monitoringUrl = "http://external-monitoring-system/status";
  }

  public void start() {
    synchronized (this) {
      if (state == State.STOPPING) {
        state = State.STARTING;
        startupDelay = getStartupDelay();
        lastStartupTime = System.currentTimeMillis();
      }
    }
  }

  public void stop() {
    synchronized (this) {
      if (state == State.RUNNING) {
        state = State.STOPPING;
        lastStopTime = System.currentTimeMillis();
      }
    }
  }

  public String getStatus() {
    return "State: " + state + ", Startups: " + startups + ", Last startup time: " + new Date(lastStartupTime) + ", Last stop time: " + new Date(lastStopTime);
  }

  public String getHealthCheck() {
    return "Service is " + (state == State.RUNNING ? "healthy" : "unhealthy");
  }

  public void log(String message) {
    LOGGER.info("Logging: " + message);
  }

  private int getStartupDelay() {
    // TODO: Implement a mechanism to calculate the startup delay based on current system load and external dependency health checks
    return 5;
  }

  private void sendStatusUpdate(String status) {
    try {
      restTemplate.postForEntity(monitoringUrl, status, String.class);
    } catch (Exception e) {
      LOGGER.warning("Failed to send status update: " + e.getMessage());
    }
  }
}
