fn main() -> i32 {
    // Measure compilation time and resident set size before and after build process
    let start = time::Instant::now();
    let mut rss_before = 0;
    let mut rss_after = 0;

    // Ensure all necessary crates are available in the local repository
    ensure_dependencies();

    // Start build process and capture exit code
    let exit_code = catch_with_exit_code(|| {
        // Build custom Rust project
        build_project();
    });

    // Measure time taken for compilation
    let duration = start.elapsed();
    println!("Compilation time: {:?}", duration);

    // Determine resident set size before and after build process
    rss_before = get_rss();
    build_project();
    rss_after = get_rss();

    // Log compilation times and memory usage metrics
    log_compilation_times(duration, rss_before, rss_after);

    // Return exit code without any additional information or preamble
    return exit_code;
}

