int resolveDomainName(char* domain_name) {
  // Initialize the DNS resolver
  struct addrinfo hints, *res;
  memset(&hints, 0, sizeof(hints));
  hints.ai_family = AF_INET;
  hints.ai_socktype = SOCK_STREAM;

  // Resolve the domain name into an IP address
  int status = getaddrinfo(domain_name, NULL, &hints, &res);

  // Check for errors
  if (status != 0) {
    fprintf(stderr, "DNS resolution error: %s\n", gai_strerror(status));
    return -1;
  }

  // Close the DNS resolver
  freeaddrinfo(res);

  return 0;
