#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>

class Octree {
public:
    // Constructor to initialize the octree with specified feature size, number of leaf nodes, and data capacity
    Octree(int featureSize, int numLeafNodes, int dataCapacity) : featureSize_(featureSize), numLeafNodes_(numLeafNodes), dataCapacity_(dataCapacity) {
        // Initialize the root node with the specified feature size and number of leaf nodes
        root_ = new Node(featureSize_, numLeafNodes_);
    }

    // Destructor to free the memory allocated for the octree
    ~Octree() {
        delete root_;
    }

    // Insert a data point into the octree
    void insert(const std::vector<double>& data) {
        // Lock the mutex to prevent concurrent access from multiple threads
        std::lock_guard<std::mutex> lock(mutex_);

        // Check if the data capacity has been exceeded and reallocate memory if necessary
        if (data_.size() >= dataCapacity_) {
            reallocate();
        }

        // Insert the data point into the octree
        insertRecursive(root_, data);
    }

    // Traverse the octree to collect data from all leaf nodes into a separate container
    std::vector<std::vector<double>> traverse() {
        // Lock the mutex to prevent concurrent access from multiple threads
        std::lock_guard<std::mutex> lock(mutex_);

        // Initialize an empty vector to store the collected data
        std::vector<std::vector<double>> collectedData;

        // Traverse the octree recursively and collect data from all leaf nodes
        traverseRecursive(root_, collectedData);

        return collectedData;
    }

private:
    // Node structure to represent an internal node in the octree
    struct Node {
        int featureSize_;
        int numLeafNodes_;
        std::vector<Node*> childNodes_;
        std::vector<std::vector<double>> data_;

        Node(int featureSize, int numLeafNodes) : featureSize_(featureSize), numLeafNodes_(numLeafNodes) {
            // Initialize the vector of child nodes and data
            childNodes_.resize(8);
            data_.resize(numLeafNodes_);
        }
    };

    // Reallocate memory for the octree to accommodate more data points
    void reallocate() {
        // Double the size of the data vector and reallocate memory for the child nodes
        dataCapacity_ *= 2;
        root_->data_.resize(dataCapacity_);
        for (int i = 0; i < 8; ++i) {
            root_->childNodes_[i] = new Node(featureSize_, numLeafNodes_);
        }
    }

    // Insert a data point into the octree recursively
    void insertRecursive(Node* node, const std::vector<double>& data) {
        // Check if the data point is within the range of the current node
        if (node->data_.size() < numLeafNodes_) {
            // Insert the data point into the current node and return
            node->data_.push_back(data);
            return;
        }

        // Find the child node that the data point belongs to
        int childIndex = getChildIndex(node, data);

        // Recursively insert the data point into the corresponding child node
        insertRecursive(node->childNodes_[childIndex], data);
    }

    // Traverse the octree recursively and collect data from all leaf nodes
    void traverseRecursive(Node* node, std::vector<std::vector<double>>& collectedData) {
        // Check if the current node is a leaf node
        if (node->childNodes_.empty()) {
            // Add the data from the leaf node to the collected data vector
            collectedData.push_back(node->data_);
            return;
        }

        // Recursively traverse the child nodes and collect data from all leaf nodes
        for (int i = 0; i < 8; ++i) {
            traverseRecursive(node->childNodes_[i], collectedData);
        }
    }

    // Get the index of the child node that a data point belongs to
    int getChildIndex(Node* node, const std::vector<double>& data) {
        // Calculate the feature value for each dimension and determine which child node the data point belongs to
        for (int i = 0; i < featureSize_; ++i) {
            if (data[i] <= node->childNodes_[i]->featureSize_) {
                return i;
            }
        }

        // If the data point does not belong to any child node, return -1
        return -1;
    }

    // Mutex to prevent concurrent access from multiple threads
    std::mutex mutex_;

