#define MAX_DATA_POINTS 50

// Structure to store sensor data
typedef struct {
    int timestamp;
    int channel;
    float signalStrength;
} SensorData;

// Function to process high-throughput sensor data stream
void processSensorData(SensorData* data, int numDataPoints) {
    // Initialize rolling average for each channel
    float* avgSignalStrength = (float*)malloc(sizeof(float) * MAX_DATA_POINTS);
    memset(avgSignalStrength, 0, sizeof(float) * MAX_DATA_POINTS);

    // Initialize peak variance for each channel
    float* peakVariance = (float*)malloc(sizeof(float) * MAX_DATA_POINTS);
    memset(peakVariance, 0, sizeof(float) * MAX_DATA_POINTS);

    // Iterate over data points in the sliding window
    for (int i = 0; i < numDataPoints - WINDOW_SIZE + 1; i++) {
        // Calculate rolling average and peak variance for each channel
        for (int j = 0; j < MAX_DATA_POINTS; j++) {
            avgSignalStrength[j] += data[i + WINDOW_SIZE - 1].signalStrength;
            peakVariance[j] = fmax(peakVariance[j], pow(data[i + WINDOW_SIZE - 1].signalStrength - avgSignalStrength[j], 2));
        }

        // Check if any data points have been lost or delayed
        for (int j = i; j < numDataPoints; j++) {
            if (data[j].timestamp > data[i + WINDOW_SIZE - 1].timestamp) {
                break;
            } else if (data[j].timestamp == data[i + WINDOW_SIZE - 1].timestamp) {
                avgSignalStrength[data[j].channel] += data[j].signalStrength;
                peakVariance[data[j].channel] = fmax(peakVariance[data[j].channel], pow(data[j].signalStrength - avgSignalStrength[data[j].channel], 2));
            } else {
                // Data point has been lost or delayed, reset rolling average and peak variance for channel
                avgSignalStrength[data[j].channel] = data[j].signalStrength;
                peakVariance[data[j].channel] = pow(data[j].signalStrength - avgSignalStrength[data[j].channel], 2);
            }
        }
    }

    // Return peak variance and timestamp of corresponding data point for each channel
    for (int i = 0; i < MAX_DATA_POINTS; i++) {
        printf("Peak variance for channel %d: %f\n", i, peakVariance[i]);
        printf("Timestamp of corresponding data point: %d\n", data[i].timestamp);
    }
}

int main() {
    // Test data
    SensorData data[] = {
        {100, 0, 5.0},
