        {106, 0, 11.0},
        {107, 0, 12.0},
        {108, 0, 13.0},
        {109, 0, 14.0},
        {110, 0, 15.0}
    };

    // Process sensor data
    processSensorData(data, sizeof(data) / sizeof(data[0]));

    return 0;
}
