using namespace std;

// Shared resource for managing cooldowns and consecutive attack counts
struct CooldownManager {
    unordered_map<int, int> cooldowns; // Map of character IDs to their current cooldown periods
    unordered_map<int, int> consecutiveAttacks; // Map of character IDs to the number of consecutive successful attacks for each type of attack
    mutex mtx; // Mutex for protecting concurrent access to the shared resource
    condition_variable cv; // Condition variable for signaling when a cooldown period has ended
};

// Function for dynamically selecting one of four attacks for a video game character
void selectAttack(int characterId, int attackType) {
    CooldownManager& manager = getCooldownManager(); // Get the shared resource for managing cooldowns and consecutive attack counts
    unique_lock<mutex> lock(manager.mtx); // Acquire a lock on the mutex to protect concurrent access to the shared resource

    // Check if the character has used all four attacks consecutively more than three times
    if (manager.consecutiveAttacks[characterId] >= 3) {
        // If so, wait for the cooldown period to end before selecting a new attack
        while (manager.cooldowns[characterId] > 0) {
            manager.cv.wait(lock); // Wait on the condition variable until the cooldown period has ended
        }
    }

    // Select one of four attacks for the character based on their current cooldown periods and consecutive attack counts
    int selectedAttack = 0;
    if (manager.cooldowns[characterId] > 9) {
        selectedAttack = 1;
    } else if (manager.cooldowns[characterId + 1] > 9) {
        selectedAttack = 2;
    } else if (manager.cooldowns[characterId + 2] > 9) {
        selectedAttack = 3;
    }

    // Update the cooldown period and consecutive attack count for the selected attack
    manager.cooldowns[selectedAttack] = 9;
    manager.consecutiveAttacks[characterId]++;

    // Print the selected attack number to the console
    cout << "Character " << characterId << " has selected attack " << selectedAttack + 1 << endl;

    lock.unlock(); // Release the lock on the mutex
}

// Get the shared resource for managing cooldowns and consecutive attack counts
CooldownManager& getCooldownManager() {
    static CooldownManager manager; // Singleton instance of the shared resource
    return manager;
}
