const aggregateTransactions = async (transactions) => {
  const approvedTransactions = transactions.filter(transaction => transaction.status === "approved");
  const totalAmount = approvedTransactions.reduce((acc, curr) => acc + curr.amount, 0);
  const successfulTransactions = approvedTransactions.filter(transaction => transaction.status === "successful");
  const failedTransactions = approvedTransactions.filter(transaction => transaction.status === "failed");
  return { totalAmount, successfulTransactions, failedTransactions };
};
