using SixLabors.ImageSharp.Metadata;

public struct ImageMetadata
{
    public int BitsPerSample { get; set; }
    public int SamplesPerPixel { get; set; }
    public string AdditionalSamples { get; set; }
}

public static class ImageProcessing
{
    private const int MaxBufferSize = 1024 * 1024; // 1 MB

    public static async Task<ImageMetadata> ProcessImageAndComputeHash(string filePath)
    {
        if (!File.Exists(filePath))
            throw new FileNotFoundException($"The file '{filePath}' does not exist.");

        using var stream = new FileStream(filePath, FileMode.Open);
        using var image = await Image.LoadAsync(stream);

        // Parse metadata
        var metadata = image.Metadata;
        var bitsPerSample = metadata.GetBitsPerSample();
        var samplesPerPixel = metadata.GetSamplesPerPixel();
        var additionalSamples = metadata.GetAdditionalSamples();

        // Compute MD5 hash of file content
        using var md5 = MD5.Create();
        var buffer = new byte[MaxBufferSize];
        int read;
        while ((read = await stream.ReadAsync(buffer, 0, MaxBufferSize)) > 0)
        {
            md5.TransformBlock(buffer, 0, read, null, 0);
        }
        md5.TransformFinalBlock(buffer, 0, 0);
        var hash = md5.Hash;

        return new ImageMetadata
        {
            BitsPerSample = bitsPerSample,
            SamplesPerPixel = samplesPerPixel,
            AdditionalSamples = additionalSamples,
            Hash = hash
        };
    }
}
