// Define the maximum length for the new filename
#define MAX_LENGTH 256

// Define the delimiter to use for padding the identifier
#define DELIMITER '-'

// Define the maximum length for the identifier
#define IDENTIFIER_MAX_LENGTH 8

// Function to generate a unique identifier based on the filename
char* generate_identifier(const char* filename, const char* type) {
    // Allocate memory for the new filename
    char* new_filename = malloc(MAX_LENGTH);
    if (!new_filename) {
        return NULL;
    }

    // Copy the original filename to the new filename
    strcpy(new_filename, filename);

    // Get the length of the original filename
    int len = strlen(filename);

    // Check if the original filename is too long
    if (len > MAX_LENGTH - IDENTIFIER_MAX_LENGTH) {
        // Truncate the original filename to fit within the allocated memory
        new_filename[MAX_LENGTH - IDENTIFIER_MAX_LENGTH] = '\0';
    }

    // Get the length of the identifier
    int id_len = strlen(type);

    // Check if the identifier is too long
    if (id_len > IDENTIFIER_MAX_LENGTH) {
        // Truncate the identifier to fit within the maximum length
        type[IDENTIFIER_MAX_LENGTH] = '\0';
    }

    // Append the identifier to the new filename
    strcat(new_filename, type);

    // Pad the identifier with the specified delimiter if necessary
    int pad_len = IDENTIFIER_MAX_LENGTH - id_len;
    for (int i = 0; i < pad_len; i++) {
        strcat(new_filename, DELIMITER);
    }

    // Return the new filename
    return new_filename;
}
