// Function to initialize an AES-256-CBC cipher with a given password
EVP_CIPHER_CTX* init_cipher(const char* password) {
    // Create a new EVP_CIPHER_CTX object
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    // Set the cipher type to AES-256-CBC
    EVP_EncryptInit(ctx, EVP_aes_256_cbc(), NULL, NULL);

    // Derive the encryption key from the password using SHA-256 hash function
    unsigned char key[32];
    SHA256_CTX sha;
    SHA256_Init(&sha);
    SHA256_Update(&sha, password, strlen(password));
    SHA256_Final(key, &sha);

    // Set the key and IV lengths to 32 bytes (for AES-256) and 16 bytes (for CBC mode)
    EVP_CIPHER_CTX_set_key_length(ctx, 32);
    EVP_CIPHER_CTX_set_iv_length(ctx, 16);

    // Set the encryption key and IV
