// Define the maximum number of concurrent processes
#define MAX_PROCESSES 10

// Define the file name prefix for each process's output file
#define OUTPUT_FILE_PREFIX "output_"

// Define the error log file path
#define ERROR_LOG_PATH "/var/log/error.log"

// Define the semaphore for managing concurrent processes
sem_t *sem;

// Define the function to execute a command in the background
int executeCommand(char *command) {
  // Check if there are available resources before starting a new process
  if (sem_wait(sem) == -1) {
    perror("Error waiting for semaphore");
    return 0;
  }

  // Fork a new process to execute the command
  pid_t pid = fork();
  if (pid == -1) {
    perror("Error forking process");
    return 0;
  } else if (pid == 0) {
    // Child process: Execute the command and exit
    int status = system(command);
    if (status != 0) {
      perror("Error executing command");
    }
    exit(status);
  } else {
    // Parent process: Wait for the child process to finish and release the semaphore
    waitpid(pid, NULL, 0);
    sem_post(sem);
  }

  return 1;
}

// Define the function to manage multiple concurrent executions
int executeCommands(char **commands, int numCommands) {
  // Initialize the semaphore with the maximum number of concurrent processes
  if (sem_init(&sem, 0, MAX_PROCESSES) == -1) {
    perror("Error initializing semaphore");
    return 0;
  }

  // Execute each command in the background and manage concurrent executions
  for (int i = 0; i < numCommands; i++) {
    char *command = commands[i];
    if (!executeCommand(command)) {
      perror("Error executing command");
      return 0;
    }
  }

  // Clean up the semaphore
  sem_destroy(&sem);

  return 1;
}

