public class CommandExecutor {
    private static final Logger logger = Logger.getLogger(CommandExecutor.class.getName());

    public void executeCommand(String command, String workingDirectory) throws IOException {
        // Create a temporary file to store the command output
        File tempFile = File.createTempFile("command-output", ".txt");

        try {
            // Execute the command and save the output to the temporary file
            Runtime.getRuntime().exec(command, workingDirectory, tempFile);

            // Read the contents of the temporary file and log them
            BufferedReader reader = new BufferedReader(new FileReader(tempFile));
            String line;
            while ((line = reader.readLine()) != null) {
                logger.log(Level.INFO, "Command output: {0}", line);
            }
        } catch (IOException e) {
            // Handle any potential failures that may occur during command execution
            logger.log(Level.SEVERE, "Error executing command", e);
        } finally {
            // Delete the temporary file regardless of success or failure
            tempFile.delete();
        }
    }
}
