    int port;
    char protocol[4];
    int timeout;
} config_t;

// Define the function to process and validate the JSON configuration file
bool process_config(const char *filename, config_t *config) {
    // Open the JSON configuration file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open configuration file %s\n", filename);
        return false;
    }

    // Read the JSON data from the file
    char buffer[1024];
    size_t len = fread(buffer, 1, sizeof(buffer), file);
    if (len == 0) {
        printf("Error: unable to read configuration file %s\n", filename);
        return false;
    }

    // Parse the JSON data using a JSON parser library
    json_t *json = json_parse(buffer, len);
    if (json == NULL) {
        printf("Error: unable to parse JSON configuration file %s\n", filename);
        return false;
    }

    // Extract the mandatory fields from the JSON data
    const char *host = json_string_value(json_object_get(json, "host"));
    int port = json_integer_value(json_object_get(json, "port"));
    const char *protocol = json_string_value(json_object_get(json, "protocol"));
    int timeout = json_integer_value(json_object_get(json, "timeout"));

    // Validate the mandatory fields
    if (host == NULL || port < 1 || port > 65535) {
        printf("Error: invalid host or port in configuration file %s\n", filename);
        return false;
    }
    if (strcmp(protocol, "TCP") && strcmp(protocol, "UDP") && strcmp(protocol, "TLS")) {
        printf("Error: invalid protocol in configuration file %s\n", filename);
        return false;
    }
    if (timeout < 0) {
        printf("Error: negative timeout in configuration file %s\n", filename);
        return false;
    }

    // Initialize the configuration settings
    config->host = host;
    config->port = port;
    strcpy(config->protocol, protocol);
    config->timeout = timeout;

    // Close the JSON configuration file
    fclose(file);

    return true;
}
