public class MessageProcessor
{
    private const int CACHE_SIZE = 5; // maximum number of decrypted messages to cache for up to 5 minutes
    private const int CACHE_TIMEOUT = 300; // timeout in seconds for cached decrypted messages

    private static Dictionary<string, string> _cache = new Dictionary<string, string>();

    public async Task<List<string>> ProcessMessages(IEnumerable<string> messages)
    {
        var processedMessages = new List<string>();

        foreach (var message in messages)
        {
            // check if the message is already cached
            if (_cache.ContainsKey(message))
            {
                processedMessages.Add(_cache[message]);
                continue;
            }

            // decrypt and validate the message
            var decryptedMessage = await DecryptAndValidateMessageAsync(message);

            // cache the decrypted message for up to 5 minutes
            _cache[message] = decryptedMessage;

            processedMessages.Add(decryptedMessage);
        }

        return processedMessages;
    }

    private async Task<string> DecryptAndValidateMessageAsync(string encryptedMessage)
    {
        // extract the key and IV from the encrypted message
        var key = GetKeyFromEncryptedMessage(encryptedMessage);
        var iv = GetIVFromEncryptedMessage(encryptedMessage);

        // decrypt the message using Triple DES encryption with the extracted key and IV
        var plainTextBytes = await DecryptAsync(encryptedMessage, key, iv);

        // validate the integrity of the decrypted data using a provided HMAC
        if (!ValidateHMAC(plainTextBytes))
        {
            throw new Exception("Invalid HMAC");
        }

        return Encoding.UTF8.GetString(plainTextBytes);
    }

    private async Task<byte[]> DecryptAsync(string encryptedMessage, byte[] key, byte[] iv)
    {
        using (var aes = new AesCryptoServiceProvider())
        {
            aes.Key = key;
            aes.IV = iv;

            return await aes.DecryptAsync(encryptedMessage);
        }
    }

    private bool ValidateHMAC(byte[] plainTextBytes)
    {
        // calculate the HMAC of the decrypted data using a provided key
        var hmac = new HMACSHA256();
        var hmacBytes = hmac.ComputeHash(plainTextBytes);

        // compare the calculated HMAC with the provided HMAC
        return hmacBytes.SequenceEqual(_providedHMAC);
    }

    private byte[] GetKeyFromEncryptedMessage(string encryptedMessage)
    {
        // extract the key from the encrypted message using a regular expression
        var regex = new Regex("key=(.*?),");
        var match = regex.Match(encryptedMessage);

        if (!match.Success)
        {
            throw new Exception("Invalid key format");
        }

        return Convert.FromBase64String(match.Groups[1].Value);
    }

    private byte[] GetIVFromEncryptedMessage(string encryptedMessage)
    {
        // extract the IV from the encrypted message using a regular expression
        var regex = new Regex("iv=(.*?),");
        var match = regex.Match(encryptedMessage);

        if (!match.Success)
        {
            throw new Exception("Invalid IV format");
        }

        return Convert.FromBase64String(match.Groups[1].Value);
    }
}
