['```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileProcessor
{
    private const int BUFFER_SIZE = 1024 * 1024; // 1 MB
    private const int MAX_MEMORY_USAGE = 500 * 1024 * 1024; // 500 MB

    public async Task ProcessFilesAsync(IEnumerable<string> filePaths)
    {
        var hashes = new Dictionary<string, string>();
        var duplicateLines = new List<string>();

        foreach (var filePath in filePaths)
        {
            using (var stream = File.OpenRead(filePath))
            {
                await ProcessFileAsync(stream, hashes, duplicateLines);
            }
        }

        Console.WriteLine("Duplicate lines:");
        foreach (var line in duplicateLines)
        {
            Console.WriteLine(line);
        }
    }

    private async Task ProcessFileAsync(Stream stream, Dictionary<string, string> hashes, List<string> duplicateLines)
    {
        var buffer = new byte[BUFFER_SIZE];
        var lineNumber = 0;
        var memoryUsage = 0;

        while (true)
        {
            var readBytes = await stream.ReadAsync(buffer, 0, BUFFER_SIZE);
            if (readBytes == 0) break;

            for (var i = 0; i < readBytes; i++)
            {
                if (buffer[i] == '\n')
                {
                    var line = Encoding.UTF8.GetString(buffer, 0, i);
                    var hash = GetHash(line);

                    if (!hashes.ContainsKey(hash))
                    {
                        hashes[hash] = line;
                    }
                    else
                    {
                        duplicateLines.Add(line);
                    }

                    memoryUsage += Encoding.UTF8.GetByteCount(line);
                    if (memoryUsage > MAX_MEMORY_USAGE)
                    {
                        await FlushMemoryAsync(hashes, duplicateLines);
                        memoryUsage = 0;
                    }
                }
            }
        }

        await FlushMemoryAsync(hashes, duplicateLines);
    }

    private async Task FlushMemoryAsync(Dictionary<string, string> hashes, List<string> duplicateLines)
    {
        foreach (var hash in hashes.Keys)
        {
            var line = hashes[hash];
            Console.WriteLine($"{lineNumber}: {line}");
            lineNumber++;
        }

        hashes.Clear();
        duplicateLines.Clear();
    }

    private string GetHash(string input)
    {
        using (var sha256 = SHA256.Create())
        {
            var bytes = Encoding.UTF8.GetBytes(input);
            return Convert.ToBase64String(sha256.ComputeHash(bytes));
        }
    }
}
```
This code uses the `FileStream` class to read the files in parallel, and the `SHA256` class to calculate the hash for each line. The `Dictionary<string, string>` is used to store the hashes and their corresponding lines, and the `List<string>` is used to store any duplicate lines found during processing.

The `ProcessFileAsync` method reads the file in chunks of 1 MB using the `ReadAsync` method, and processes each line by calculating its hash and storing it in the `hashes` dictionary. If a duplicate line is found, it is added to the `duplicateLines` list. The memory usage is tracked using the `memoryUsage` variable, and if it exceeds the maximum allowed usage (500 MB), the method flushes the memory by writing all the hashes and lines stored in the `hashes` dictionary to the console.

The `FlushMemoryAsync` method writes all the remaining hashes and lines stored in the `hashes` dictionary to the console, and clears both dictionaries.

The `GetHash` method uses the `SHA256` class to calculate the hash for a given input string.

This code is designed to be easily integrated into an existing pipeline that processes text files from various sources, such as FTP servers or local directories. It minimizes the impact on overall performance by using asynchronous operations and efficiently managing memory usage.']

