public class AESDecryption
{
    private static readonly Dictionary<string, EncryptionMode> _encryptionModes = new Dictionary<string, EncryptionMode>()
    {
        {"CBC", EncryptionMode.CBC},
        {"GCM", EncryptionMode.GCM}
    };

    private static readonly Dictionary<string, PaddingMode> _paddingModes = new Dictionary<string, PaddingMode>()
    {
        {"PKCS7", PaddingMode.PKCS7},
        {"Zeros", PaddingMode.Zeros}
    };

    public static byte[] Decrypt(byte[] ciphertext, string encryptionMode, string paddingMode, byte[] key, byte[] iv)
    {
        if (ciphertext == null || ciphertext.Length == 0)
            throw new ArgumentException("Invalid ciphertext", nameof(ciphertext));

        if (!_encryptionModes.ContainsKey(encryptionMode))
            throw new ArgumentException($"Unsupported encryption mode: {encryptionMode}", nameof(encryptionMode));

        if (!_paddingModes.ContainsKey(paddingMode))
            throw new ArgumentException($"Unsupported padding mode: {paddingMode}", nameof(paddingMode));

        if (key == null || key.Length == 0)
            throw new ArgumentException("Invalid key", nameof(key));

        if (iv == null || iv.Length == 0)
            throw new ArgumentException("Invalid IV", nameof(iv));

        using var aes = Aes.Create();
        aes.Mode = _encryptionModes[encryptionMode];
        aes.Padding = _paddingModes[paddingMode];
        aes.KeySize = 256;
        aes.BlockSize = 128;
        aes.Key = key;
        aes.IV = iv;

        using var msDecrypted = new MemoryStream();
        using (var csEncrypt = new CryptoStream(msDecrypted, aes.CreateDecryptor(), CryptoStreamMode.Write))
        {
            csEncrypt.Write(ciphertext, 0, ciphertext.Length);
        }

        return msDecrypted.ToArray();
    }
}
```
