using System;
using System.IO;
using System.IO.Compression;
using System.Threading;
using System.Collections.Generic;

namespace DataLoader
{
    public class CompressedDataLoader
    {
        private readonly Dictionary<string, byte[]> _cache = new Dictionary<string, byte[]>();
        private readonly object _lock = new object();

        public void Load(string filePath)
        {
            lock (_lock)
            {
                if (!_cache.ContainsKey(filePath))
                {
                    using (var stream = File.OpenRead(filePath))
                    {
                        var compressionFormat = GetCompressionFormat(stream);
                        switch (compressionFormat)
                        {
                            case CompressionFormat.Gzip:
                                _cache[filePath] = DecompressGzip(stream);
                                break;
                            case CompressionFormat.Zip:
                                _cache[filePath] = DecompressZip(stream);
                                break;
                        }
                    }
                }
            }
        }

        public byte[] GetData(string filePath)
        {
            lock (_lock)
            {
                if (!_cache.ContainsKey(filePath))
                {
                    Load(filePath);
                }
                return _cache[filePath];
            }
        }

        private CompressionFormat GetCompressionFormat(Stream stream)
        {
            var magicNumber = new byte[2];
            stream.Read(magicNumber, 0, 2);
            if (magicNumber[0] == 0x1f && magicNumber[1] == 0x8b)
            {
                return CompressionFormat.Gzip;
            }
            else if (magicNumber[0] == 0x50 && magicNumber[1] == 0x4b)
            {
                return CompressionFormat.Zip;
            }
            throw new Exception("Unsupported compression format");
        }

        private byte[] DecompressGzip(Stream stream)
        {
            using (var gzipStream = new GZipStream(stream, CompressionMode.Decompress))
            {
                var buffer = new byte[1024];
                var totalBytesRead = 0;
                while (true)
                {
                    int bytesRead = gzipStream.Read(buffer, 0, buffer.Length);
                    if (bytesRead == 0)
                    {
                        break;
                    }
                    totalBytesRead += bytesRead;
                }
                return buffer;
            }
        }

        private byte[] DecompressZip(Stream stream)
        {
            using (var zipStream = new ZipArchive(stream, ZipArchiveMode.Read))
            {
                var entry = zipStream.Entries[0];
                using (var entryStream = entry.Open())
                {
                    var buffer = new byte[1024];
                    var totalBytesRead = 0;
                    while (true)
                    {
                        int bytesRead = entryStream.Read(buffer, 0, buffer.Length);
                        if (bytesRead == 0)
                        {
                            break;
                        }
                        totalBytesRead += bytesRead;
                    }
                    return buffer;
                }
            }
        }

        public void ClearCache()
        {
            lock (_lock)
            {
                _cache.Clear();
            }
        }
    }
}
```
