        close(fd);
        return NULL;
    }

    // Read file in chunks and write to output file
    while ((bytesRead = read(fd, buffer + totalBytesRead, BUFFER_SIZE - totalBytesRead)) > 0) {
        totalBytesRead += bytesRead;
        lteBuffer = (LTE_PHY_RX_BUFFER*)buffer;
        for (i = 0; i < numBuffers; i++) {
            // Write buffer to output file
            write(fd, &lteBuffer[i], sizeof(LTE_PHY_RX_BUFFER));
        }
    }

    // Close file and free memory
    close(fd);
    free(buffer);

    return NULL;
}

int calculateReceptionQuality(int frameLen, int demodSymbol) {
