Here is a sample implementation of the JavaScript function that integrates with a remote API to fetch user data and display it in a paginated format on a web page:
```
function fetchUserData(pageNumber) {
  // Check if there are any cached results for this page number
  const cachedResults = getCachedResults(pageNumber);
  if (cachedResults) {
    return Promise.resolve(cachedResults);
  }

  // Fetch data from remote API
  return fetch(`https://api.example.com/users?page=${pageNumber}`)
    .then(response => response.json())
    .catch(error => {
      console.log("Error fetching user data:", error);
      // Handle network errors gracefully by returning an empty array
      return [];
    });
}

function getCachedResults(pageNumber) {
  const cachedData = localStorage.getItem(`user-data-${pageNumber}`);
  if (cachedData) {
    return JSON.parse(cachedData);
  } else {
    return null;
  }
}

function displayUserData(users) {
  // Display users in paginated format on web page
  const userList = document.getElementById("user-list");
  userList.innerHTML = "";
  users.forEach(user => {
    const li = document.createElement("li");
    li.textContent = `${user.name} (${user.email})`;
    userList.appendChild(li);
  });
}

function handlePageChange(pageNumber) {
  fetchUserData(pageNumber).then(users => displayUserData(users));
}
```
