['Here is an example of how you could implement the directory management utility in Rust:
```
use std::fs;
use std::path::PathBuf;
use std::env;
use std::error::Error;

fn create_directory(name: &str) -> Result<(), Box<dyn Error>> {
    let path = PathBuf::from(name);
    if fs::metadata(&path).is_ok() {
        return Ok(());
    }
    fs::create_dir(&path)?;
    Ok(())
}

fn log_directory_creation(name: &str) -> Result<(), Box<dyn Error>> {
    let path = PathBuf::from(name);
    if fs::metadata(&path).is_ok() {
        return Ok(());
    }
    let mut logger = env::logger();
    logger.log("Directory created", &format!("{}", name));
    Ok(())
}

fn cleanup_directories(retention: u64) -> Result<(), Box<dyn Error>> {
    let mut directories = Vec::new();
    for entry in fs::read_dir(".").unwrap() {
        if let Some(entry) = entry.ok() {
            let path = entry.path();
            if path.is_dir() && path.metadata().unwrap().modified().unwrap().elapsed().as_secs() > retention {
                directories.push(path);
            }
        }
    }
    for directory in directories {
        fs::remove_dir(&directory)?;
    }
    Ok(())
}
```
