// Define a structure to store RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a function to read and validate input from standard input
int readInput(int *input, int size) {
    // Initialize variables
    int i = 0;
    int valid = 1;

    // Read input from standard input
    while (i < size && scanf("%d", &input[i]) == 1) {
        // Check if the input is a duplicate
        for (int j = 0; j < i; j++) {
            if (input[j] == input[i]) {
                valid = 0;
                break;
            }
        }

        // Check if the input falls within the specified range
        if (input[i] < 1 || input[i] > 10) {
            valid = 0;
        }

        i++;
    }

    return valid ? i : -1;
}

// Define a function to find and print the largest integer in an array
void printLargest(int *input, int size) {
    // Initialize variables
    int largest = 0;
    int index = 0;

    // Find the largest integer in the array
    for (int i = 0; i < size; i++) {
        if (input[i] > largest) {
            largest = input[i];
            index = i;
        }
    }

    // Print the largest integer and its index
    printf("Largest integer: %d\n", largest);
    printf("Index of largest integer: %d\n", index);
}

// Define a function to populate an array of NFAPI_CRC_INDICATION_PDU_T structures
void populateArray(NFAPI_CRC_INDICATION_PDU_T *array, int size) {
    // Initialize variables
    int i = 0;
    time_t timestamp;

    // Populate the array with random values
    while (i < size) {
        // Generate a random RX_UE_INFORMATION_TAG
        array[i].RX_UE_INFORMATION_TAG = rand() % 10 + 1;

        // Generate a random RNTI
        array[i].RNTI = rand() % 10000 + 1;

        // Generate a random CRC_INDICATION_REL8_TAG
        array[i].CRC_INDICATION_REL8_TAG = rand() % 10 + 1;

        // Set the timestamp to the current time
        timestamp = time(NULL);
        array[i].timestamp = (unsigned long)timestamp;

        i++;
