#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>
#include <openssl/rand.h>
#include <stdlib.h>
#include <string.h>

// Context structure to manage resources and lifecycle
typedef struct {
    long *offset_array;
    int *key_array;
    record *record_array;
} context_t;

void init_cryptographic_functions(context_t *ctx) {
    // Register AES block cipher
    EVP_add_cipher(EVP_aes_256_cbc());

    // Register Camellia block cipher
    EVP_add_cipher(EVP_camellia_192_cbc());

    // Register MD5 digest
    EVP_add_digest(EVP_md5());

    // Register SHA digest
    EVP_add_digest(EVP_sha1());

    // Register RSA with SHA1 signature algorithm
    EVP_add_signature_algorithm("RSA-SHA1");
}

void generate_random_keys(context_t *ctx) {
    // Generate random keys for AES and Camellia block ciphers
    ctx->offset_array = (long *)malloc(sizeof(long) * 2);
    ctx->key_array = (int *)malloc(sizeof(int) * 2);
    for (int i = 0; i < 2; i++) {
        ctx->offset_array[i] = RAND_bytes(16, NULL);
        ctx->key_array[i] = RAND_bytes(32, NULL);
    }
}

void generate_random_records(context_t *ctx) {
    // Generate random records for each key
    ctx->record_array = (record *)malloc(sizeof(record) * 2);
    for (int i = 0; i < 2; i++) {
        ctx->record_array[i].value = RAND_bytes(32, NULL);
    }
}

void free_resources(context_t *ctx) {
    // Free all allocated memory before exiting
    if (ctx->offset_array != NULL) {
        free(ctx->offset_array);
    }
    if (ctx->key_array != NULL) {
        free(ctx->key_array);
    }
    if (ctx->record_array != NULL) {
        free(ctx->record_array);
    }
}

void init_and_register_cryptographic_functions() {
    // Initialize and register cryptographic functions
    context_t ctx;
    init_cryptographic_functions(&ctx);
    generate_random_keys(&ctx);
    generate_random_records(&ctx);
    free_resources(&ctx);
}
```
