    if (!new_buffer) {
        printf("Error: Failed to initialize new buffer\n");
        return;
    }

    // Add the new buffer to the dynamic array
    new_buffers[num_buffers++] = new_buffer;
}

// Function to remove a buffer from the dynamic array
void remove_buffer(LTE_PHY_RX_BUFFER* buffer) {
    // Find the index of the given buffer in the dynamic array
