namespace CryptoService {
    class CryptographicOperation {
        public:
            virtual void performOperation() = 0;
    };

    class EncryptionOperation : public CryptographicOperation {
        private:
            std::string input;
            std::string key;
            std::string iv;

        public:
            EncryptionOperation(std::string input, std::string key, std::string iv) {
                this->input = input;
                this->key = key;
                this->iv = iv;
            }

            void performOperation() override {
                // Perform encryption operation using OpenSSL library
                EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
                if (!ctx) {
                    std::cerr << "Error: Failed to create cipher context" << std::endl;
                    return;
                }

                int ret = EVP_EncryptInit(ctx, EVP_aes_256_cbc(), key.data(), iv.data());
                if (ret != 1) {
                    std::cerr << "Error: Failed to initialize encryption" << std::endl;
                    return;
                }

                int len = input.size();
                unsigned char* out = new unsigned char[len];
                int out_len = 0;
                ret = EVP_EncryptUpdate(ctx, out, &out_len, (unsigned char*)input.data(), len);
                if (ret != 1) {
                    std::cerr << "Error: Failed to encrypt data" << std::endl;
                    return;
                }

                ret = EVP_EncryptFinal(ctx, out + out_len, &out_len);
                if (ret != 1) {
                    std::cerr << "Error: Failed to finalize encryption" << std::endl;
                    return;
                }

                std::string encrypted = std::string((char*)out, out_len);
                delete[] out;

                // Print the encrypted data
                std::cout << "Encrypted data: " << encrypted << std::endl;
            }
    };

    class DecryptionOperation : public CryptographicOperation {
        private:
            std::string input;
            std::string key;
            std::string iv;

        public:
            DecryptionOperation(std::string input, std::string key, std::string iv) {
                this->input = input;
                this->key = key;
                this->iv = iv;
            }

            void performOperation() override {
                // Perform decryption operation using OpenSSL library
                EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
                if (!ctx) {
                    std::cerr << "Error: Failed to create cipher context" << std::endl;
                    return;
                }

                int ret = EVP_DecryptInit(ctx, EVP_aes_256_cbc(), key.data(), iv.data());
                if (ret != 1) {
                    std::cerr << "Error: Failed to initialize decryption" << std::endl;
                    return;
                }

                int len = input.size();
                unsigned char* out = new unsigned char[len];
                int out_len = 0;
                ret = EVP_DecryptUpdate(ctx, out, &out_len, (unsigned char*)input.data(), len);
                if (ret != 1) {
                    std::cerr << "Error: Failed to decrypt data" << std::endl;
                    return;
                }

                ret = EVP_DecryptFinal(ctx, out + out_len, &out_len);
                if (ret != 1) {
                    std::cerr << "Error: Failed to finalize decryption" << std::endl;
                    return;
                }

                std::string decrypted = std::string((char*)out, out_len);
                delete[] out;

                // Print the decrypted data
                std::cout << "Decrypted data: " << decrypted << std::endl;
            }
    };

    class CryptographicService {
        private:
            std::mt19937 random_engine;
            std::uniform_int_distribution<unsigned int> distribution;

        public:
            CryptographicService() {
                // Initialize the random engine with a secure entropy source
                unsigned int seed = distribution(random_engine);
                RAND_seed(seed);
            }

            void performOperation(CryptographicOperation* operation) {
                // Perform the cryptographic operation using OpenSSL library
                operation->performOperation();
            }
    };
}
