namespace GameWorldConfiguration
{
    class ConfigurationManager
    {
        private static Dictionary<string, object> _configSettings = new Dictionary<string, object>();
        private static Dictionary<string, object> _cachedConfigSettings = new Dictionary<string, object>();

        public static void LoadConfiguration(string configFilePath)
        {
            // Load the configuration settings from the JSON file
            string jsonString = File.ReadAllText(configFilePath);
            JsonSerializer serializer = new JsonSerializer();
            _configSettings = (Dictionary<string, object>)serializer.Deserialize(new StringReader(jsonString), typeof(Dictionary<string, object>));
        }

        public static void UpdateConfiguration(string configKey, object configValue)
        {
            // Update the configuration setting in memory
            _configSettings[configKey] = configValue;

            // Update the cached configuration setting
            if (_cachedConfigSettings.ContainsKey(configKey))
            {
                _cachedConfigSettings[configKey] = configValue;
            }
        }

        public static object GetConfigurationSetting(string configKey)
        {
            // Check if the configuration setting is in memory
            if (_configSettings.ContainsKey(configKey))
            {
                return _configSettings[configKey];
            }
            else
            {
                // If not, check if it's in the cached configuration settings
                if (_cachedConfigSettings.ContainsKey(configKey))
                {
                    return _cachedConfigSettings[configKey];
                }
                else
                {
                    // If not, load the configuration setting from the JSON file
                    LoadConfiguration();
                    return GetConfigurationSetting(configKey);
                }
            }
        }

        public static void SaveConfiguration()
        {
            // Serialize the configuration settings to a JSON string
            JsonSerializer serializer = new JsonSerializer();
            StringWriter writer = new StringWriter();
            serializer.Serialize(writer, _configSettings);
            string jsonString = writer.ToString();

            // Save the JSON string to a file
            File.WriteAllText("configuration.json", jsonString);
        }
    }
}
