namespace MyCompany.WebApplication.Services
{
    public class ElementUpdateService
    {
        private readonly UnionFind _unionFind = new UnionFind();

        public async Task<string> UpdateElementWithDisjointPairs(int pageSectionId, int elementId, string htmlContent)
        {
            // Validate input parameters
            if (pageSectionId <= 0 || elementId <= 0 || string.IsNullOrEmpty(htmlContent))
            {
                return JsonConvert.SerializeObject(new { success = false, message = "Invalid input parameters" });
            }

            // Parse and manipulate HTML content
            var htmlDocument = new HtmlAgilityPack.HtmlDocument();
            htmlDocument.LoadHtml(htmlContent);
            var element = htmlDocument.GetElementById(elementId);

            if (element == null)
            {
                return JsonConvert.SerializeObject(new { success = false, message = "Invalid element ID" });
            }

            // Update element's HTML content using Union-Find algorithm
            var disjointPairs = _unionFind.GetDisjointPairs(element);
            foreach (var pair in disjointPairs)
            {
                var parentElement = htmlDocument.GetElementById(pair.ParentId);
                if (parentElement != null)
                {
                    parentElement.InnerHtml = pair.Content;
                }
            }

            // Return JSON response indicating page should be refreshed
            return JsonConvert.SerializeObject(new { success = true, message = "Page should be refreshed" });
        }
    }
}
```
