// Define the maximum length of a filename
#define MAX_FILENAME_LEN 256

// Define the maximum length of a file type extension
#define MAX_EXTENSION_LEN 10

// Define the list of allowed characters in a filename
const char *allowed_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-";

// Define the list of allowed file types
const char *allowed_file_types[] = {"jpg", "png", "gif"};

// Function to generate a new filename based on a given filename
char* generate_new_filename(const char* filename) {
    // Initialize variables
    int base_name_len, extension_len, identifier;
    char *base_name, *extension, *new_filename;

    // Parse the filename to extract the base name and extension
    base_name = strtok(filename, ".");
    if (base_name == NULL) {
        return NULL;
    }
    extension = strtok(NULL, "");

    // Calculate the identifier by summing the ASCII values of all alphabetic characters in the base name
    for (identifier = 0; *base_name != '\0'; base_name++) {
        if (isalpha(*base_name)) {
            identifier += *base_name;
        }
    }

    // Generate a random number of digits to append to the new filename
    int num_digits = rand() % 10 + 1;
    char *random_digits = malloc(num_digits + 1);
    for (int i = 0; i < num_digits; i++) {
        random_digits[i] = '0' + (rand() % 10);
    }
    random_digits[num_digits] = '\0';

    // Generate the new filename by appending the calculated identifier, the random digits, and a file type extension derived from the base name’s first character
    int new_filename_len = strlen(base_name) + num_digits + 1 + strlen(extension);
    new_filename = malloc(new_filename_len + 1);
    snprintf(new_filename, new_filename_len + 1, "%s%s.%s", base_name, random_digits, extension);

    // Validate the new filename against a predefined list of allowed characters and file types
    for (int i = 0; i < strlen(new_filename); i++) {
        if (!strchr(allowed_chars, new_filename[i])) {
            free(random_digits);
            free(new_filename);
            return NULL;
        }
    }
    for (int i = 0; i < sizeof(allowed_file_types) / sizeof(char*); i++) {
        if (!strcmp(extension, allowed_file_types[i])) {
            break;
        } else if (i == sizeof(allowed_file_types) / sizeof(char*) - 1) {
            free(random_digits);
            free(new_filename);
            return NULL;
        }
    }

    // Integrate with an external logging system to record errors or unusual behavior
    if (errno != 0) {
        log_error("Error generating new filename: %s", strerror(errno));
    }

    // Optimize the function for performance, especially when dealing with large numbers of filenames
    free(random_digits);
    return new_filename;
}
