#include <pthread.h>
#include "nfapi_crc_indication_pdu.h"

// Define the maximum number of PDUs to be created
#define MAX_PDU_COUNT 1000

// Define the minimum and maximum delay times for network latency simulation (in milliseconds)
#define MIN_DELAY_TIME 50
#define MAX_DELAY_TIME 200

// Define the percentage of PDUs that may fail to be created due to network packet loss
#define FAILURE_PERCENTAGE 10

// Define the maximum number of retries for failed PDU creation
#define MAX_RETRIES 3

// Define the logging mechanism for recording detailed information about the creation process
#define LOGGING_MECHANISM printf

// Define a structure to hold the CRC indication PDUs
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
} crc_indication_pdu_t;

// Define a function to create and populate a list of CRC indication PDUs
void create_crc_indication_pdus(int n, int *rnti, int *crc_flag) {
    // Initialize the list of CRC indication PDUs
    crc_indication_pdu_t *pdu_list = (crc_indication_pdu_t *)malloc(n * sizeof(crc_indication_pdu_t));
    if (!pdu_list) {
        LOGGING_MECHANISM("Failed to allocate memory for CRC indication PDU list\n");
        return;
    }

    // Initialize the RX UE information tag and RNTI values
    int rx_ue_information_tag = 0;
    for (int i = 0; i < n; i++) {
        pdu_list[i].pdu.rx_ue_information_tag = rx_ue_information_tag++;
        pdu_list[i].pdu.rnti = rnti[i];
    }

    // Simulate network latency by introducing a delay before each PDU is created
    int delay_time = MIN_DELAY_TIME + (rand() % (MAX_DELAY_TIME - MIN_DELAY_TIME));
    LOGGING_MECHANISM("Simulating network latency with a delay time of %d milliseconds\n", delay_time);
    usleep(delay_time * 1000);

    // Create and populate the CRC indication PDUs
    int pdu_count = 0;
    while (pdu_count < n) {
        // Generate a random CRC flag value
        crc_flag[pdu_count] = rand() % 2;

        // Create the CRC indication PDU
        NFAPI_CRC_INDICATION_PDU_T *pdu = &(pdu_list[pdu_count].pdu);
        pdu->crc_indication_rel8.crc_flag = crc_flag[pdu_count];

        // Simulate network packet loss by randomly failing to create some PDUs
        int failure_probability = FAILURE_PERCENTAGE / 100;
        if (rand() % 100 < failure_probability) {
            LOGGING_MECHANISM("Simulating network packet loss: failed to create CRC indication PDU for RNTI %d\n", rnti[pdu_count]);
            continue;
        }

        // Increment the PDU count and validate the integrity of the created PDU
        pdu_count++;
        if (!validate_crc_indication_pdu(pdu)) {
            LOGGING_MECHANISM("Failed to validate CRC indication PDU for RNTI %d\n", rnti[pdu_count]);
            continue;
        }
    }

    // Log the total time taken to create the PDUs
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    for (int i = 0; i < pdu_count; i++) {
        LOGGING_MECHANISM("Created CRC indication PDU for RNTI %d with CRC flag %d\n", pdu_list[i].pdu.rnti, pdu_list[i].pdu.crc_indication_rel8.crc_flag);
    }
    clock_gettime(CLOCK_MONOTONIC, &end);
    long total_time = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000;
    LOGGING_MECHANISM("Total time taken to create %d CRC indication PDUs: %ld milliseconds\n", pdu_count, total_time);

    // Free the memory allocated for the list of CRC indication PDUs
    free(pdu_list);
}

// Define a function to validate the integrity of a CRC indication PDU
int validate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Check that all fields are correctly initialized
    if (pdu->rx_ue_information_tag == 0 || pdu->rnti == 0 || pdu->crc_indication_rel8.crc_flag == 0) {
        return 0;
    }
    return 1;
}

// Define a function to handle memory allocation and deallocation safely
void *safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        LOGGING_MECHANISM("Failed to allocate memory\n");
        return NULL;
    }
    return ptr;
}

// Define a function to handle memory deallocation safely
void safe_free(void *ptr) {
    if (ptr) {
        free(ptr);
    }
}
