// Function to securely derive an encryption key from a password using PBKDF2 and SHA-256 hashing
void deriveKey(const char* password, unsigned char* key) {
    // Initialize the PBKDF2 context with the given password and salt
    EVP_PKEY_CTX *pctx = EVP_PKEY_CTX_new_id(EVP_PKEY_HMAC, NULL);
    EVP_PKEY_derive_init(pctx);
    EVP_PKEY_CTX_set_hkdf_md(pctx, EVP_sha256());
    EVP_PKEY_CTX_set1_hkdf_salt(pctx, "salt", 4);
    EVP_PKEY_CTX_set1_hkdf_key(pctx, password, strlen(password));

    // Derive the encryption key from the password using PBKDF2 with the given number of iterations
    unsigned char* derivedKey = NULL;
    int derivedKeyLen = 0;
    EVP_PKEY_derive(pctx, &derivedKey, &derivedKeyLen);
    memcpy(key, derivedKey, AES_KEY_SIZE);
    OPENSSL_free(derivedKey);
    EVP_PKEY_CTX_free(pctx);
}

// Function to initialize an AES-256-CBC cipher with a given key and IV
void initCipher(const unsigned char* key, const unsigned char* iv) {
    // Initialize the AES-256-CBC context with the given key and IV
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
}

