    while (scanf("%d", &((*arr)[i])) != EOF) {
        // If the array is full, double its size and reallocate memory
        if (i == (*arr)[i]) {
            *arr = (int*)realloc(*arr, sizeof(int) * 2 * i);
        }
        i++;
    }
}

