    // Allocate memory for the list of frames
    DL_FRAME_INFO* frames = (DL_FRAME_INFO*)malloc(sizeof(DL_FRAME_INFO) * F);
    if (!frames) {
        return NULL;
    }

    // Initialize each frame structure with a valid SRS_INFO, CSI_REPORT, and MCS_LEVEL
    for (int i = 0; i < F; i++) {
        frames[i].srs_info.valid = true;
        frames[i].csi_report.valid = true;
        frames[i].mcs_level = mcs_table->lookup(frames[i].srs_info.metric);
    }

    // Validate the integrity of each frame structure to ensure all fields are correctly initialized
    for (int i = 0; i < F; i++) {
        if (!frames[i].srs_info.valid || !frames[i].csi_report.valid || frames[i].mcs_level == MCS_LEVEL_INVALID) {
            free(frames);
            return NULL;
        }
    }

    // Return the list of DL_FRAME_INFO structures
    return frames;
}

// Define the lookup function for the MCS table
