#define MAX_HANDOVER_REQUESTS 100
#define MAX_CELL_ID_LENGTH 20
#define MAX_UE_ID_LENGTH 20
#define MAX_CAUSE_VALUE 5

typedef struct handover_request {
    char target_cell_id[MAX_CELL_ID_LENGTH];
    char source_cell_id[MAX_CELL_ID_LENGTH];
    char ue_id[MAX_UE_ID_LENGTH];
    int cause;
} handover_request_t;

typedef struct handover_request_list {
    handover_request_t requests[MAX_HANDOVER_REQUESTS];
    size_t num_requests;
} handover_request_list_t;

void init_handover_request(handover_request_t *req) {
    memset(req, 0, sizeof(*req));
}

void add_handover_request(handover_request_list_t *list, handover_request_t *req) {
    if (list->num_requests < MAX_HANDOVER_REQUESTS) {
        list->requests[list->num_requests++] = *req;
    } else {
        printf("Maximum number of handover requests reached\n");
    }
}

void remove_handover_request(handover_request_list_t *list, size_t index) {
    if (index < list->num_requests) {
        memmove(&list->requests[index], &list->requests[index + 1], sizeof(*req) * (list->num_requests - index));
        list->num_requests--;
    } else {
        printf("Invalid handover request index\n");
    }
}

void clear_handover_request_list(handover_request_list_t *list) {
    list->num_requests = 0;
}

int generate_handover_request_message(char *buf, size_t buflen, handover_request_t *req) {
    int ret = snprintf(buf, buflen, "HANDOVER REQUEST: Target Cell ID %s, Source Cell ID %s, UE ID %s, Cause %d\n", req->target_cell_id, req->source_cell_id, req->ue_id, req->cause);
    if (ret < 0 || ret >= buflen) {
        printf("Error generating handover request message: %s\n", strerror(errno));
        return -1;
    }
    return ret;
}

int send_handover_request(int sockfd, handover_request_t *req) {
    char buf[256];
    int ret = generate_handover_request_message(buf, sizeof(buf), req);
    if (ret < 0) {
        printf("Error generating handover request message: %s\n", strerror(errno));
        return -1;
    }
    ret = send(sockfd, buf, ret, 0);
    if (ret < 0) {
        printf("Error sending handover request: %s\n", strerror(errno));
        return -1;
    }
    return ret;
}

int handle_handover_request(int sockfd, handover_request_t *req) {
    // Implement your code here to handle the handover request
    printf("Handling handover request: Target Cell ID %s, Source Cell ID %s, UE ID %s, Cause %d\n", req->target_cell_id, req->source_cell_id, req->ue_id, req->cause);
    return 0;
}

int main(void) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        printf("Error creating socket: %s\n", strerror(errno));
        return -1;
    }

    struct sockaddr_in serv_addr = {
        .sin_family = AF_INET,
        .sin_port = htons(80),
        .sin_addr.s_addr = INADDR_ANY
    };

