        printf("Error binding socket: %s\n", strerror(errno));
        return -1;
    }

    if (listen(sockfd, MAX_HANDOVER_REQUESTS) < 0) {
        printf("Error listening on socket: %s\n", strerror(errno));
        return -1;
    }

    handover_request_list_t req_list = { .num_requests = 0 };

    while (true) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int connfd = accept(sockfd, (struct sockaddr *)&client_addr, &addrlen);
        if (connfd < 0) {
            printf("Error accepting connection: %s\n", strerror(errno));
            return -1;
        }

        handover_request_t req = { .cause = 0 };
        init_handover_request(&req);

        char buf[256];
        int ret = recv(connfd, buf, sizeof(buf), 0);
        if (ret < 0) {
            printf("Error receiving handover request: %s\n", strerror(errno));
            return -1;
        }

        // Parse the received message and extract the target cell ID, source cell ID, UE ID, and cause value
        char *token = strtok(buf, " ");
        while (token != NULL) {
            if (strcmp(token, "HANDOVER") == 0) {
                token = strtok(NULL, " ");
                if (token != NULL) {
                    strncpy(req.target_cell_id, token, MAX_CELL_ID_LENGTH);
                    token = strtok(NULL, " ");
                    if (token != NULL) {
                        strncpy(req.source_cell_id, token, MAX_CELL_ID_LENGTH);
                        token = strtok(NULL, " ");
                        if (token != NULL) {
                            strncpy(req.ue_id, token, MAX_UE_ID_LENGTH);
                            token = strtok(NULL, " ");
                            if (token != NULL) {
                                req.cause = atoi(token);
                            } else {
                                printf("Error parsing handover request: Invalid cause value\n");
                                return -1;
                            }
                        } else {
                            printf("Error parsing handover request: Invalid UE ID\n");
                            return -1;
                        }
                    } else {
                        printf("Error parsing handover request: Invalid source cell ID\n");
                        return -1;
                    }
                } else {
                    printf("Error parsing handover request: Invalid target cell ID\n");
                    return -1;
                }
            } else {
                token = strtok(NULL, " ");
            }
        }

        // Add the received handover request to the list of requests
        add_handover_request(&req_list, &req);

        // Handle the received handover request
        handle_handover_request(connfd, &req);

        // Close the connection with the client
        close(connfd);
    }

    return 0;
}
