int manage_memory(long* offset_array, int* key_array, Record** record_array, size_t num_records, size_t max_offset, size_t max_key, size_t max_record, bool allow_duplicates) {
    // Check if the input parameters are valid
    if (offset_array == NULL || key_array == NULL || record_array == NULL || num_records == 0 || max_offset == 0 || max_key == 0 || max_record == 0) {
        return -1;
    }

    // Initialize the offset array
    if (max_offset > INT_MAX) {
        fprintf(stderr, "Error: Maximum offset value exceeds the maximum integer value\n");
        return -1;
    }
    *offset_array = malloc(sizeof(long) * num_records);
    if (*offset_array == NULL) {
        perror("malloc");
        return -1;
    }

    // Initialize the key array
    if (max_key > INT_MAX) {
        fprintf(stderr, "Error: Maximum key value exceeds the maximum integer value\n");
        free(*offset_array);
        *offset_array = NULL;
        return -1;
    }
    *key_array = malloc(sizeof(int) * num_records);
    if (*key_array == NULL) {
        perror("malloc");
        free(*offset_array);
        *offset_array = NULL;
        return -1;
    }

    // Initialize the record array
    *record_array = malloc(sizeof(Record*) * num_records);
    if (*record_array == NULL) {
        perror("malloc");
        free(*key_array);
        *key_array = NULL;
        free(*offset_array);
        *offset_array = NULL;
        return -1;
    }

    // Initialize the record structures
