        (*record_array)[i] = malloc(sizeof(Record));
        if ((*record_array)[i] == NULL) {
            perror("malloc");
            free(*key_array);
            *key_array = NULL;
            free(*offset_array);
            *offset_array = NULL;
            return -1;
