    }

    // Initialize the offset and key values
    for (size_t i = 0; i < num_records; i++) {
        (*offset_array)[i] = 0;
        (*key_array)[i] = 0;
    }

    // Save the initialized records to a file in binary format
    FILE* fp = fopen("records.bin", "wb");
    if (fp == NULL) {
        perror("fopen");
        free(*record_array);
        *record_array = NULL;
        free(*key_array);
        *key_array = NULL;
        free(*offset_array);
        *offset_array = NULL;
        return -1;
    }
    for (size_t i = 0; i < num_records; i++) {
        fwrite(&((*record_array)[i]), sizeof(Record), 1, fp);
