    // Check if the input directory path is valid
    if (argc < 2 || strlen(argv[1]) == 0) {
        handle_error("Invalid input directory path");
        return -1;
    }

    // Initialize the external file processing library
    int ret = init_file_processing_library();
    if (ret != 0) {
        handle_error("Failed to initialize file processing library");
        return -1;
    }

    // Get the input directory path and command line options
    char* directory_path = argv[1];
    bool generate_reports = false;
    int num_threads = 0;
    if (argc > 2) {
        generate_reports = true;
        num_threads = atoi(argv[2]);
    }

    // Initialize the report object
    Report* report = malloc(sizeof(Report));
    report->directory = directory_path;
    report->num_threads = num_threads;
    report->generate_reports = generate_reports;
    report->num_files_processed = 0;
    report->num_errors = 0;

    // Initialize the thread pool for parallel processing
    pthread_t* threads = malloc(sizeof(pthread_t) * num_threads);
    if (threads == NULL) {
        handle_error("Failed to allocate memory for thread pool");
        return -1;
    }

    // Initialize the file descriptor for the input directory
    int dir_fd = open(directory_path, O_RDONLY);
    if (dir_fd == -1) {
        handle_error("Failed to open input directory");
        return -1;
    }

    // Initialize the file descriptor for the output report file
    int report_fd = 0;
    if (generate_reports) {
        char* report_file_path = "report.txt";
        report_fd = open(report_file_path, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
        if (report_fd == -1) {
            handle_error("Failed to create output report file");
            return -1;
        }
    }

    // Iterate over the files in the input directory and process them in parallel
    struct dirent* entry = NULL;
    while ((entry = readdir(dir_fd)) != NULL) {
        char* filename = entry->d_name;
        if (strcmp(filename, ".") == 0 || strcmp(filename, "..") == 0) {
            continue;
        }

        // Create a thread for each file and add it to the thread pool
        pthread_t thread;
        int ret = pthread_create(&thread, NULL, process_file, (void*)filename);
        if (ret != 0) {
            handle_error("Failed to create thread");
            return -1;
        }
        threads[report->num_files_processed] = thread;
        report->num_files_processed++;
    }

    // Wait for all threads to complete and join them
    for (int i = 0; i < report->num_files_processed; i++) {
        pthread_join(threads[i], NULL);
    }

    // Close the file descriptors
    close(dir_fd);
    if (report_fd != 0) {
        close(report_fd);
    }

    // Log the report and return
    log_message("Processing completed");
    log_message("Number of files processed: %d", report->num_files_processed);
    log_message("Number of errors encountered: %d", report->num_errors);
    if (generate_reports) {
        write(report_fd, "Processing completed\n", strlen("Processing completed\n"));
        write(report_fd, "Number of files processed: ", strlen("Number of files processed: "));
        write(report_fd, report->num_files_processed, sizeof(int));
        write(report_fd, "\n", strlen("\n"));
        write(report_fd, "Number of errors encountered: ", strlen("Number of errors encountered: "));
        write(report_fd, report->num_errors, sizeof(int));
        write(report_fd, "\n", strlen("\n"));
    }
    return 0;
}

// Define the file processing function
void process_file(char* filename, int thread_id) {
    // Initialize the external file processing library for this thread
    int ret = init_file_processing_library();
    if (ret != 0) {
        handle_error("Failed to initialize file processing library");
        return;
    }

    // Open the input file and process it
    char* filepath = malloc(strlen(filename) + strlen(report->directory) + 2);
    sprintf(filepath, "%s/%s", report->directory, filename);
    int fd = open(filepath, O_RDONLY);
    if (fd == -1) {
        handle_error("Failed to open input file");
        return;
    }
    process_file_contents(fd);
    close(fd);

    // Log the completion of this thread
    log_message("Thread %d completed", thread_id);
}

// Define the error handling function
void handle_error(const char* message) {
    perror(message);
    exit(-1);
}

// Define the logging function
void log_message(const char* message, ...) {
    va_list args;
    va_start(args, message);
    vfprintf(stderr, message, args);
    fprintf(stderr, "\n");
    va_end(args);
}
