// Function to generate a unique identifier for a filename
char *generate_identifier(const char *filename, const char *extension) {
    // Check if the filename is empty or contains only invalid characters
    if (strlen(filename) == 0 || strpbrk(filename, "\\/:*?\"<>|") != NULL) {
        return NULL;
    }

    // Allocate memory for the identifier
    char *identifier = malloc(MAX_IDENTIFIER_LENGTH + 1);
    if (identifier == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for identifier\n");
        return NULL;
    }

    // Generate the identifier
    int i = 0;
    while (i < MAX_IDENTIFIER_LENGTH && filename[i] != '\0') {
        if (!isalnum(filename[i])) {
            identifier[i] = '_';
        } else {
            identifier[i] = tolower(filename[i]);
        }
        i++;
    }
    identifier[i] = '\0';

    // Return the identifier
    return identifier;
}

// Function to modify a filename by appending a unique identifier
char *modify_filename(const char *filename, const char *extension) {
    // Check if the filename is empty or contains only invalid characters
    if (strlen(filename) == 0 || strpbrk(filename, "\\/:*?\"<>|") != NULL) {
        return NULL;
    }

    // Allocate memory for the modified filename
    char *modified_filename = malloc(MAX_FILENAME_LENGTH + 1);
    if (modified_filename == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for modified filename\n");
        return NULL;
    }

    // Generate the unique identifier
    char *identifier = generate_identifier(filename, extension);
    if (identifier == NULL) {
        free(modified_filename);
        return NULL;
    }

    // Construct the modified filename
    int i = 0;
    while (i < MAX_FILENAME_LENGTH && filename[i] != '\0') {
        modified_filename[i] = filename[i];
        i++;
    }
    if (i == MAX_FILENAME_LENGTH) {
        free(modified_filename);
        return NULL;
    }
    modified_filename[i++] = '_';
    for (int j = 0; j < MAX_IDENTIFIER_LENGTH && identifier[j] != '\0'; j++) {
        modified_filename[i++] = identifier[j];
    }
    modified_filename[i] = '\0';

    // Add the file extension if necessary
    if (strlen(extension) > 0) {
        int ext_length = strlen(extension);
        for (int j = 0; j < ext_length && i + j < MAX_FILENAME_LENGTH; j++) {
            modified_filename[i++] = extension[j];
        }
    }

    // Return the modified filename
    return modified_filename;
}

// Function to handle memory allocation failures and truncation events
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Function to process a single filename concurrently
void process_filename(const char *filename, const char *extension) {
    // Check if the filename is empty or contains only invalid characters
    if (strlen(filename) == 0 || strpbrk(filename, "\\/:*?\"<>|") != NULL) {
        log_error("Invalid filename");
        return;
    }

    // Check if the extension is valid
    int ext_length = strlen(extension);
    if (ext_length == 0 || strpbrk(extension, "\\/:*?\"<>|") != NULL) {
        log_error("Invalid extension");
        return;
    }

    // Check if the filename is already cached
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (strcmp(cache[i].filename, filename) == 0 && strcmp(cache[i].extension, extension) == 0) {
            // Return the cached identifier
            printf("%s\n", cache[i].identifier);
            return;
        }
    }

    // Generate a unique identifier for the filename
    char *identifier = generate_identifier(filename, extension);
    if (identifier == NULL) {
        log_error("Failed to generate identifier");
        return;
    }

    // Construct the modified filename
    char *modified_filename = modify_filename(filename, extension);
    if (modified_filename == NULL) {
        free(identifier);
        log_error("Failed to modify filename");
        return;
    }

    // Add the identifier and modified filename to the cache
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].filename == NULL) {
            cache[i].filename = strdup(filename);
            cache[i].extension = strdup(extension);
            cache[i].identifier = identifier;
            break;
        }
    }

    // Return the modified filename
    printf("%s\n", modified_filename);
}

// Function to process multiple filenames concurrently
void process_filenames(const char *filenames, const char *extensions) {
    // Split the filenames and extensions into arrays
    char **filenames_array = strsplit(filenames, ",");
    char **extensions_array = strsplit(extensions, ",");

    // Process each filename and extension pair concurrently
    for (int i = 0; i < sizeof(filenames_array) / sizeof(char *); i++) {
        process_filename(filenames_array[i], extensions_array[i]);
    }
}
