```c
#include <wolfssl/wolfssl.h>

int init_secure_websocket(const char* server_address, int port, const char* username, const char* password) {
    // Initialize WolfSSL context
    WOLFSSL_CTX* ctx = wolfSSL_CTX_new(WOLFSSLv23_CLIENT_METHOD);
    if (!ctx) {
        return -1;
    }

    // Set up TLS 1.2 protocol version
    wolfSSL_CTX_set_min_proto_version(ctx, WOLFSSL_PROTOCOL_TLSv1_2);

    // Create a new WolfSSL object
    WOLFSSL* ssl = wolfSSL_new(ctx);
    if (!ssl) {
        wolfSSL_CTX_free(ctx);
        return -1;
    }

    // Set up the server address and port
    wolfSSL_set_fd(ssl, server_address, port);

    // Authenticate the client using a username and password
    if (wolfSSL_connect(ssl) != WOLFSSL_SUCCESS) {
        wolfSSL_free(ssl);
        wolfSSL_CTX_free(ctx);
        return -1;
    }

    // Negotiate TLS 1.2 for secure communication
    if (wolfSSL_negotiate_tls(ssl) != WOLFSSL_SUCCESS) {
        wolfSSL_free(ssl);
        wolfSSL_CTX_free(ctx);
        return -1;
    }

    // Implement session resumption to optimize reconnection times for subsequent connections
    if (wolfSSL_session_resume(ssl) != WOLFSSL_SUCCESS) {
        wolfSSL_free(ssl);
        wolfSSL_CTX_free(ctx);
        return -1;
    }

    // Clean up the WolfSSL object and context
    wolfSSL_free(ssl);
    wolfSSL_CTX_free(ctx);

    return 0;
}
```
This function takes in a server address, port, username, and password as input parameters. It initializes a secure WebSocket connection using the wolfSSL library by creating a new WolfSSL context and object, setting up the TLS 1.2 protocol version, authenticating the client using the given username and password, and negotiating TLS 1.2 for secure communication. The function also implements session resumption to optimize reconnection times for subsequent connections while balancing resource usage with performance goals.

