// Define a graph structure using Boost library
typedef adjacency_list<vecS, vecS, undirectedS, no_property, property<edge_weight_t, int>> Graph;

// Function to create a graph from a file
Graph createGraph(string filename) {
    ifstream infile(filename);
    string line;
    vector<int> vertices;
    vector<pair<int, int>> edges;

    // Read the file and populate the graph structure
    while (getline(infile, line)) {
        istringstream iss(line);
        int v1, v2;
        if (iss >> v1 >> v2) {
            vertices.push_back(v1);
            vertices.push_back(v2);
            edges.push_back({v1, v2});
        }
    }

    // Create the graph structure using the populated vectors
    Graph g(vertices.begin(), vertices.end(), edges.begin(), edges.end());
    return g;
}

// Function to calculate shortest paths between two nodes in a graph
vector<int> dijkstraShortestPaths(Graph& g, int src, int dest) {
    vector<int> distances(num_vertices(g));
    vector<int> predecessors(num_vertices(g));
    dijkstra_shortest_paths(g, src,
        distance_map(&distances[0]).
        predecessor_map(&predecessors[0]));
    return distances;
}

