    vector<int> centrality(num_vertices(g));
    centrality_map<Graph, int> cm = make_centrality_map(g);
    centrality_map<Graph, int>::iterator iter;
    for (iter = cm.begin(); iter != cm.end(); ++iter) {
        centrality[iter->first] = iter->second;
