NFAPI_CRC_INDICATION_PDU_T *crc_indication_array = NULL;

// Define the mutex for protecting concurrent access to the array
pthread_mutex_t crc_indication_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new element to the array
void add_element(NFAPI_CRC_INDICATION_PDU_T *new_element) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&crc_indication_mutex);

    // Allocate memory for the new element
    NFAPI_CRC_INDICATION_PDU_T *new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_element == NULL) {
        // Handle out of memory error
        pthread_mutex_unlock(&crc_indication_mutex);
        return;
    }

    // Copy the data from the new element to the array
    memcpy(new_element, new_element, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Add the new element to the end of the array
    if (crc_indication_array == NULL) {
        crc_indication_array = new_element;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *last_element = crc_indication_array;
        while (last_element->next != NULL) {
            last_element = last_element->next;
        }
        last_element->next = new_element;
