    while (element != NULL && element->next != updated_element) {
        element = element->next;
    }

    // If the element is found, update its data
    if (element != NULL) {
        memcpy(element, updated_element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else {
        // Handle element not found error
        pthread_mutex_unlock(&crc_indication_mutex);
        return;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&crc_indication_mutex);
}

// Function to retrieve an element from the array by index
