    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&crc_indication_mutex);

    // Find the element in the array that needs to be retrieved
    NFAPI_CRC_INDICATION_PDU_T *element = crc_indication_array;
    for (int i = 0; i < index && element != NULL; i++) {
        element = element->next;
    }

    // If the element is found, return it
    if (element != NULL) {
        pthread_mutex_unlock(&crc_indication_mutex);
        return element;
    } else {
        // Handle element not found error
        pthread_mutex_unlock(&crc_indication_mutex);
        return NULL;
    }
}

// Function to delete an element from the array by index
