    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&crc_indication_mutex);

    // Find the element in the array that needs to be deleted
    NFAPI_CRC_INDICATION_PDU_T *element = crc_indication_array;
    for (int i = 0; i < index && element != NULL; i++) {
        element = element->next;
    }

    // If the element is found, delete it from the array
    if (element != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *previous_element = crc_indication_array;
        while (previous_element->next != element) {
            previous_element = previous_element->next;
        }
        previous_element->next = element->next;
    } else {
        // Handle element not found error
        pthread_mutex_unlock(&crc_indication_mutex);
        return;
