#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>

// Define the structure to store the CRC indication data
typedef struct {
    RX_UE_INFORMATION_TAG rxUeInformation;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the maximum size of the dynamic array
#define MAX_ARRAY_SIZE 1024

// Define the custom resizing mechanism for the dynamic array
void resizeArray(NFAPI_CRC_INDICATION_PDU_T **array, int newSize) {
    // Check if the new size is within the maximum allowed size
    assert(newSize <= MAX_ARRAY_SIZE);

    // Allocate a new array with the new size
    NFAPI_CRC_INDICATION_PDU_T *newArray = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * newSize);

    // Copy the elements from the old array to the new array
    for (int i = 0; i < (*array)->size; i++) {
        newArray[i] = (*array)[i];
    }

    // Free the old array and set the new array as the current one
    free(*array);
    *array = newArray;
}

// Define the function to add a new element to the dynamic array
void addElement(NFAPI_CRC_INDICATION_PDU_T **array, RX_UE_INFORMATION_TAG rxUeInformation, RNTI rnti, CRC_INDICATION_REL8_TAG crcIndicationRel8) {
    // Check if the array is full and needs to be resized
    if ((*array)->size == MAX_ARRAY_SIZE) {
        resizeArray(array, (*array)->size * 2);
    }

    // Add a new element to the end of the array
    (*array)[(*array)->size].rxUeInformation = rxUeInformation;
    (*array)[(*array)->size].rnti = rnti;
    (*array)[(*array)->size].crcIndicationRel8 = crcIndicationRel8;
    (*array)->size++;
}

// Define the function to update an existing element in the dynamic array
void updateElement(NFAPI_CRC_INDICATION_PDU_T **array, int index, RX_UE_INFORMATION_TAG rxUeInformation, RNTI rnti, CRC_INDICATION_REL8_TAG crcIndicationRel8) {
    // Check if the index is within the bounds of the array
    assert(index >= 0 && index < (*array)->size);

    // Update the element at the specified index
    (*array)[index].rxUeInformation = rxUeInformation;
    (*array)[index].rnti = rnti;
    (*array)[index].crcIndicationRel8 = crcIndicationRel8;
}

// Define the function to retrieve an element from the dynamic array by index
NFAPI_CRC_INDICATION_PDU_T getElement(NFAPI_CRC_INDICATION_PDU_T **array, int index) {
    // Check if the index is within the bounds of the array
    assert(index >= 0 && index < (*array)->size);

    // Return the element at the specified index
    return (*array)[index];
}

// Define the function to remove an element from the dynamic array by index
void removeElement(NFAPI_CRC_INDICATION_PDU_T **array, int index) {
    // Check if the index is within the bounds of the array
    assert(index >= 0 && index < (*array)->size);

    // Shift all elements after the specified index to the left by one position
    for (int i = index; i < (*array)->size - 1; i++) {
        (*array)[i] = (*array)[i + 1];
    }

    // Decrement the size of the array
    (*array)->size--;
}

// Define the function to clear all elements from the dynamic array
void clearArray(NFAPI_CRC_INDICATION_PDU_T **array) {
    // Set the size of the array to 0
    (*array)->size = 0;
}

int main() {
    // Initialize an empty dynamic array
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_ARRAY_SIZE);
    array->size = 0;

    // Add some elements to the dynamic array
    addElement(&array, RX_UE_INFORMATION_TAG_1, RNTI_1, CRC_INDICATION_REL8_TAG_1);
    addElement(&array, RX_UE_INFORMATION_TAG_2, RNTI_2, CRC_INDICATION_REL8_TAG_2);
    addElement(&array, RX_UE_INFORMATION_TAG_3, RNTI_3, CRC_INDICATION_REL8_TAG_3);

    // Update an existing element in the dynamic array
    updateElement(&array, 1, RX_UE_INFORMATION_TAG_4, RNTI_4, CRC_INDICATION_REL8_TAG_4);

    // Retrieve an element from the dynamic array by index
    NFAPI_CRC_INDICATION_PDU_T element = getElement(&array, 2);

    // Remove an element from the dynamic array by index
    removeElement(&array, 1);

    // Clear all elements from the dynamic array
    clearArray(&array);

    return 0;
}
