// Define the plugin interface structure
typedef struct {
    void (*init)(void);
    void (*destroy)(void);
} PluginInterface;

// Define a list of pointers to the loaded plugins
PluginInterface *plugins[MAX_PLUGINS];

// Define a mutex for thread safety
pthread_mutex_t plugin_mutex = PTHREAD_MUTEX_INITIALIZER;

// Load a plugin module based on the configuration file path provided
int loadPlugin(const char *configFilePath) {
    // Open the configuration file and read the plugin path
    FILE *configFile = fopen(configFilePath, "r");
    if (configFile == NULL) {
        printf("Error: unable to open configuration file\n");
        return -1;
    }
    char pluginPath[MAX_PATH];
    if (fscanf(configFile, "%s", pluginPath) != 1) {
        printf("Error: unable to read plugin path from configuration file\n");
        fclose(configFile);
        return -1;
    }
    fclose(configFile);

    // Load the plugin module using dlopen
    void *pluginHandle = dlopen(pluginPath, RTLD_LAZY | RTLD_LOCAL);
    if (pluginHandle == NULL) {
        printf("Error: unable to load plugin module\n");
        return -1;
    }

    // Get the plugin interface structure from the plugin module
    PluginInterface *(*getPluginInterface)(void) = dlsym(pluginHandle, "getPluginInterface");
    if (getPluginInterface == NULL) {
        printf("Error: unable to get plugin interface\n");
        dlclose(pluginHandle);
        return -1;
    }

    // Initialize the plugin using its init function
    PluginInterface *plugin = getPluginInterface();
    if (plugin->init == NULL) {
        printf("Error: unable to initialize plugin\n");
        dlclose(pluginHandle);
        return -1;
    }
    plugin->init();

    // Add the plugin to the list of loaded plugins
    pthread_mutex_lock(&plugin_mutex);
    for (int i = 0; i < MAX_PLUGINS; i++) {
        if (plugins[i] == NULL) {
            plugins[i] = plugin;
            break;
        }
    }
    pthread_mutex_unlock(&plugin_mutex);

    return 0;
}

// Unload a plugin module based on the configuration file path provided
int unloadPlugin(const char *configFilePath) {
    // Open the configuration file and read the plugin path
    FILE *configFile = fopen(configFilePath, "r");
    if (configFile == NULL) {
        printf("Error: unable to open configuration file\n");
        return -1;
    }
    char pluginPath[MAX_PATH];
    if (fscanf(configFile, "%s", pluginPath) != 1) {
        printf("Error: unable to read plugin path from configuration file\n");
        fclose(configFile);
        return -1;
    }
    fclose(configFile);

    // Find the plugin in the list of loaded plugins
    pthread_mutex_lock(&plugin_mutex);
    for (int i = 0; i < MAX_PLUGINS; i++) {
        if (plugins[i] != NULL && strcmp(plugins[i]->path, pluginPath) == 0) {
            // Destroy the plugin using its destroy function
            plugins[i]->destroy();

            // Unload the plugin module using dlclose
            dlclose(plugins[i]->handle);

            // Remove the plugin from the list of loaded plugins
            plugins[i] = NULL;
        }
    }
    pthread_mutex_unlock(&plugin_mutex);

    return 0;
}

// Return a list of pointers to the loaded plugin interfaces
PluginInterface **getLoadedPlugins() {
    // Create a new array of pointers to the loaded plugins
    PluginInterface **loadedPlugins = malloc(sizeof(PluginInterface *) * MAX_PLUGINS);
    if (loadedPlugins == NULL) {
        printf("Error: unable to allocate memory for loaded plugins\n");
        return NULL;
    }

    // Copy the pointers to the loaded plugins into the new array
    pthread_mutex_lock(&plugin_mutex);
    int i = 0;
    for (int j = 0; j < MAX_PLUGINS; j++) {
        if (plugins[j] != NULL) {
            loadedPlugins[i++] = plugins[j];
        }
    }
    pthread_mutex_unlock(&plugin_mutex);

    return loadedPlugins;
}
