  sem_t *sem = malloc(sizeof(sem_t));
  if (sem == NULL) {
    perror("Failed to allocate memory for semaphore");
    exit(1);
  }
  if (sem_init(sem, 0, value) != 0) {
    perror("Failed to initialize semaphore");
    exit(1);
  }
  return sem;
}

// Define the function to delete a semaphore
void delete_semaphore(sem_t *sem) {
  if (sem_destroy(sem) != 0) {
    perror("Failed to destroy semaphore");
    exit(1);
  }
  free(sem);
}

// Define the function to add a vertex to the graph
void add_vertex(struct Graph *graph, int id, char *label) {
  struct Vertex *new_vertex = malloc(sizeof(struct Vertex));
  new_vertex->id = id;
  strcpy(new_vertex->label, label);
  new_vertex->edges = NULL;
  graph->vertices[graph->num_vertices++] = new_vertex;
}

// Define the function to remove a vertex from the graph
