  struct Vertex *vertex = find_vertex(graph, id);
  if (vertex == NULL) {
    printf("Vertex with ID %d not found\n", id);
    return;
  }
  graph->num_vertices--;
  for (int i = vertex - graph->vertices; i < graph->num_vertices; i++) {
    graph->vertices[i] = graph->vertices[i + 1];
  }
}

// Define the function to add an edge between two vertices in the graph
void add_edge(struct Graph *graph, int src_id, int dst_id, char *label) {
  struct Vertex *src = find_vertex(graph, src_id);
  struct Vertex *dst = find_vertex(graph, dst_id);
  if (src == NULL || dst == NULL) {
    printf("Vertex with ID %d or %d not found\n", src_id, dst_id);
    return;
  }
  struct Edge *new_edge = malloc(sizeof(struct Edge));
  new_edge->src_id = src_id;
  new_edge->dst_id = dst_id;
  strcpy(new_edge->label, label);
  new_edge->next = NULL;
  if (src->edges == NULL) {
    src->edges = new_edge;
  } else {
    struct Edge *last_edge = find_last_edge(graph, src_id);
    last_edge->next = new_edge;
  }
}

// Define the function to remove an edge between two vertices in the graph
void remove_edge(struct Graph *graph, int src_id, int dst_id) {
  struct Vertex *src = find_vertex(graph, src_id);
  struct Vertex *dst = find_vertex(graph, dst_id);
  if (src == NULL || dst == NULL) {
    printf("Vertex with ID %d or %d not found\n", src_id, dst_id);
    return;
