  if (edge == NULL) {
    printf("Edge between vertices %d and %d not found\n", src_id, dst_id);
    return;
  }
  struct Edge *prev_edge = find_previous_edge(graph, edge);
  if (prev_edge == NULL) {
    src->edges = edge->next;
  } else {
    prev_edge->next = edge->next;
  }
}

// Define the function to find a vertex in the graph by ID
struct Vertex* find_vertex(struct Graph *graph, int id) {
  for (int i = 0; i < graph->num_vertices; i++) {
    if (graph->vertices[i]->id == id) {
      return graph->vertices[i];
    }
  }
  return NULL;
}

// Define the function to find an edge between two vertices in the graph
struct Edge* find_edge(struct Graph *graph, int src_id, int dst_id) {
  struct Vertex *src = find_vertex(graph, src_id);
  if (src == NULL) {
    return NULL;
  }
  for (struct Edge *edge = src->edges; edge != NULL; edge = edge->next) {
    if (edge->dst_id == dst_id) {
      return edge;
    }
  }
  return NULL;
}

// Define the function to find the previous edge in a list of edges
struct Edge* find_previous_edge(struct Graph *graph, struct Edge *edge) {
  for (int i = 0; i < graph->num_vertices; i++) {
    if (graph->vertices[i]->edges == edge) {
      return graph->vertices[i];
    }
  }
  return NULL;
}

// Define the function to find the last edge in a list of edges
struct Edge* find_last_edge(struct Graph *graph, int src_id) {
  struct Vertex *src = find_vertex(graph, src_id);
  if (src == NULL) {
    return NULL;
  }
  for (struct Edge *edge = src->edges; edge != NULL; edge = edge->next) {
    if (edge->next == NULL) {
      return edge;
    }
  }
  return NULL;
}

// Define the function to print a summary of the graph state
void print_summary(struct Graph *graph) {
  printf("Graph with %d vertices and %d edges\n", graph->num_vertices, graph->num_edges);
  for (int i = 0; i < graph->num_vertices; i++) {
    struct Vertex *vertex = graph->vertices[i];
    printf("Vertex %d: %s\n", vertex->id, vertex->label);
    for (struct Edge *edge = vertex->edges; edge != NULL; edge = edge->next) {
      printf("  -> %d: %s\n", edge->dst_id, edge->label);
    }
  }
}

// Define the main function to read command-line arguments and process input file
int main(int argc, char *argv[]) {
  // Check for command-line arguments
  if (argc < 2) {
    printf("Usage: %s [--help | -v | -o output_file]\n", argv[0]);
    return 1;
  }

  // Initialize the graph data structure
  struct Graph *graph = malloc(sizeof(struct Graph));
  graph->num_vertices = 0;
  graph->num_edges = 0;
  graph->vertices = NULL;

  // Read configurations from YAML file
  YAML::Node config = YAML::LoadFile("config.yaml");
  int thread_safety = config["thread_safety"].as<int>();
  int logging_level = config["logging_level"].as<int>();
  int performance_threshold = config["performance_threshold"].as<int>();

  // Create semaphores for thread safety
  sem_t *semaphore = create_semaphore(thread_safety);

  // Read input file line by line and process each line
  FILE *input_file = fopen("input.txt", "r");
  char line[256];
  while (fgets(line, sizeof(line), input_file) != NULL) {
    // Parse the command from the line
    char *command = strtok(line, " ");
    if (strcmp(command, "add") == 0) {
      // Add a vertex to the graph
      int id = atoi(strtok(NULL, " "));
      char *label = strtok(NULL, "\n");
      add_vertex(graph, id, label);
    } else if (strcmp(command, "remove") == 0) {
      // Remove a vertex from the graph
      int id = atoi(strtok(NULL, " "));
      remove_vertex(graph, id);
    } else if (strcmp(command, "add-edge") == 0) {
      // Add an edge between two vertices in the graph
      int src_id = atoi(strtok(NULL, " "));
      int dst_id = atoi(strtok(NULL, " "));
      char *label = strtok(NULL, "\n");
      add_edge(graph, src_id, dst_id, label);
    } else if (strcmp(command, "remove-edge") == 0) {
      // Remove an edge between two vertices in the graph
      int src_id = atoi(strtok(NULL, " "));
      int dst_id = atoi(strtok(NULL, " "));
      remove_edge(graph, src_id, dst_id);
    } else {
      // Unknown command
      printf("Unknown command: %s\n", command);
    }
  }
  fclose(input_file);

  // Log detailed information about added vertices and edges
  if (logging_level > 0) {
    for (int i = 0; i < graph->num_vertices; i++) {
      struct Vertex *vertex = graph->vertices[i];
      printf("Vertex %d: %s\n", vertex->id, vertex->label);
      for (struct Edge *edge = vertex->edges; edge != NULL; edge = edge->next) {
        printf("  -> %d: %s\n", edge->dst_id, edge->label);
      }
    }
  }

  // Print a summary of the graph state
  print_summary(graph);

  // Clean up resources
  delete_semaphore(semaphore);
  free(graph);

  return 0;
}
```
This code block implements a graph database that can dynamically manage vertices and edges in a concurrent environment. It reads configurations from an external YAML file, which includes parameters for thread safety, logging levels, and performance thresholds. The program creates semaphores to ensure resource management is efficient and deadlock-free, and it provides command-line arguments for operation mode, including --help, -v verbose, and -o output_file, providing usage information if no input is provided. It reads an input file line by line, processing each line to add or remove vertices and edges, while maintaining an internal cache for performance optimization. The program logs detailed information about added vertices and edges, including timestamps and performance metrics, to ensure comprehensive record-keeping.

The final output should include a summary of the graph state, including the number of vertices and edges, their properties, and the associated performance metrics. Developers are encouraged to analyze the trade-offs between memory efficiency, cache hit rates, and the complexity of concurrent operations to achieve optimal performance.']

