    if (input_file == NULL) {
        perror("Error opening input file");
        return;
    }
    FILE* output_file = fopen(output_filename, "wb");
    if (output_file == NULL) {
        perror("Error opening output file");
        fclose(input_file);
        return;
    }

    // Read the input file into memory
    size_t file_size = get_file_size(input_filename);
    char* buffer = (char*)malloc(max_buffer_size);
    if (buffer == NULL) {
        perror("Error allocating memory for buffer");
        fclose(input_file);
        fclose(output_file);
        return;
    }
    size_t bytes_read = fread(buffer, 1, max_buffer_size, input_file);
    if (bytes_read < file_size) {
        perror("Error reading from input file");
        free(buffer);
        fclose(input_file);
        fclose(output_file);
        return;
    }

    // Parse the buffer and transform the contents into the output file
    char* current_position = buffer;
    while (current_position < buffer + bytes_read) {
        // Apply transformation rules to the current position in the buffer
        size_t bytes_transformed = apply_transformation(current_position, transformation_rules);
        if (bytes_transformed == 0) {
            perror("Error applying transformation");
            free(buffer);
            fclose(input_file);
            fclose(output_file);
            return;
        }
        current_position += bytes_transformed;
    }

    // Write the transformed contents to the output file
    size_t bytes_written = fwrite(buffer, 1, current_position - buffer, output_file);
    if (bytes_written < current_position - buffer) {
        perror("Error writing to output file");
        free(buffer);
        fclose(input_file);
        fclose(output_file);
        return;
