void processValues(std::vector<int>& vec, int arg1, int arg2, int arg3) {
    // Find the first occurrence of the smallest value among the three arguments
    auto smallest = std::min({arg1, arg2, arg3});
    auto it = std::find(vec.begin(), vec.end(), smallest);

    // If none of the three values are present in the vector, append their sum to the end
    if (it == vec.end()) {
        vec.push_back(arg1 + arg2 + arg3);
        return;
    }

    // Replace all occurrences of the smallest value with its sum
    auto diff = arg1 + arg2 + arg3 - smallest;
    std::for_each(it, vec.end(), [&](int& x) { x += diff; });
}
