// Define the connection pool class
class ConnectionPool {
private:
    vector<CURL*> connections;
    mutex connectionsMutex;
    condition_variable connectionsCondVar;
public:
    ConnectionPool() {
        for (int i = 0; i < connectionPoolSize; i++) {
            CURL* curl = curl_easy_init();
            if (curl) {
                connections.push_back(curl);
            }
        }
    }

    ~ConnectionPool() {
        for (CURL* curl : connections) {
            curl_easy_cleanup(curl);
        }
    }

    CURL* getConnection() {
        unique_lock<mutex> lock(connectionsMutex);
        while (connections.empty()) {
            connectionsCondVar.wait(lock);
        }
        return connections.back();
    }

    void releaseConnection(CURL* curl) {
        unique_lock<mutex> lock(connectionsMutex);
        connections.push_back(curl);
        connectionsCondVar.notify_one();
    }
};

// Define the HTTP client class
class HttpClient {
private:
    CURL* curl;
    string url;
    string method;
    string body;
    map<string, string> headers;
public:
    HttpClient(const string& url, const string& method = "GET", const string& body = "", const map<string, string>& headers = {}) {
        this->url = url;
        this->method = method;
        this->body = body;
        this->headers = headers;
    }

    ~HttpClient() {
        curl_easy_cleanup(curl);
    }

    CURL* getCurlHandle() {
        if (!curl) {
            ConnectionPool& pool = *new ConnectionPool();
            curl = pool.getConnection();
        }
        return curl;
    }

    void setUrl(const string& url) {
        this->url = url;
    }

    void setMethod(const string& method) {
        this->method = method;
    }

    void setBody(const string& body) {
        this->body = body;
    }

    void addHeader(const string& key, const string& value) {
        headers[key] = value;
    }

    string getResponse() {
        CURL* curl = getCurlHandle();
        if (!curl) {
            throw runtime_error("Failed to initialize cURL handle");
        }
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
        if (!method.empty()) {
            curl_easy_setopt(curl, CURLOPT_CUSTOMREQUEST, method.c_str());
        }
        if (!body.empty()) {
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, body.c_str());
        }
        for (const auto& header : headers) {
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, header.first.c_str());
        }
        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            throw runtime_error("Failed to perform cURL request: " + string(curl_easy_strerror(res)));
        }
        long httpCode;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &httpCode);
        if (httpCode != 200) {
            throw runtime_error("Received non-OK HTTP status code: " + to_string(httpCode));
        }
        return response;
    }

private:
    string response;

    static size_t writeCallback(void* contents, size_t size, size_t nmemb, void* userp) {
        ((string*)userp)->append((char*)contents, size * nmemb);
        return size * nmemb;
    }
};

