namespace RandomLib {
    class MTGenerator {
    public:
        // Constructor that accepts an optional unsigned seed value
        explicit MTGenerator(unsigned seed = std::chrono::system_clock::now().time_since_epoch().count()) : mt_(seed) {}

        // Generate a random integer between [0, max]
        int generateInt(int max) {
            return std::uniform_int_distribution<>(0, max)(mt_);
        }

        // Generate a random floating-point number between [0.0, 1.0)
        double generateFloat() {
            return std::uniform_real_distribution<>(0.0, 1.0)(mt_);
        }

        // Shuffle a vector of integers in place using the Fisher-Yates algorithm
        void shuffle(std::vector<int>& vec) {
            for (int i = vec.size() - 1; i > 0; --i) {
                std::swap(vec[i], vec[mt_.generateInt(i)]);
            }
        }

    private:
        // Mersenne Twister algorithm implementation
        std::mt19937 mt_;
    };

    // Singleton instance of the MTGenerator class
    static MTGenerator globalGenerator;
}

int main() {
    // Generate a sequence of random numbers and print them to the console
    for (int i = 0; i < 10; ++i) {
        std::cout << RandomLib::globalGenerator.generateInt(10) << " ";
    }
    std::cout << "\n";

    // Shuffle a vector of integers and print the shuffled sequence to the console
    std::vector<int> vec = {1, 2, 3, 4, 5};
    RandomLib::globalGenerator.shuffle(vec);
    for (const auto& i : vec) {
        std::cout << i << " ";
    }
    std::cout << "\n";

    // Dynamically switch between the global generator and a new instance for specific use cases
    RandomLib::MTGenerator localGenerator(12345);
    for (int i = 0; i < 10; ++i) {
        std::cout << localGenerator.generateInt(10) << " ";
    }
    std::cout << "\n";

    return 0;
}
```
