        // Monitor user activity logs and trigger alerts for unusual behavior
        public override async Task<IdentityResult> AccessDeniedAsync(ApplicationUser user)
        {
            var result = await base.AccessDeniedAsync(user);
            if (result.Succeeded)
            {
                // Check for new devices or unexpected geographic locations
                var deviceInfo = await UserManager.GetDeviceInfoAsync(user);
                if (deviceInfo != null && deviceInfo.IsNewDevice())
                {
                    // Send notification for new device detected
