#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <dirent.h>
#include <errno.h>

struct file_info {
    char *filename;
    char *contents;
    char *new_filename;
};

struct file_info process_file(char *filename) {
    struct stat st;
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return NULL;
    }

    if (fstat(fd, &st) == -1) {
        perror("fstat");
        close(fd);
        return NULL;
    }

    char *contents = malloc(st.st_size + 1);
    if (read(fd, contents, st.st_size) == -1) {
        perror("read");
        free(contents);
        close(fd);
        return NULL;
    }
    contents[st.st_size] = '\0';

    char *new_filename = malloc(MAX_FILENAME_LENGTH + 1);
    if (sprintf(new_filename, "%s%d.%s", "prefix", st.st_size, "suffix") > MAX_FILENAME_LENGTH) {
        perror("sprintf");
        free(contents);
        close(fd);
        return NULL;
    }

    struct file_info info = {filename, contents, new_filename};
    return info;
}

struct file_info *process_directory(char *dirname) {
    DIR *dir = opendir(dirname);
    if (dir == NULL) {
        perror("opendir");
        return NULL;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char *filename = entry->d_name;
        struct file_info info = process_file(filename);
        if (info == NULL) {
            perror("process_file");
            closedir(dir);
            return NULL;
        }
    }

    closedir(dir);
    return NULL;
}
