class DataHandler {
  constructor(numBytes) {
    this.buffer = Buffer.allocUnsafe(numBytes);
    this.offset = 0;
  }

  streamChunk(numBytes) {
    const chunkSize = Math.min(this.buffer.length - this.offset, numBytes);
    if (chunkSize > 0) {
      const chunk = this.buffer.slice(this.offset, this.offset + chunkSize);
      this.offset += chunkSize;
      return chunk;
    } else {
      return null;
    }
  }

  static registerStreamProcessor(id, processorFunc) {
    if (!DataHandler.processors[id]) {
      DataHandler.processors[id] = processorFunc;
    }
  }

  static createStreamInstance(id, streamData) {
    const processor = DataHandler.processors[id];
    if (processor) {
      return new DataHandler(streamData).streamChunk();
    } else {
      throw new Error(`No stream processor registered for ID ${id}`);
    }
  }
}
```
