const moduleLoader = {
  // Map of module names to their dependencies
  dependencies: new Map(),

  // Map of module names to their loading statuses
  statuses: new Map(),

  // Queue of modules to load
  queue: [],

  // Function to add a module to the queue and its dependencies
  addModule(moduleName, dependencies) {
    this.queue.push(moduleName);
    this.dependencies.set(moduleName, dependencies);
    this.statuses.set(moduleName, 'pending');
  },

  // Function to load a module and its dependencies
  loadModule(moduleName) {
    const dependencies = this.dependencies.get(moduleName);
    if (dependencies) {
      for (const dependency of dependencies) {
        if (!this.statuses.has(dependency)) {
          // Dependency not loaded yet, add it to the queue
          this.addModule(dependency, []);
        } else if (this.statuses.get(dependency) === 'failed') {
          // Dependency failed to load, skip it
          return;
        }
      }
    }

    // Load module and its dependencies
    const script = document.createElement('script');
    script.src = `https://example.com/${moduleName}.js`;
    script.onload = () => {
      this.statuses.set(moduleName, 'loaded');
      if (this.queue.length > 0) {
        // Load next module in the queue
        const nextModule = this.queue[0];
        this.loadModule(nextModule);
        this.queue.shift();
      }
    };
    script.onerror = () => {
      this.statuses.set(moduleName, 'failed');
      if (this.queue.length > 0) {
        // Load next module in the queue
        const nextModule = this.queue[0];
        this.loadModule(nextModule);
        this.queue.shift();
      }
    };
    document.head.appendChild(script);
  },

  // Function to execute a module and its dependencies
  executeModule(moduleName) {
    const status = this.statuses.get(moduleName);
    if (status === 'loaded') {
