import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class DisjointPairs {
    private static final int MAX_ARRAY_SIZE = 1000000; // 1 million elements
    private static final long TIMEOUT = 5000L; // 5 seconds per invocation

    public static Map<Integer, Integer> process(int[] arr) {
        if (arr.length > MAX_ARRAY_SIZE) {
            throw new IllegalArgumentException("Array size exceeds maximum limit");
        }

        long startTime = System.currentTimeMillis();
        UnionFind uf = new UnionFind(arr);
        Map<Integer, Integer> pairs = new HashMap<>();

        for (int i = 0; i < arr.length - 1; i++) {
            if (uf.find(i) == uf.find(i + 1)) {
                continue;
            }

            int pairCount = pairs.getOrDefault(i, 0) + 1;
            pairs.put(i, pairCount);
            pairs.put(i + 1, pairCount);

            uf.union(i, i + 1);
        }

        long endTime = System.currentTimeMillis();
        long processingTime = endTime - startTime;

        if (processingTime > TIMEOUT) {
            throw new IllegalStateException("Processing time exceeds timeout limit");
        }

        return pairs;
    }
}

class UnionFind {
    private int[] parent;
    private int[] size;

    public UnionFind(int[] arr) {
        parent = new int[arr.length];
        size = new int[arr.length];

        for (int i = 0; i < arr.length; i++) {
            parent[i] = i;
            size[i] = 1;
        }
    }

    public int find(int x) {
        while (x != parent[x]) {
            parent[x] = find(parent[x]);
            x = parent[x];
        }

        return x;
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY) {
            return;
        }

        if (size[rootX] < size[rootY]) {
            parent[rootX] = rootY;
            size[rootY] += size[rootX];
        } else {
            parent[rootY] = rootX;
            size[rootX] += size[rootY];
        }
    }
}
