import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class BackgroundService {
    private static final int MAX_BATCH_SIZE = 100;
    private static final int MIN_THREADS = 2;
    private static final int MAX_THREADS = 5;
    private static final int RETRY_LIMIT = 3;
    private static final long EXPONENTIAL_BACKOFF_BASE = 1000L; // milliseconds
    private static final long EXPONENTIAL_BACKOFF_MAX = 60000L; // seconds

    private ExecutorService executor;
    private RequestQueue requestQueue;
    private MonitoringSystem monitoringSystem;

    public BackgroundService() {
        this.executor = Executors.newFixedThreadPool(MIN_THREADS);
        this.requestQueue = new RequestQueue();
        this.monitoringSystem = new MonitoringSystem();
    }

    public void start() {
        // Start the executor service and request queue
        executor.execute(() -> {
            while (true) {
                try {
                    processRequests();
                } catch (InterruptedException e) {
                    break;
                }
            }
        });
        requestQueue.start();
    }

    public void stop() {
        // Stop the executor service and request queue
        executor.shutdownNow();
        requestQueue.stop();
    }

    public void restart() {
        // Restart the executor service and request queue
        executor = Executors.newFixedThreadPool(MIN_THREADS);
        requestQueue = new RequestQueue();
        monitoringSystem = new MonitoringSystem();
        start();
    }

    private void processRequests() throws InterruptedException {
        // Check for new requests and process them in batches
        while (true) {
            Request[] requests = requestQueue.getNextBatch(MAX_BATCH_SIZE);
            if (requests == null || requests.length == 0) {
                break;
            }

            // Process the requests in parallel using the executor service
            executor.invokeAll(Arrays.asList(requests));
        }
    }

    private class Request implements Callable<Void> {
        private String requestId;
        private String externalSystem;
