            try {
                processRequest(this);
                monitoringSystem.notifyProcessingComplete(requestId, externalSystem);
            } catch (Exception e) {
                monitoringSystem.notifyProcessingFailed(requestId, externalSystem, e);
                throw e;
            }
            return null;
        }
    }

