    }

    private class RequestQueue {
        private Queue<Request> queue = new LinkedList<>();
        private boolean running = true;

        public void start() {
            // Start the request queue thread
            Thread thread = new Thread(() -> {
                while (running) {
                    try {
                        Request request = getNextRequest();
                        if (request != null) {
                            queue.add(request);
                        } else {
                            break;
                        }
                    } catch (InterruptedException e) {
                        break;
                    }
                }
            });
            thread.start();
        }

        public void stop() {
            // Stop the request queue thread
            running = false;
            thread.interrupt();
        }

        private Request getNextRequest() throws InterruptedException {
