class OAuthAuthenticator {
  private $min;
  private $max;
  private $token;
  private $refreshToken;
  private $expiresAt;

  public function __construct(int $min, int $max) {
    $this->min = $min;
    $this->max = $max;
  }

  public function authenticate(): bool {
    // Generate a random number within the specified range.
    $randomNumber = rand($this->min, $this->max);

    // Use the random number to obtain an access token from the OAuth service provider.
    $response = $this->getAccessToken($randomNumber);

    if ($response === null) {
      return false;
    }

    $this->token = $response['access_token'];
    $this->refreshToken = $response['refresh_token'];
    $this->expiresAt = time() + $response['expires_in'];

    return true;
  }

  public function getAccessToken(): string {
    if ($this->token === null) {
      return false;
    }

    return $this->token;
  }

  public function refreshAccessToken(): bool {
    // Use the refresh token to obtain a new access token from the OAuth service provider.
    $response = $this->getAccessToken($this->refreshToken);

    if ($response === null) {
      return false;
    }

    $this->token = $response['access_token'];
    $this->expiresAt = time() + $response['expires_in'];

