    string filename = attack + ext;
    vector<char> buf(filename.begin(), filename.end());
    char* c_str = &buf[0];

    // Address the possibility of concurrent execution, ensuring thread safety and preventing data corruption
    unique_lock<mutex> lck(state->mtx);
    state->cooldowns[attack] = chrono::steady_clock::now();
    cv.wait(lck, [&]() { return state->cv.wait_for(lck, chrono::seconds(1)) == cv_status::timeout; });
