// Define a Union-Find data structure to manage disjoint pairs based on specific attributes of the structures
typedef struct {
    int id;
    int parentId;
    int size;
} UnionFind;

// Function to dynamically allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocateArray(int numStructures) {
    // Check if the allocated memory exceeds available system resources
    if (numStructures > 10000) {
        printf("Error: Allocated memory exceeds available system resources. Exiting...\n");
        return NULL;
    }

    // Dynamically allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        printf("Error: Failed to allocate memory for the array of structures. Exiting...\n");
        return NULL;
    }

    // Initialize each structure with valid data and set the CRCFLAG according to a predefined algorithm
    for (int i = 0; i < numStructures; i++) {
        array[i].rxUeInformationTag = RX_UE_INFORMATION_TAG_CRC_INDICATION;
        array[i].rnti = i + 1;
        array[i].crcIndicationRel8Tag = CRC_INDICATION_REL8_TAG_CRC_INDICATION;
        // Additional fields for error handling
        array[i].timestamp = time(NULL);
        array[i].initialized = true;
    }

    return array;
}

// Function to populate the Union-Find data structure with disjoint pairs based on specific attributes of the structures
void populateUnionFind(NFAPI_CRC_INDICATION_PDU_T* array, int numStructures) {
    // Initialize the Union-Find data structure with the number of structures
    UnionFind* unionFind = (UnionFind*)malloc(numStructures * sizeof(UnionFind));
    for (int i = 0; i < numStructures; i++) {
        unionFind[i].id = i;
        unionFind[i].parentId = i;
        unionFind[i].size = 1;
    }

    // Iterate over each structure and check for disjoint pairs based on specific attributes
    for (int i = 0; i < numStructures; i++) {
        for (int j = i + 1; j < numStructures; j++) {
            if (array[i].rxUeInformationTag == array[j].rxUeInformationTag &&
                array[i].rnti == array[j].rnti &&
                array[i].crcIndicationRel8Tag == array[j].crcIndicationRel8Tag) {
                    // If the structures are disjoint, merge their Union-Find sets
                    int root1 = findRoot(unionFind, i);
                    int root2 = findRoot(unionFind, j);
                    if (root1 != root2) {
                        unionFind[root1].parentId = root2;
                        unionFind[root1].size += unionFind[root2].size;
                    }
            }
        }
    }
}

// Function to find the root of a Union-Find set
int findRoot(UnionFind* unionFind, int id) {
    while (unionFind[id].parentId != id) {
        id = unionFind[id].parentId;
    }
    return id;
}

// Function to calculate the difference between the start and end timestamps for initialization time measurement
double calculateInitTime(time_t start, time_t end) {
    return difftime(end, start);
}

