    char **module_descriptions;
    char **module_versions;
} config_system;

// Function to load configurations from a directory path
config_system *load_configurations(const char *directory_path) {
    // Initialize the configuration system structure
    config_system *config = malloc(sizeof(config_system));
    config->num_modules = 0;
    config->module_names = NULL;
    config->module_descriptions = NULL;
    config->module_versions = NULL;

    // Open the directory and iterate over its contents
    DIR *dir = opendir(directory_path);
    struct dirent *file;
    while ((file = readdir(dir)) != NULL) {
        // Skip non-configuration files
        if (strcmp(file->d_name, ".") == 0 || strcmp(file->d_name, "..") == 0) {
            continue;
        }

        // Load the configuration file and add it to the system
        char *filename = malloc(strlen(directory_path) + strlen(file->d_name) + 2);
        sprintf(filename, "%s/%s", directory_path, file->d_name);
        FILE *config_file = fopen(filename, "r");
        if (config_file == NULL) {
            // Handle missing files gracefully
            continue;
        }

        // Read the configuration file and add it to the system
        char line[1024];
        while (fgets(line, 1024, config_file)) {
            // Skip comments and empty lines
            if (strlen(line) == 0 || line[0] == '#') {
                continue;
            }

            // Parse the configuration file and add it to the system
            char *module_name = strtok(line, " ");
            char *module_description = strtok(NULL, "\n");
            char *module_version = strtok(NULL, "\n");
            if (module_name != NULL && module_description != NULL && module_version != NULL) {
                config->num_modules++;
                config->module_names = realloc(config->module_names, config->num_modules * sizeof(char*));
                config->module_descriptions = realloc(config->module_descriptions, config->num_modules * sizeof(char*));
                config->module_versions = realloc(config->module_versions, config->num_modules * sizeof(char*));
                config->module_names[config->num_modules - 1] = strdup(module_name);
                config->module_descriptions[config->num_modules - 1] = strdup(module_description);
                config->module_versions[config->num_modules - 1] = strdup(module_version);
            }
        }

        // Close the configuration file and free its memory
        fclose(config_file);
        free(filename);
    }

    // Sort the module names, descriptions, and versions alphabetically
