#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>

// Define a structure to store metadata for each page in the TIFF file
typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
    int compression_type;
    int extra_samples;
} PageMetadata;

// Define a structure to store metadata for the entire TIFF file
typedef struct {
    int page_count;
    PageMetadata *page_metadata;
} FileMetadata;

// Function to process a TIFF image file and return comprehensive metadata
FileMetadata process_tiff(const char* filename) {
    // Open the TIFF file for reading
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error: unable to open TIFF file %s\n", filename);
        return NULL;
    }

    // Initialize the metadata for the entire file
    FileMetadata metadata = {0};
    metadata.page_metadata = malloc(sizeof(PageMetadata) * TIFFNumberOfStrips(tif));

    // Iterate over each page in the TIFF file
    for (int i = 0; i < TIFFNumberOfStrips(tif); i++) {
        // Get the metadata for the current page
        PageMetadata page_metadata = {0};
        page_metadata.bits_per_sample = TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &page_metadata.samples_per_pixel);
        page_metadata.compression_type = TIFFGetField(tif, TIFFTAG_COMPRESSION, &page_metadata.extra_samples);

        // Handle unsupported bit depths
        if (page_metadata.bits_per_sample != 1 && page_metadata.bits_per_sample != 2 &&
            page_metadata.bits_per_sample != 4 && page_metadata.bits_per_sample != 8 &&
            page_metadata.bits_per_sample != 16) {
            fprintf(stderr, "Error: unsupported bit depth %d in TIFF file %s\n", page_metadata.bits_per_sample, filename);
            return NULL;
        }

        // Handle multi-page TIFF files
        if (TIFFIsTiled(tif)) {
            fprintf(stderr, "Error: tiled TIFF files not supported in process_tiff()\n");
            return NULL;
        } else {
            metadata.page_count++;
            metadata.page_metadata[i] = page_metadata;
        }
    }

    // Close the TIFF file
    TIFFClose(tif);

    return metadata;
}
```
This code uses the `TIFFOpen()` function from the `libtiff` library to open a TIFF image file for reading. It then iterates over each page in the file using the `TIFFNumberOfStrips()` function, and gets the metadata for each page using the `TIFFGetField()` function. The metadata is stored in a structure called `PageMetadata`, which contains fields for the bits per sample, samples per pixel, compression type, and extra samples.

The code also handles unsupported bit depths by returning an error message to the user. It also handles multi-page TIFF files by aggregating information across all pages and storing it in a structure called `FileMetadata`, which contains fields for the total number of pages and metadata for each page.

Finally, the code closes the TIFF file using the `TIFFClose()` function.']

