using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;

namespace MD5HashManager
{
    public class HashManager
    {
        private readonly object _lock = new object();
        private readonly Dictionary<string, string> _hashes = new Dictionary<string, string>();
        private readonly int _maxMemorySize;
        private readonly int _maxConcurrency;

        public HashManager(int maxMemorySize, int maxConcurrency)
        {
            _maxMemorySize = maxMemorySize;
            _maxConcurrency = maxConcurrency;
        }

        public async Task<string> GenerateHashAsync(string inputString)
        {
            string hash;
            lock (_lock)
            {
                if (_hashes.ContainsKey(inputString))
                {
                    return _hashes[inputString];
                }

                using (var md5 = MD5.Create())
                {
                    byte[] inputBytes = Encoding.UTF8.GetBytes(inputString);
                    byte[] hashBytes = md5.ComputeHash(inputBytes);
                    hash = BitConverter.ToString(hashBytes).Replace("-", "");
                }

                _hashes[inputString] = hash;
            }

            return hash;
        }

        public async Task<string> GetHashAsync(string inputString)
        {
            string hash;
            lock (_lock)
            {
                if (!_hashes.ContainsKey(inputString))
                {
                    throw new ArgumentException("Input string not found in hash table.");
                }

                hash = _hashes[inputString];
            }

            return hash;
        }

        public async Task<bool> CheckDuplicateAsync(string inputString)
        {
            bool isDuplicate;
            lock (_lock)
            {
                isDuplicate = _hashes.ContainsKey(inputString);
            }

            return isDuplicate;
        }

        public async Task<int> GetHashCountAsync()
        {
            int hashCount;
            lock (_lock)
            {
                hashCount = _hashes.Count;
            }

            return hashCount;
        }

        public async Task PruneOldHashesAsync(int maxAgeInDays)
        {
            DateTime cutoffDate = DateTime.UtcNow.AddDays(-maxAgeInDays);
            List<string> oldHashes = new List<string>();

            lock (_lock)
            {
                foreach (var hash in _hashes)
                {
                    if (hash.Value < cutoffDate)
                    {
                        oldHashes.Add(hash.Key);
                    }
                }
            }

            foreach (string oldHash in oldHashes)
            {
                lock (_lock)
                {
                    _hashes.Remove(oldHash);
                }
            }
        }

        public async Task<int> GetMemorySizeAsync()
        {
            int memorySize;
            lock (_lock)
            {
                memorySize = _hashes.Count * 16; // assuming each hash is 16 bytes
            }

            return memorySize;
        }

        public async Task<int> GetConcurrencyAsync()
        {
            int concurrency;
            lock (_lock)
            {
                concurrency = _maxConcurrency;
            }

            return concurrency;
        }
    }
}
```

