using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace BinaryFileLoader
{
    public class FileLoader
    {
        private readonly string[] _fileNames;
        private readonly Dictionary<string, Type> _fileTypes = new Dictionary<string, Type>();
        private readonly object _lockObject = new object();

        public FileLoader(string[] fileNames)
        {
            _fileNames = fileNames;
        }

        public void LoadFiles()
        {
            foreach (var fileName in _fileNames)
            {
                var fileType = GetFileType(fileName);
                if (fileType == null) continue;

                using (var stream = new FileStream(fileName, FileMode.Open))
                {
                    var serializer = new BinaryFormatter();
                    var objects = (List<object>)serializer.Deserialize(stream);

                    lock (_lockObject)
                    {
                        _fileTypes[fileName] = fileType;
                    }

                    foreach (var obj in objects)
                    {
                        var type = obj.GetType();
                        if (!_fileTypes.ContainsKey(type))
                        {
                            lock (_lockObject)
                            {
                                _fileTypes[type] = fileType;
                            }
                        }
                    }
                }
            }
        }

        public void LoadFilesParallel()
        {
            var tasks = new List<Task>();
            foreach (var fileName in _fileNames)
            {
                var task = Task.Run(() =>
                {
                    using (var stream = new FileStream(fileName, FileMode.Open))
                    {
                        var serializer = new BinaryFormatter();
                        var objects = (List<object>)serializer.Deserialize(stream);

                        lock (_lockObject)
                        {
                            _fileTypes[fileName] = GetFileType(fileName);
                        }

                        foreach (var obj in objects)
                        {
                            var type = obj.GetType();
                            if (!_fileTypes.ContainsKey(type))
                            {
                                lock (_lockObject)
                                {
                                    _fileTypes[type] = GetFileType(fileName);
                                }
                            }
                        }
                    }
                });
                tasks.Add(task);
            }
            Task.WaitAll(tasks.ToArray());
        }

        private Type GetFileType(string fileName)
        {
            using (var stream = new FileStream(fileName, FileMode.Open))
            {
                var serializer = new BinaryFormatter();
                var objects = (List<object>)serializer.Deserialize(stream);
                if (objects.Count == 0) return null;

                var type = objects[0].GetType();
                foreach (var obj in objects)
                {
                    if (obj.GetType() != type) return null;
                }
                return type;
            }
        }

        public List<object> GetObjects(string fileName)
        {
            using (var stream = new FileStream(fileName, FileMode.Open))
            {
                var serializer = new BinaryFormatter();
                return (List<object>)serializer.Deserialize(stream);
            }
        }

        public List<object> GetObjectsParallel(string fileName)
        {
            using (var stream = new FileStream(fileName, FileMode.Open))
            {
                var serializer = new BinaryFormatter();
                return (List<object>)serializer.Deserialize(stream);
            }
        }
    }
}
