use std::collections::HashMap;
use std::sync::Arc;
use tokio::stream::StreamExt;
use tokio::task::JoinHandle;
use tokio::time::{Duration, Instant};

struct DataProcessor {
    api_urls: Vec<String>,
    data_pipelines: HashMap<String, String>,
    log_levels: HashMap<String, u8>,
}

impl DataProcessor {
    fn new(api_urls: Vec<String>) -> Self {
        let mut data_pipelines = HashMap::new();
        data_pipelines.insert("default".to_string(), "process_data".to_string());
        data_pipelines.insert("secondary".to_string(), "process_data_secondary".to_string());

        let mut log_levels = HashMap::new();
        log_levels.insert("default".to_string(), 1);
        log_levels.insert("secondary".to_string(), 2);

        Self {
            api_urls,
            data_pipelines,
            log_levels,
        }
    }

    async fn process_data(&self, url: &str) -> Result<String, String> {
        let response = reqwest::get(url).await?;
        let body = response.text().await?;
        Ok(body)
    }

    async fn process_data_secondary(&self, url: &str) -> Result<String, String> {
        let response = reqwest::get(url).await?;
        let body = response.text().await?;
        Ok(body)
    }

    async fn run(&self) -> Result<(), String> {
        let mut tasks: Vec<JoinHandle<Result<String, String>>> = vec![];
        for url in &self.api_urls {
            let task = self.process_data(url);
            tasks.push(task);
        }

        let mut results = vec![];
        while !tasks.is_empty() {
            let (result, remaining) = tokio::join!(tasks);
            if result.is_ok() {
                results.push(result?);
            } else {
                return Err("Error processing data".to_string());
            }
            tasks = remaining;
        }

        Ok(())
    }
}
