['```rust
use std::env;
use std::fs;
use std::path::PathBuf;
use std::sync::Mutex;
use std::thread;

struct DirectoryHierarchy {
    directories: Vec<String>,
}

impl DirectoryHierarchy {
    fn new(directories: Vec<String>) -> Self {
        Self { directories }
    }

    fn create_directories(&self) -> Result<(), String> {
        let mut created_directories = vec![];
        for directory in &self.directories {
            let parent_directory = PathBuf::from(directory).parent().unwrap();
            if !fs::metadata(parent_directory).is_ok() {
                return Err("Parent directory does not exist".to_string());
            }
            let mut lock = DIRECTORY_LOCK.lock().unwrap();
            if created_directories.contains(&directory) {
                continue;
            }
            fs::create_dir(directory).map_err(|e| e.to_string())?;
            env::set_var("DIRECTORY", directory);
            created_directories.push(directory);
        }
        Ok(())
    }
}

lazy_static! {
    static ref DIRECTORY_LOCK: Mutex<()> = Mutex::new(());
}

fn main() -> Result<(), String> {
    let directories = vec![
        "directory1",
        "directory2",
        "directory3/subdirectory1",
        "directory4/subdirectory2",
    ];
    let directory_hierarchy = DirectoryHierarchy::new(directories);
    directory_hierarchy.create_directories()?;
    Ok(())
}
```
