```
// DialogFieldRefreshComponent.js
import { Component, OnInit } from '@angular/core';
import { DialogFieldRefreshService } from './dialog-field-refresh.service';
import { JSONUtility } from './json-utility';

@Component({
  selector: 'app-dialog-field-refresh',
  templateUrl: './dialog-field-refresh.component.html',
  styleUrls: ['./dialog-field-refresh.component.css']
})
export class DialogFieldRefreshComponent implements OnInit {
  resourceId = '';
  fieldsToRefresh = [];
  refreshedFields = {};

  constructor(private dialogFieldRefreshService: DialogFieldRefreshService) {}

  ngOnInit(): void {
    this.dialogFieldRefreshService.refreshFields(this.resourceId).subscribe((data) => {
      if (data) {
        for (const fieldName of this.fieldsToRefresh) {
          const value = data[fieldName];
          if (value) {
            this.updateField(fieldName, value);
          }
        }
      }
    });
  }

  updateField(fieldName: string, value: any): void {
    this.refreshedFields[fieldName] = value;
  }

  refreshFields(): void {
    this.dialogFieldRefreshService.refreshFields(this.resourceId);
  }

  getRefreshedFieldsAsJsonString(): string {
    return JSONUtility.stringify(this.refreshedFields, true);
  }
}
