#include <iostream>
#include <vector>
#include <unordered_map>
#include <memory>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

using namespace std;

struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
};

struct OctreeNode {
    vector<NFAPI_CRC_INDICATION_PDU_T> data;
    unordered_map<uint16_t, shared_ptr<OctreeNode>> children;
};

class Octree {
public:
    Octree(int maxSize) : maxSize_(maxSize), size_(0) {}

    void insert(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        // Check if the RNTI is within a valid range
        if (pdu.RNTI < 1 || pdu.RNTI > 65535) {
            throw invalid_argument("Invalid RNTI value");
        }

        // Create a new node if necessary
        if (!root_) {
            root_ = make_shared<OctreeNode>();
        }

        // Insert the PDU into the octree
        insertRecursive(root_, pdu);
    }

    void insertRecursive(shared_ptr<OctreeNode> node, const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        // Check if the RNTI is within a valid range
        if (pdu.RNTI < 1 || pdu.RNTI > 65535) {
            throw invalid_argument("Invalid RNTI value");
        }

        // Insert the PDU into the current node
        node->data.push_back(pdu);

        // Check if the node is full and needs to be split
        if (node->data.size() > maxSize_) {
            splitNode(node);
        }
    }

    void splitNode(shared_ptr<OctreeNode> node) {
        // Split the current node into four child nodes
        auto child1 = make_shared<OctreeNode>();
        auto child2 = make_shared<OctreeNode>();
        auto child3 = make_shared<OctreeNode>();
        auto child4 = make_shared<OctreeNode>();

        // Insert the PDUs into the child nodes
        for (auto& pdu : node->data) {
            if (pdu.RNTI < 1 || pdu.RNTI > 65535) {
                throw invalid_argument("Invalid RNTI value");
            }

            // Insert the PDU into the child nodes based on its RNTI value
            if (pdu.RNTI <= 2048) {
                child1->data.push_back(pdu);
            } else if (pdu.RNTI <= 4096) {
                child2->data.push_back(pdu);
            } else if (pdu.RNTI <= 6144) {
                child3->data.push_back(pdu);
            } else {
                child4->data.push_back(pdu);
            }
        }

        // Add the child nodes to the current node
        node->children[0] = child1;
        node->children[1] = child2;
        node->children[2] = child3;
        node->children[3] = child4;
    }

    void search(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        // Check if the RNTI is within a valid range
        if (pdu.RNTI < 1 || pdu.RNTI > 65535) {
            throw invalid_argument("Invalid RNTI value");
        }

        // Search for the PDU in the octree
        searchRecursive(root_, pdu);
    }

    void searchRecursive(shared_ptr<OctreeNode> node, const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        // Check if the RNTI is within a valid range
        if (pdu.RNTI < 1 || pdu.RNTI > 65535) {
            throw invalid_argument("Invalid RNTI value");
        }

        // Search for the PDU in the current node
        auto it = find(node->data.begin(), node->data.end(), pdu);
        if (it != node->data.end()) {
            return;
        }

        // Check if the node has child nodes and search them recursively
        for (auto& child : node->children) {
            searchRecursive(child.second, pdu);
        }
    }

    void clear() {
        root_ = nullptr;
        size_ = 0;
    }

