        return NULL;
    }

    // Initialize the list with the specified capacity
    int currentSize = 0;
    for (int i = 0; i < initialCapacity; i++) {
        list[i].RX_UE_INFORMATION_TAG = -1;
        list[i].RNTI = -1;
        list[i].CRC_INDICATION_REL8_TAG = -1;
        list[i].CRCFLAG = false;
    }

