    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Define the function to add an element to the list
    void addElement(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, bool CRCFLAG) {
