        list[currentSize].RNTI = RNTI;
        list[currentSize].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        list[currentSize].CRCFLAG = CRCFLAG;
        currentSize++;

        pthread_mutex_unlock(&mutex);
    }

    // Define the function to remove an element from the list
    void removeElement(int index) {
        pthread_mutex_lock(&mutex);

        // Check if the index is valid
        if (index < 0 || index >= currentSize) {
            printf("Invalid index\n");
            pthread_mutex_unlock(&mutex);
            return;
        }

        // Remove the element from the list
        for (int i = index; i < currentSize - 1; i++) {
            list[i] = list[i + 1];
        }
        currentSize--;

        pthread_mutex_unlock(&mutex);
    }

    // Define the function to get the total number of elements in the list
