// Define a structure to store WiFi scan results
typedef struct {
    char ssid[32];
    int8_t rssi;
    uint16_t channel_bandwidth;
    uint8_t mac_addresses[6];
} wifi_scan_result_t;

// Define a linked list data structure to store WiFi scan results
typedef struct {
    wifi_scan_result_t *data;
    struct node *next;
} wifi_scan_results_list_t;

// Define a function to add a new WiFi scan result to the linked list
void add_wifi_scan_result(wifi_scan_results_list_t *list, char *ssid, int8_t rssi, uint16_t channel_bandwidth, uint8_t mac_addresses[6]) {
    // Allocate memory for the new scan result structure
    wifi_scan_result_t *new_scan_result = malloc(sizeof(wifi_scan_result_t));
    if (new_scan_result == NULL) {
        printf("Error: Out of memory\n");
        return;
    }

    // Copy the scan result data into the new structure
    strcpy(new_scan_result->ssid, ssid);
    new_scan_result->rssi = rssi;
    new_scan_result->channel_bandwidth = channel_bandwidth;
    memcpy(new_scan_result->mac_addresses, mac_addresses, 6);

    // Add the new scan result to the linked list
    wifi_scan_results_list_t *node = malloc(sizeof(wifi_scan_results_list_t));
    if (node == NULL) {
        printf("Error: Out of memory\n");
        free(new_scan_result);
        return;
    }
    node->data = new_scan_result;
    node->next = list->next;
    list->next = node;
}

// Define a function to remove stale WiFi scan results from the linked list
void prune_wifi_scan_results(wifi_scan_results_list_t *list, uint32_t time_threshold) {
    // Iterate through the linked list and remove any scan results that are older than the specified threshold
    wifi_scan_results_list_t *node = list->next;
    while (node != NULL) {
        if ((time(NULL) - node->data->timestamp) > time_threshold) {
            // Remove the stale scan result from the linked list
            wifi_scan_results_list_t *prev_node = node;
            node = node->next;
            free(prev_node);
        } else {
            node = node->next;
        }
    }
}

// Define a function to lookup a WiFi scan result by MAC address
wifi_scan_result_t *lookup_wifi_scan_result(wifi_scan_results_list_t *list, uint8_t mac_addresses[6]) {
    // Iterate through the linked list and search for the specified MAC address
    wifi_scan_results_list_t *node = list->next;
    while (node != NULL) {
        if (memcmp(node->data->mac_addresses, mac_addresses, 6) == 0) {
            return node->data;
        }
        node = node->next;
    }
    return NULL;
}
```
