// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t rnti;
    uint8_t crcflag;
    uint32_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to dynamically create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(uint16_t n) {
    // Check if the input parameter is valid
    if (n == 0) {
        printf("Error: Invalid input parameter. N must be greater than 0.\n");
        return NULL;
    }

    // Dynamically allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (!pdu_list) {
        printf("Error: Failed to allocate memory for the list of structures.\n");
        return NULL;
    }

    // Initialize each structure with a unique RNTI and CRCFLAG
    uint16_t rnti = 0;
    uint8_t crcflag = 0;
    for (uint16_t i = 0; i < n; i++) {
        pdu_list[i].rnti = rnti++;
        pdu_list[i].crcflag = crcflag++;
        pdu_list[i].timestamp = time(NULL);
    }

    // Derive the RX_UE_INFORMATION_TAG from the RNTI and timestamp
    for (uint16_t i = 0; i < n; i++) {
        uint32_t tag = pdu_list[i].rnti << 16 | pdu_list[i].timestamp;
        pdu_list[i].rx_ue_information_tag = tag;
    }

    // Set the CRCFLAG using a pseudo-random number generator seeded with the current time
    srand(time(NULL));
    for (uint16_t i = 0; i < n; i++) {
        pdu_list[i].crcflag = rand() % 256;
    }

    // Implement error handling to manage invalid input parameters and I/O errors during logging
    FILE* log_file = fopen("log.txt", "a");
    if (!log_file) {
        printf("Error: Failed to open the log file.\n");
        free(pdu_list);
        return NULL;
    }
    for (uint16_t i = 0; i < n; i++) {
        fprintf(log_file, "RNTI: %u, CRCFLAG: %u, TIMESTAMP: %lu\n", pdu_list[i].rnti, pdu_list[i].crcflag, pdu_list[i].timestamp);
    }
    fclose(log_file);

    // Optimize memory usage and access times for large N to support high-throughput scenarios
    uint16_t cache_size = 32;
    uint16_t cache_index = 0;
    for (uint16_t i = 0; i < n; i++) {
        if (cache_index == cache_size) {
            // Flush the cache to disk every 32 structures to optimize memory usage and access times
            fflush(log_file);
            cache_index = 0;
        }
        pdu_list[i].rx_ue_information_tag = pdu_list[i].rnti << 16 | pdu_list[i].timestamp;
        cache_index++;
    }

    // Ensure all resources, including file descriptors for logging, are properly managed and closed after use
    fclose(log_file);
    free(pdu_list);

    return pdu_list;
}
