// Define a function to allocate memory from the pool
static void* mem_alloc(size_t size) {
    // Check if there is enough space in the pool for the allocation
    if (mem_pool_used + size > MEM_POOL_SIZE) {
        return NULL;
    }

    // Allocate memory from the pool and update the used counter
    void* mem = &mem_pool[mem_pool_used];
    mem_pool_used += size;

    return mem;
}

// Define a function to free memory in the pool
static void mem_free(void* mem) {
    // Check if the memory is within the pool bounds
    if (mem < &mem_pool[0] || mem > &mem_pool[MEM_POOL_SIZE - 1]) {
        return;
    }

    // Update the used counter and free the memory
    size_t offset = (char*)mem - mem_pool;
    mem_pool_used -= offset;
}

