#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <math.h>

// Define a struct to store the data for each dataset
typedef struct {
    int *data; // Pointer to an array of integers
    size_t count; // Number of elements in the array
} Dataset;

// Function to process a single dataset
void processDataset(const char *input) {
    // Allocate memory for the dataset
    Dataset *dataset = malloc(sizeof(Dataset));
    if (!dataset) {
        fprintf(stderr, "Error: Failed to allocate memory for dataset\n");
        return;
    }

    // Initialize variables to track largest integer and frequency
    int largest = INT_MIN;
    int frequency[1000] = {0};

    // Read the input data from standard input
    while (fgets(input, 1000, stdin)) {
        // Split the input into individual integers
        char *token = strtok(input, " ");
        while (token != NULL) {
            int value = atoi(token);
            if (value > largest) {
                largest = value;
            }
            frequency[value]++;
            token = strtok(NULL, " ");
        }
    }

    // Print the largest integer and its frequency
    printf("Largest integer: %d (Frequency: %d)\n", largest, frequency[largest]);

    // Calculate the average of the dataset
    double sum = 0;
    for (int i = 0; i < dataset->count; i++) {
        sum += dataset->data[i];
    }
    printf("Average: %f\n", sum / dataset->count);

    // Free the memory allocated for the dataset
    free(dataset->data);
    free(dataset);
}

// Function to process multiple datasets in parallel
void processDatasets() {
    // Create a thread pool with 4 threads
    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        // Create a new thread to process the next dataset
        pthread_create(&threads[i], NULL, processDataset, NULL);
    }

    // Wait for all threads to complete
    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }
}

// Main function to manage multiple datasets
int main() {
    // Read the input data from standard input
    char *input = malloc(1000);
    while (fgets(input, 1000, stdin)) {
        // Process each dataset in parallel using a thread pool
        processDatasets();
    }

    // Free the memory allocated for the input data
    free(input);

    return 0;
}
```
