import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

// Structure to represent a pair of integers
class Pair {
    int first;
    int second;

    public Pair(int first, int second) {
        this.first = first;
        this.second = second;
    }
}

// Function to identify and count disjoint pairs within a large integer array using the Union-Find algorithm
void countDisjointPairs(int[] arr, int num_pairs) {
    // Create a concurrent hash map to store the pair counts
    ConcurrentHashMap<Pair, AtomicInteger> pairCounts = new ConcurrentHashMap<>();

    // Iterate over the array and update the pair counts
    for (int i = 0; i < num_pairs; i++) {
        int first = arr[i];
        int second = arr[i + 1];

        Pair pair = new Pair(first, second);
