    free(*data);

    // Set the data pointer to NULL and the number of values to 0
    *data = NULL;
    *numValues = 0;
}

// Define a function to handle file size exceeding limits
void handleFileSizeExceedingLimits(FILE *inputFile, struct InputData **data, int *numValues) {
    // Log an error message to the log file
    fprintf(stderr, "Error: File size exceeds limits\n");

    // Free any allocated memory
    free(*data);

    // Set the data pointer to NULL and the number of values to 0
    *data = NULL;
    *numValues = 0;
}

// Define a function to handle precision issues during calculations
void handlePrecisionIssues(struct InputData *data, int numValues) {
    // Initialize variables
    float sum = 0.0f;
    int count = 0;

    // Calculate the sum of the valid input values
    for (int i = 0; i < numValues; i++) {
        if (data[i].isValid) {
            sum += data[i].value;
            count++;
        }
    }

    // Print the average of the valid input values with precision issues handled
    printf("Average: %f\n", sum / count);
}

// Define a function to log processing times and errors to a separate log file
void logProcessingTimesAndErrors(struct InputData *data, int numValues) {
    // Initialize variables
    clock_t startTime = clock();
    clock_t endTime = clock();
    float elapsedTime = 0.0f;

    // Calculate the elapsed time for processing the input values
    endTime = clock();
    elapsedTime = (float)(endTime - startTime) / CLOCKS_PER_SEC;

    // Log the elapsed time and any errors that occurred during processing to a separate log file
    fprintf(stderr, "Elapsed Time: %f\n", elapsedTime);
}

int main() {
