    struct InputData *data = NULL;
    int numValues = 0;

    // Open the input file stream
    FILE *inputFile = fopen("input.txt", "r");

    // Check if the input file stream is valid
    if (inputFile == NULL) {
        handleFileReadingFailure(inputFile, &data, &numValues);
        return 1;
    }

    // Allocate memory for the input data array
    data = malloc(sizeof(struct InputData) * 10000);

    // Check if memory allocation failed
    if (data == NULL) {
        handleMemoryAllocationFailure(&data, &numValues);
        return 1;
    }

    // Read and validate input values from the file stream
    readInputValues(inputFile, &data, &numValues);

    // Check if there are any valid input values
    if (numValues == 0) {
        printf("No valid numbers\n");
        return 0;
    }

    // Calculate and print the average of the valid input values
    calculateAverage(data, numValues);

    // Log processing times and errors to a separate log file
    logProcessingTimesAndErrors(data, numValues);

    // Free any allocated memory
    free(data);

    return 0;
}
