#include <iostream>
#include <forward_list>
#include <string>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <future>
#include <vector>
#include <algorithm>

using namespace std;

// Forward list of strings
forward_list<string> forwardList;

// Mutex for protecting concurrent access to the forward list
mutex mtx;

// Condition variable for signaling changes to the forward list
condition_variable cv;

// Vector of threads for handling concurrent access to the forward list
vector<thread> threads;

// Function to insert a string after a target string in the forward list
void insertAfterForwardList(const string& target, const string& additional) {
    // Lock the mutex to prevent concurrent access to the forward list
    unique_lock<mutex> lock(mtx);

    // Find the first occurrence of the target string in the forward list
    auto it = find(forwardList.begin(), forwardList.end(), target);

    // If the target string is not found, append the additional string to the end of the list
    if (it == forwardList.end()) {
        forwardList.push_back(additional);
    } else {
        // Insert the additional string immediately after the target string
        forwardList.insert_after(it, additional);
    }

    // Unlock the mutex and signal changes to the forward list
    lock.unlock();
    cv.notify_all();
}

// Function to handle concurrent access to the forward list
void handleConcurrentAccess() {
    while (true) {
        // Wait for a notification from the main thread
        unique_lock<mutex> lock(mtx);
        cv.wait(lock);

        // Handle any changes to the forward list
        if (!forwardList.empty()) {
            // Print the contents of the forward list
            cout << "Forward list: ";
            for (const auto& s : forwardList) {
                cout << s << " ";
            }
            cout << endl;
        }
    }
}

int main() {
    // Create a thread to handle concurrent access to the forward list
    threads.emplace_back(handleConcurrentAccess);

    // Insert strings into the forward list
    insertAfterForwardList("apple", "banana");
    insertAfterForwardList("banana", "cherry");
    insertAfterForwardList("cherry", "date");

    // Wait for the thread to finish
    threads.back().join();

    return 0;
}
```
