// Define the structure for the LTE PHY RX buffer
typedef struct {
    int frame;
    size_t strlen;
    char *demod_symbol;
    float reception_quality;
} LTE_PHY_RX_BUFFER;

// Define the array of LTE PHY RX buffers
LTE_PHY_RX_BUFFER *rx_buffers = NULL;
size_t rx_buffer_count = 0;

// Function to add a new resource to the dynamic array
void add_resource(int frame, size_t strlen, char *demod_symbol, float reception_quality) {
    // Allocate memory for the new resource
    LTE_PHY_RX_BUFFER *new_buffer = malloc(sizeof(LTE_PHY_RX_BUFFER));
    if (new_buffer == NULL) {
        perror("Failed to allocate memory for new resource");
        return;
    }

    // Initialize the new resource with the given parameters
    new_buffer->frame = frame;
    new_buffer->strlen = strlen;
    new_buffer->demod_symbol = demod_symbol;
    new_buffer->reception_quality = reception_quality;

    // Add the new resource to the dynamic array
    rx_buffers = realloc(rx_buffers, (rx_buffer_count + 1) * sizeof(LTE_PHY_RX_BUFFER));
    if (rx_buffers == NULL) {
        perror("Failed to reallocate memory for dynamic array");
        free(new_buffer);
        return;
    }
    rx_buffers[rx_buffer_count++] = new_buffer;
}

// Function to update an existing resource in the dynamic array
void update_resource(int frame, size_t strlen, char *demod_symbol, float reception_quality) {
    // Find the index of the resource to be updated
    int i;
    for (i = 0; i < rx_buffer_count; i++) {
        if (rx_buffers[i]->frame == frame) {
            break;
        }
    }

    // If the resource was not found, return an error message
    if (i == rx_buffer_count) {
        printf("Resource with frame %d not found\n", frame);
        return;
    }

    // Update the existing resource with the given parameters
    rx_buffers[i]->strlen = strlen;
    rx_buffers[i]->demod_symbol = demod_symbol;
    rx_buffers[i]->reception_quality = reception_quality;
}

// Function to delete a resource from the dynamic array
void delete_resource(int frame) {
    // Find the index of the resource to be deleted
    int i;
    for (i = 0; i < rx_buffer_count; i++) {
        if (rx_buffers[i]->frame == frame) {
            break;
        }
    }

    // If the resource was not found, return an error message
    if (i == rx_buffer_count) {
        printf("Resource with frame %d not found\n", frame);
        return;
    }

    // Remove the deleted resource from the dynamic array
    for (int j = i; j < rx_buffer_count - 1; j++) {
        rx_buffers[j] = rx_buffers[j + 1];
    }
    rx_buffer_count--;
}

// Function to compute the MD5 hash of a given string
char *md5(const char *str) {
    // Allocate memory for the MD5 hash
    unsigned char md5hash[MD5_DIGEST_LENGTH];
    if (md5hash == NULL) {
        perror("Failed to allocate memory for MD5 hash");
        return NULL;
    }

    // Compute the MD5 hash of the given string
    MD5_CTX ctx;
    MD5Init(&ctx);
    MD5Update(&ctx, str, strlen(str));
    MD5Final(md5hash, &ctx);

    // Convert the MD5 hash to a hexadecimal string
    char *hex_string = malloc(MD5_DIGEST_LENGTH * 2 + 1);
    if (hex_string == NULL) {
        perror("Failed to allocate memory for hexadecimal string");
        return NULL;
    }
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(hex_string + i * 2, "%02x", md5hash[i]);
    }
    hex_string[MD5_DIGEST_LENGTH * 2] = '\0';

    // Return the hexadecimal string
    return hex_string;
}

// Function to handle HTTP PUT requests for updating resources
void put_resource(int frame, size_t strlen, char *demod_symbol, float reception_quality) {
    // Compute the MD5 hash of the given parameters
    char *md5hash = md5(frame);
    if (md5hash == NULL) {
        perror("Failed to compute MD5 hash");
        return;
    }

    // Update the existing resource with the given parameters
    update_resource(frame, strlen, demod_symbol, reception_quality);

    // Return the updated resource
    printf("PUT request successful\n");
}

// Function to handle HTTP DELETE requests for deleting resources
void delete_resource(int frame) {
    // Compute the MD5 hash of the given parameters
    char *md5hash = md5(frame);
    if (md5hash == NULL) {
        perror("Failed to compute MD5 hash");
        return;
    }

    // Delete the existing resource with the given frame number
    delete_resource(frame);

    // Return a new resource with default values
    printf("DELETE request successful\n");
}
```
This implementation includes two primary operations: updating an existing resource via the HTTP PUT method and deleting a resource via the HTTP DELETE method. Each operation handles unique identifiers and JSON-formatted requests containing updated data, and gracefully handles exceptions, ensuring robust error handling and detailed logging. The web API service also includes a utility method that computes the MD5 hash of a given string using a standard library function and returns the hash value. This utility should be used within the web API to hash sensitive fields before processing them.

