// Configuration file for dynamic settings
#include "config.h"

// Record structure containing a long offset and an int key
typedef struct {
    long offset;
    int key;
} record_t;

// Function to allocate and manage memory for an array of records
void init_records(record_t **records, size_t *num_records) {
    // Load configuration file for initial key value and maximum number of records allowed
    int initial_key = load_config("initial_key", 0);
    int max_records = load_config("max_records", 1000);

    // Allocate memory for the array of records
    *records = (record_t *)malloc(sizeof(record_t) * max_records);
    if (*records == NULL) {
        log_error("Failed to allocate memory for records");
        return;
    }

    // Initialize each record with the initial key value and a unique key
    for (size_t i = 0; i < max_records; i++) {
        (*records)[i].offset = i * 100;
        (*records)[i].key = initial_key++;
        while (find_duplicate(*records, i) != -1) {
            (*records)[i].key++;
        }
    }

    // Sort the records based on their offset values in ascending order
    qsort(*records, max_records, sizeof(record_t), compare_offsets);

    // Update the number of records to the actual number of initialized records
    *num_records = max_records;
}

// Function to find a duplicate key in an array of records
int find_duplicate(const record_t *records, size_t index) {
    for (size_t i = 0; i < index; i++) {
        if ((*records)[i].key == (*records)[index].key) {
            return i;
        }
    }
    return -1;
}

// Function to compare the offset values of two records
int compare_offsets(const void *a, const void *b) {
    record_t *record_a = (record_t *)a;
    record_t *record_b = (record_t *)b;
    if (record_a->offset < record_b->offset) {
        return -1;
    } else if (record_a->offset > record_b->offset) {
        return 1;
    } else {
        return 0;
    }
}
