// Function to read integers from a file and store them in an array
int readIntsFromFile(const char* filename, int** arr, size_t* capacity) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening file");
        return -1;
    }

    // Initialize variables to store the array and its capacity
    *arr = malloc(sizeof(int*) * 10000);
    *capacity = 10000;

    // Read each line from the file and process it as an integer
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Trim any whitespace characters from the end of the line
        char* trimmedLine = strtok(line, " \f\n\r\t\v");

        // Check if the line is empty or contains non-integer values
        int value;
        if (trimmedLine == NULL || sscanf(trimmedLine, "%d", &value) != 1) {
            continue;
        }

        // Add the integer to the array if it's within the maximum capacity
        if (*capacity > 0) {
            (*arr)[(*capacity)--] = value;
        }
    }

    // Close the file and free the memory allocated for the line buffer
    fclose(fp);
    free(line);

    // If the array is empty, print "No integers found"
    if (*capacity == 0) {
        printf("No integers found\n");
        return -1;
    }

    // Find and print the largest integer in the array
    struct IntIndex max = {INT_MIN, 0};
    for (size_t i = 0; i < *capacity; i++) {
        if ((*arr)[i] > max.value) {
            max.value = (*arr)[i];
            max.index = i;
        }
    }
    printf("Largest integer: %d\n", max.value);

    // Free the memory allocated for the array
    free(*arr);

    return 0;
}
