// Define the data structure for each element in the dynamic array
typedef struct {
    long timestamp;
    int packet_length;
    char modulation_type;
    float reception_quality_index;
} protocol_data_t;

// Define the dynamic array type and its functions
typedef struct {
    protocol_data_t* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} dynamic_array_t;

// Initialize a new dynamic array with the given capacity
dynamic_array_t* dynamic_array_init(size_t capacity) {
    dynamic_array_t* arr = malloc(sizeof(dynamic_array_t));
    if (!arr) {
        return NULL;
    }
    arr->data = calloc(capacity, sizeof(protocol_data_t));
    if (!arr->data) {
        free(arr);
        return NULL;
    }
    arr->capacity = capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
    return arr;
}

// Add a new element to the dynamic array
bool dynamic_array_add(dynamic_array_t* arr, protocol_data_t data) {
    if (arr->size == arr->capacity) {
        // Reallocate memory for the array if it's full
        size_t new_capacity = arr->capacity * 2;
        protocol_data_t* new_data = realloc(arr->data, new_capacity * sizeof(protocol_data_t));
        if (!new_data) {
            return false;
        }
        arr->data = new_data;
        arr->capacity = new_capacity;
    }
    pthread_mutex_lock(&arr->mutex);
    arr->data[arr->size++] = data;
    pthread_mutex_unlock(&arr->mutex);
    return true;
}

// Remove an element from the dynamic array by its index
bool dynamic_array_remove(dynamic_array_t* arr, size_t index) {
    if (index >= arr->size) {
        return false;
    }
    pthread_mutex_lock(&arr->mutex);
    for (size_t i = index; i < arr->size - 1; i++) {
        arr->data[i] = arr->data[i + 1];
    }
    arr->size--;
    pthread_mutex_unlock(&arr->mutex);
    return true;
}

// Free the memory allocated for the dynamic array
void dynamic_array_free(dynamic_array_t* arr) {
    free(arr->data);
    pthread_mutex_destroy(&arr->mutex);
    free(arr);
}
