int populate_records(record_t *records, int num_records) {
    // Initialize random seed for generating random numbers
    srand(time(NULL));

    // Populate each record with a random integer and string
    for (int i = 0; i < num_records; i++) {
        records[i].int_value = malloc(sizeof(int));
        if (!records[i].int_value) {
            return -1; // Memory allocation failed
        }
        *records[i].int_value = rand() % 100 + 1; // Generate random integer within range

        records[i].str_value = malloc(STRING_BUFFER_SIZE);
        if (!records[i].str_value) {
            return -2; // Memory allocation failed
        }
        for (int j = 0; j < STRING_BUFFER_SIZE; j++) {
            records[i].str_value[j] = 'a' + rand() % 26; // Generate random alphanumeric string
        }
    }

    return 0; // Successfully populated all records
}

// Function to manage memory for the flexible data structure
void manage_memory(record_t *records, int num_records) {
    // Allocate memory for the records
    records = malloc(num_records * sizeof(record_t));
    if (!records) {
        return; // Memory allocation failed
    }

    // Populate each record with a random integer and string
    populate_records(records, num_records);

    // Concatenate all strings in the buffer for printing
    char *concatenated_strings = malloc(STRING_BUFFER_SIZE);
    if (!concatenated_strings) {
        return; // Memory allocation failed
    }
    concatenated_strings[0] = '\0';
