    printf("Total number of records: %d\n", num_records);
    printf("Range of int values: [1, 100]\n");
    printf("Concatenated list of strings: %s\n", concatenated_strings);

    // Free memory for the records and buffer
    free(concatenated_strings);
    for (int i = 0; i < num_records; i++) {
        free(records[i].str_value);
        free(records[i].int_value);
    }
    free(records);
}

