// Function to initialize an NFAPI_RX_FRAME_PDU_T structure with a valid RRC_MESSAGE_TAG and PDSCH_SYMBOLS structure
NFAPI_RX_FRAME_PDU_T *init_nfapi_rx_frame_pdu(const char *json_file) {
    // Check if the JSON file is already in the cache, if so return it
    json_object *json = NULL;
    if (json_cache != NULL && json_cache->name != NULL && strcmp(json_cache->name, json_file) == 0) {
        json = json_cache;
    } else {
        // Parse the JSON file asynchronously to avoid blocking the main application thread
        json = json_tokener_parse_ex(json_file, strlen(json_file));
        if (json == NULL) {
            fprintf(stderr, "Error parsing JSON file: %s\n", json_file);
            return NULL;
        }
        // Validate the JSON file and handle errors gracefully
        if (!json_object_is_type(json, json_type_object)) {
            fprintf(stderr, "JSON file is not an object: %s\n", json_file);
            return NULL;
