        // Parse the configuration settings from the JSON file and apply them to the PDSCH_SYMBOLS structure
        CONFIG_FILE_FORMAT config = {0};
        if (!json_object_object_get_ex(json, "min_num_symbols", &config.min_num_symbols) ||
            !json_object_object_get_ex(json, "max_num_symbols", &config.max_num_symbols)) {
            fprintf(stderr, "Error parsing configuration settings from JSON file: %s\n", json_file);
            return NULL;
        }
        // Generate a random number of symbols within the specified range
        int num_symbols = config.min_num_symbols + (rand() % (config.max_num_symbols - config.min_num_symbols));
        PDSCH_SYMBOLS *symbols = malloc(sizeof(PDSCH_SYMBOLS));
        if (symbols == NULL) {
            fprintf(stderr, "Error allocating memory for PDSCH_SYMBOLS structure: %s\n", json_file);
            return NULL;
        }
        symbols->num_symbols = num_symbols;
        // Add other fields as needed...
        // Store the JSON file in the cache for future use
        if (json_cache == NULL) {
            json_cache = malloc(sizeof(json_object));
        }
        json_cache->name = strdup(json_file);
        json_cache->json = json;
    }
    // Initialize an NFAPI_RX_FRAME_PDU_T structure with the valid RRC_MESSAGE_TAG and PDSCH_SYMBOLS structure
    NFAPI_RX_FRAME_PDU_T *pdu = malloc(sizeof(NFAPI_RX_FRAME_PDU_T));
    if (pdu == NULL) {
        fprintf(stderr, "Error allocating memory for NFAPI_RX_FRAME_PDU_T structure: %s\n", json_file);
        return NULL;
    }
    pdu->message_tag = RRC_MESSAGE_TAG;
    pdu->symbols = symbols;
    return pdu;
}

// Function to free an NFAPI_RX_FRAME_PDU_T structure and its associated PDSCH_SYMBOLS structure
void free_nfapi_rx_frame_pdu(NFAPI_RX_FRAME_PDU_T *pdu) {
    if (pdu != NULL) {
        // Free the PDSCH_SYMBOLS structure and its associated memory
        free(pdu->symbols);
        pdu->symbols = NULL;
        // Free the NFAPI_RX_FRAME_PDU_T structure and its associated memory
        free(pdu);
        pdu = NULL;
    }
}
