#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>

#define CONFIG_FILE_PATH "/path/to/config/file"
#define MAX_CONFIG_BUNDLES 1024
#define MAX_CONFIG_ITEMS 1024

typedef struct {
    char *id;
    char *content;
} ConfigItem;

typedef struct {
    int num_items;
    ConfigItem items[MAX_CONFIG_ITEMS];
} ConfigBundle;

int load_config(const char *file_path, ConfigBundle **bundles) {
    int fd = open(file_path, O_RDONLY);
    if (fd < 0) {
        perror("open");
        return -1;
    }

    struct stat st;
    if (fstat(fd, &st) < 0) {
        perror("fstat");
        close(fd);
        return -1;
    }

    size_t file_size = st.st_size;
    char *file_data = malloc(file_size + 1);
    if (file_data == NULL) {
        perror("malloc");
        close(fd);
        return -1;
    }

    ssize_t bytes_read = read(fd, file_data, file_size);
    if (bytes_read < 0) {
        perror("read");
        free(file_data);
        close(fd);
        return -1;
    }

    int num_bundles = 0;
    ConfigBundle *bundle = NULL;
    char *line = file_data;
    while (line < file_data + file_size) {
        if (*line == '#') {
            // Skip comments
            line++;
            continue;
        }

        int num_items = 0;
        ConfigItem *item = NULL;
        char *token = strtok(line, " \t\n");
        while (token != NULL) {
            if (num_items >= MAX_CONFIG_ITEMS) {
                fprintf(stderr, "Too many items in config bundle\n");
                free(file_data);
                close(fd);
                return -1;
            }

            item = malloc(sizeof(ConfigItem));
            if (item == NULL) {
                perror("malloc");
                free(file_data);
                close(fd);
                return -1;
            }

            item->id = strdup(token);
            token = strtok(NULL, " \t\n");
            if (token == NULL) {
                fprintf(stderr, "Invalid config bundle format\n");
                free(item);
                free(file_data);
                close(fd);
                return -1;
            }

            item->content = strdup(token);
            token = strtok(NULL, " \t\n");
            if (token != NULL) {
                fprintf(stderr, "Invalid config bundle format\n");
                free(item->id);
                free(item->content);
                free(item);
                free(file_data);
                close(fd);
                return -1;
            }

            if (bundle == NULL) {
                bundle = malloc(sizeof(ConfigBundle));
                if (bundle == NULL) {
                    perror("malloc");
                    free(item->id);
                    free(item->content);
                    free(item);
                    free(file_data);
                    close(fd);
                    return -1;
                }
            }

            bundle->items[num_items++] = *item;
        }

        if (bundle != NULL) {
            bundle->num_items = num_items;
            bundles[num_bundles++] = bundle;
            bundle = NULL;
        }

        line++;
    }

    free(file_data);
    close(fd);
    return num_bundles;
}

int update_element(const char *page_section_id, const char *element_id, const char *content) {
    ConfigBundle **bundles = NULL;
    int num_bundles = load_config(CONFIG_FILE_PATH, &bundles);
    if (num_bundles < 0) {
        return -1;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int ret = 0;
    for (int i = 0; i < num_bundles; i++) {
        ConfigBundle *bundle = bundles[i];
        pthread_mutex_lock(&mutex);
        for (int j = 0; j < bundle->num_items; j++) {
            ConfigItem *item = &bundle->items[j];
            if (strcmp(page_section_id, item->id) == 0 && strcmp(element_id, item->content) == 0) {
                free(item->content);
                item->content = strdup(content);
                ret++;
            }
        }
        pthread_mutex_unlock(&mutex);
    }

    for (int i = 0; i < num_bundles; i++) {
        free(bundles[i]);
    }
    free(bundles);
    return ret;
}
