// Define a struct for the state list
typedef struct StateList {
    int *states;
    int num_states;
    FSA *fsa;
    int last_state;
} StateList;

// Define a function to create a new state list
StateList* create_state_list(int *states, int num_states, FSA *fsa, int last_state) {
    // Validate the input parameters
    if (states == NULL || fsa == NULL || last_state < 0) {
        return NULL;
    }

    // Allocate memory for the new state list
    StateList *new_list = malloc(sizeof(StateList));
    if (new_list == NULL) {
        return NULL;
    }

    // Initialize the new state list
    new_list->states = malloc(num_states * sizeof(int));
    if (new_list->states == NULL) {
        free(new_list);
        return NULL;
    }
    memcpy(new_list->states, states, num_states * sizeof(int));
    new_list->num_states = num_states;
    new_list->fsa = fsa;
    new_list->last_state = last_state;

    // Update the 'next' pointer of the last state in the list
    int *last_state_ptr = &new_list->states[last_state];
    if (*last_state_ptr >= 0) {
        StateList *next_list = create_state_list(fsa, *last_state_ptr);
        if (next_list == NULL) {
            free(new_list->states);
            free(new_list);
            return NULL;
        }
        new_list->next = next_list;
    }

    // Return the newly created state list
    return new_list;
}

// Define a function to update the state list
void update_state_list(StateList *list, int *states, int num_states) {
    // Validate the input parameters
    if (list == NULL || states == NULL || num_states < 0) {
        return;
    }

    // Update the state list
    memcpy(list->states, states, num_states * sizeof(int));
    list->num_states = num_states;
}

// Define a function to delete a state list
void delete_state_list(StateList *list) {
    // Validate the input parameter
    if (list == NULL) {
        return;
    }

    // Delete the state list and its children recursively
    while (list != NULL) {
        StateList *next = list->next;
        free(list->states);
        free(list);
        list = next;
    }
}

// Define a function to clear the current state list
void clear_state_list(StateList *list) {
    // Validate the input parameter
    if (list == NULL) {
        return;
    }

    // Clear the state list and its children recursively
    while (list != NULL) {
        StateList *next = list->next;
        free(list->states);
        list->next = NULL;
        list = next;
    }
}

// Define a function to log state list creation and deletion
void log_state_list(StateList *list, char *action) {
    // Validate the input parameters
    if (list == NULL || action == NULL) {
        return;
    }

    // Log the state list creation or deletion
    printf("[%s] State list created: %p\n", action, list);
}
