// Define the context structure for cryptographic functions
typedef struct {
    EVP_CIPHER_CTX *cipher_ctx;
    EVP_MD_CTX *md_ctx;
} CryptoContext;

// Define the function to initialize and register cryptographic functions
void init_crypto(CryptoContext *ctx) {
    // Initialize the cipher context
    ctx->cipher_ctx = EVP_CIPHER_CTX_new();
    if (ctx->cipher_ctx == NULL) {
        printf("Error: Failed to initialize cipher context\n");
        return;
    }

    // Register the AES and Camellia block ciphers
    EVP_add_cipher(EVP_aes_128_cbc());
    EVP_add_cipher(EVP_camellia_128_cbc());

    // Register the MD5 and SHA digests
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha1());

    // Register the RSA with SHA1 using OpenSSL's EVP functions
    EVP_add_digest_alias("RSA-SHA1", "RSA");

    // Initialize the MD context
    ctx->md_ctx = EVP_MD_CTX_new();
    if (ctx->md_ctx == NULL) {
        printf("Error: Failed to initialize MD context\n");
        return;
    }
}

// Define the function to process a single line of text
void process_line(char *line, CryptoContext *ctx) {
    // Split the line into fields using comma as delimiter
    char **fields = strtok(line, ",");

    // Compute the average of the last two numerical fields
    int num1 = atoi(fields[strlen(fields) - 2]);
    int num2 = atoi(fields[strlen(fields) - 1]);
    int avg = (num1 + num2) / 2;

    // Append the average as the last field in the line
    fields[strlen(fields)] = malloc(sizeof(char) * 5);
    sprintf(fields[strlen(fields)], "%d", avg);

    // Encrypt the line using AES or Camellia block cipher
    if (ctx->cipher_ctx != NULL) {
        EVP_EncryptUpdate(ctx->cipher_ctx, fields[0], strlen(fields[0]));
    }

    // Compute the hash digest using MD5 or SHA1
    if (ctx->md_ctx != NULL) {
        EVP_DigestUpdate(ctx->md_ctx, fields[0], strlen(fields[0]));
    }
}

// Define the function to process multiple large text files concurrently
void process_files(char **files, int num_files, CryptoContext *ctx) {
    // Initialize and register cryptographic functions within the context structure
    init_crypto(ctx);

    // Create a thread pool for processing files concurrently
    pthread_t threads[num_files];
    for (int i = 0; i < num_files; i++) {
        pthread_create(&threads[i], NULL, process_file, &files[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
    }
}

// Define the function to process a single large text file
void process_file(char *file, CryptoContext *ctx) {
    // Open the file for reading
    FILE *fp = fopen(file, "r");
    if (fp == NULL) {
        printf("Error: Failed to open file %s\n", file);
        return;
    }

    // Read each line of the file and process it using the process_line function
    char *line = malloc(sizeof(char) * 1024);
    while (fgets(line, 1024, fp)) {
        process_line(line, ctx);
    }

    // Close the file
