// Function to read and process lines from the text file
void readLines(char *filePath) {
    FILE *fp = fopen(filePath, "r");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filePath);
        return;
    }

    // Read each line from the text file and process it
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Calculate the average of the last two fields in the line
        int numFields = 2;
        char *delimiter = " ";
        char **fields = str_split(line, delimiter);
        if (fields == NULL) {
            printf("Error: unable to split line %s\n", line);
            continue;
        }
        int sum = 0;
        for (int i = 0; i < numFields; i++) {
