            if (field == NULL) {
                printf("Error: unable to get field %d from line %s\n", i, line);
                continue;
            }
            sum += atoi(field);
        }
        int average = sum / numFields;

        // Print the contents of each line in a comma-separated format
        printf("%s, %d\n", line, average);
    }

    // Clean up memory allocated for the line data structure
    free(line);
    free(fields);
}

// Function to split a string into an array of substrings based on a delimiter
char **str_split(char *str, char *delimiter) {
    int numFields = 0;
    char **fields = NULL;
    char *token = strtok(str, delimiter);
    while (token != NULL) {
        fields = realloc(fields, sizeof(char *) * (numFields + 1));
        if (fields == NULL) {
            printf("Error: unable to allocate memory for field %d\n", numFields);
            return NULL;
        }
        fields[numFields++] = token;
        token = strtok(NULL, delimiter);
    }
    return fields;
}

// Function to handle errors and clean up resources
