    RX_UE_INFORMATION_TAG ue_info;
    CRC_INDICATION_REL8_TAG crc_indication;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *items;
    size_t count;
    size_t capacity;
} ResourceBundle;

ResourceBundle* load_resource_bundle_from_file(const char *file_path);

int create_and_populate_nfaapi_crcindication_pdu(int n, const char *file_path) {
    ResourceBundle *bundle = load_resource_bundle_from_file(file_path);
    if (!bundle || bundle->count == 0) {
        fprintf(stderr, "Error loading resource bundle or it's empty.\n");
        free(bundle);
        return -1;
    }

    srand(time(NULL));  // Seed the random number generator

    NFAPI_CRC_INDICATION_PDU_T *bundle_items = bundle->items;
    size_t item_count = bundle->count;
    if (item_count > n) {
        item_count = n;
    }

    for (size_t i = 0; i < item_count; ++i) {
        bundle_items[i].ue_info.rnti = i + 1;  // Example RNTI value
        bundle_items[i].crc_indication.crcflag = (rand() % 2) ? 1 : 0;  // Randomly set CRCFLAG
    }

    size_t allocated_capacity = item_count;
    NFAPI_CRC_INDICATION_PDU_T **new_items = realloc(bundle_items, allocated_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!new_items) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -1;
    }
    bundle_items = new_items;

    // Now, bundle_items contains 'item_count' populated structures
    return item_count;
}

