// Function to parse a TIFF image file and extract detailed metadata
void parseTIFF(const char* filename) {
    // Open the TIFF file for reading
    TIFF *tif = TIFFOpen(filename, "r");
    if (tif == NULL) {
        printf("Error: Unable to open TIFF file %s\n", filename);
        return;
    }

    // Read the image header and get the number of bits per sample
    uint16_t bitsPerSample = 0;
    if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample) == 0) {
        printf("Error: Unable to read bits per sample from TIFF file %s\n", filename);
        return;
    }

    // Read the image header and get the number of samples per pixel
    uint16_t samplesPerPixel = 0;
    if (TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel) == 0) {
        printf("Error: Unable to read samples per pixel from TIFF file %s\n", filename);
        return;
    }

    // Read the image header and get the compression method
    uint16_t compressionMethod = 0;
    if (TIFFGetField(tif, TIFFTAG_COMPRESSION, &compressionMethod) == 0) {
        printf("Error: Unable to read compression method from TIFF file %s\n", filename);
        return;
    }

    // Read the image header and get the resolution metrics
    uint16_t xResolution = 0, yResolution = 0;
    if (TIFFGetField(tif, TIFFTAG_XRESOLUTION, &xResolution) == 0 ||
        TIFFGetField(tif, TIFFTAG_YRESOLUTION, &yResolution) == 0) {
        printf("Error: Unable to read resolution metrics from TIFF file %s\n", filename);
        return;
    }

    // Read the image data and get the number of extra samples
    uint16_t extraSamples = 0;
    if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extraSamples) == 0) {
        printf("Error: Unable to read extra samples from TIFF file %s\n", filename);
        return;
    }

    // Read the image data and get the corresponding information for each extra sample
    uint16_t* extraSampleInfo = (uint16_t*)malloc(extraSamples * sizeof(uint16_t));
    if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extraSamples) == 0) {
        printf("Error: Unable to read extra samples from TIFF file %s\n", filename);
        return;
    }

    // Close the TIFF file
    TIFFClose(tif);
}
```
This function uses the `TIFFOpen` and `TIFFClose` functions from the `tiffio.h` header to open and close the TIFF file, respectively. It then reads the image header using the `TIFFGetField` function to get the number of bits per sample, samples per pixel, compression method, and resolution metrics.

The function also reads the image data using the `TIFFReadScanline` function to get the number of extra samples and their corresponding information. It then uses the `malloc` function to allocate memory for the extra sample information array.

Finally, the function closes the TIFF file using the `TIFFClose` function.

Note that this is just a basic implementation of a TIFF parser, and there are many other features and options that can be added to make it more robust and flexible.']

