#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>
#include <json-c/json.h>

// Define the structure to hold the metadata information
typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int imageWidth;
    int imageHeight;
    char* compressionType;
    char* colorSpace;
} MetadataInfo;

// Define the function to parse the TIFF file and extract metadata information
MetadataInfo parseTIFF(const char* filename) {
    // Initialize the metadata structure
    MetadataInfo info = {0};

    // Open the TIFF file for reading
    TIFF* tif = TIFFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error: unable to open TIFF file %s\n", filename);
        return info;
    }

    // Read the image width and height from the TIFF header
    uint32 imageWidth = 0;
    uint32 imageHeight = 0;
    if (TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &imageWidth) == 0 ||
            TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &imageHeight) == 0) {
        fprintf(stderr, "Error: unable to read image dimensions from TIFF file %s\n", filename);
        TIFFClose(tif);
        return info;
    }

    // Read the bits per sample and samples per pixel from the TIFF header
    uint16 bitsPerSample = 0;
    uint16 samplesPerPixel = 0;
    if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample) == 0 ||
            TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel) == 0) {
        fprintf(stderr, "Error: unable to read bits per sample and samples per pixel from TIFF file %s\n", filename);
        TIFFClose(tif);
        return info;
    }

    // Read the compression type and color space from the TIFF header
    char* compressionType = NULL;
    char* colorSpace = NULL;
    if (TIFFGetField(tif, TIFFTAG_COMPRESSION, &compressionType) == 0 ||
            TIFFGetField(tif, TIFFTAG_PHOTOMETRIC, &colorSpace) == 0) {
        fprintf(stderr, "Error: unable to read compression type and color space from TIFF file %s\n", filename);
        TIFFClose(tif);
        return info;
    }

    // Validate the bits per sample and samples per pixel values
    if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 && bitsPerSample != 8 && bitsPerSample != 16) {
        fprintf(stderr, "Error: unsupported bit depth %d in TIFF file %s\n", bitsPerSample, filename);
        TIFFClose(tif);
        return info;
    }

    // Validate the image dimensions and calculate the total number of pixels
    uint64 totalPixels = (uint64)imageWidth * (uint64)imageHeight;
    if (totalPixels > UINT32_MAX) {
        fprintf(stderr, "Error: image dimensions are too large for 32-bit unsigned integer in TIFF file %s\n", filename);
        TIFFClose(tif);
        return info;
    }

    // Read the extra samples count and information if present
    uint16 extraSamplesCount = 0;
    char* extraSamplesInfo = NULL;
    if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extraSamplesCount, &extraSamplesInfo) == 0) {
        fprintf(stderr, "Error: unable to read extra samples information from TIFF file %s\n", filename);
        TIFFClose(tif);
        return info;
    }

    // Close the TIFF file and return the metadata structure
    TIFFClose(tif);
    info.bitsPerSample = bitsPerSample;
    info.samplesPerPixel = samplesPerPixel;
    info.imageWidth = imageWidth;
    info.imageHeight = imageHeight;
    info.compressionType = compressionType;
    info.colorSpace = colorSpace;
    return info;
}

// Define the function to generate XML output for the metadata information
void generateXMLOutput(const MetadataInfo* info, const char* filename) {
    // Open the XML file for writing
    FILE* xmlFile = fopen("output.xml", "w");
    if (!xmlFile) {
        fprintf(stderr, "Error: unable to open output XML file %s\n", filename);
        return;
    }

    // Write the XML header and metadata information
    fprintf(xmlFile, "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
    fprintf(xmlFile, "<metadata>\n");
    fprintf(xmlFile, "\t<bitsPerSample>%d</bitsPerSample>\n", info->bitsPerSample);
    fprintf(xmlFile, "\t<samplesPerPixel>%d</samplesPerPixel>\n", info->samplesPerPixel);
    fprintf(xmlFile, "\t<imageWidth>%d</imageWidth>\n", info->imageWidth);
    fprintf(xmlFile, "\t<imageHeight>%d</imageHeight>\n", info->imageHeight);
    fprintf(xmlFile, "\t<compressionType>%s</compressionType>\n", info->compressionType);
    fprintf(xmlFile, "\t<colorSpace>%s</colorSpace>\n", info->colorSpace);
    if (info->extraSamplesCount > 0) {
        fprintf(xmlFile, "\t<extraSamplesCount>%d</extraSamplesCount>\n", info->extraSamplesCount);
        for (int i = 0; i < info->extraSamplesCount; i++) {
            fprintf(xmlFile, "\t\t<extraSampleInfo>%s</extraSampleInfo>\n", info->extraSamplesInfo[i]);
        }
    }
    fprintf(xmlFile, "</metadata>\n");

    // Close the XML file
    fclose(xmlFile);
}

// Define the function to generate JSON output for the metadata information
void generateJSONOutput(const MetadataInfo* info, const char* filename) {
    // Open the JSON file for writing
    FILE* jsonFile = fopen("output.json", "w");
    if (!jsonFile) {
        fprintf(stderr, "Error: unable to open output JSON file %s\n", filename);
        return;
    }

    // Write the JSON header and metadata information
    json_object* root = json_object_new_object();
    json_object_object_add(root, "bitsPerSample", json_object_new_int(info->bitsPerSample));
    json_object_object_add(root, "samplesPerPixel", json_object_new_int(info->samplesPerPixel));
    json_object_object_add(root, "imageWidth", json_object_new_int(info->imageWidth));
    json_object_object_add(root, "imageHeight", json_object_new_int(info->imageHeight));
    json_object_object_add(root, "compressionType", json_object_new_string(info->compressionType));
    json_object_object_add(root, "colorSpace", json_object_new_string(info->colorSpace));
    if (info->extraSamplesCount > 0) {
        json_object* extraSamples = json_object_new_array();
        for (int i = 0; i < info->extraSamplesCount; i++) {
            json_object_array_add(extraSamples, json_object_new_string(info->extraSamplesInfo[i]));
        }
        json_object_object_add(root, "extraSamples", extraSamples);
    }
    char* jsonString = json_object_to_json_string(root);
    fprintf(jsonFile, "%s\n", jsonString);

    // Close the JSON file
    fclose(jsonFile);
}

// Define the main function to parse and generate output for the TIFF image metadata
int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    // Parse the TIFF file and extract metadata information
    MetadataInfo info = parseTIFF(argv[1]);

    // Generate XML output for the metadata information
    generateXMLOutput(&info, argv[1]);

    // Generate JSON output for the metadata information
    generateJSONOutput(&info, argv[1]);

    return 0;
}
