NFAPI_CRC_INDICATION_LIST_T *manage_list(NFAPI_CRC_INDICATION_LIST_T *list, size_t count) {
    // Check if the list is NULL and allocate memory for it if necessary
    if (list == NULL) {
        list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
        assert(list != NULL);
        list->count = 0;
        list->list = NULL;
