} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to create and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
int create_and_populate_crc_indication_list(char **hostnames, int num_hostnames, NFAPI_CRC_INDICATION_PDU_T **crc_indication_list) {
    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures to NULL
    *crc_indication_list = NULL;

    // Allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
    *crc_indication_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_hostnames * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*crc_indication_list == NULL) {
        printf("Failed to allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures\n");
        return -1;
    }

