            continue;
        }

        // Iterate over the IP addresses and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
        for (j = 0; res != NULL; j++) {
            struct sockaddr_in *sa = (struct sockaddr_in *)res->ai_addr;
            inet_ntop(AF_INET, &(sa->sin_addr), hostnames[i], INET_ADDRSTRLEN);
            (*crc_indication_list)[j].rx_ue_information_tag = i + 1; // Set the RX_UE_INFORMATION_TAG to the index of the hostname in the list
            (*crc_indication_list)[j].rnti = j + 1; // Set the RNTI to the index of the IP address in the list
            (*crc_indication_list)[j].crc_indication_rel8_tag = rand() % 256; // Set the CRC_INDICATION_REL8_TAG to a random value between 0 and 255
        }
    }

    return 0;
}

// Define the function to free the dynamically allocated memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
void free_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T **crc_indication_list) {
    if (*crc_indication_list != NULL) {
        free(*crc_indication_list);
        *crc_indication_list = NULL;
    }
}
