void crc_indication_list_add(CRC_INDICATION_LIST *list, uint16_t rx_ue_information_tag, uint32_t rnti, bool crcflag) {
    // Allocate memory for the new element
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
