    list->count++;
    list->pdu = realloc(list->pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->count);
    if (!list->pdu) {
        printf("Error: Failed to allocate memory for CRC indication PDU\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    list->pdu[list->count - 1] = *new_pdu;
    pthread_mutex_unlock(&list->mutex);
}

// Function to update an existing element in the list
void crc_indication_list_update(CRC_INDICATION_LIST *list, uint16_t rx_ue_information_tag, uint32_t rnti, bool crcflag) {
    // Find the index of the element to update
    size_t i;
    for (i = 0; i < list->count; i++) {
        if (list->pdu[i].rx_ue_information_tag == rx_ue_information_tag && list->pdu[i].rnti == rnti) {
            break;
        }
    }

    // If the element was not found, return
    if (i == list->count) {
        printf("Error: CRC indication PDU with RX UE information tag %d and RNTI %d not found\n", rx_ue_information_tag, rnti);
        return;
    }

    // Update the element with the given values
    list->pdu[i].crc_indication_rel8_tag = crcflag;
}

// Function to iterate over the elements in the list
void crc_indication_list_iterate(CRC_INDICATION_LIST *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    // Iterate over the elements in the list and call the callback function for each one
    size_t i;
    for (i = 0; i < list->count; i++) {
        callback(&list->pdu[i]);
    }
}

// Function to free the memory allocated by the list
void crc_indication_list_free(CRC_INDICATION_LIST *list) {
    // Free the memory allocated for the PDUs in the list
    pthread_mutex_lock(&list->mutex);
    free(list->pdu);
