void convert_jpegs(const char* config_file) {
    // Load configuration file and parse parameters
    FILE* config = fopen(config_file, "r");
    if (config == NULL) {
        log_error("Failed to open configuration file: %s", strerror(errno));
        return;
    }
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, config)) != -1) {
        // Parse each line of the configuration file
        char* token = strtok(line, " ");
        if (token == NULL) {
            log_error("Failed to parse configuration file: %s", strerror(errno));
            break;
        }
        char* filename = token;
        token = strtok(NULL, " ");
        if (token == NULL) {
            log_error("Failed to parse configuration file: %s", strerror(errno));
            break;
        }
        int compression_level = atoi(token);
        token = strtok(NULL, " ");
        if (token == NULL) {
            log_error("Failed to parse configuration file: %s", strerror(errno));
            break;
        }
        int encryption_setting = atoi(token);
        // Open JPEG file and convert to PDF
        FILE* jpeg = fopen(filename, "rb");
        if (jpeg == NULL) {
            log_error("Failed to open JPEG file: %s", strerror(errno));
            continue;
        }
        struct jpeg_decompress_struct cinfo;
        struct pdf_document* doc = pdf_create_document();
        if (doc == NULL) {
            log_error("Failed to create PDF document: %s", strerror(errno));
            fclose(jpeg);
            continue;
        }
        jpeg_create_decompress(&cinfo);
        jpeg_stdio_src(&cinfo, jpeg);
        if (jpeg_read_header(&cinfo, TRUE) != JPEG_HEADER_OK) {
            log_error("Failed to read JPEG header: %s", strerror(errno));
            fclose(jpeg);
            pdf_destroy_document(doc);
            continue;
        }
        jpeg_start_decompress(&cinfo);
        while (cinfo.output_scanline < cinfo.output_height) {
            JSAMPROW row = (JSAMPROW)malloc(cinfo.output_width * cinfo.output_components);
            if (row == NULL) {
                log_error("Failed to allocate memory for JPEG row: %s", strerror(errno));
                fclose(jpeg);
                pdf_destroy_document(doc);
                break;
            }
            jpeg_read_scanlines(&cinfo, &row, 1);
            pdf_add_page(doc, PDF_PAGE_FORMAT_A4, PDF_ORIENTATION_PORTRAIT);
            pdf_draw_image(doc, row, cinfo.output_width, cinfo.output_components, compression_level, encryption_setting);
            free(row);
        }
        jpeg_finish_decompress(&cinfo);
        fclose(jpeg);
        pdf_save_document(doc, filename, "pdf");
        pdf_destroy_document(doc);
    }
    fclose(config);
}
```
