// Define a structure to represent an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a hash map to store the RNTIs and their corresponding indices in the linked list
typedef struct {
    uint32_t key;
    int index;
} RNTI_HASH_MAP;

// Define a linked list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} LinkedList;

// Function to dynamically build and maintain a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void buildAndMaintainLinkedList(NFAPI_CRC_INDICATION_PDU_T *pdu, int size) {
    // Initialize the hash map
    RNTI_HASH_MAP *hashMap = (RNTI_HASH_MAP *)malloc(sizeof(RNTI_HASH_MAP));
    memset(hashMap, 0, sizeof(RNTI_HASH_MAP));

    // Initialize the linked list
    LinkedList *list = (LinkedList *)malloc(sizeof(LinkedList));
    list->data = NULL;
    list->next = NULL;

    // Iterate through the PDUs and insert them into the linked list
    for (int i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *currentPdu = &pdu[i];

        // Check if the RNTI is already in the hash map
        bool found = false;
        for (int j = 0; j < hashMap->size; j++) {
            if (hashMap->data[j].key == currentPdu->RNTI) {
                found = true;
                break;
            }
        }

        // If the RNTI is not in the hash map, insert it into the linked list and update the hash map
        if (!found) {
            LinkedList *newNode = (LinkedList *)malloc(sizeof(LinkedList));
            newNode->data = currentPdu;
            newNode->next = NULL;

            // Update the hash map
            hashMap->size++;
            hashMap->data[hashMap->size - 1].key = currentPdu->RNTI;
            hashMap->data[hashMap->size - 1].index = list->size;

            // Insert the new node into the linked list
            LinkedList *currentNode = list;
            while (currentNode->next != NULL) {
                currentNode = currentNode->next;
            }
            currentNode->next = newNode;
        }
    }

    // Free the hash map and return the linked list
    free(hashMap);
    return list;
}

// Function to handle potential duplicate RNTIs by maintaining a hash map for quick lookup and efficient insertion
void handleDuplicateRNTIs(NFAPI_CRC_INDICATION_PDU_T *pdu, int size) {
    // Initialize the hash map
    RNTI_HASH_MAP *hashMap = (RNTI_HASH_MAP *)malloc(sizeof(RNTI_HASH_MAP));
    memset(hashMap, 0, sizeof(RNTI_HASH_MAP));

    // Iterate through the PDUs and insert them into the hash map
    for (int i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *currentPdu = &pdu[i];

        // Check if the RNTI is already in the hash map
        bool found = false;
        for (int j = 0; j < hashMap->size; j++) {
            if (hashMap->data[j].key == currentPdu->RNTI) {
                found = true;
                break;
            }
        }

        // If the RNTI is not in the hash map, insert it into the linked list and update the hash map
        if (!found) {
            LinkedList *newNode = (LinkedList *)malloc(sizeof(LinkedList));
