DoubleArray* create_double_array(int size, int capacity) {
    DoubleArray* arr = malloc(sizeof(DoubleArray));
    if (arr == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    arr->size = size;
    arr->capacity = capacity;
    arr->data = malloc(capacity * sizeof(int));
    if (arr->data == NULL) {
        // Handle memory allocation failure
        free(arr);
        return NULL;
    }
    return arr;
}

// Function to dynamically allocate memory for a char string buffer
CharStringBuffer* create_char_string_buffer(int size, int capacity) {
    CharStringBuffer* buf = malloc(sizeof(CharStringBuffer));
    if (buf == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    buf->size = size;
    buf->capacity = capacity;
    buf->data = malloc(capacity * sizeof(char));
    if (buf->data == NULL) {
        // Handle memory allocation failure
        free(buf);
        return NULL;
    }
    return buf;
}

// Function to dynamically resize a linked list
void resize_linked_list(Node** head, int new_size) {
    Node* current = *head;
    while (current != NULL && current->next != NULL) {
        current = current->next;
    }
    if (current == NULL) {
        // Handle empty list
        return;
    }
    int old_size = 0;
    Node* new_head = create_node(current->key);
    while (old_size < new_size && current != NULL) {
        Node* new_node = create_node(current->key);
        new_node->next = new_head;
        new_head = new_node;
        old_size++;
        current = current->next;
    }
    *head = new_head;
}

// Function to dynamically resize a double array
void resize_double_array(DoubleArray** arr, int new_capacity) {
    DoubleArray* new_arr = create_double_array((*arr)->size, new_capacity);
    if (new_arr == NULL) {
        // Handle memory allocation failure
        return;
    }
    for (int i = 0; i < (*arr)->size; i++) {
        new_arr->data[i] = (*arr)->data[i];
    }
    free((*arr)->data);
    (*arr)->data = new_arr->data;
    (*arr)->capacity = new_capacity;
}

// Function to dynamically resize a char string buffer
void resize_char_string_buffer(CharStringBuffer** buf, int new_capacity) {
    CharStringBuffer* new_buf = create_char_string_buffer((*buf)->size, new_capacity);
    if (new_buf == NULL) {
        // Handle memory allocation failure
        return;
    }
    for (int i = 0; i < (*buf)->size; i++) {
        new_buf->data[i] = (*buf)->data[i];
    }
    free((*buf)->data);
    (*buf)->data = new_buf->data;
    (*buf)->capacity = new_capacity;
}

// Function to serialize a linked list to an external file format
void serialize_linked_list(Node* head, FILE* fp) {
    Node* current = head;
    while (current != NULL) {
        fprintf(fp, "%d ", current->key);
        current = current->next;
    }
}

// Function to deserialize a linked list from an external file format
Node* deserialize_linked_list(FILE* fp) {
    Node* head = NULL;
    int key;
    while (fscanf(fp, "%d", &key) == 1) {
        Node* node = create_node(key);
        if (head == NULL) {
            head = node;
        } else {
            Node* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = node;
        }
    }
    return head;
}
