void update_message(int sender_id, time_t timestamp, char* new_payload) {
    // Lock the mutex before modifying the linked list and hash maps
    pthread_mutex_lock(&mutex);

    // Find the node with the specified sender ID and timestamp in the linked list and hash maps
    message_node_t* current = head;
    while (current != NULL) {
        if (current->message->sender_id == sender_id && current->message->timestamp == timestamp) {
            break;
        }
        current = current->next;
    }

    // Update the payload of the message
    if (current != NULL) {
        free(current->message->payload);
        current->message->payload = new_payload;
    }

    // Unlock the mutex after modifying the linked list and hash maps
    pthread_mutex_unlock(&mutex);
}

// Function to delete messages based on their sender ID
void delete_messages(int sender_id) {
    // Lock the mutex before modifying the linked list and hash maps
    pthread_mutex_lock(&mutex);

    // Find the node with the specified sender ID in the linked list and hash maps
    message_node_t* current = head;
    while (current != NULL) {
        if (current->message->sender_id == sender_id) {
            break;
        }
        current = current->next;
