void add_nfapi_message(NFAPI_MESSAGE_T* message) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&nfapi_mutex);

    // Check if there is enough memory allocated for the new entry
    if (nfapi_message_count >= 10000) {
        // Reallocate the array with a larger size
        nfapi_messages = realloc(nfapi_messages, sizeof(NFAPI_MESSAGE_T) * (nfapi_message_count + 1));
