    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&nfapi_mutex);

    // Find the index of the entry to be removed
    size_t i = 0;
    for (; i < nfapi_message_count; i++) {
        if (nfapi_messages[i].rnti == rnti) {
            break;
        }
    }

    // Check if the entry was found
    if (i < nfapi_message_count) {
        // Shift all subsequent entries to fill the gap
        for (size_t j = i; j < nfapi_message_count - 1; j++) {
            memcpy(&nfapi_messages[j], &nfapi_messages[j + 1], sizeof(NFAPI_MESSAGE_T));
        }

        // Decrement the count of messages
        nfapi_message_count--;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&nfapi_mutex);
}

// Function to retrieve all entries that match a specific RNTI
NFAPI_MESSAGE_T* get_nfapi_messages(RNTI rnti) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&nfapi_mutex);

    // Find all entries that match the specified RNTI
    size_t i = 0;
    for (; i < nfapi_message_count; i++) {
        if (nfapi_messages[i].rnti == rnti) {
            break;
        }
    }

    // Check if any entries were found
    if (i < nfapi_message_count) {
        // Create a new array to hold the matching entries
        NFAPI_MESSAGE_T* matching_messages = malloc(sizeof(NFAPI_MESSAGE_T) * (nfapi_message_count - i));

        // Copy the matching entries to the new array
        for (size_t j = 0; j < nfapi_message_count - i; j++) {
            memcpy(&matching_messages[j], &nfapi_messages[i + j], sizeof(NFAPI_MESSAGE_T));
        }

        // Unlock the mutex and return the new array
        pthread_mutex_unlock(&nfapi_mutex);
        return matching_messages;
    } else {
        // No entries were found, so unlock the mutex and return NULL
        pthread_mutex_unlock(&nfapi_mutex);
        return NULL;
    }
}
