#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Structure to represent a network packet header
typedef struct {
    uint16_t protocol; // Protocol type (e.g., IPv4, IPv6)
    uint32_t src_ip;   // Source IP address
    uint32_t dst_ip;   // Destination IP address
    size_t payload_len; // Payload length
} packet_header_t;

// Structure to represent the dynamic array of network packet headers
typedef struct {
    packet_header_t *headers; // Array of packet headers
    size_t capacity;         // Capacity of the array (number of elements)
    size_t count;            // Number of elements in the array
} packet_header_array_t;

// Function to add a new packet header to the dynamic array
void add_packet_header(packet_header_array_t *array, uint16_t protocol, uint32_t src_ip, uint32_t dst_ip, size_t payload_len) {
    // Check if the array is full and needs to be resized
    if (array->count == array->capacity) {
        // Resize the array by 50%
        array->capacity *= 1.5;
        array->headers = realloc(array->headers, array->capacity * sizeof(packet_header_t));
    }

    // Add the new packet header to the end of the array
    array->headers[array->count].protocol = protocol;
    array->headers[array->count].src_ip = src_ip;
    array->headers[array->count].dst_ip = dst_ip;
    array->headers[array->count].payload_len = payload_len;
    array->count++;
}

// Function to update a packet header in the dynamic array
void update_packet_header(packet_header_array_t *array, size_t index, uint16_t protocol, uint32_t src_ip, uint32_t dst_ip, size_t payload_len) {
    // Check if the index is valid
    if (index >= array->count) {
        return;
    }

    // Update the packet header at the specified index
    array->headers[index].protocol = protocol;
    array->headers[index].src_ip = src_ip;
    array->headers[index].dst_ip = dst_ip;
    array->headers[index].payload_len = payload_len;
}

// Function to iterate over the packet headers in the dynamic array
void iterate_packet_headers(packet_header_array_t *array, void (*callback)(packet_header_t *)) {
    // Iterate over each packet header and call the callback function
    for (size_t i = 0; i < array->count; i++) {
        callback(&array->headers[i]);
    }
}

// Function to checksum validate a packet header in the dynamic array
void checksum_validate(packet_header_array_t *array, size_t index) {
    // Check if the index is valid
    if (index >= array->count) {
        return;
    }

    // Calculate the checksum of the packet header at the specified index
    uint32_t checksum = 0;
    for (size_t i = 0; i < sizeof(packet_header_t); i++) {
        checksum += ((uint8_t *)&array->headers[index])[i];
    }

    // Print the checksum result
    printf("Checksum: %u\n", checksum);
}

// Function to compress a packet header in the dynamic array
void compress(packet_header_array_t *array, size_t index) {
    // Check if the index is valid
    if (index >= array->count) {
        return;
    }

    // Compress the packet header at the specified index
    uint32_t src_ip = array->headers[index].src_ip;
    uint32_t dst_ip = array->headers[index].dst_ip;
    size_t payload_len = array->headers[index].payload_len;

    // Calculate the compressed packet header
    packet_header_t compressed_header;
    compressed_header.protocol = array->headers[index].protocol;
    compressed_header.src_ip = src_ip >> 16;
