    size_t capacity;          // Capacity of the array (in number of elements)
    size_t count;             // Number of elements in the array
} packet_array_t;

// Initialize a new dynamic array for storing packet headers
packet_array_t* init_packet_array(size_t capacity) {
    packet_array_t* arr = malloc(sizeof(packet_array_t));
    if (!arr) {
        return NULL;
    }
    arr->headers = malloc(capacity * sizeof(packet_header_t));
    if (!arr->headers) {
        free(arr);
        return NULL;
    }
    arr->capacity = capacity;
    arr->count = 0;
    return arr;
}

// Add a new packet header to the dynamic array
bool add_packet_header(packet_array_t* arr, uint16_t protocol, uint32_t src_ip, uint32_t dst_ip, uint16_t payload_len, const uint8_t* metadata) {
    if (arr->count >= arr->capacity) {
        // Array is full, cannot add more headers
        return false;
    }
    packet_header_t* header = &(arr->headers[arr->count]);
    header->protocol = protocol;
    header->src_ip = src_ip;
    header->dst_ip = dst_ip;
    header->payload_len = payload_len;
    memcpy(header->metadata, metadata, sizeof(uint8_t) * 10); // Assuming metadata is 10 bytes long
    arr->count++;
    return true;
}

// Update a packet header in the dynamic array
bool update_packet_header(packet_array_t* arr, size_t index, uint16_t protocol, uint32_t src_ip, uint32_t dst_ip, uint16_t payload_len, const uint8_t* metadata) {
    if (index >= arr->count) {
        // Index is out of bounds, cannot update header
        return false;
    }
    packet_header_t* header = &(arr->headers[index]);
    header->protocol = protocol;
    header->src_ip = src_ip;
    header->dst_ip = dst_ip;
    header->payload_len = payload_len;
    memcpy(header->metadata, metadata, sizeof(uint8_t) * 10); // Assuming metadata is 10 bytes long
    return true;
}

// Iterate over all packet headers in the dynamic array
void iterate_packet_headers(packet_array_t* arr, void (*callback)(const packet_header_t*)) {
    for (size_t i = 0; i < arr->count; i++) {
        callback(&(arr->headers[i]));
    }
}

// Checksum validation function
bool validate_checksum(packet_array_t* arr, size_t index) {
    if (index >= arr->count) {
        // Index is out of bounds, cannot validate checksum
        return false;
    }
    packet_header_t* header = &(arr->headers[index]);
    uint16_t checksum = calculate_checksum(header);
    if (checksum != header->checksum) {
        // Checksum does not match, packet is invalid
        return false;
    }
    return true;
}

// Header compression function
bool compress_headers(packet_array_t* arr, size_t index) {
    if (index >= arr->count) {
        // Index is out of bounds, cannot compress headers
        return false;
    }
    packet_header_t* header = &(arr->headers[index]);
    uint16_t protocol = header->protocol;
    uint32_t src_ip = header->src_ip;
    uint32_t dst_ip = header->dst_ip;
    uint16_t payload_len = header->payload_len;
    memcpy(header->metadata, &protocol, sizeof(uint16_t));
    memcpy(header->metadata + sizeof(uint16_t), &src_ip, sizeof(uint32_t));
    memcpy(header->metadata + sizeof(uint16_t) + sizeof(uint32_t), &dst_ip, sizeof(uint32_t));
    memcpy(header->metadata + sizeof(uint16_t) + sizeof(uint32_t) + sizeof(uint32_t), &payload_len, sizeof(uint16_t));
    return true;
}

// Advanced filtering function based on user-defined criteria
bool filter_headers(packet_array_t* arr, size_t index, uint16_t protocol, uint32_t src_ip, uint32_t dst_ip) {
    if (index >= arr->count) {
        // Index is out of bounds, cannot filter headers
        return false;
    }
    packet_header_t* header = &(arr->headers[index]);
    if (protocol != 0 && protocol != header->protocol) {
        // Protocol does not match, skip this header
        return false;
    }
    if (src_ip != 0 && src_ip != header->src_ip) {
        // Source IP does not match, skip this header
        return false;
    }
    if (dst_ip != 0 && dst_ip != header->dst_ip) {
        // Destination IP does not match, skip this header
        return false;
    }
    return true;
}
