        // If there are no consecutive duplicate CRCFLAG occurrences, add the new element to the end of the list
        if (!consecutiveDuplicates) {
            list->data[list->size] = *newElement;
            list->size++;
        } else {
            // If there are consecutive duplicate CRCFLAG occurrences, limit them to no more than three instances
            size_t duplicateCount = 0;
            for (size_t i = 0; i < list->size; i++) {
                if (list->data[i].rnti == rnti && list->data[i].crcFlag == crcFlag) {
                    duplicateCount++;
                    if (duplicateCount > 3) {
                        break;
                    }
                }
            }
            // If the number of consecutive duplicate CRCFLAG occurrences is less than or equal to three, add the new element to the end of the list
            if (duplicateCount <= 3) {
                list->data[list->size] = *newElement;
                list->size++;
            }
        }
    }
