    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
} NFAPI_CRC_INDICATION_LIST;

// Define the function to dynamically populate the linked list
void populateNfapiCrcIndicationList(NFAPI_CRC_INDICATION_LIST *list, int numNodes) {
    // Initialize the list head and tail pointers
    list->head = NULL;
    list->tail = NULL;

    // Generate a random boolean value for the CRCFLAG of each node
    bool crcFlag = false;
    srand(time(NULL));
    crcFlag = rand() % 2 == 0 ? true : false;

    // Iterate over the number of nodes to be added to the list
    for (int i = 0; i < numNodes; i++) {
        // Allocate memory for the new node
        NFAPI_CRC_INDICATION_PDU_T *newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Initialize the RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG of the new node
        newNode->rxUeInformationTag = rand() % 100;
        newNode->crcIndicationRel8Tag.crcFlag = crcFlag;

        // Generate a random RNTI value for the new node
        newNode->rnti = rand() % 10000;

        // Add the new node to the list
        if (list->head == NULL) {
            list->head = newNode;
            list->tail = newNode;
        } else {
            list->tail->next = newNode;
            list->tail = newNode;
        }
    }
}

// Define the function to traverse the linked list and print the RNTI values
void traverseNfapiCrcIndicationList(NFAPI_CRC_INDICATION_LIST *list) {
    // Initialize a temporary pointer to the head of the list
    NFAPI_CRC_INDICATION_PDU_T *currentNode = list->head;

    // Iterate over the list until the end is reached
    while (currentNode != NULL) {
        printf("RNTI: %d\n", currentNode->rnti);
        currentNode = currentNode->next;
    }
}

// Define the function to track the total number of unique RNTI values used across all nodes in the list
void countUniqueRntis(NFAPI_CRC_INDICATION_LIST *list) {
    // Initialize a hash table to store the unique RNTIs
    int *rntiCount = calloc(10000, sizeof(int));

    // Iterate over the list and increment the count for each unique RNTI
    NFAPI_CRC_INDICATION_PDU_T *currentNode = list->head;
    while (currentNode != NULL) {
        int rnti = currentNode->rnti;
        if (rntiCount[rnti] == 0) {
            rntiCount[rnti]++;
        }
        currentNode = currentNode->next;
    }

    // Print the total number of unique RNTIs
    printf("Total number of unique RNTIs: %d\n", countUniqueRntis(list));
}
