    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} LinkedList;

// Function to dynamically manage a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void manageLinkedList(LinkedList **list) {
    // Check if the list is empty
    if (*list == NULL) {
        return;
    }

    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&(*list)->mutex);

    // Generate a random boolean value for the CRCFLAG
    bool crcflag = (rand() % 2) == 0;

    // Create a new node with the generated CRCFLAG
    NFAPI_CRC_INDICATION_PDU_T *newNode = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newNode->crc_indication_rel8.CRCFlag = crcflag;

    // Check if the list is not empty and the last node has a different RNTI value
    if (*list != NULL && (*list)->data->rnti != newNode->rnti) {
        // Update the 'next' pointer of the last node to point to the newly created node
        (*list)->data->next = newNode;
    } else {
        // If the list is empty or the last node has the same RNTI value, create a new node and add it to the list
        LinkedList *newList = malloc(sizeof(LinkedList));
        newList->data = newNode;
        newList->next = NULL;
        (*list) = newList;
    }

    // Increment the count of unique RNTI values used in the list
    if (crcflag) {
        (*list)->count++;
    }

    // Unlock the list to allow concurrent access
    pthread_mutex_unlock(&(*list)->mutex);
