The Java component using the Union-Find algorithm to identify and count disjoint pairs within a large integer array:
```java
import java.util.ArrayList;
import java.util.List;

public class UnionFind {
    private List<Integer> elements;

    public UnionFind(int[] arr) {
        this.elements = new ArrayList<>();
        for (int i : arr) {
            this.elements.add(i);
        }
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX == rootY) {
            return;
        }
        elements.get(rootX).addAll(elements.get(rootY));
        elements.remove(rootY);
    }

    public void count() {
        int count = 0;
        for (int i : elements) {
            if (i == null) {
                continue;
            }
            count++;
        }
        System.out.println("Number of disjoint pairs: " + count);
    }

    private int find(int x) {
        while (elements.get(x) != null && elements.get(x) != x) {
            x = elements.get(x);
        }
        return x;
    }
}
