#include <time.h>

// Define the structure for a data packet
typedef struct {
    int id;
    time_t timestamp;
    size_t payload_length;
} DataPacket;

// Define the maximum number of packets to store in the array
#define MAX_PACKETS 10000

// Define a mutex for thread-safe access to the array
pthread_mutex_t packet_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define an array of data packets
DataPacket *packets[MAX_PACKETS];

// Function to add a new packet to the array
void add_packet(int id, time_t timestamp, size_t payload_length) {
    // Acquire the mutex for thread-safe access to the array
    pthread_mutex_lock(&packet_mutex);

    // Check if the maximum number of packets has been reached
    if (num_packets >= MAX_PACKETS) {
        // If so, remove the oldest packet from the array
        DataPacket *oldest_packet = packets[0];
        for (int i = 1; i < num_packets; i++) {
            packets[i - 1] = packets[i];
        }
        free(oldest_packet);
        num_packets--;
    }

    // Allocate memory for the new packet
    DataPacket *new_packet = malloc(sizeof(DataPacket));
    if (new_packet == NULL) {
        // If allocation fails, log an error and return
        printf("Error: Failed to allocate memory for new packet\n");
        pthread_mutex_unlock(&packet_mutex);
        return;
    }

    // Initialize the new packet with the given values
    new_packet->id = id;
    new_packet->timestamp = timestamp;
    new_packet->payload_length = payload_length;

    // Add the new packet to the end of the array
    packets[num_packets++] = new_packet;

    // Release the mutex for thread-safe access to the array
    pthread_mutex_unlock(&packet_mutex);
}

// Function to remove a packet from the array by its ID
void remove_packet(int id) {
    // Acquire the mutex for thread-safe access to the array
    pthread_mutex_lock(&packet_mutex);

    // Find the index of the packet with the given ID in the array
    int i;
    for (i = 0; i < num_packets; i++) {
        if (packets[i]->id == id) {
            break;
        }
    }

    // If the packet was found, remove it from the array and free its memory
    if (i < num_packets) {
        DataPacket *removed_packet = packets[i];
        for (int j = i; j < num_packets - 1; j++) {
            packets[j] = packets[j + 1];
        }
        free(removed_packet);
        num_packets--;
    }

    // Release the mutex for thread-safe access to the array
    pthread_mutex_unlock(&packet_mutex);
}
