typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list structure to hold the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct node *next;
} LIST_NODE;

// Define the function to dynamically generate and manage a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void generate_crc_indication_pdu(int num_structures, int seed, CRYPTO_MODE mode) {
    // Initialize the linked list head pointer to NULL
    LIST_NODE *head = NULL;

    // Loop through each structure and populate it with the desired data
    for (int i = 0; i < num_structures; i++) {
        // Allocate memory for the current structure
        NFAPI_CRC_INDICATION_PDU_T *current = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Set the RX_UE_INFORMATION_TAG field to a random value
        current->rx_ue_information_tag = rand() % 10;

        // Set the RNTI field to a random value
        current->rnti = rand() % 10000;

        // Set the CRC_INDICATION_REL8_TAG field to a random value
        current->crc_indication_rel8_tag = rand() % 10000;

        // Add the current structure to the linked list
        if (head == NULL) {
            head = malloc(sizeof(LIST_NODE));
            head->data = current;
            head->next = NULL;
        } else {
            LIST_NODE *temp = head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = malloc(sizeof(LIST_NODE));
            temp->next->data = current;
            temp->next->next = NULL;
        }
    }

    // Return the linked list head pointer
    return head;
}
