#include <string.h>
#include <time.h>

// Define the structure for the log file line
typedef struct {
    char* content;
} LOG_LINE_T;

// Define the function to read a line from the log file
LOG_LINE_T* read_log_line(FILE* fp) {
    // Allocate memory for the line content
    LOG_LINE_T* line = (LOG_LINE_T*)malloc(sizeof(LOG_LINE_T));

    // Read a line from the log file
    char* line_content = fgets(line->content, 1024, fp);

    return line;
}

// Define the function to calculate the average of the last two numeric fields in a line
double calculate_average(LOG_LINE_T* line) {
    // Extract the last two numeric fields from the line content
    char* field1 = strtok(line->content, ",");
    char* field2 = strtok(NULL, ",");

    // Convert the fields to integers
    int num1 = atoi(field1);
    int num2 = atoi(field2);

    // Calculate the average of the two numbers
    double average = (num1 + num2) / 2.0;

    return average;
}

// Define the function to print a line in a comma-separated format
void print_log_line(LOG_LINE_T* line, FILE* fp) {
    // Print the contents of the line to the console
    printf("%s\n", line->content);
}

// Define the main function for the hybrid program
int main() {
    // Open the log file for reading
    FILE* fp = fopen("log_file.txt", "r");

    // Read a line from the log file and calculate its average
    LOG_LINE_T* line = read_log_line(fp);
    double average = calculate_average(line);

    // Print the contents of the line in a comma-separated format
    print_log_line(line, stdout);

    // Free the memory allocated for the line content
    free(line->content);
    free(line);

    return 0;
}
