// Structure to represent a database record
typedef struct {
    long offset;
    int key;
    CRC_INDICATION_REL8_TAG crc;
} databaseRecord;

// Global variable to store the array of records
databaseRecord* records = NULL;

// Global variable to store the number of records in the array
int numRecords = 0;

// Global variable to store the maximum number of records allowed
int maxNumRecords = 1000;

// Function to initialize the database records
void initializeDatabaseRecords(int initialKey, int maxNumRecords) {
    // Allocate memory for the array of records
    records = (databaseRecord*) malloc(maxNumRecords * sizeof(databaseRecord));
    if (records == NULL) {
        LOG_ERROR("Failed to allocate memory for database records");
        return;
    }

    // Initialize the number of records in the array
    numRecords = 0;

    // Set the initial key value and maximum number of records allowed
    initialKey = 1;
    maxNumRecords = 1000;

    // Create a mutex to protect concurrent access to the array of records
    pthread_mutex_t* mutex = (pthread_mutex_t*) malloc(sizeof(pthread_mutex_t));
    if (mutex == NULL) {
        LOG_ERROR("Failed to allocate memory for mutex");
        return;
    }
    pthread_mutex_init(mutex, NULL);

    // Iterate over the array of records and initialize each record
    for (int i = 0; i < maxNumRecords; i++) {
        databaseRecord* record = &records[i];
        record->offset = i * sizeof(databaseRecord);
        record->key = initialKey++;
        record->crc = CRC_INDICATION_REL8_TAG();
    }

    // Sort the array of records based on their offset values in ascending order
    qsort(records, numRecords, sizeof(databaseRecord), compareOffsets);

    // Release the mutex to allow other threads to access the array of records
    pthread_mutex_unlock(mutex);
}

// Function to add a new record to the database
void addNewRecord(long offset, int key, CRC_INDICATION_REL8_TAG crc) {
    // Acquire the mutex to protect concurrent access to the array of records
    pthread_mutex_lock(mutex);

    // Check if the maximum number of records has been reached
    if (numRecords == maxNumRecords) {
        LOG_WARNING("Maximum number of records has been reached");
        return;
    }

    // Increment the key value if a duplicate is detected
    while (keyExists(key)) {
        key++;
    }

    // Add the new record to the array of records
    databaseRecord* record = &records[numRecords++];
    record->offset = offset;
    record->key = key;
    record->crc = crc;

    // Sort the array of records based on their offset values in ascending order
    qsort(records, numRecords, sizeof(databaseRecord), compareOffsets);

    // Release the mutex to allow other threads to access the array of records
    pthread_mutex_unlock(mutex);
}

// Function to check if a key exists in the database
bool keyExists(int key) {
    // Acquire the mutex to protect concurrent access to the array of records
    pthread_mutex_lock(mutex);

    // Iterate over the array of records and check if the key exists
    for (int i = 0; i < numRecords; i++) {
        databaseRecord* record = &records[i];
        if (record->key == key) {
            pthread_mutex_unlock(mutex);
            return true;
        }
    }

    // Release the mutex to allow other threads to access the array of records
    pthread_mutex_unlock(mutex);

    return false;
}

// Function to compare two offset values in ascending order
int compareOffsets(const void* a, const void* b) {
    databaseRecord* recordA = (databaseRecord*) a;
    databaseRecord* recordB = (databaseRecord*) b;
    if (recordA->offset < recordB->offset) {
        return -1;
    } else if (recordA->offset > recordB->offset) {
        return 1;
    } else {
        return 0;
    }
}
```
