#define ERROR_CURL -3

// Function to generate NFAPI CRC indications
int generateNFAPICRCIndications(int n, struct SESSION *session) {
    // Initialize the connection pool and session-like structure
    struct CONNECTION_POOL *connection_pool = (struct CONNECTION_POOL *)malloc(sizeof(struct CONNECTION_POOL) * CONNECTION_POOL_SIZE);
    for (int i = 0; i < CONNECTION_POOL_SIZE; i++) {
        connection_pool[i].curl = NULL;
        connection_pool[i].access_token = NULL;
        connection_pool[i].is_active = false;
    }
    session->connection_pool = connection_pool;

    // Initialize the NFAPI CRC indication structure
    struct NFAPI_CRC_INDICATION_PDU_T *crc_indications = (struct NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T) * n);
    for (int i = 0; i < n; i++) {
        crc_indications[i].RX_UE_INFORMATION_TAG = 0;
        crc_indications[i].RNTI = 0;
        crc_indications[i].CRCFLAG = false;
    }

