        crc_indications[i].RNTI = rand() % 1000000000;
        crc_indications[i].CRCFLAG = (rand() % 2) == 0 ? true : false;
    }

    // Clean up the connection pool and session-like structure
    for (int i = 0; i < CONNECTION_POOL_SIZE; i++) {
        if (connection_pool[i].curl != NULL) {
            curl_easy_cleanup(connection_pool[i].curl);
        }
        free(connection_pool[i].access_token);
    }
    free(connection_pool);
    session->connection_pool = NULL;

    return ERROR_NONE;
