    time_t timestamp;
    char* metric_name;
    double value;
    int source_id;
} METRIC_RECORD_T;

// Define a list of metric records
METRIC_RECORD_T* metrics = NULL;

// Define the function to initialize the dynamic metric collector
void initializeDynamicMetricCollector() {
    // Initialize the list of metric records
    metrics = (METRIC_RECORD_T*) malloc(sizeof(METRIC_RECORD_T) * 10);
    if (!metrics) {
        printf("Error: Failed to allocate memory for metric records\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the list of metric records with random unique identifiers
    srand(time(NULL));
    for (int i = 0; i < 10; i++) {
        metrics[i].timestamp = time(NULL);
        metrics[i].metric_name = "Metric Name";
        metrics[i].value = rand() % 100;
        metrics[i].source_id = rand();
    }
}

// Define the function to add a new metric record
void addNewMetricRecord(METRIC_RECORD_T* record) {
    // Check if the list of metric records is full
    if (metrics == NULL || metrics->size >= 10) {
        printf("Error: The list of metric records is full\n");
        return;
    }

    // Add the new metric record to the list
    metrics[metrics->size++] = *record;
}

// Define the function to retrieve a metric record by its unique identifier
METRIC_RECORD_T* getMetricRecordById(int id) {
    // Check if the list of metric records is empty
    if (metrics == NULL || metrics->size <= 0) {
        printf("Error: The list of metric records is empty\n");
        return NULL;
    }

    // Iterate through the list of metric records and find the record with the matching unique identifier
    for (int i = 0; i < metrics->size; i++) {
        if (metrics[i].source_id == id) {
            return &metrics[i];
        }
    }

    // Return NULL if no record is found with the matching unique identifier
    return NULL;
}

// Define the function to retrieve all metric records for a given source
METRIC_RECORD_T* getMetricRecordsBySource(int source) {
    // Check if the list of metric records is empty
    if (metrics == NULL || metrics->size <= 0) {
        printf("Error: The list of metric records is empty\n");
        return NULL;
    }

    // Initialize an array to store the matching metric records
    METRIC_RECORD_T* records = (METRIC_RECORD_T*) malloc(sizeof(METRIC_RECORD_T) * 10);
    if (!records) {
        printf("Error: Failed to allocate memory for metric records\n");
        return NULL;
    }

    // Iterate through the list of metric records and find all records with the matching source identifier
    int count = 0;
    for (int i = 0; i < metrics->size; i++) {
        if (metrics[i].source_id == source) {
            records[count++] = metrics[i];
        }
    }

    // Return the array of matching metric records
    return records;
}

