    // Iterate through the list of metric records and find all records with timestamps within the given time range
    int count = 0;
    for (int i = 0; i < metrics->size; i++) {
        if (metrics[i].timestamp >= start && metrics[i].timestamp <= end) {
            records[count++] = metrics[i];
        }
    }

    // Return the array of matching metric records
    return records;
}
