// Define the function to initialize the dynamic array of LTE PHY Receiver Context structures
void init_lte_phy_receiver_contexts(int num_cells) {
    // Allocate memory for the dynamic array of LTE PHY Receiver Context structures
    LTEPHYReceiverContext *contexts = malloc(num_cells * sizeof(LTEPHYReceiverContext));

    // Initialize each context with a valid cell ID and an empty reception channel array
    for (int i = 0; i < num_cells; i++) {
        contexts[i].cell_id = i + 1;
        contexts[i].num_channels = 0;
        contexts[i].channels = malloc(sizeof(ReceptionChannel) * MAX_NUM_CHANNELS);
    }

    // Initialize the thread-safe mechanism for concurrent access to the dynamic array of LTE PHY Receiver Context structures
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Define a cleanup function to release all allocated resources when the context is no longer needed
    void cleanup(LTEPHYReceiverContext *context) {
        free(context->channels);
        free(context);
    }
}

// Define a function to add a new channel to an existing LTE PHY Receiver Context structure
void add_channel(LTEPHYReceiverContext *context, int sample_rate, int buffer_size) {
    // Acquire the mutex lock for the context
    pthread_mutex_lock(&mutex);

    // Check if there is enough space in the reception channel array to add a new channel
    if (context->num_channels < MAX_NUM_CHANNELS) {
        // Allocate memory for the new reception channel
        ReceptionChannel *new_channel = malloc(sizeof(ReceptionChannel));

        // Initialize the new reception channel with the given sample rate and buffer size
        new_channel->sample_rate = sample_rate;
        new_channel->buffer_size = buffer_size;

        // Add the new reception channel to the end of the array
        context->channels[context->num_channels++] = new_channel;
    } else {
        // Release the mutex lock and return if there is no space in the reception channel array
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Define a function to update the cell ID and reception parameters of an existing LTE PHY Receiver Context structure
void update_context(LTEPHYReceiverContext *context, int cell_id, int sample_rate, int buffer_size) {
    // Acquire the mutex lock for the context
    pthread_mutex_lock(&mutex);

    // Update the cell ID and reception parameters of the context
    context->cell_id = cell_id;
    context->sample_rate = sample_rate;
    context->buffer_size = buffer_size;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Define a function to release all allocated resources when the context is no longer needed
void cleanup(LTEPHYReceiverContext *context) {
    // Acquire the mutex lock for the context
    pthread_mutex_lock(&mutex);

    // Release all allocated resources for the context
    free(context->channels);
    free(context);

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}
