    time_t last_active;
    char *ip_addresses[];
} ConnectionRecord;

// Function to add a new connection record
void addConnection(int session_id, char *ip_addresses[]) {
    // Create a new connection record
    ConnectionRecord *record = malloc(sizeof(ConnectionRecord));
    if (!record) {
        printf("Error: Failed to allocate memory for connection record\n");
        return;
    }

    // Initialize the fields of the record
    record->session_id = session_id;
    record->last_active = time(NULL);
    memcpy(record->ip_addresses, ip_addresses, sizeof(char *) * (strlen(ip_addresses) + 1));

    // Add the record to the list of connections
    pthread_mutex_lock(&connections_mutex);
    connections = realloc(connections, (num_connections + 1) * sizeof(ConnectionRecord *));
    if (!connections) {
        printf("Error: Failed to allocate memory for connection list\n");
        pthread_mutex_unlock(&connections_mutex);
        return;
    }
    connections[num_connections++] = record;
    pthread_mutex_unlock(&connections_mutex);
}

// Function to remove a connection record
void removeConnection(int session_id) {
    // Find the index of the record with the given session ID
    int i;
    for (i = 0; i < num_connections; i++) {
        if (connections[i]->session_id == session_id) {
            break;
        }
    }

    // If the record was found, remove it from the list and free its memory
    if (i < num_connections) {
        pthread_mutex_lock(&connections_mutex);
        connections[i] = connections[--num_connections];
        free(connections[i]);
        pthread_mutex_unlock(&connections_mutex);
    }
}

// Function to update the last active time of a connection record
void updateLastActive(int session_id) {
    // Find the index of the record with the given session ID
    int i;
    for (i = 0; i < num_connections; i++) {
        if (connections[i]->session_id == session_id) {
            break;
        }
    }

    // If the record was found, update its last active time and return
    if (i < num_connections) {
        pthread_mutex_lock(&connections_mutex);
        connections[i]->last_active = time(NULL);
        pthread_mutex_unlock(&connections_mutex);
    }
}

// Function to iterate over the list of connection records and perform an operation on each record
void iterateConnections(void (*operation)(ConnectionRecord *)) {
    // Iterate over the list of connections and perform the given operation on each one
    pthread_mutex_lock(&connections_mutex);
    for (int i = 0; i < num_connections; i++) {
        operation(connections[i]);
    }
    pthread_mutex_unlock(&connections_mutex);
}

