// Function to initialize and configure a network interface for high-throughput data transfer
int init_network(struct net_config *config) {
    // Create a socket for the network interface
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket creation failed");
        return -1;
    }

    // Set the MAC address of the network interface
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, config->mac_addr, IFNAMSIZ-1);
    if (ioctl(sock, SIOCSIFHWADDR, &ifr) < 0) {
        perror("setting MAC address failed");
        return -1;
    }

    // Set the IP address of the network interface
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(0);
    inet_pton(AF_INET, config->ip_addr, &addr.sin_addr);
    if (bind(sock, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("binding socket failed");
        return -1;
    }

    // Set the subnet mask of the network interface
    struct in_addr netmask;
    memset(&netmask, 0, sizeof(netmask));
    inet_pton(AF_INET, config->subnet_mask, &netmask);
    if (ioctl(sock, SIOCSIFNETMASK, &netmask) < 0) {
        perror("setting subnet mask failed");
        return -1;
    }

    // Set the gateway of the network interface
    struct sockaddr_in gw;
    memset(&gw, 0, sizeof(gw));
    gw.sin_family = AF_INET;
    gw.sin_port = htons(0);
    inet_pton(AF_INET, config->gateway, &gw.sin_addr);
    if (ioctl(sock, SIOCSIFGATEWAY, &gw) < 0) {
        perror("setting gateway failed");
        return -1;
    }

    // Set the MTU size of the network interface
    struct ifreq mtu_req;
    memset(&mtu_req, 0, sizeof(mtu_req));
    strncpy(mtu_req.ifr_name, config->mac_addr, IFNAMSIZ-1);
    mtu_req.ifr_mtu = config->mtu;
    if (ioctl(sock, SIOCSIFMTU, &mtu_req) < 0) {
        perror("setting MTU failed");
        return -1;
    }

    // Close the socket
    close(sock);

    return 0;
}

