#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define structure for MAC PDUs
typedef struct {
    MAC_HEADER header;
    MAC_PAYLOAD payload;
} MAC_PDU_T;

// Function to initialize dynamic array of MAC PDUs
void init_mac_pdu(MAC_PDU_T **pdu, size_t capacity) {
    *pdu = (MAC_PDU_T *)malloc(capacity * sizeof(**pdu));
    memset(*pdu, 0, capacity * sizeof(**pdu));
}

// Function to add a new MAC PDU to the dynamic array
void add_mac_pdu(MAC_PDU_T **pdu, size_t capacity, size_t index) {
    if (index >= capacity) {
        // Reallocate memory for the dynamic array if necessary
        *pdu = (MAC_PDU_T *)realloc(*pdu, 2 * capacity * sizeof(**pdu));
        memset((*pdu + capacity), 0, capacity * sizeof(**pdu));
        capacity *= 2;
    }
    (*pdu)[index].header = {0};
    (*pdu)[index].payload = {0};
}

// Function to calculate the average latency of packet transmissions across multiple network interfaces under varying traffic loads and error rates
void calc_latency(size_t num_interfaces, size_t *interface_ids, double *latencies) {
    // Initialize variables for calculating average latency
    size_t total_packets = 0;
    double total_latency = 0.0;

    // Loop through each network interface and calculate the average latency
    for (size_t i = 0; i < num_interfaces; i++) {
        // Get the current interface ID and its corresponding statistics
        size_t interface_id = interface_ids[i];
        struct ifreq interface_stats;
        memset(&interface_stats, 0, sizeof(interface_stats));
        strcpy(interface_stats.ifr_name, "eth0"); // Replace with the actual interface name
        ioctl(interface_id, SIOCGIFSTATS, &interface_stats);

        // Calculate the average latency for this interface
        double avg_latency = (double)interface_stats.ifr_data.ifi_avg_lat / 1000; // Convert to milliseconds
        total_packets += interface_stats.ifr_data.ifi_ipackets;
        total_latency += avg_latency * interface_stats.ifr_data.ifi_ipackets;
    }

    // Calculate the average latency across all interfaces
    double average_latency = total_latency / (double)total_packets;

    // Store the average latency in the output array
    latencies[0] = average_latency;
}
