// Structure to represent a configuration setting
typedef struct ConfigSetting {
    char* name;
    int defaultValue;
    int currentUsageCount;
} ConfigSetting;

// Linked list node for storing configuration settings
typedef struct ConfigNode {
    ConfigSetting* setting;
    struct ConfigNode* next;
} ConfigNode;

// Global variable to store the head of the linked list
ConfigNode* head = NULL;

// Mutex to protect concurrent access to the linked list
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new configuration setting to the linked list
void addSetting(char* name, int defaultValue) {
    ConfigNode* node = malloc(sizeof(ConfigNode));
    node->setting = malloc(sizeof(ConfigSetting));
    node->setting->name = strdup(name);
    node->setting->defaultValue = defaultValue;
    node->setting->currentUsageCount = 0;
    pthread_mutex_lock(&mutex);
    if (head == NULL) {
        head = node;
    } else {
        ConfigNode* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to update an existing configuration setting by name
void updateSetting(char* name, int newValue) {
    ConfigNode* current = head;
    while (current != NULL) {
        if (strcmp(name, current->setting->name) == 0) {
            pthread_mutex_lock(&mutex);
            current->setting->defaultValue = newValue;
            current->setting->currentUsageCount++;
            pthread_mutex_unlock(&mutex);
            return;
        }
        current = current->next;
    }
}

// Function to retrieve a configuration setting by name
ConfigSetting* getSetting(char* name) {
    ConfigNode* current = head;
    while (current != NULL) {
        if (strcmp(name, current->setting->name) == 0) {
            return current->setting;
        }
        current = current->next;
    }
    return NULL;
}

// Function to prune infrequently used settings from the linked list
void pruneSettings() {
    ConfigNode* current = head;
    while (current != NULL) {
        if (current->setting->currentUsageCount < 10) {
            pthread_mutex_lock(&mutex);
            ConfigNode* next = current->next;
            free(current->setting->name);
            free(current->setting);
            free(current);
            current = next;
        } else {
            current = current->next;
        }
    }
}

// Function to handle concurrent access to the linked list without data corruption
void* threadFunction(void* arg) {
    int id = (int)arg;
    while (1) {
        pthread_mutex_lock(&mutex);
        ConfigNode* current = head;
        while (current != NULL) {
            if (current->setting->currentUsageCount > 0) {
                current->setting->currentUsageCount--;
            }
            current = current->next;
        }
        pthread_mutex_unlock(&mutex);
    }
}
