    radioFrame->modulationScheme = modulationScheme;
    radioFrame->numSlots = numSlots;
    radioFrame->slotDuration = slotDuration;
    radioFrame->numSymbols = numSymbols;
    radioFrame->symbolDuration = symbolDuration;
