#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

// Define a structure to represent a UE context
typedef struct {
    char imsi[15];
    int rfLayerConfig;
} UEContext;

// Define a structure to represent a PDU session
typedef struct {
    char imsi[15];
    int qosProfile;
    int sessionType;
} PduSession;

// Define an array of UE contexts
UEContext *ueContexts = NULL;
size_t ueContextCount = 0;
pthread_mutex_t ueContextMutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to initialize the UE context array
void initUeContextArray(int size) {
    // Allocate memory for the UE context array
    ueContexts = (UEContext *)malloc(size * sizeof(UEContext));
    if (!ueContexts) {
        perror("Failed to allocate memory for UE context array");
        exit(1);
    }
    memset(ueContexts, 0, size * sizeof(UEContext));
    ueContextCount = size;
}

// Define a function to add a new PDU session to the UE context array
void addPduSession(char *imsi, int qosProfile, int sessionType) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&ueContextMutex);

    // Find an available slot in the UE context array
    for (int i = 0; i < ueContextCount; i++) {
        if (!strcmp(imsi, ueContexts[i].imsi)) {
            // Update the existing UE context with the new session information
            ueContexts[i].qosProfile = qosProfile;
            ueContexts[i].sessionType = sessionType;
            break;
        }
    }

    // If no available slot was found, add a new UE context
    if (i == ueContextCount) {
        UEContext *newUeContext = (UEContext *)malloc(sizeof(UEContext));
        strcpy(newUeContext->imsi, imsi);
        newUeContext->qosProfile = qosProfile;
        newUeContext->sessionType = sessionType;
        ueContexts[i] = *newUeContext;
        ueContextCount++;
    }

    // Unlock the mutex to allow other threads to access the UE context array
    pthread_mutex_unlock(&ueContextMutex);
}

// Define a function to retrieve a PDU session from the UE context array
PduSession *getPduSession(char *imsi) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&ueContextMutex);

    // Find the UE context with the specified IMSI
    for (int i = 0; i < ueContextCount; i++) {
        if (!strcmp(imsi, ueContexts[i].imsi)) {
            PduSession *session = (PduSession *)malloc(sizeof(PduSession));
            strcpy(session->imsi, imsi);
            session->qosProfile = ueContexts[i].qosProfile;
            session->sessionType = ueContexts[i].sessionType;
            pthread_mutex_unlock(&ueContextMutex);
            return session;
        }
    }

    // If no matching UE context was found, return NULL
    pthread_mutex_unlock(&ueContextMutex);
    return NULL;
}
