// Define a structure to store status updates
typedef struct {
    char mac_status[10]; // MAC layer status indicator (e.g., "up", "down")
    int vlan_id;         // Unique VLAN ID
    time_t timestamp;   // Timestamp of the error code
    int error_code;     // Error code associated with the update
} status_update_t;

// Define a linked list to store the status updates
typedef struct {
    status_update_t *head;
    status_update_t *tail;
} status_update_list_t;

// Function to initialize and manage the scalable collection of network interface status updates
void update_status(status_update_list_t *list, char *mac_status, int vlan_id, int error_code) {
    // Create a new status update structure
    status_update_t *new_update = (status_update_t *)malloc(sizeof(status_update_t));
    strcpy(new_update->mac_status, mac_status);
    new_update->vlan_id = vlan_id;
    new_update->error_code = error_code;
    new_update->timestamp = time(NULL);

    // Add the new update to the linked list
    if (list->head == NULL) {
        list->head = new_update;
        list->tail = new_update;
    } else {
        list->tail->next = new_update;
        list->tail = new_update;
    }
}

// Function to retrieve the status update with the latest timestamp
status_update_t *get_latest_update(status_update_list_t *list) {
    if (list->head == NULL) {
        return NULL;
    } else {
        return list->tail;
    }
}

// Function to remove the oldest status update from the linked list
void remove_oldest_update(status_update_list_t *list) {
    if (list->head == NULL) {
        return;
    } else {
        status_update_t *oldest = list->head;
        list->head = oldest->next;
        free(oldest);
    }
}

// Function to retrieve the number of status updates in the linked list
int get_num_updates(status_update_list_t *list) {
    int count = 0;
    status_update_t *current = list->head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    return count;
}

// Function to retrieve the status update with a given VLAN ID
status_update_t *get_vlan_update(status_update_list_t *list, int vlan_id) {
    status_update_t *current = list->head;
    while (current != NULL) {
        if (current->vlan_id == vlan_id) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}
