void handleInconsistencies(NetworkInterfaceUpdate *updates, int numUpdates) {
    // Initialize the inconsistency detection variables
    int inconsistentRecords = 0;
    time_t lastSyncTime = time(NULL);

    // Iterate over each update in the array
    for (int i = 0; i < numUpdates; i++) {
        NetworkInterfaceUpdate *update = &updates[i];

        // Check if the update is within the specified age and number of recent updates criteria
        if (update->timestamp > lastSyncTime - 3 && update->timestamp > inconsistentRecords) {
