    struct_ptr->rnti = rand() % 65536; // Randomly set the RNTI
    struct_ptr->crcflag = false; // Initialize the CRC flag to false
}

// Function to calculate the CRC flag based on a parity check of the combined bits of the UE information tag and RNTI
void calculate_crc(NFAPI_CRC_INDICATION_PDU_T *struct_ptr) {
    uint16_t crc = 0;
    for (int i = 0; i < sizeof(struct_ptr->rx_ue_information_tag); i++) {
        crc ^= ((uint8_t *)&struct_ptr->rx_ue_information_tag)[i];
    }
    for (int i = 0; i < sizeof(struct_ptr->rnti); i++) {
        crc ^= ((uint8_t *)&struct_ptr->rnti)[i];
    }
    struct_ptr->crcflag = (crc & 1) == 1; // Set the CRC flag based on the parity check result
}

