        calculate_crc(struct_ptr); // Calculate the CRC flag for the current structure
        struct_ptr = struct_ptr->next; // Move to the next structure in the pool
    }
}

// Main function to handle the processing of UE information tags and RNTIs in a multi-threaded environment
