// Define the condition variable for signaling when the list is full
pthread_cond_t mac_pdu_list_full = PTHREAD_COND_INITIALIZER;

// Define the list of MAC PDUs
MAC_PDU *mac_pdu_list = NULL;

// Define the number of structures currently in the list
int num_structures = 0;

// Define the total length of all PDUs in the list
int total_length = 0;

// Define the number of processed PDUs
int num_processed = 0;

// Define the maximum number of threads to use for processing data
#define MAX_THREADS 16

// Define the array of thread IDs
pthread_t thread_ids[MAX_THREADS];

// Define the function for initializing a MAC PDU structure
void init_mac_pdu(MAC_PDU *mac_pdu) {
    // Generate a random MAC layer ID within the specified range
    mac_pdu->mac_layer_id = rand() % (MAX_MAC_LAYER_ID - MIN_MAC_LAYER_ID + 1) + MIN_MAC_LAYER_ID;

    // Generate a random PDU length within the specified range
    mac_pdu->pdu_length = rand() % (MAX_PDU_LENGTH - MIN_PDU_LENGTH + 1) + MIN_PDU_LENGTH;

    // Initialize the sequence number to 0
    mac_pdu->sequence_number = 0;
}

// Define the function for calculating the PDU length based on the cumulative sum of all previously processed PDU lengths
int calculate_pdu_length(int previous_length) {
    // Calculate the new PDU length based on the cumulative sum and number of processed PDUs
    int new_length = (previous_length * num_processed) / (num_processed + 1);

    // Return the new PDU length
    return new_length;
}

// Define the function for adding a MAC PDU to the list
void add_mac_pdu(MAC_PDU *mac_pdu) {
    // Acquire the mutex for protecting the list of MAC PDUs
    pthread_mutex_lock(&mac_pdu_list_mutex);

    // Check if the list is full
    while (num_structures == MAX_STRUCTURES) {
        // Wait for the condition variable to be signaled
        pthread_cond_wait(&mac_pdu_list_full, &mac_pdu_list_mutex);
    }

    // Add the MAC PDU to the list
    mac_pdu_list[num_structures++] = *mac_pdu;

    // Increment the total length of all PDUs in the list
    total_length += mac_pdu->pdu_length;

    // Increment the number of processed PDUs
    num_processed++;

    // Release the mutex for protecting the list of MAC PDUs
    pthread_mutex_unlock(&mac_pdu_list_mutex);
}

// Define the function for processing a MAC PDU
void process_mac_pdu(MAC_PDU *mac_pdu) {
    // Calculate the new PDU length based on the cumulative sum of all previously processed PDU lengths
    mac_pdu->pdu_length = calculate_pdu_length(mac_pdu->pdu_length);

    // Add the MAC PDU to the list
    add_mac_pdu(mac_pdu);
}

