#define MAX_POOL_SIZE 10000
NFAPI_CRC_INDICATION_PDU_T *pool = NULL;
size_t pool_size = 0;

// Initialize the pool with a randomly set CRCFLAG
void init_pool(void) {
    // Allocate memory for the pool
    pool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_POOL_SIZE);
    assert(pool != NULL);

    // Initialize each structure in the pool with a valid RX_UE_INFORMATION_TAG and RNTI
    for (size_t i = 0; i < MAX_POOL_SIZE; i++) {
        pool[i].rx_ue_information_tag = rand() % 65536;
        pool[i].rnti = rand() % 65536;
        pool[i].crcflag = false;
    }
}

// Calculate the CRCFLAG based on a parity check of the combined bits of the UE information tag and RNTI
void calculate_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Perform a parity check on the combined bits of the UE information tag and RNTI
    uint16_t crc = 0;
    for (size_t i = 0; i < sizeof(uint16_t); i++) {
        crc ^= ((uint8_t *)&pdu->rx_ue_information_tag)[i] ^ ((uint8_t *)&pdu->rnti)[i];
    }

    // Set the CRCFLAG based on the parity check result
    pdu->crcflag = (crc == 0);
}

// Populate a structure in the pool with a valid RX_UE_INFORMATION_TAG and RNTI, calculating the CRCFLAG
NFAPI_CRC_INDICATION_PDU_T *populate_pool(void) {
    // Find an empty slot in the pool
    for (size_t i = 0; i < MAX_POOL_SIZE; i++) {
        if (!pool[i].crcflag) {
            // Set the RX_UE_INFORMATION_TAG and RNTI in the structure
            pool[i].rx_ue_information_tag = rand() % 65536;
            pool[i].rnti = rand() % 65536;

            // Calculate the CRCFLAG for the structure
            calculate_crcflag(&pool[i]);

            return &pool[i];
        }
    }

    // No empty slots found, return NULL
    return NULL;
}

// Free a structure in the pool
void free_pool(NFAPI_CRC_INDICATION_PDU_T *pdu) {
