    // Reset the CRCFLAG for the structure
    pdu->crcflag = false;
}

// DNS resolution mechanism to retrieve IP addresses from domain names
#define MAX_DNS_RESOLUTION_ATTEMPTS 3
int dns_resolve(const char *domain, struct in_addr *ip) {
    // Perform DNS resolution attempts
    for (size_t i = 0; i < MAX_DNS_RESOLUTION_ATTEMPTS; i++) {
        // Resolve the domain name to an IP address
        int result = gethostbyname(domain, AF_INET);
        if (result == 0) {
            // Return the resolved IP address
            *ip = *((struct in_addr *)gethostbyname(domain, AF_INET));
            return 0;
        } else if (result < 0) {
            // DNS resolution failed, try again after a delay
            usleep(100000);
        } else {
            // Invalid input data, return an appropriate error code
            return -EINVAL;
        }
    }

    // All attempts failed, return an appropriate error code
    return -ENOENT;
}

// Main function for processing the UE information tags and RNTIs
