    for (size_t i = 0; i < sizeof(ue_information_tags) / sizeof(uint16_t); i++) {
        // Populate a structure in the pool with a valid RX_UE_INFORMATION_TAG and RNTI, calculating the CRCFLAG
        NFAPI_CRC_INDICATION_PDU_T *pdu = populate_pool();
        if (pdu == NULL) {
