            return -ENOMEM;
        }

        // Set the RX_UE_INFORMATION_TAG and RNTI in the structure
        pdu->rx_ue_information_tag = ue_information_tags[i];
        pdu->rnti = rntis[i];

        // Calculate the CRCFLAG for the structure
        calculate_crcflag(pdu);

        // Perform DNS resolution to retrieve IP addresses from domain names
        struct in_addr ip;
        int result = dns_resolve("example.com", &ip);
        if (result < 0) {
            // DNS resolution failed, return an appropriate error code
            free_pool(pdu);
