        if (ret != 0) {
            printf("Error loading configuration file: %s\n", strerror(errno));
            continue;
        }

        // Add the configuration to the cache
        pthread_mutex_lock(&cache->mutex);
        cache->config = config;
        pthread_mutex_unlock(&cache->mutex);
    }

    return 0;
}

