} nfapi_crc_indication_pdu_t;

// Define a list data structure to hold the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    int size;
    int capacity;
    nfapi_crc_indication_pdu_t* data;
} nfapi_crc_indication_list_t;

// Define a function to initialize the list
void nfapi_crc_indication_list_init(nfapi_crc_indication_list_t* list) {
    list->size = 0;
    list->capacity = 1024; // Start with a default capacity of 1024 elements
    list->data = (nfapi_crc_indication_pdu_t*)malloc(list->capacity * sizeof(nfapi_crc_indication_pdu_t));
}

// Define a function to insert an element into the list
void nfapi_crc_indication_list_insert(nfapi_crc_indication_list_t* list, RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8) {
    // Check if the list is full and needs to be resized
    if (list->size == list->capacity) {
        list->capacity *= 2; // Double the capacity of the list
        list->data = (nfapi_crc_indication_pdu_t*)realloc(list->data, list->capacity * sizeof(nfapi_crc_indication_pdu_t));
    }

    // Insert the element into the list
    list->data[list->size].rx_ue_information = rx_ue_information;
    list->data[list->size].rnti = rnti;
    list->data[list->size].crc_indication_rel8 = crc_indication_rel8;
    list->size++;
}

// Define a function to retrieve an element from the list
nfapi_crc_indication_pdu_t* nfapi_crc_indication_list_get(nfapi_crc_indication_list_t* list, int index) {
    if (index < 0 || index >= list->size) {
        return NULL;
    }
    return &list->data[index];
}

// Define a function to remove an element from the list
void nfapi_crc_indication_list_remove(nfapi_crc_indication_list_t* list, int index) {
    if (index < 0 || index >= list->size) {
        return;
    }
    // Shift all elements after the removed element to fill the gap
    for (int i = index + 1; i < list->size; i++) {
        list->data[i - 1] = list->data[i];
    }
    list->size--;
}

// Define a function to clear the list
void nfapi_crc_indication_list_clear(nfapi_crc_indication_list_t* list) {
    list->size = 0;
}

// Define a function to destroy the list and free its memory
void nfapi_crc_indication_list_destroy(nfapi_crc_indication_list_t* list) {
    free(list->data);
}
