    RRC_MEASUREMENTS *rrcm;
    DL_AMBR *dlamb;
} DL_FRAME_INFO_T;

// Define the cache for frame information
static DL_FRAME_INFO_T *frame_cache[MAX_FRAMES];

// Define the mutex for thread-safe operations
static pthread_mutex_t frame_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically manage a list of DL_FRAME_INFO_T structures
void dl_frame_manager(PDU_SESSION_CONTEXT_T *psc, RRC_MEASUREMENTS *rrcm, DL_AMBR *dlamb) {
    // Acquire the mutex for thread-safe operations
    pthread_mutex_lock(&frame_mutex);

    // Check if there is space in the cache for a new frame
    if (frame_cache[MAX_FRAMES - 1] == NULL) {
        // Allocate memory for the new frame
        DL_FRAME_INFO_T *new_frame = malloc(sizeof(DL_FRAME_INFO_T));
        if (new_frame == NULL) {
            // Handle allocation failure
            pthread_mutex_unlock(&frame_mutex);
            return;
        }

        // Initialize the new frame with input parameters
        new_frame->psc = psc;
        new_frame->rrcm = rrcm;
        new_frame->dlamb = dlamb;

        // Add the new frame to the cache
        frame_cache[MAX_FRAMES - 1] = new_frame;
    } else {
        // Check if there is a free slot in the cache for an existing frame
        int i;
        for (i = 0; i < MAX_FRAMES; i++) {
            if (frame_cache[i] == NULL) {
                break;
            }
        }

        // If there is a free slot, use it to store the new frame
        if (i < MAX_FRAMES) {
            DL_FRAME_INFO_T *new_frame = malloc(sizeof(DL_FRAME_INFO_T));
            if (new_frame == NULL) {
                // Handle allocation failure
                pthread_mutex_unlock(&frame_mutex);
                return;
            }

            new_frame->psc = psc;
            new_frame->rrcm = rrcm;
            new_frame->dlamb = dlamb;

            frame_cache[i] = new_frame;
        } else {
            // If there is no free slot, remove the oldest frame from the cache and add the new one
            DL_FRAME_INFO_T *oldest_frame = frame_cache[0];
            for (int i = 1; i < MAX_FRAMES; i++) {
                if (frame_cache[i] != NULL && frame_cache[i]->timestamp > oldest_frame->timestamp) {
                    oldest_frame = frame_cache[i];
                }
            }

            free(oldest_frame);

            DL_FRAME_INFO_T *new_frame = malloc(sizeof(DL_FRAME_INFO_T));
            if (new_frame == NULL) {
                // Handle allocation failure
                pthread_mutex_unlock(&frame_mutex);
                return;
            }

            new_frame->psc = psc;
            new_frame->rrcm = rrcm;
            new_frame->dlamb = dlamb;

            frame_cache[0] = new_frame;
        }
    }

    // Release the mutex for thread-safe operations
    pthread_mutex_unlock(&frame_mutex);
}
