// Define the configuration parameters for the function
typedef struct {
    int tile_size;
    int world_width;
    int world_height;
    float camera_movement_speed;
} ConfigurationParameters;

// Define the function to populate the NFADeviceIndicationPDU array
void populateNFADeviceIndications(ConfigurationParameters *config, NFADeviceIndicationPDU **pdu_array) {
    // Initialize the configuration parameters from the JSON file
    json_object *json = json_object_from_file("configuration.json");
    if (json == NULL) {
        printf("Error: failed to load configuration file\n");
        return;
    }
    config->tile_size = json_object_get_int(json, "tileSize");
    config->world_width = json_object_get_int(json, "worldWidth");
    config->world_height = json_object_get_int(json, "worldHeight");
    config->camera_movement_speed = json_object_get_float(json, "cameraMovementSpeed");
    json_object_put(json);

    // Validate the configuration parameters
    if (config->tile_size <= 0 || config->world_width <= 0 || config->world_height <= 0) {
        printf("Error: invalid configuration parameters\n");
        return;
    }

    // Dynamically allocate memory for the NFADeviceIndicationPDU array
    *pdu_array = (NFADeviceIndicationPDU *)malloc(sizeof(NFADeviceIndicationPDU) * config->tile_size);
    if (*pdu_array == NULL) {
        printf("Error: failed to allocate memory for NFADeviceIndicationPDU array\n");
        return;
    }

    // Populate the NFADeviceIndicationPDU array with valid RxUeInfoTag and RNTI values
    for (int i = 0; i < config->tile_size; i++) {
        (*pdu_array)[i].rx_ue_info.rnti = rand() % 10000;
        (*pdu_array)[i].rx_ue_info.cell_id = rand() % 10000;
        (*pdu_array)[i].rx_ue_info.sfn = rand() % 10000;
        (*pdu_array)[i].rx_ue_info.slot = rand() % 10000;
        (*pdu_array)[i].rnti = rand() % 10000;
        (*pdu_array)[i].crc_indication.crci = rand() % 2;
    }

    // Free the configuration parameters structure
    free(config);
}
