void manage_lte_enb_stats(LTE_ENB_STATS_LIST_T *list, LTE_ENB_STATS_T *new_data) {
    // Acquire a semaphore to prevent concurrent access from multiple threads
    sem_wait(&semaphore);

    // Check if the list is full and needs to be resized
    if (list->count == list->capacity) {
        // Resize the list by 50%
        size_t new_capacity = list->capacity * 1.5;
        LTE_ENB_STATS_T *new_data = realloc(list->data, new_capacity * sizeof(LTE_ENB_STATS_T));
        if (new_data == NULL) {
            // Handle out-of-memory condition gracefully
            sem_post(&semaphore);
            return;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    // Add the new data to the end of the list
    list->data[list->count++] = *new_data;

    // Release the semaphore to allow other threads to access the list
    sem_post(&semaphore);
}

// Define the function to fetch the latest LTE_ENB_STATS_T structure from the list
LTE_ENB_STATS_T *fetch_lte_enb_stats(LTE_ENB_STATS_LIST_T *list) {
    // Acquire a semaphore to prevent concurrent access from multiple threads
    sem_wait(&semaphore);

    // Check if the list is empty
    if (list->count == 0) {
        // Release the semaphore and return NULL
        sem_post(&semaphore);
        return NULL;
    }

    // Return the latest data from the list
    LTE_ENB_STATS_T *data = &list->data[list->count - 1];

    // Release the semaphore to allow other threads to access the list
    sem_post(&semaphore);

    return data;
}

// Define the function to clear all elements from the list and reset it to its initial state
void clear_lte_enb_stats(LTE_ENB_STATS_LIST_T *list) {
    // Acquire a semaphore to prevent concurrent access from multiple threads
    sem_wait(&semaphore);

    // Free the memory allocated for the list
    free(list->data);

    // Reset the list to its initial state
    list->data = NULL;
    list->capacity = 0;
    list->count = 0;

    // Release the semaphore to allow other threads to access the list
    sem_post(&semaphore);
}
