// Define the structure for a MAC transaction record
typedef struct {
    uint64_t transaction_id;
    uint32_t source_address;
    uint32_t destination_address;
    uint16_t payload_size;
} mac_transaction_record_t;

// Define the maximum size of the collection in bytes
#define MAX_COLLECTION_SIZE 200 * 1024

// Define the default number of transactions to process
#define DEFAULT_NUM_TRANSACTIONS 1000

// Define the threshold for determining when a transaction is considered a duplicate
#define DUPLICATE_THRESHOLD 5

// Define the maximum allowed size of the collection in bytes
static uint32_t max_collection_size = MAX_COLLECTION_SIZE;

// Define the current number of transactions processed
static uint64_t num_transactions = 0;

// Define the collection of MAC transaction records
mac_transaction_record_t *transaction_records = NULL;

// Define a mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a condition variable for signaling when the collection is full
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Function to add a new MAC transaction record to the collection
void add_transaction(mac_transaction_record_t *record) {
    // Acquire the mutex
    pthread_mutex_lock(&mutex);

    // Check if the collection is full
    if (num_transactions >= max_collection_size / sizeof(mac_transaction_record_t)) {
        // Release the mutex and return
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Check if the transaction is a duplicate
    for (int i = 0; i < num_transactions; i++) {
        if (transaction_records[i].transaction_id == record->transaction_id) {
            // Release the mutex and return
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // Add the transaction to the collection
    transaction_records[num_transactions++] = *record;

    // Signal that a new transaction has been added
    pthread_cond_signal(&cond);

    // Release the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to remove a MAC transaction record from the collection
void remove_transaction(uint64_t transaction_id) {
    // Acquire the mutex
    pthread_mutex_lock(&mutex);

    // Find the index of the transaction with the given ID
    int i = 0;
    while (i < num_transactions && transaction_records[i].transaction_id != transaction_id) {
        i++;
    }

    // Check if the transaction was found
    if (i == num_transactions) {
        // Release the mutex and return
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Remove the transaction from the collection
    for (int j = i; j < num_transactions - 1; j++) {
        transaction_records[j] = transaction_records[j + 1];
    }
    num_transactions--;

    // Signal that a transaction has been removed
    pthread_cond_signal(&cond);

    // Release the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to get the number of transactions in the collection
uint64_t get_num_transactions() {
    return num_transactions;
}

// Function to get a MAC transaction record from the collection by ID
mac_transaction_record_t *get_transaction(uint64_t transaction_id) {
    // Acquire the mutex
    pthread_mutex_lock(&mutex);

    // Find the index of the transaction with the given ID
    int i = 0;
    while (i < num_transactions && transaction_records[i].transaction_id != transaction_id) {
        i++;
    }

    // Check if the transaction was found
    if (i == num_transactions) {
        // Release the mutex and return NULL
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Return a pointer to the transaction record
    mac_transaction_record_t *record = &transaction_records[i];

    // Release the mutex
    pthread_mutex_unlock(&mutex);

    return record;
}

// Function to export the collection of MAC transaction records to a CSV file
void export_transactions(const char *filename) {
    // Open the output file for writing
    FILE *output = fopen(filename, "w");
    if (output == NULL) {
        printf("Error: unable to open output file\n");
        return;
    }

    // Acquire the mutex
    pthread_mutex_lock(&mutex);

    // Write the header row to the CSV file
    fprintf(output, "transaction_id,source_address,destination_address,payload_size\n");

    // Iterate over each transaction record in the collection
    for (int i = 0; i < num_transactions; i++) {
        mac_transaction_record_t *record = &transaction_records[i];

        // Write the transaction record to the CSV file
        fprintf(output, "%lu,%u,%u,%hu\n", record->transaction_id, record->source_address, record->destination_address, record->payload_size);
    }

    // Release the mutex
    pthread_mutex_unlock(&mutex);

    // Close the output file
    fclose(output);
}

// Function to import a CSV file of MAC transaction records into the collection
void import_transactions(const char *filename) {
    // Open the input file for reading
    FILE *input = fopen(filename, "r");
    if (input == NULL) {
        printf("Error: unable to open input file\n");
        return;
    }

    // Acquire the mutex
    pthread_mutex_lock(&mutex);

    // Read each line of the CSV file
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, input)) != -1) {
        // Skip empty lines and comments
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }

        // Parse the transaction record from the CSV line
        mac_transaction_record_t *record = parse_transaction_record(line);
        if (record != NULL) {
            add_transaction(record);
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&mutex);

    // Close the input file
    fclose(input);
}

// Function to parse a MAC transaction record from a CSV line
mac_transaction_record_t *parse_transaction_record(const char *line) {
    // Split the line into fields using commas as delimiters
    char **fields = str_split(line, ',');
    if (fields == NULL) {
        return NULL;
    }

    // Check that there are at least 4 fields in the line
    if (strlen(fields[0]) < 1 || strlen(fields[1]) < 1 || strlen(fields[2]) < 1 || strlen(fields[3]) < 1) {
        return NULL;
    }

    // Parse the transaction ID, source address, and destination address from the fields
    uint64_t transaction_id = atoi(fields[0]);
    uint32_t source_address = atoi(fields[1]);
    uint32_t destination_address = atoi(fields[2]);
    uint16_t payload_size = atoi(fields[3]);

    // Check that the transaction ID, source address, and destination address are valid
    if (transaction_id == 0 || source_address == 0 || destination_address == 0) {
        return NULL;
    }

    // Create a new MAC transaction record with the parsed values
    mac_transaction_record_t *record = malloc(sizeof(mac_transaction_record_t));
    if (record == NULL) {
        return NULL;
    }
    record->transaction_id = transaction_id;
    record->source_address = source_address;
    record->destination_address = destination_address;
    record->payload_size = payload_size;

    // Free the fields and return the MAC transaction record
    free(fields);
    return record;
}

// Function to split a string into an array of substrings using a delimiter character
char **str_split(const char *str, char delim) {
    // Count the number of tokens in the string
    int num_tokens = 1;
    for (int i = 0; str[i] != '\0'; i++) {
        if (str[i] == delim) {
            num_tokens++;
        }
    }

    // Create an array of pointers to substrings
    char **tokens = malloc(num_tokens * sizeof(char*));
    if (tokens == NULL) {
        return NULL;
    }

    // Iterate over the string and split it into tokens
    int token_index = 0;
    char *token = strtok((char *)str, &delim);
    while (token != NULL) {
        tokens[token_index++] = token;
        token = strtok(NULL, &delim);
    }

    // Return the array of pointers to substrings
    return tokens;
}
```
