// Define a structure to hold cell measurement data
typedef struct {
    int measurement_id;
    int pci;
    float rsrp;
    float rsrq;
} nfapi_cell_measurement_pdu_t;

// Define a list of cell measurements
nfapi_cell_measurement_pdu_t *measurements = NULL;

// Function to generate and populate the list of cell measurements
void generate_measurements(int num_measurements) {
    // Allocate memory for the list of measurements
    measurements = (nfapi_cell_measurement_pdu_t *)malloc(num_measurements * sizeof(nfapi_cell_measurement_pdu_t));

    // Populate the list of measurements with random data
    for (int i = 0; i < num_measurements; i++) {
        measurements[i].measurement_id = i + 1;
        measurements[i].pci = rand() % 256;
        measurements[i].rsrp = (float)rand() / RAND_MAX * 100.0f;
        measurements[i].rsrq = (float)rand() / RAND_MAX * 100.0f;
    }
}

// Function to compute the weighted average of signal strength metrics for each cell measurement
void compute_weighted_average(int num_measurements) {
    // Compute the weighted average of the signal strength metrics for each cell measurement
    float rsrp_sum = 0.0f;
    float rsrq_sum = 0.0f;
    for (int i = 0; i < num_measurements; i++) {
        rsrp_sum += measurements[i].rsrp * measurements[i].pci;
        rsrq_sum += measurements[i].rsrq * measurements[i].pci;
    }
    float weighted_average_rsrp = rsrp_sum / (float)num_measurements;
    float weighted_average_rsrq = rsrq_sum / (float)num_measurements;

    // Print the weighted average of signal strength metrics for each cell measurement
    printf("Weighted Average RSRP: %f\n", weighted_average_rsrp);
    printf("Weighted Average RSRQ: %f\n", weighted_average_rsrq);
}

