    uint32_t RNTI;
    uint8_t CRCFLAG;
    uint64_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the hash table for storing the structures
static pthread_mutex_t hash_table_lock = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T *hash_table[10000];

// Define the function for allocating memory for a new structure
NFAPI_CRC_INDICATION_PDU_T* allocate_structure(uint32_t RNTI, uint64_t timestamp) {
    NFAPI_CRC_INDICATION_PDU_T *new_struct = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_struct) {
        printf("Error: Failed to allocate memory for new structure\n");
        return NULL;
    }
    new_struct->RX_UE_INFORMATION_TAG = 0;
    new_struct->RNTI = RNTI;
    new_struct->CRCFLAG = (uint8_t) rand() % 256;
    new_struct->timestamp = timestamp;
    return new_struct;
}

// Define the function for freeing memory of a structure
void free_structure(NFAPI_CRC_INDICATION_PDU_T *struct_ptr) {
    if (struct_ptr) {
        free(struct_ptr);
    }
}

// Define the function for adding a new structure to the hash table
int add_to_hash_table(NFAPI_CRC_INDICATION_PDU_T *new_struct) {
    pthread_mutex_lock(&hash_table_lock);
    uint32_t RNTI = new_struct->RNTI;
    uint64_t timestamp = new_struct->timestamp;
    if (hash_table[RNTI] != NULL) {
        // Check for duplicates within the 100-millisecond window
        if (abs(hash_table[RNTI]->timestamp - timestamp) < 100000) {
            pthread_mutex_unlock(&hash_table_lock);
            return -1;
        }
    }
    hash_table[RNTI] = new_struct;
    pthread_mutex_unlock(&hash_table_lock);
    return 0;
}

// Define the function for removing a structure from the hash table
int remove_from_hash_table(uint32_t RNTI) {
    pthread_mutex_lock(&hash_table_lock);
    if (hash_table[RNTI] == NULL) {
        pthread_mutex_unlock(&hash_table_lock);
        return -1;
    }
    free_structure(hash_table[RNTI]);
    hash_table[RNTI] = NULL;
    pthread_mutex_unlock(&hash_table_lock);
    return 0;
}

// Define the function for handling a CRC indication message
int handle_crc_indication(uint32_t RNTI, uint64_t timestamp) {
    NFAPI_CRC_INDICATION_PDU_T *new_struct = allocate_structure(RNTI, timestamp);
    if (!new_struct) {
        return -1;
    }
    int ret = add_to_hash_table(new_struct);
    if (ret < 0) {
        free_structure(new_struct);
    }
    return ret;
}

// Define the function for handling a CRC indication message with a specific RNTI
int handle_crc_indication_with_rnti(uint32_t RNTI) {
    pthread_mutex_lock(&hash_table_lock);
    if (hash_table[RNTI] == NULL) {
        pthread_mutex_unlock(&hash_table_lock);
        return -1;
    }
    NFAPI_CRC_INDICATION_PDU_T *struct_ptr = hash_table[RNTI];
    free_structure(struct_ptr);
    hash_table[RNTI] = NULL;
    pthread_mutex_unlock(&hash_table_lock);
    return 0;
}
```
