// Define the function to dynamically allocate memory for multiple arrays
void *allocate_memory(size_t size) {
    void *ptr = NULL;
    if (posix_memalign(&ptr, 4096, size)) {
        perror("Failed to allocate memory");
        return NULL;
    }
    return ptr;
}

// Define the function to manage a collection of NFAPI_CRC_INDICATION_PDU_T structures
void manage_collection(NFAPI_CRC_INDICATION_PDU_T *pdu, size_t count) {
    // Allocate memory for the arrays
    long *offset_array = allocate_memory(count * sizeof(long));
    int *key_array = allocate_memory(count * sizeof(int));
    Record **record_array = allocate_memory(count * sizeof(Record *));

    // Initialize the arrays and structures
    for (size_t i = 0; i < count; i++) {
        offset_array[i] = pdu[i].rx_ue_information_tag.offset;
        key_array[i] = pdu[i].rnti;
        record_array[i] = allocate_memory(sizeof(Record));
        record_array[i]->value = pdu[i].crc_indication_rel8_tag.crc_flag;
        record_array[i]->buffer = allocate_memory(1024);
