#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Custom memory pool for allocating NFAPI_CRC_INDICATION_PDU_T structures
struct MemoryPool {
    struct MemoryPool* next;
    size_t size;
    char data[];
};

// Global memory pool for managing allocated structures
static struct MemoryPool* mempool = NULL;

// Mutex for synchronizing access to the memory pool
static pthread_mutex_t mempool_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_pdu_array(size_t n) {
    // Acquire lock on memory pool
    pthread_mutex_lock(&mempool_lock);

    // Check if there is enough space in the memory pool to allocate N structures
    size_t required_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * n;
    if (required_size > mempool->size) {
        // Not enough space, need to reallocate the memory pool
        struct MemoryPool* new_mempool = malloc(required_size);
        if (!new_mempool) {
            pthread_mutex_unlock(&mempool_lock);
            return NULL;
        }
        // Copy existing data from old memory pool to new one
        memcpy(new_mempool->data, mempool->data, mempool->size);
        // Free the old memory pool
        free(mempool);
        // Update the global memory pool and size
        mempool = new_mempool;
        mempool->size = required_size;
    }

    // Allocate N structures in the memory pool
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)mempool->data;
    mempool->data += sizeof(NFAPI_CRC_INDICATION_PDU_T) * n;
    mempool->size -= required_size;

    // Initialize the structures with random values for RX_UE_INFORMATION_TAG and RNTI
    for (size_t i = 0; i < n; ++i) {
        pdu_array[i].RX_UE_INFORMATION_TAG.tag = rand();
        pdu_array[i].RX_UE_INFORMATION_TAG.rnti = rand();
    }

    // Initialize the structures with random values for CRC_INDICATION_REL8_TAG and CRCFLAG
