void processIntegerList(std::forward_list<int>& list, int divisor, int multiplier, int integrationFactor) {
    // Check if the list is empty
    if (list.empty()) {
        return;
    }

    // Initialize variables to keep track of the sum and product
    int sum = 0;
    int product = 1;

    // Iterate through the list and update the values as needed
    for (auto it = list.begin(); it != list.end(); ++it) {
        if (*it % divisor == 0) {
            *it += multiplier;
        }
        sum += *it;
        product *= *it;
    }

    // If no integers in the list meet the condition, append the product of integrationFactor and the sum to the end of the list
    if (sum == 0) {
        list.push_back(integrationFactor * product);
    }
}
