void add_rxinfo(int UE_ID, int RACH_PREAMBLE, int RX_POWER_LEVEL) {
    // Acquire mutex for thread-safe access and modification of the array
    pthread_mutex_lock(&rxinfo_mutex);

    // Check if array is NULL, allocate memory for it if necessary
    if (rxinfo_array == NULL) {
        rxinfo_array = malloc(sizeof(LTEPHY_RXINFO_T));
    } else {
        // Reallocate memory for the array to accommodate new entry
        rxinfo_array = realloc(rxinfo_array, (num_entries + 1) * sizeof(LTEPHY_RXINFO_T));
