    rxinfo_array[num_entries].RACH_PREAMBLE = RACH_PREAMBLE;
    rxinfo_array[num_entries].RX_POWER_LEVEL = RX_POWER_LEVEL;

    // Increment number of entries in the array
    num_entries++;

    // Release mutex for thread-safe access and modification of the array
    pthread_mutex_unlock(&rxinfo_mutex);
}

