    // Acquire mutex for thread-safe access and modification of the array
    pthread_mutex_lock(&rxinfo_mutex);

    // Find index of entry with matching UE_ID in the array
    int idx = -1;
    for (int i = 0; i < num_entries; i++) {
        if (rxinfo_array[i].UE_ID == UE_ID) {
            idx = i;
            break;
        }
    }

    // Update entry with provided data if found, otherwise do nothing
    if (idx != -1) {
        rxinfo_array[idx].RACH_PREAMBLE = RACH_PREAMBLE;
        rxinfo_array[idx].RX_POWER_LEVEL = RX_POWER_LEVEL;
    }

    // Release mutex for thread-safe access and modification of the array
    pthread_mutex_unlock(&rxinfo_mutex);
}

// Function to remove entry from the array by UE_ID
void remove_rxinfo(int UE_ID) {
    // Acquire mutex for thread-safe access and modification of the array
    pthread_mutex_lock(&rxinfo_mutex);

    // Find index of entry with matching UE_ID in the array
    int idx = -1;
    for (int i = 0; i < num_entries; i++) {
        if (rxinfo_array[i].UE_ID == UE_ID) {
            idx = i;
            break;
        }
