    // Remove entry from the array if found, otherwise do nothing
    if (idx != -1) {
        for (int i = idx; i < num_entries - 1; i++) {
            rxinfo_array[i] = rxinfo_array[i + 1];
        }
        num_entries--;
    }

    // Release mutex for thread-safe access and modification of the array
    pthread_mutex_unlock(&rxinfo_mutex);
