// Custom message structure
typedef struct {
    uint64_t timestamp;
    char* payload;
    bool status;
} Message;

// Dynamic array of messages
struct MessageList {
    Message** messages;
    size_t capacity;
    size_t count;
};

// Initialize a new message list with the given capacity
static struct MessageList* initMessageList(size_t capacity) {
    struct MessageList* list = malloc(sizeof(struct MessageList));
    if (!list) {
        return NULL;
    }
    list->messages = calloc(capacity, sizeof(Message*));
    if (!list->messages) {
        free(list);
        return NULL;
    }
    list->capacity = capacity;
    list->count = 0;
    return list;
}

// Add a new message to the list
static bool addMessage(struct MessageList* list, uint64_t timestamp, char* payload, bool status) {
    if (list->count == list->capacity) {
        // Reallocate memory for more messages
        size_t newCapacity = list->capacity * 2;
        Message** newMessages = realloc(list->messages, newCapacity * sizeof(Message*));
        if (!newMessages) {
            return false;
        }
        list->messages = newMessages;
        list->capacity = newCapacity;
    }
    // Create a new message and add it to the list
    Message* newMessage = malloc(sizeof(Message));
    if (!newMessage) {
        return false;
    }
    newMessage->timestamp = timestamp;
    newMessage->payload = payload;
    newMessage->status = status;
    list->messages[list->count++] = newMessage;
    return true;
}

// Update an existing message in the list by its timestamp
static bool updateMessage(struct MessageList* list, uint64_t timestamp, char* payload, bool status) {
    for (size_t i = 0; i < list->count; i++) {
        if (list->messages[i]->timestamp == timestamp) {
            // Update the message's fields
            free(list->messages[i]->payload);
            list->messages[i]->payload = payload;
            list->messages[i]->status = status;
            return true;
        }
    }
    return false;
}

// Retrieve a message from the list by its timestamp and status flag
static Message* getMessage(struct MessageList* list, uint64_t timestamp, bool status) {
    for (size_t i = 0; i < list->count; i++) {
        if (list->messages[i]->timestamp == timestamp && list->messages[i]->status == status) {
            return list->messages[i];
        }
    }
    return NULL;
}

// Free the memory allocated for a message list
static void freeMessageList(struct MessageList* list) {
    if (list) {
        for (size_t i = 0; i < list->count; i++) {
            free(list->messages[i]->payload);
            free(list->messages[i]);
        }
        free(list->messages);
        free(list);
    }
}

