// Define a structure to hold a record with an integer value
typedef struct {
    int value;
} Record;

// Define a hash table to store the records
typedef struct {
    int size; // Size of the hash table
    int count; // Number of records in the hash table
    Record **records; // Array of pointers to records
} HashTable;

// Initialize a new hash table with a given size
HashTable *init_hash_table(int size) {
    HashTable *ht = malloc(sizeof(HashTable));
    ht->size = size;
    ht->count = 0;
    ht->records = calloc(size, sizeof(Record*));
    return ht;
}

// Add a new record to the hash table with a given key and value
void add_record(HashTable *ht, int key, int value) {
    // Calculate the index of the record in the hash table
    int index = key % ht->size;

    // Check if there is already a record at that index
    if (ht->records[index] != NULL) {
        // If so, resize the hash table to accommodate more records
        resize_hash_table(ht);
        index = key % ht->size;
    }

    // Create a new record and add it to the hash table
    Record *record = malloc(sizeof(Record));
    record->value = value;
    ht->records[index] = record;
    ht->count++;
}

// Retrieve a record from the hash table with a given key
Record *get_record(HashTable *ht, int key) {
    // Calculate the index of the record in the hash table
    int index = key % ht->size;

    // Check if there is a record at that index
    if (ht->records[index] == NULL) {
        return NULL;
    }

    // Return the record with the given key
    return ht->records[index];
}

// Resize the hash table to accommodate more records
void resize_hash_table(HashTable *ht) {
    int new_size = ht->size * 2;
    HashTable *new_ht = init_hash_table(new_size);

    // Copy all existing records to the new hash table
    for (int i = 0; i < ht->size; i++) {
        Record *record = ht->records[i];
        if (record != NULL) {
            add_record(new_ht, record->key, record->value);
        }
    }

    // Free the old hash table and replace it with the new one
    free(ht);
    ht = new_ht;
}

// Set a random value for each record in the hash table within a specified range
void set_random_values(HashTable *ht, int min, int max) {
    srand(time(NULL));
    for (int i = 0; i < ht->size; i++) {
        Record *record = ht->records[i];
        if (record != NULL) {
            record->value = rand() % (max - min + 1) + min;
        }
    }
}

// Free the memory allocated by the hash table
void free_hash_table(HashTable *ht) {
    for (int i = 0; i < ht->size; i++) {
        Record *record = ht->records[i];
        if (record != NULL) {
            free(record);
        }
    }
    free(ht);
}
