#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Define the structure for LTEPHY_RXINFO_T
typedef struct {
    int UE_ID;
    int RACH_PREAMBLE;
    int RX_POWER_LEVEL;
} LTEPHY_RXINFO_T;

// Define the dynamic array for storing LTEPHY_RXINFO_T structures
typedef struct {
    LTEPHY_RXINFO_T* entries;
    int size;
    int capacity;
} LTEPHY_RXINFO_ARRAY;

// Define the mutex and semaphore for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
semaphore_t semaphore = SEMAPHORE_INITIALIZER;

// Function to add a new entry to the array
void addEntry(LTEPHY_RXINFO_T* entry) {
    // Acquire the mutex and semaphore
    pthread_mutex_lock(&mutex);
    semaphore_wait(&semaphore);

    // Check if the array needs to be resized
    if (array.size == array.capacity) {
        // Resize the array by 50%
        int newCapacity = array.capacity * 1.5;
        LTEPHY_RXINFO_T* newEntries = realloc(array.entries, sizeof(LTEPHY_RXINFO_T) * newCapacity);
        if (newEntries == NULL) {
            // Handle the error case
            pthread_mutex_unlock(&mutex);
            semaphore_post(&semaphore);
            return;
        }
        array.entries = newEntries;
        array.capacity = newCapacity;
    }

    // Add the new entry to the array
    array.entries[array.size++] = *entry;

    // Release the mutex and semaphore
    pthread_mutex_unlock(&mutex);
    semaphore_post(&semaphore);
}

// Function to update an existing entry in the array by UE_ID
void updateEntry(int UE_ID, LTEPHY_RXINFO_T* entry) {
    // Acquire the mutex and semaphore
    pthread_mutex_lock(&mutex);
    semaphore_wait(&semaphore);

    // Find the index of the entry to be updated
    int index = -1;
    for (int i = 0; i < array.size; i++) {
        if (array.entries[i].UE_ID == UE_ID) {
            index = i;
            break;
        }
    }

    // Check if the entry was found
    if (index != -1) {
        // Update the entry with the new values
        array.entries[index] = *entry;
    } else {
        // Handle the error case
        pthread_mutex_unlock(&mutex);
        semaphore_post(&semaphore);
        return;
    }

    // Release the mutex and semaphore
    pthread_mutex_unlock(&mutex);
    semaphore_post(&semaphore);
}

// Function to remove an entry from the array by UE_ID
void removeEntry(int UE_ID) {
    // Acquire the mutex and semaphore
    pthread_mutex_lock(&mutex);
    semaphore_wait(&semaphore);

    // Find the index of the entry to be removed
    int index = -1;
    for (int i = 0; i < array.size; i++) {
        if (array.entries[i].UE_ID == UE_ID) {
            index = i;
            break;
        }
    }

    // Check if the entry was found
    if (index != -1) {
        // Remove the entry from the array
        for (int i = index; i < array.size - 1; i++) {
            array.entries[i] = array.entries[i + 1];
        }
        array.size--;
    } else {
        // Handle the error case
        pthread_mutex_unlock(&mutex);
        semaphore_post(&semaphore);
        return;
    }

    // Release the mutex and semaphore
    pthread_mutex_unlock(&mutex);
    semaphore_post(&semaphore);
}

// Function to handle asynchronous external data sources for RACH_PREAMBLE values
void handleRachPreamble(int UE_ID, int rachPreamble) {
    // Acquire the mutex and semaphore
    pthread_mutex_lock(&mutex);
    semaphore_wait(&semaphore);

    // Check if the array needs to be resized
    if (array.size == array.capacity) {
        // Resize the array by 50%
        int newCapacity = array.capacity * 1.5;
        LTEPHY_RXINFO_T* newEntries = realloc(array.entries, sizeof(LTEPHY_RXINFO_T) * newCapacity);
        if (newEntries == NULL) {
            // Handle the error case
            pthread_mutex_unlock(&mutex);
            semaphore_post(&semaphore);
            return;
        }
        array.entries = newEntries;
        array.capacity = newCapacity;
    }

    // Add the new entry to the array
    LTEPHY_RXINFO_T entry = { UE_ID, rachPreamble, 0 };
    array.entries[array.size++] = entry;

    // Release the mutex and semaphore
    pthread_mutex_unlock(&mutex);
    semaphore_post(&semaphore);
}

// Function to handle partial failures gracefully
void handlePartialFailures(int UE_ID) {
    // Acquire the mutex and semaphore
    pthread_mutex_lock(&mutex);
    semaphore_wait(&semaphore);

