pthread_cond_t array_cv = PTHREAD_COND_INITIALIZER;

// Define the function to manage the dynamic array of NR PDUs
void manage_nr_pdus(NR_PDU_T *pdu, bool is_valid) {
    // Acquire the mutex for thread-safe access to the array
    pthread_mutex_lock(&array_mutex);

    // Check if the PDU is valid and should be added to the array
    if (is_valid) {
        // Allocate memory for the new PDU
        NR_PDU_T *new_pdu = malloc(sizeof(NR_PDU_T));
        if (!new_pdu) {
            LOG_ERROR("Failed to allocate memory for new PDU");
            pthread_mutex_unlock(&array_mutex);
            return;
        }

        // Copy the contents of the PDU into the new structure
        memcpy(new_pdu, pdu, sizeof(NR_PDU_T));

        // Add the new PDU to the end of the array
        NR_PDU_T **array = realloc(NULL, MAX_ARRAY_SIZE * sizeof(NR_PDU_T *));
        if (!array) {
            LOG_ERROR("Failed to allocate memory for new PDU");
            free(new_pdu);
            pthread_mutex_unlock(&array_mutex);
            return;
        }
        array[MAX_ARRAY_SIZE - 1] = new_pdu;

        // Release the mutex and signal the condition variable to wake up any waiting threads
        pthread_mutex_unlock(&array_mutex);
        pthread_cond_signal(&array_cv);
    } else {
        // Check if the PDU is already in the array
        for (int i = 0; i < MAX_ARRAY_SIZE; i++) {
            NR_PDU_T *current_pdu = array[i];
            if (current_pdu && current_pdu->ue_context == pdu->ue_context) {
                // Remove the PDU from the array and free its memory
                free(array[i]);
                array[i] = NULL;
                break;
