    size_t capacity; // The maximum number of elements that can be stored in the list
    size_t count; // The current number of elements in the list
    NFAPI_CRC_INDICATION_PDU_T* data; // A pointer to an array of NFAPI_CRC_INDICATION_PDU_T structures
} NFAPI_CRC_INDICATION_LIST_T;

// Define a mutex to protect the list from concurrent access
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_LIST_T* populate_nfa_crc_indication_list(size_t initial_capacity) {
    // Allocate memory for the list and initialize its capacity and count to 0
    NFAPI_CRC_INDICATION_LIST_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (list == NULL) {
        return NULL; // Memory allocation failed, return NULL
    }
    list->capacity = initial_capacity;
    list->count = 0;
    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * initial_capacity);
    if (list->data == NULL) {
        free(list); // Memory allocation failed, free the list and return NULL
        return NULL;
    }

    // Initialize the mutex for protecting the list from concurrent access
    pthread_mutex_init(&list_mutex, NULL);

    return list; // Return the populated list
}

void add_nfa_crc_indication(NFAPI_CRC_INDICATION_LIST_T* list, uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI, uint8_t CRC_INDICATION_REL8_TAG, bool CRCFLAG) {
    // Acquire the mutex for protecting the list from concurrent access
    pthread_mutex_lock(&list_mutex);

    // Check if the list needs to be resized
    if (list->count == list->capacity) {
        // Resize the list by doubling its capacity
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (new_data == NULL) {
            // Memory allocation failed, release the mutex and return
            pthread_mutex_unlock(&list_mutex);
            return;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    // Add a new element to the list
    NFAPI_CRC_INDICATION_PDU_T* element = &list->data[list->count++];
    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;
    element->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    element->CRCFLAG = CRCFLAG;

    // Release the mutex for protecting the list from concurrent access
    pthread_mutex_unlock(&list_mutex);
}

void free_nfa_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T* list) {
    // Acquire the mutex for protecting the list from concurrent access
    pthread_mutex_lock(&list_mutex);

    // Release the memory allocated to the list and its elements
    free(list->data);
    free(list);

    // Release the mutex for protecting the list from concurrent access
    pthread_mutex_unlock(&list_mutex);
}
