// Initialize a new thread-safe hash map for tracking used RNTIs
nfapi_rnti_map_t* nfapi_rnti_map_init() {
    nfapi_rnti_map_t* map = malloc(sizeof(nfapi_rnti_map_t));
    if (!map) {
