// Insert a new RNTI into the hash map
void nfapi_rnti_map_insert(nfapi_rnti_map_t* map, int rnti) {
    pthread_mutex_lock(&map->mutex);
    if (map->size == map->capacity) {
        // Resize the hash map if it's full
        map->capacity *= 2;
        map->keys = realloc(map->keys, sizeof(int) * map->capacity);
        if (!map->keys) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        map->values = realloc(map->values, sizeof(void*) * map->capacity);
        if (!map->values) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
    }
    map->keys[map->size] = rnti;
    map->values[map->size] = NULL;
    map->size++;
    pthread_mutex_unlock(&map->mutex);
}

