        bytes_sent = send(network_nodes[i]->socket_fd, request, sizeof(*request), 0);
        if (bytes_sent < 0) {
            perror("send");
            pthread_mutex_unlock(&network_nodes[i]->mutex);
            continue;
        }
        pthread_mutex_unlock(&network_nodes[i]->mutex);
    }
}

