#define THREAD_SAFETY_UNLOCK(lock) pthread_mutex_unlock(&lock);

// Define the error handling mechanism for buffer allocation failures, network errors, and processing timeouts
#define ERROR_HANDLING(err) { perror("Error: "); exit(1); }

void init_nfapi_rx_frame(NFAPI_RX_FRAME_T *frame) {
    // Initialize the NFAPI_RX_FRAME_T structure
    frame->tag = NFAPI_RRC_RX_FRAME_TAG;
    frame->srb1_tag = NULL;
}

void populate_srb1_tag(NFAPI_RX_FRAME_T *frame) {
    // Allocate memory for the SRB1 message
    size_t msg_size = MAX_MSG_SIZE;
    uint8_t *msg = malloc(msg_size);
    if (msg == NULL) {
        ERROR_HANDLING("Failed to allocate memory for SRB1 message");
    }

    // Fetch the SRB1 message from the remote server via HTTP GET requests
    int retry_count = 0;
    while (retry_count < RETRY_COUNT) {
        int sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockfd == -1) {
            ERROR_HANDLING("Failed to create socket");
        }

        struct sockaddr_in serv_addr;
        memset(&serv_addr, 0, sizeof(serv_addr));
        serv_addr.sin_family = AF_INET;
        serv_addr.sin_port = htons(80); // HTTP port
        if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0) {
            ERROR_HANDLING("Failed to convert IP address");
        }

        int rc = connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr));
        if (rc == -1) {
            ERROR_HANDLING("Failed to connect to server");
        }

        char *http_request = "GET /srb1 HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n";
        size_t http_request_size = strlen(http_request);
        ssize_t sent_bytes = send(sockfd, http_request, http_request_size, 0);
        if (sent_bytes == -1) {
            ERROR_HANDLING("Failed to send HTTP request");
        }

        char *http_response = malloc(msg_size);
        if (http_response == NULL) {
            ERROR_HANDLING("Failed to allocate memory for HTTP response");
        }

        ssize_t received_bytes = recv(sockfd, http_response, msg_size, 0);
        if (received_bytes == -1) {
            ERROR_HANDLING("Failed to receive HTTP response");
        }

        // Check for network errors or timeouts
        if (received_bytes < msg_size) {
            retry_count++;
            usleep(RETRY_DELAY * 1000); // in microseconds
            continue;
        } else {
            break;
        }
    }

    // Populate the SRB1 message into the NFAPI_RX_FRAME_T structure
    frame->srb1_tag = malloc(msg_size);
    if (frame->srb1_tag == NULL) {
        ERROR_HANDLING("Failed to allocate memory for SRB1 tag");
    }
    memcpy(frame->srb1_tag, msg, msg_size);

    // Free the HTTP response buffer
    free(http_response);
}

void process_nfapi_rx_frame(NFAPI_RX_FRAME_T *frame) {
    // Process the NFAPI_RX_FRAME_T structure in parallel with other frames
    THREAD_SAFETY_LOCK(lock);
    // Perform signal processing on the SRB1 message
    THREAD_SAFETY_UNLOCK(lock);
}

int main() {
    // Initialize the NFAPI_RX_FRAME_T structures for each frame
    NFAPI_RX_FRAME_T frames[MAX_FRAMES];
    for (int i = 0; i < MAX_FRAMES; i++) {
        init_nfapi_rx_frame(&frames[i]);
    }

    // Populate the SRB1 message for each frame
    for (int i = 0; i < MAX_FRAMES; i++) {
        populate_srb1_tag(&frames[i]);
    }

    // Process the NFAPI_RX_FRAME_T structures in parallel
    pthread_t threads[MAX_FRAMES];
    for (int i = 0; i < MAX_FRAMES; i++) {
        pthread_create(&threads[i], NULL, process_nfapi_rx_frame, &frames[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < MAX_FRAMES; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
