// Define the structure to hold the PDU header information
typedef struct {
    int id;
    char* data;
} NR_PDU_HEADER_T;

// Define a global variable to store the maximum size of the array
#define MAX_SIZE 1024

// Define a mutex for synchronizing access to the array
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to allocate memory for the array and initialize it with default values
void init_array(NR_PDU_HEADER_T** arr, int size) {
    // Allocate memory for the array
    *arr = (NR_PDU_HEADER_T*)malloc(size * sizeof(NR_PDU_HEADER_T));

    // Initialize the array with default values
    for (int i = 0; i < size; i++) {
        (*arr)[i].id = -1;
        (*arr)[i].data = NULL;
    }
}

// Define a function to add a new element to the array
void add_element(NR_PDU_HEADER_T** arr, int size, NR_PDU_HEADER_T* elem) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the array is full
    if (size == MAX_SIZE) {
        // If the array is full, double its size and reallocate memory
        NR_PDU_HEADER_T* new_arr = (NR_PDU_HEADER_T*)realloc(*arr, 2 * size * sizeof(NR_PDU_HEADER_T));
        if (new_arr == NULL) {
            // If reallocation fails, handle the error and return
            pthread_mutex_unlock(&mutex);
            return;
        }
        *arr = new_arr;
    }

    // Add the new element to the array
    (*arr)[size].id = elem->id;
    (*arr)[size].data = elem->data;

    // Increment the size of the array
    size++;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Define a function to remove an element from the array
void remove_element(NR_PDU_HEADER_T** arr, int* size, int id) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Find the index of the element to be removed
    int i = 0;
    while (i < *size && (*arr)[i].id != id) {
        i++;
    }

    // If the element is found, remove it from the array and decrement the size
    if (i < *size) {
        for (int j = i; j < *size - 1; j++) {
            (*arr)[j].id = (*arr)[j + 1].id;
            (*arr)[j].data = (*arr)[j + 1].data;
        }
        *size--;
    }

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Define a function to update an element in the array
void update_element(NR_PDU_HEADER_T** arr, int size, NR_PDU_HEADER_T* elem) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Find the index of the element to be updated
    int i = 0;
    while (i < size && (*arr)[i].id != elem->id) {
        i++;
    }

    // If the element is found, update its data and release the mutex lock
    if (i < size) {
        (*arr)[i].data = elem->data;
        pthread_mutex_unlock(&mutex);
    } else {
        // If the element is not found, handle the error and return
        pthread_mutex_unlock(&mutex);
        return;
    }
}

// Define a function to retrieve an element from the array
NR_PDU_HEADER_T* get_element(NR_PDU_HEADER_T** arr, int size, int id) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Find the index of the element to be retrieved
    int i = 0;
    while (i < size && (*arr)[i].id != id) {
        i++;
    }

    // If the element is found, retrieve it and release the mutex lock
    if (i < size) {
        NR_PDU_HEADER_T* elem = &(*arr)[i];
        pthread_mutex_unlock(&mutex);
        return elem;
    } else {
        // If the element is not found, handle the error and return NULL
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
}
