#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <sys/socket.h>
#include <pthread.h>

#define MAX_DNS_QUERIES 10
#define MAX_NFAPI_CRC_INDICATION_PDU_T_LIST 50

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int resolveHostname(const char *hostname, struct in_addr **ipAddrList) {
    int error = 0;
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_DGRAM;
    if ((error = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(error));
        return -1;
    }
    *ipAddrList = (struct in_addr **)malloc(sizeof(struct in_addr *) * MAX_DNS_QUERIES);
    int i = 0;
    for (struct addrinfo *rp = res; rp != NULL && i < MAX_DNS_QUERIES; rp = rp->ai_next) {
        if (rp->ai_family == AF_INET) {
            (*ipAddrList)[i] = (struct in_addr *)malloc(sizeof(struct in_addr));
            memcpy((*ipAddrList)[i], &((struct sockaddr_in *)rp->ai_addr)->sin_addr, sizeof(struct in_addr));
            i++;
        }
    }
    freeaddrinfo(res);
    return i;
}

int populateNFAPI_CRC_INDICATION_PDU_TList(const char *hostname, NFAPI_CRC_INDICATION_PDU_T **pduList) {
    int error = 0;
    struct in_addr **ipAddrList = NULL;
    if ((error = resolveHostname(hostname, &ipAddrList)) < 0) {
        return -1;
    }
    *pduList = (NFAPI_CRC_INDICATION_PDU_T **)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *) * MAX_NFAPI_CRC_INDICATION_PDU_T_LIST);
    int i = 0;
    for (int j = 0; j < error && i < MAX_NFAPI_CRC_INDICATION_PDU_T_LIST; j++) {
        (*pduList)[i] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        (*pduList)[i]->RX_UE_INFORMATION_TAG = 0x12;
        (*pduList)[i]->RNTI = htons(j);
        (*pduList)[i]->CRC_INDICATION_REL8_TAG = 0x34;
        (*pduList)[i]->CRCFLAG = rand() % 2;
        i++;
    }
    freeaddrinfo(ipAddrList);
    return i;
}

void *dnsQueryThread(void *args) {
