    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_DGRAM;
    char *hostname = (char *)args;
    if ((error = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(error));
        return NULL;
    }
    struct in_addr **ipAddrList = (struct in_addr **)malloc(sizeof(struct in_addr *) * MAX_DNS_QUERIES);
    int i = 0;
    for (struct addrinfo *rp = res; rp != NULL && i < MAX_DNS_QUERIES; rp = rp->ai_next) {
        if (rp->ai_family == AF_INET) {
            (*ipAddrList)[i] = (struct in_addr *)malloc(sizeof(struct in_addr));
            memcpy((*ipAddrList)[i], &((struct sockaddr_in *)rp->ai_addr)->sin_addr, sizeof(struct in_addr));
            i++;
        }
    }
    freeaddrinfo(res);
    return ipAddrList;
}

int main() {
    pthread_t dnsQueryThreads[MAX_DNS_QUERIES];
    struct in_addr **ipAddrList = NULL;
    NFAPI_CRC_INDICATION_PDU_T **pduList = NULL;
    for (int i = 0; i < MAX_DNS_QUERIES; i++) {
