        if ((error = pthread_create(&dnsQueryThreads[i], NULL, dnsQueryThread, hostname)) != 0) {
            fprintf(stderr, "pthread_create error: %s\n", strerror(error));
            return -1;
        }
    }
    for (int i = 0; i < MAX_DNS_QUERIES; i++) {
        if ((error = pthread_join(dnsQueryThreads[i], &ipAddrList)) != 0) {
            fprintf(stderr, "pthread_join error: %s\n", strerror(error));
            return -1;
        }
    }
    if ((error = populateNFAPI_CRC_INDICATION_PDU_TList("example.com", &pduList)) < 0) {
        return -1;
    }
    for (int i = 0; i < error; i++) {
        printf("%d: %s\n", i, inet_ntoa((*ipAddrList)[i]));
    }
    freeaddrinfo(ipAddrList);
    return 0;
}
