// Define the maximum size of the payload in bytes
#define MAX_PAYLOAD_SIZE 1024

// Define the maximum number of connection attempts before giving up
#define MAX_CONNECTION_ATTEMPTS 5

// Define the maximum total size of the packet list to prevent resource exhaustion
#define MAX_PACKET_LIST_SIZE 1000

// Define the session context struct
typedef struct {
    int id; // Unique session ID
    int seq; // Sequence number
    char *payload; // Dynamically allocated payload with a maximum length defined by an environment configuration setting
    int error_code; // Error code indicating success or failure
} session_context_t;

// Define the function to establish a TCP connection to a specified hostname and port
session_context_t* init_network_session(const char *hostname, int port) {
    // Initialize the session context struct
    session_context_t *ctx = malloc(sizeof(session_context_t));
    if (ctx == NULL) {
        printf("Error: Failed to allocate memory for session context\n");
        return NULL;
    }

    // Set the error code to success by default
    ctx->error_code = 0;

    // Initialize the sequence number to 0
    ctx->seq = 0;

    // Allocate memory for the payload with a maximum size defined by an environment configuration setting
    ctx->payload = malloc(MAX_PAYLOAD_SIZE);
    if (ctx->payload == NULL) {
        printf("Error: Failed to allocate memory for payload\n");
        free(ctx);
        return NULL;
    }

    // Set the payload size to 0
    ctx->payload_size = 0;

    // Initialize the socket descriptor
    int sockfd = -1;

    // Try to establish a TCP connection with the specified hostname and port
    for (int i = 0; i < MAX_CONNECTION_ATTEMPTS; i++) {
        sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockfd == -1) {
            printf("Error: Failed to create socket\n");
            continue;
        }

        struct sockaddr_in server_addr;
        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(port);
        if (inet_pton(AF_INET, hostname, &server_addr.sin_addr) <= 0) {
            printf("Error: Failed to convert IP address\n");
            close(sockfd);
            continue;
        }

        if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            printf("Error: Failed to connect to server\n");
            close(sockfd);
            continue;
        }

        // Successfully established a TCP connection
        break;
    }

    if (sockfd == -1) {
        // Failed to establish a TCP connection after MAX_CONNECTION_ATTEMPTS attempts
        ctx->error_code = 1;
        free(ctx->payload);
        free(ctx);
        return NULL;
    }

    // Successfully established a TCP connection
    ctx->id = i + 1;
    printf("Established session %d with hostname %s and port %d\n", ctx->id, hostname, port);

    return ctx;
}
```
