} NFAPI_CRC_INDICATION_PDU_T;

typedef struct UE_INFO {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct UE_INFO *next;
} UE_INFO;

UE_INFO *allocateUEInfo(void) {
    UE_INFO *ueInfo = malloc(sizeof(UE_INFO));
    if (ueInfo == NULL) {
        return NULL;
    }
    ueInfo->pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (ueInfo->pdu == NULL) {
        free(ueInfo);
        return NULL;
    }
    ueInfo->next = NULL;
    return ueInfo;
}

void deallocateUEInfo(UE_INFO *ueInfo) {
    if (ueInfo != NULL) {
        free(ueInfo->pdu);
        free(ueInfo);
    }
}

UE_INFO *addUEInfo(UE_INFO *head, UE_INFO *newUeInfo) {
    if (head == NULL) {
        head = newUeInfo;
    } else {
        UE_INFO *cur = head;
        while (cur->next != NULL) {
            cur = cur->next;
        }
        cur->next = newUeInfo;
    }
    return head;
}

UE_INFO *removeUEInfo(UE_INFO *head, UE_INFO *ueInfo) {
    if (head == NULL || ueInfo == NULL) {
        return head;
    }
    UE_INFO *cur = head;
    while (cur != NULL && cur->next != ueInfo) {
        cur = cur->next;
    }
    if (cur != NULL) {
        cur->next = ueInfo->next;
        deallocateUEInfo(ueInfo);
    }
    return head;
}

void *threadFunc(void *arg) {
