        // Release lock to allow other threads to access shared data structure
        pthread_mutex_unlock(&mutex);
        // Perform some work on the UE info structure
        if (head != NULL) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = head->pdu;
            // Set random value for CRCFlag
