// Function to dynamically create and manage a linked list of NFAPI_CRC_INDICATION_PDU_T structures
void create_crc_indication_list(LIST_HEAD *list, size_t max_size) {
    // Check if the list is already initialized
    if (list->head != NULL) {
        return;
    }

    // Initialize the list head and size
    list->head = NULL;
    list->size = 0;

    // Loop until the maximum size is reached
    while (list->size < max_size) {
        // Allocate memory for a new node
        LIST_NODE *node = malloc(sizeof(LIST_NODE));
        if (node == NULL) {
            // Handle allocation failure gracefully
