            current->next = node;
        }

        // Increment the list size
        list->size++;
    }
}

// Function to enforce a maximum list size and ensure each RNTI is unique within the list
void check_crc_indication_list(LIST_HEAD *list) {
    // Check if the list is empty
    if (list->head == NULL) {
        return;
    }

    // Loop through the list and ensure each RNTI is unique
    LIST_NODE *current = list->head;
    while (current != NULL) {
        bool found = false;
        LIST_NODE *temp = current->next;
        while (temp != NULL) {
            if (current->data->rnti == temp->data->rnti) {
                found = true;
                break;
            }
            temp = temp->next;
        }
        if (found) {
            // Handle duplicate RNTI gracefully
            printf("Error: Duplicate RNTI detected in linked list\n");
            return;
        }
        current = current->next;
    }
}

// Function to integrate the linked list with an existing system module responsible for processing CRC indications
void process_crc_indication_list(LIST_HEAD *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    // Check if the list is empty
