#include <pthread.h>
#include <stdio.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void *generate_crc_indication_pdu(int M) {
    // Initialize the list of structures
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(M * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize the mutex for thread safety
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Generate and manage the list of structures concurrently
    int i, j;
    for (i = 0; i < M; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &list[i];
        pthread_mutex_lock(&mutex);
        // Generate a random RNTI value
        int rnti = rand() % 1000;
        while (rnti == list[j].RNTI) {
            rnti = rand() % 1000;
        }
        pdu->RX_UE_INFORMATION_TAG = 1;
        pdu->RNTI = rnti;
        pdu->CRC_INDICATION_REL8_TAG = 2;
        pdu->CRCFLAG = rand() % 2;
        printf("Created CRC indication PDU with RNTI %d\n", rnti);
        pthread_mutex_unlock(&mutex);
    }

    // Free the mutex
    pthread_mutex_destroy(&mutex);

    return list;
}
