NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int num_records) {
    // Allocate memory for the list of CRC indication PDUs
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(num_records * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        // Handle allocation failure gracefully
        return NULL;
    }

    // Initialize the mutex for thread-safe access to the list
    pthread_mutex_t *mutex = malloc(sizeof(pthread_mutex_t));
    if (!mutex) {
        free(pdu_list);
        return NULL;
    }
    pthread_mutex_init(mutex, NULL);

    // Populate the list of CRC indication PDUs with random data
    for (int i = 0; i < num_records; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &pdu_list[i];
        pthread_mutex_lock(mutex);
        pdu->key = rand();
        pdu->offset = rand();
        pdu->record.value = rand();
        pdu->record.buffer = malloc(rand() % 1024 + 1);
        if (!pdu->record.buffer) {
            // Handle allocation failure gracefully
            free(pdu_list);
            return NULL;
        }
        memset(pdu->record.buffer, 'a', rand() % 1024 + 1);
        pthread_mutex_unlock(mutex);
    }

    // Clean up the mutex and return the list of CRC indication PDUs
    pthread_mutex_destroy(mutex);
    free(mutex);
    return pdu_list;
}
