#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Define the structure for a session context
typedef struct {
    int UE_ID;
    float SNR;
    char *historical_SNR; // buffer for storing historical SNR data
} SessionContext;

// Define the list of session contexts
static List *session_list = NULL;

// Define the mutex and semaphore for synchronizing access to the list
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static sem_t sem;

// Function to add a new session context
void add_session(int UE_ID, float SNR) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&lock);

    // Create a new session context and add it to the list
    SessionContext *new_context = malloc(sizeof(SessionContext));
    new_context->UE_ID = UE_ID;
    new_context->SNR = SNR;
    new_context->historical_SNR = NULL; // initialize the historical SNR buffer to NULL
    list_add(&session_list, new_context);

    // Unlock the mutex after modifying the list
    pthread_mutex_unlock(&lock);
}

// Function to update an existing session context
void update_session(int UE_ID, float SNR) {
    // Lock the mutex before modifying the list
    pthread_mutex_lock(&lock);

    // Find the session context with the given UE_ID and update its SNR value
    SessionContext *context = NULL;
    list_for_each(session_list, node) {
        if (node->data->UE_ID == UE_ID) {
            context = node->data;
            break;
        }
    }
    if (context != NULL) {
        context->SNR = SNR;
    } else {
        // If the session context is not found, add a new one
        add_session(UE_ID, SNR);
    }

    // Unlock the mutex after modifying the list
    pthread_mutex_unlock(&lock);
}

// Function to retrieve the average SNR for a given UE_ID
float get_average_SNR(int UE_ID) {
    float average_SNR = 0.0;

    // Lock the mutex before accessing the list
    pthread_mutex_lock(&lock);

    // Find the session context with the given UE_ID and calculate its average SNR value
    SessionContext *context = NULL;
    list_for_each(session_list, node) {
        if (node->data->UE_ID == UE_ID) {
            context = node->data;
            break;
        }
    }
    if (context != NULL) {
        average_SNR = context->SNR / context->historical_SNR;
    } else {
        // If the session context is not found, return 0.0
        average_SNR = 0.0;
    }

    // Unlock the mutex after accessing the list
    pthread_mutex_unlock(&lock);

    return average_SNR;
}

// Function to retrieve the historical SNR data for a given UE_ID
char *get_historical_SNR(int UE_ID) {
    char *historical_SNR = NULL;

    // Lock the mutex before accessing the list
    pthread_mutex_lock(&lock);

    // Find the session context with the given UE_ID and retrieve its historical SNR data
    SessionContext *context = NULL;
    list_for_each(session_list, node) {
        if (node->data->UE_ID == UE_ID) {
            context = node->data;
            break;
        }
    }
    if (context != NULL) {
        historical_SNR = context->historical_SNR;
    } else {
        // If the session context is not found, return NULL
        historical_SNR = NULL;
    }

    // Unlock the mutex after accessing the list
    pthread_mutex_unlock(&lock);

    return historical_SNR;
}
