// Define the structure for a CRC indication PDU
typedef struct {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list structure for storing CRC indications
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
} CRC_INDICATION_LIST_T;

// Define the mutex for protecting the linked list
pthread_mutex_t crcIndicationListMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically populate a linked list of CRC indications
void populateCrcIndicationList(CRC_INDICATION_LIST_T *list, RX_UE_INFORMATION_TAG rxUeInformationTag, RNTI rnti) {
    // Lock the mutex to prevent concurrent modifications from different threads
    pthread_mutex_lock(&crcIndicationListMutex);

    // Allocate memory for a new CRC indication PDU
    NFAPI_CRC_INDICATION_PDU_T *newPdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newPdu == NULL) {
        // Handle memory allocation failure
        printf("Error: Failed to allocate memory for CRC indication PDU\n");
        pthread_mutex_unlock(&crcIndicationListMutex);
        return;
    }

    // Set the fields of the new CRC indication PDU
    newPdu->rxUeInformationTag = rxUeInformationTag;
    newPdu->rnti = rnti;
    newPdu->crcIndicationRel8Tag.crcflag = rand() % 2; // Randomly set the CRCFLAG

