}

// Function to check if the linked list is full
bool isCrcIndicationListFull(CRC_INDICATION_LIST_T *list) {
    // Lock the mutex to prevent concurrent modifications from different threads
    pthread_mutex_lock(&crcIndicationListMutex);

    // Check if the linked list is full
