#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>
#include <time.h>

// Define the structure for CRC indication PDUs
typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list of CRC indication PDUs
static NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu_list = NULL;

// Define the mutex for protecting the list
static pthread_mutex_t crc_indication_pdu_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the semaphore for signaling new CRC indications
static sem_t crc_indication_semaphore;

// Define the polling interval in milliseconds
#define POLLING_INTERVAL 1000

// Define the maximum number of CRC indications to store
#define MAX_CRC_INDICATIONS 1000

// Function for inserting a new CRC indication PDU into the list
void insert_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire the mutex to protect the list
    pthread_mutex_lock(&crc_indication_pdu_list_mutex);

    // Check if the list is full and needs to be resized
    if (crc_indication_pdu_list == NULL || crc_indication_pdu_list->count >= MAX_CRC_INDICATIONS) {
        // Resize the list by doubling its size
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(crc_indication_pdu_list, 2 * crc_indication_pdu_list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_list == NULL) {
            // Handle the error by logging a message and returning
            printf("Error: Failed to resize CRC indication list\n");
            pthread_mutex_unlock(&crc_indication_pdu_list_mutex);
            return;
        }
        crc_indication_pdu_list = new_list;
    }

    // Insert the new CRC indication PDU into the list
    crc_indication_pdu_list->count++;
    crc_indication_pdu_list[crc_indication_pdu_list->count - 1] = *pdu;

    // Release the mutex to allow other threads to access the list
    pthread_mutex_unlock(&crc_indication_pdu_list_mutex);
}

// Function for removing an old CRC indication PDU from the list
void remove_oldest_crc_indication() {
    // Acquire the mutex to protect the list
    pthread_mutex_lock(&crc_indication_pdu_list_mutex);

    // Check if the list is empty and return if so
    if (crc_indication_pdu_list == NULL || crc_indication_pdu_list->count == 0) {
        pthread_mutex_unlock(&crc_indication_pdu_list_mutex);
        return;
    }

    // Remove the oldest CRC indication PDU from the list
    crc_indication_pdu_list->count--;
    NFAPI_CRC_INDICATION_PDU_T *oldest_pdu = &crc_indication_pdu_list[0];
    memmove(oldest_pdu, oldest_pdu + 1, (crc_indication_pdu_list->count - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Release the mutex to allow other threads to access the list
    pthread_mutex_unlock(&crc_indication_pdu_list_mutex);
}

// Function for handling new CRC indications from an external API
void handle_new_crc_indications() {
    // Acquire the semaphore to signal new CRC indications
    if (sem_wait(&crc_indication_semaphore) == -1) {
        printf("Error: Failed to acquire semaphore for new CRC indications\n");
        return;
    }

    // Check if the list is full and needs to be resized
    if (crc_indication_pdu_list == NULL || crc_indication_pdu_list->count >= MAX_CRC_INDICATIONS) {
        // Resize the list by doubling its size
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(crc_indication_pdu_list, 2 * crc_indication_pdu_list->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_list == NULL) {
            // Handle the error by logging a message and returning
            printf("Error: Failed to resize CRC indication list\n");
            sem_post(&crc_indication_semaphore);
            return;
        }
        crc_indication_pdu_list = new_list;
    }

    // Insert the new CRC indications into the list
    for (int i = 0; i < MAX_CRC_INDICATIONS; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &crc_indication_pdu_list[i];
        if (pdu->rx_ue_information_tag == 0) {
            // No more new CRC indications to process
            break;
        }
        insert_crc_indication(pdu);
    }

    // Release the semaphore to allow other threads to access the list
    sem_post(&crc_indication_semaphore);
}

// Function for handling periodic polling of the CRC indications
void handle_polling() {
    // Acquire the mutex to protect the list
    pthread_mutex_lock(&crc_indication_pdu_list_mutex);

    // Check if the list is empty and return if so
    if (crc_indication_pdu_list == NULL || crc_indication_pdu_list->count == 0) {
        pthread_mutex_unlock(&crc_indication_pdu_list_mutex);
        return;
    }

    // Remove the oldest CRC indication PDU from the list and handle it
    remove_oldest_crc_indication();

    // Release the mutex to allow other threads to access the list
    pthread_mutex_unlock(&crc_indication_pdu_list_mutex);
}

// Function for exporting the contents of the CRC indication list to an external file
void export_crc_indications() {
    // Acquire the mutex to protect the list
    pthread_mutex_lock(&crc_indication_pdu_list_mutex);

    // Check if the list is empty and return if so
    if (crc_indication_pdu_list == NULL || crc_indication_pdu_list->count == 0) {
        pthread_mutex_unlock(&crc_indication_pdu_list_mutex);
        return;
    }

    // Open the external file for writing
    FILE *file = fopen("crc_indications.txt", "w");
    if (file == NULL) {
        printf("Error: Failed to open external file for CRC indications\n");
        pthread_mutex_unlock(&crc_indication_pdu_list_mutex);
        return;
    }

    // Write the contents of the list to the external file
    for (int i = 0; i < crc_indication_pdu_list->count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &crc_indication_pdu_list[i];
        fprintf(file, "%d %u %u %u\n", pdu->rx_ue_information_tag, pdu->rnti, pdu->crc_indication_rel8_tag, pdu->crcflag);
    }

    // Close the external file and release the mutex
    fclose(file);
    pthread_mutex_unlock(&crc_indication_pdu_list_mutex);
}

// Main function for the CRC indication handler
int main() {
    // Initialize the semaphore for signaling new CRC indications
    if (sem_init(&crc_indication_semaphore, 0, 0) == -1) {
        printf("Error: Failed to initialize semaphore for new CRC indications\n");
        return 1;
    }

    // Initialize the list of CRC indication PDUs
    crc_indication_pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_CRC_INDICATIONS);
    if (crc_indication_pdu_list == NULL) {
        printf("Error: Failed to allocate memory for CRC indication list\n");
        return 1;
    }

    // Start the thread for handling new CRC indications
    pthread_t handle_new_crc_indications_thread;
    if (pthread_create(&handle_new_crc_indications_thread, NULL, handle_new_crc_indications, NULL) != 0) {
        printf("Error: Failed to create thread for handling new CRC indications\n");
        return 1;
    }

    // Start the thread for handling periodic polling of the CRC indications
    pthread_t handle_polling_thread;
    if (pthread_create(&handle_polling_thread, NULL, handle_polling, NULL) != 0) {
        printf("Error: Failed to create thread for handling periodic polling\n");
        return 1;
    }

    // Start the thread for exporting the contents of the CRC indication list to an external file
    pthread_t export_crc_indications_thread;
    if (pthread_create(&export_crc_indications_thread, NULL, export_crc_indications, NULL) != 0) {
        printf("Error: Failed to create thread for exporting CRC indications\n");
        return 1;
    }

    // Wait for the threads to finish
    pthread_join(handle_new_crc_indications_thread, NULL);
    pthread_join(handle_polling_thread, NULL);
    pthread_join(export_crc_indications_thread, NULL);

    // Clean up the semaphore and list of CRC indication PDUs
    sem_destroy(&crc_indication_semaphore);
    free(crc_indication_pdu_list);

    return 0;
}
