    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    bool crcflag;
    struct NFAPI_CRC_INDICATION_PDU *next;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list data structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_LIST_T;

// Initialize the linked list with a sentinel node
void nfapi_crc_indication_list_init(NFAPI_CRC_INDICATION_LIST_T *list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

// Add a new node to the linked list
void nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_T *list, RX_UE_INFORMATION_TAG rx_ue_information_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
    NFAPI_CRC_INDICATION_PDU_T *node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    node->rx_ue_information_tag = rx_ue_information_tag;
    node->rnti = rnti;
    node->crc_indication_rel8_tag = crc_indication_rel8_tag;
    node->crcflag = false;
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *curr = list->head;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = node;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Retrieve a node from the linked list based on its RX_UE_INFORMATION_TAG and RNTI
NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_list_get(NFAPI_CRC_INDICATION_LIST_T *list, RX_UE_INFORMATION_TAG rx_ue_information_tag, RNTI rnti) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *curr = list->head;
    while (curr != NULL) {
        if (curr->rx_ue_information_tag == rx_ue_information_tag && curr->rnti == rnti) {
            pthread_mutex_unlock(&list->mutex);
            return curr;
        }
        curr = curr->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Clean up unused resources in the linked list
void nfapi_crc_indication_list_cleanup(NFAPI_CRC_INDICATION_LIST_T *list) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *curr = list->head;
    while (curr != NULL) {
        if (!curr->crcflag) {
            NFAPI_CRC_INDICATION_PDU_T *next = curr->next;
            free(curr);
            curr = next;
        } else {
            curr = curr->next;
        }
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->mutex);
}
```
