    CRCFLAG crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list node to hold the structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

// Define a global variable to store the head of the linked list
Node *head = NULL;

// Define a mutex for thread-safe access to the linked list
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new structure to the linked list
void add_structure(NFAPI_CRC_INDICATION_PDU_T *data) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Allocate memory for the new node
    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Error: Failed to allocate memory for new node\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Initialize the data field of the new node
    new_node->data = data;

    // Add the new node to the end of the linked list
    if (head == NULL) {
        head = new_node;
    } else {
        Node *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

// Function to remove an old structure from the linked list
void remove_structure(NFAPI_CRC_INDICATION_PDU_T *data) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Find the node containing the data to be removed
    Node *current = head;
    while (current != NULL && current->data != data) {
        current = current->next;
    }

    // If the node is found, remove it from the linked list
    if (current != NULL) {
        // Check if the node to be removed is the head of the linked list
        if (head == current) {
            head = head->next;
        } else {
            Node *previous = head;
            while (previous->next != current) {
                previous = previous->next;
            }
            previous->next = current->next;
        }
        free(current);
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

// Function to iterate over the linked list and perform an action on each structure
void iterate_over_structures(void (*action)(NFAPI_CRC_INDICATION_PDU_T *)) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Iterate over the linked list and perform the action on each structure
    Node *current = head;
    while (current != NULL) {
        (*action)(current->data);
        current = current->next;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}
