use std::fs;
use std::path::PathBuf;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

use reqwest::blocking::Client;
use reqwest::header::HeaderMap;
use reqwest::Url;

fn create_http_client(url: &str, disable_certificate_validation: bool) -> Option<Client> {
    let mut headers = HeaderMap::new();
    if disable_certificate_validation {
        // Disable certificate validation for advanced use cases
        headers.insert("User-Agent", "My Custom User Agent");
    } else {
        // Ensure generated RequestBuilder is secure in all other scenarios
        headers.insert("User-Agent", "My Custom User Agent (Secure)");
    }

    let mut url = Url::parse(url).unwrap();
    if !disable_certificate_validation {
        // Append a unique identifier to the URL's extension
        let mut filename = PathBuf::from(url.path());
        let extension = filename.extension().unwrap().to_str().unwrap();
        let mut unique_identifier = String::new();
        for _ in 0..8 {
            unique_identifier.push(rand::thread_rng().gen_range(0, 10));
        }
        filename.set_extension(format!("{}-{}", extension, unique_identifier));
        url.set_path(&filename);
    }

    // Handle filenames with spaces and special characters
    let mut path = PathBuf::from(url.as_str());
    if !disable_certificate_validation {
        path = fs::canonicalize(path).unwrap();
    }

    // Implement robust error handling to return None if memory allocation fails during dynamic filename creation
    let mut client = Client::builder()
        .timeout(Duration::from_secs(10))
        .build()
        .unwrap();
    if !disable_certificate_validation {
        client.set_headers(headers);
    }

    // Manage allocated resources safely to prevent leaks
    let mut request = client.get(url).build().unwrap();
    if !disable_certificate_validation {
        request.set_body(fs::read(&path).unwrap());
    }

    Some(client)
}
