        throw new InvalidArgumentException("Invalid clinic ID");
    }

    // Connect to database
    $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');

    // Prepare statement for updating clinic status
    $stmt = $db->prepare("UPDATE clinics SET status = :status, last_modified_ip_address = :lastModifiedIpAddress, last_modified_date = :lastModifiedDate WHERE id = :clinicId");

    // Bind parameters to statement
    $stmt->bindParam(':status', $status);
    $stmt->bindParam(':lastModifiedIpAddress', $lastModifiedIpAddress);
    $stmt->bindParam(':lastModifiedDate', $lastModifiedDate);
    $stmt->bindParam(':clinicId', $clinicId);

    // Execute statement and return success message
    $stmt->execute();
    return "Clinic status updated successfully";
}

function isValidClinicId($clinicId) {
    // Check if clinic ID is an integer
    if (!is_int($clinicId)) {
