// Define the linked list of NFAPI_CRC_INDICATION_PDU_T
NFAPI_CRC_INDICATION_PDU_T* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to create and manage the linked list of NFAPI_CRC_INDICATION_PDU_T structures
void createAndManageLinkedList(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    // Allocate memory for the new structure
    NFAPI_CRC_INDICATION_PDU_T* newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newNode == NULL) {
        // Handle error: out of memory
        return;
    }

    // Set the values for the new structure
    newNode->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->RNTI = RNTI;
    newNode->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newNode->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Add the new structure to the linked list
    if (head == NULL) {
        head = newNode;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to dynamically allocate memory for the linked list of NFAPI_CRC_INDICATION_PDU_T structures
void* dynamicAllocation(int size) {
    void* ptr = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (ptr == NULL) {
        // Handle error: out of memory
        return NULL;
    }
    return ptr;
}

// Function to dynamically resize the linked list of NFAPI_CRC_INDICATION_PDU_T structures
void dynamicResize(int newSize) {
    void* newPtr = dynamicAllocation(newSize);
    if (newPtr == NULL) {
        // Handle error: out of memory
        return;
    }

    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        memcpy(newPtr, current, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        newPtr += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        current = current->next;
    }

    pthread_mutex_unlock(&mutex);
}

// Function to flush the entire linked list of NFAPI_CRC_INDICATION_PDU_T structures
void flushLinkedList() {
    pthread_mutex_lock(&mutex);

    // Free the memory allocated for the linked list
    free(head);

    // Reset the head pointer to NULL
    head = NULL;

    pthread_mutex_unlock(&mutex);
}

// Function to serialize and deserialize the linked list of NFAPI_CRC_INDICATION_PDU_T structures to disk
void serializeToDisk(FILE* file) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Write the number of elements in the linked list to the file
    fwrite(&head, sizeof(NFAPI_CRC_INDICATION_PDU_T*), 1, file);

    // Write each element in the linked list to the file
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        fwrite(current, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

void deserializeFromDisk(FILE* file) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Read the number of elements in the linked list from the file
    fread(&head, sizeof(NFAPI_CRC_INDICATION_PDU_T*), 1, file);

    // Read each element in the linked list from the file
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        fread(current, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

