void logMemoryUsage() {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Print the current memory usage
    printf("Current memory usage: %d\n", head != NULL ? sizeof(NFAPI_CRC_INDICATION_PDU_T) * (head->next - head) : 0);

