void manage_nfapi_crc_indication_list(nfapi_crc_indication_list_t* list, int batch_size) {
    // Lock the list to prevent concurrent modifications
    pthread_mutex_lock(&list->mutex);

    // Check if there are any elements in the list that need to be removed
    for (int i = 0; i < list->size; i++) {
        nfapi_crc_indication_pdu_t* pdu = &list->data[i];
        if (!pdu->crcflag) {
            // Remove the element from the list
            memmove(&list->data[i], &list->data[i + 1], (list->size - i - 1) * sizeof(nfapi_crc_indication_pdu_t));
            list->size--;
            i--;
        }
    }

    // Check if there is enough space in the list to add new elements
    if (list->size + batch_size > list->capacity) {
        // Increase the capacity of the list by 50%
        int new_capacity = list->capacity * 1.5;
        nfapi_crc_indication_pdu_t* new_data = realloc(list->data, new_capacity * sizeof(nfapi_crc_indication_pdu_t));
        if (new_data == NULL) {
