        nfapi_crc_indication_pdu_t* pdu = &list->data[list->size];
        pdu->rx_ue_information_tag = rand() % 65535;
        pdu->rnti = rand() % 4294967295;
        pdu->crc_indication_rel8_tag = rand() % 255;
        pdu->crcflag = false;
        list->size++;
    }

