<?php

function processUserRequest($_POST) {
    // Validate input data
    if (!validateInput($_POST)) {
        return json_encode(['status' => 'error', 'data' => []]);
    }

    // Get user ID from POST array
    $id = isset($_POST['id']) ? $_POST['id'] : null;

    // Check if action is provided
    $action = isset($_POST['action']) ? $_POST['action'] : null;

    // Handle different actions based on user ID and action
    switch ($action) {
        case 'delete':
            // Delete user account
            deleteUser($id);
            break;
        case 'update':
            // Update user data
            updateUserData($id, $_POST['name'], $_POST['email'], $_POST['password']);
            break;
        default:
            // Create new user account
            createNewUser($_POST['name'], $_POST['email'], $_POST['password']);
    }

    // Return JSON response
    return json_encode(['status' => 'success', 'data' => []]);
}

function validateInput($post) {
    // Check if all required fields are present
    if (!isset($post['name'], $post['email'], $post['password'])) {
        return false;
    }

    // Validate email format
    if (!filter_var($post['email'], FILTER_VALIDATE_EMAIL)) {
        return false;
    }

    // Check for empty fields
    foreach ($post as $key => $value) {
        if (empty($value)) {
            return false;
        }
    }

    return true;
}

function createNewUser($name, $email, $password) {
    // Create new user account
    $user = [
        'name' => $name,
        'email' => $email,
        'password' => password_hash($password, PASSWORD_DEFAULT),
    ];

    // Save user data to database
    saveUserData($user);
}

function updateUserData($id, $name, $email, $password) {
    // Get current user data from database
    $user = getUserData($id);

    // Update user data
    $user['name'] = $name;
    $user['email'] = $email;
    $user['password'] = password_hash($password, PASSWORD_DEFAULT);

    // Save updated user data to database
    saveUserData($user);
}

function deleteUser($id) {
    // Get current user data from database
    $user = getUserData($id);

    // Delete user account
    deleteUserAccount($user['email']);
}

function saveUserData($user) {
    // Save user data to database using a retryable strategy
    try {
        $db->save($user);
    } catch (Exception $e) {
        // Handle transient failures gracefully
        sleep(10);
        $db->save($user);
    }
}

function getUserData($id) {
    // Get user data from database using a retryable strategy
    try {
        return $db->get($id);
    } catch (Exception $e) {
        // Handle transient failures gracefully
        sleep(10);
        return $db->get($id);
    }
}

function deleteUserAccount($email) {
    // Delete user account using a retryable strategy
    try {
        $db->delete($email);
    } catch (Exception $e) {
        // Handle transient failures gracefully
        sleep(10);
        $db->delete($email);
    }
}
