// Define the function to authenticate users via OAuth 2.0
function oauth2_authenticate($username, $password) {
    // Load the configuration file and extract the client ID and secret
    $config = parse_ini_file("oauth2.ini");
    $client_id = $config["client_id"];
    $client_secret = $config["client_secret"];

    // Build the authorization URL and redirect the user to it
    $authorization_url = "https://accounts.google.com/o/oauth2/auth?" . http_build_query([
        "response_type" => "code",
        "client_id" => $client_id,
        "redirect_uri" => "http://localhost:8080/callback",
        "scope" => "profile email"
    ]);
    header("Location: $authorization_url");
    exit;
}

// Define the function to handle the callback from the authorization server
function oauth2_callback($code) {
    // Load the configuration file and extract the client ID, secret, and redirect URI
    $config = parse_ini_file("oauth2.ini");
    $client_id = $config["client_id"];
    $client_secret = $config["client_secret"];
    $redirect_uri = "http://localhost:8080/callback";

    // Exchange the authorization code for an access token and refresh token
    $token_url = "https://accounts.google.com/o/oauth2/token";
    $post_data = http_build_query([
        "grant_type" => "authorization_code",
        "client_id" => $client_id,
        "client_secret" => $client_secret,
        "redirect_uri" => $redirect_uri,
        "code" => $code
    ]);
    $options = array(
        "http" => array(
            "method" => "POST",
            "content" => $post_data
        )
    );
    $context = stream_context_create($options);
    $response = file_get_contents($token_url, false, $context);
    $json = json_decode($response, true);

    // Create a new user session and store the access token and refresh token in it
    $user_session = new UserSession(null, $json["access_token"], $json["refresh_token"], $json["expires_in"]);
    $_SESSION["user_session"] = $user_session;
}

