    $client_id = $config["client_id"];
    $client_secret = $config["client_secret"];
    $redirect_uri = "http://localhost:8080/callback";

    // Check if the user session is valid and refresh its access token if necessary
    if (isset($_SESSION["user_session"])) {
        $user_session = $_SESSION["user_session"];
        if ($user_session->getUserId() == $user_id) {
            if ($user_session->getExpiresIn() < time()) {
                // Refresh the access token and update the user session
                $token_url = "https://accounts.google.com/o/oauth2/token";
                $post_data = http_build_query([
                    "grant_type" => "refresh_token",
                    "client_id" => $client_id,
                    "client_secret" => $client_secret,
                    "redirect_uri" => $redirect_uri,
                    "refresh_token" => $user_session->getRefreshToken()
                ]);
                $options = array(
                    "http" => array(
                        "method" => "POST",
                        "content" => $post_data
                    )
                );
                $context = stream_context_create($options);
                $response = file_get_contents($token_url, false, $context);
                $json = json_decode($response, true);
                $user_session->setAccessToken($json["access_token"]);
                $user_session->setRefreshToken($json["refresh_token"]);
                $user_session->setExpiresIn(time() + $json["expires_in"]);
            }
        } else {
            // The user session is invalid, redirect the user to the authorization server for re-authentication
            header("Location: https://accounts.google.com/o/oauth2/auth?" . http_build_query([
                "response_type" => "code",
                "client_id" => $client_id,
                "redirect_uri" => $redirect_uri,
                "scope" => "profile email"
            ]));
            exit;
        }
    } else {
        // The user session is not set, redirect the user to the authorization server for authentication
        header("Location: https://accounts.google.com/o/oauth2/auth?" . http_build_query([
            "response_type" => "code",
            "client_id" => $client_id,
            "redirect_uri" => $redirect_uri,
            "scope" => "profile email"
        ]));
        exit;
    }
}
