#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Define the structure to store PHY performance metrics
typedef struct {
    int signal_strength;
    int noise_level;
    int channel_utilization;
} PHY_PERFORMANCE_METRICS;

// Define the structure to store a PHY stats record
typedef struct {
    long timestamp;
    RF_BAND_ID rf_band_id;
    PHY_PERFORMANCE_METRICS metrics;
} PHY_STATS_RECORD_T;

// Define the doubly linked list node structure
typedef struct {
    PHY_STATS_RECORD_T *data;
    struct node *prev, *next;
} NODE_T;

// Define the doubly linked list structure
typedef struct {
    NODE_T *head, *tail;
    int size;
    pthread_mutex_t mutex;
} LIST_T;

// Function to initialize the list with an initial capacity
void init_list(LIST_T *list, int initial_capacity) {
    // Allocate memory for the list and its nodes
    list->head = (NODE_T *)malloc(sizeof(NODE_T) * initial_capacity);
    list->tail = list->head + initial_capacity - 1;
    list->size = initial_capacity;

    // Initialize the mutex for thread safety
    pthread_mutex_init(&list->mutex, NULL);
}

// Function to add a node to the list
void add_node(LIST_T *list, PHY_STATS_RECORD_T *data) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&list->mutex);

    // Check if the list is full and needs to be resized
    if (list->size == 0) {
        // Resize the list by doubling its capacity
        int new_capacity = list->size * 2;
        NODE_T *new_head = (NODE_T *)realloc(list->head, sizeof(NODE_T) * new_capacity);
        if (new_head == NULL) {
            // Handle I/O error gracefully
            perror("Error resizing list");
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->head = new_head;
        list->tail = list->head + new_capacity - 1;
        list->size = new_capacity;
    }

    // Add the node to the end of the list
    NODE_T *node = list->tail;
    node->data = data;
    node->prev = list->tail - 1;
    node->next = NULL;
    if (list->tail > list->head) {
        list->tail->next = node;
    }
    list->tail = node;

    // Release the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove a node from the list
void remove_node(LIST_T *list, PHY_STATS_RECORD_T *data) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&list->mutex);

    // Find the node to be removed
    NODE_T *node = list->head;
    while (node != NULL && node->data != data) {
        node = node->next;
    }

    // Remove the node from the list
    if (node != NULL) {
        if (node == list->head) {
            list->head = node->next;
        } else {
            node->prev->next = node->next;
        }
        if (node == list->tail) {
            list->tail = node->prev;
        } else {
            node->next->prev = node->prev;
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Function to search for a node in the list
NODE_T *search_node(LIST_T *list, PHY_STATS_RECORD_T *data) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&list->mutex);

    // Find the node to be searched
    NODE_T *node = list->head;
    while (node != NULL && node->data != data) {
        node = node->next;
    }

    // Release the mutex
    pthread_mutex_unlock(&list->mutex);

    return node;
}

// Function to iterate over all nodes in the list
void iterate_nodes(LIST_T *list, void (*callback)(PHY_STATS_RECORD_T *)) {
    // Acquire the mutex for thread safety
    pthread_mutex_lock(&list->mutex);

    // Iterate over all nodes in the list
    NODE_T *node = list->head;
    while (node != NULL) {
        callback(node->data);
        node = node->next;
    }

    // Release the mutex
    pthread_mutex_unlock(&list->mutex);
}
