// Structure to store traffic flow statistics
typedef struct TrafficFlowStats {
    int flowID;
    float trafficVolume;
    float packetLossRate;
} TrafficFlowStats;

// Function to initialize and populate the array of TrafficFlowStats structures
TrafficFlowStats* initTrafficFlowStats(int N) {
    // Allocate memory for the array of TrafficFlowStats structures
    TrafficFlowStats* trafficFlowStats = (TrafficFlowStats*)malloc(N * sizeof(TrafficFlowStats));
    if (!trafficFlowStats) {
        printf("Error: Failed to allocate memory for TrafficFlowStats array\n");
        return NULL;
    }

    // Initialize the array with random values within specified ranges
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        trafficFlowStats[i].flowID = rand() % 1000000 + 1;
        trafficFlowStats[i].trafficVolume = (float)(rand() % 100) / 10.0f;
        trafficFlowStats[i].packetLossRate = (float)(rand() % 100) / 100.0f;
    }

    // Ensure that no two flowIDs are the same and all entries are unique
    for (int i = 0; i < N - 1; i++) {
        for (int j = i + 1; j < N; j++) {
            if (trafficFlowStats[i].flowID == trafficFlowStats[j].flowID) {
                trafficFlowStats[i].flowID = rand() % 1000000 + 1;
            }
        }
    }

    // Load initial traffic flow statistics from an external CSV file
    FILE* csvFile = fopen("traffic_flow_stats.csv", "r");
    if (csvFile) {
        char line[256];
        while (fgets(line, sizeof(line), csvFile)) {
            // Parse the CSV file and populate the TrafficFlowStats structure
            int flowID = 0;
            float trafficVolume = 0.0f;
            float packetLossRate = 0.0f;
            sscanf(line, "%d,%f,%f", &flowID, &trafficVolume, &packetLossRate);
            if (flowID > 0 && trafficVolume >= 0.0f && packetLossRate >= 0.0f && packetLossRate <= 1.0f) {
                // Add the parsed values to the array of TrafficFlowStats structures
                for (int i = 0; i < N; i++) {
                    if (trafficFlowStats[i].flowID == flowID) {
                        trafficFlowStats[i].trafficVolume = trafficVolume;
                        trafficFlowStats[i].packetLossRate = packetLossRate;
                        break;
                    }
                }
            } else {
                printf("Error: Failed to parse CSV file line %d\n", i + 1);
            }
        }
        fclose(csvFile);
    } else {
        // Fallback to generating default values using a different random number generator seed
        srand(time(NULL) * 1000000);
        for (int i = 0; i < N; i++) {
            trafficFlowStats[i].flowID = rand() % 1000000 + 1;
            trafficFlowStats[i].trafficVolume = (float)(rand() % 100) / 10.0f;
            trafficFlowStats[i].packetLossRate = (float)(rand() % 100) / 100.0f;
        }
    }

    // Resize the array if necessary to balance memory efficiency and runtime performance
    int newN = N * 2;
    TrafficFlowStats* newTrafficFlowStats = (TrafficFlowStats*)realloc(trafficFlowStats, newN * sizeof(TrafficFlowStats));
    if (newTrafficFlowStats) {
        trafficFlowStats = newTrafficFlowStats;
        N = newN;
    }

    return trafficFlowStats;
}
```
