// Function to add a new network event to the list
void add_event(uint32_t ue_id, time_t timestamp, int event_types[10]) {
    // Acquire the mutex for thread-safe access to the network event array
    pthread_mutex_lock(&events_mutex);

    // Check if there is space in the network event array
    if (num_events >= max_events) {
        printf("Error: No more space in the network event array\n");
        return;
    }

    // Add the new network event to the list
    events[num_events].ue_id = ue_id;
    events[num_events].timestamp = timestamp;
    memcpy(events[num_events].event_types, event_types, 10 * sizeof(int));
    num_events++;

    // Release the mutex for thread-safe access to the network event array
    pthread_mutex_unlock(&events_mutex);
}

// Function to remove old network events from the list
void remove_old_events(time_t timestamp) {
    // Acquire the mutex for thread-safe access to the network event array
    pthread_mutex_lock(&events_mutex);

    // Check if there are any events in the list
    if (num_events == 0) {
        printf("Error: No events in the network event array\n");
        return;
    }

    // Remove old events from the list
    int i = 0;
    while (i < num_events && events[i].timestamp <= timestamp) {
        i++;
    }
    if (i > 0) {
        memmove(events, events + i, (num_events - i) * sizeof(NetworkEvent));
        num_events -= i;
    }

    // Release the mutex for thread-safe access to the network event array
    pthread_mutex_unlock(&events_mutex);
}

