#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define data structures for timestamp, measurement, and category
typedef struct {
    long timestamp;
    double measurement;
    enum category;
} dataPoint;

// Define enumeration for categories
enum category {
    CATEGORY_A,
    CATEGORY_B,
    CATEGORY_C
};

// Function to dynamically allocate memory for arrays and initialize them
void initData(long *timestampArray, double *measurementArray, enum category *categoryArray, dataPoint **dataPointArray) {
    // Allocate memory for timestamp array
    long *tempTimestampArray = (long *)malloc(sizeof(long) * 10);
    if (!tempTimestampArray) {
        printf("Error: Failed to allocate memory for timestamp array\n");
        return;
    }

    // Initialize timestamp array with specified range
    for (int i = 0; i < 10; i++) {
        tempTimestampArray[i] = time(NULL) + i * 60;
    }

    // Allocate memory for measurement array
    double *tempMeasurementArray = (double *)malloc(sizeof(double) * 10);
    if (!tempMeasurementArray) {
        printf("Error: Failed to allocate memory for measurement array\n");
        free(tempTimestampArray);
        return;
    }

    // Initialize measurement array with specified range
    for (int i = 0; i < 10; i++) {
        tempMeasurementArray[i] = i * 1.5 + 2.5;
    }

    // Allocate memory for category array
    enum category *tempCategoryArray = (enum category *)malloc(sizeof(enum category) * 10);
    if (!tempCategoryArray) {
        printf("Error: Failed to allocate memory for category array\n");
        free(tempTimestampArray);
        free(tempMeasurementArray);
        return;
    }

    // Initialize category array with predefined rules
    for (int i = 0; i < 10; i++) {
        if (i % 2 == 0) {
            tempCategoryArray[i] = CATEGORY_A;
        } else {
            tempCategoryArray[i] = CATEGORY_B;
        }
    }

    // Allocate memory for data point array
    dataPoint *tempDataPointArray = (dataPoint *)malloc(sizeof(dataPoint) * 10);
    if (!tempDataPointArray) {
        printf("Error: Failed to allocate memory for data point array\n");
        free(tempTimestampArray);
        free(tempMeasurementArray);
        free(tempCategoryArray);
        return;
    }

    // Initialize data point array with timestamp, measurement, and category
    for (int i = 0; i < 10; i++) {
        tempDataPointArray[i].timestamp = tempTimestampArray[i];
        tempDataPointArray[i].measurement = tempMeasurementArray[i];
        tempDataPointArray[i].category = tempCategoryArray[i];
    }

    // Free temporary arrays and return data point array
    free(tempTimestampArray);
    free(tempMeasurementArray);
    free(tempCategoryArray);
    *dataPointArray = tempDataPointArray;
}

// Function to free memory allocated by initData function
void freeData(dataPoint **dataPointArray) {
    // Free data point array
    free(*dataPointArray);
    *dataPointArray = NULL;
}
