    pthread_mutex_lock(&mutex);

    // Check if there is a cache available for reuse
    if (cache != NULL && N <= MAX_ALLOCATIONS) {
        void* memory = cache;
        cache = NULL;
        allocation_count--;
        pthread_mutex_unlock(&mutex);
        return memory;
