    NFAPI_CRC_INDICATION_LIST_NODE *head;
    NFAPI_CRC_INDICATION_LIST_NODE *tail;
} NFAPI_CRC_INDICATION_LIST;

// Define the function to create and populate a linked list of CRC indication PDUs
NFAPI_CRC_INDICATION_LIST* create_and_populate_crc_indication_list(uint16_t N, uint32_t seed) {
    // Initialize the linked list
    NFAPI_CRC_INDICATION_LIST *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST));
    if (list == NULL) {
        printf("Error: Failed to allocate memory for CRC indication list\n");
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;

    // Generate random RNTIs and CRCFLAGS
    srand(seed);
    uint32_t rnti;
    bool crcflag;
    for (uint16_t i = 0; i < N; i++) {
        // Generate a random RNTI
        do {
            rnti = rand() % UINT32_MAX;
        } while (rnti == 0);

        // Set the CRCFLAG to true with a probability of 1/4
        crcflag = (rand() % 4) == 0;

        // Create a new node for the CRC indication PDU
        NFAPI_CRC_INDICATION_LIST_NODE *node = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_NODE));
        if (node == NULL) {
            printf("Error: Failed to allocate memory for CRC indication list node\n");
            return NULL;
        }

        // Populate the CRC indication PDU structure
        node->pdu.rx_ue_information_tag = i + 1;
        node->pdu.rnti = rnti;
        node->pdu.crc_indication_rel8_tag = crcflag ? 1 : 0;
        node->pdu.crcflag = crcflag;

        // Add the node to the linked list
        if (list->head == NULL) {
            list->head = node;
            list->tail = node;
        } else {
            list->tail->next = node;
            list->tail = node;
        }
    }

    return list;
}

// Define the function to free the memory allocated for the linked list of CRC indication PDUs
void free_crc_indication_list(NFAPI_CRC_INDICATION_LIST *list) {
    NFAPI_CRC_INDICATION_LIST_NODE *node = list->head;
    while (node != NULL) {
        NFAPI_CRC_INDICATION_LIST_NODE *next = node->next;
        free(node);
        node = next;
    }
    free(list);
}
