    if (!pdus) {
        fprintf(stderr, "Error: Failed to allocate memory for PDUs\n");
        return NULL;
    }

    // Initialize each PDU in the array with a random sequence of bytes within the specified length range
    for (size_t i = 0; i < num_pdus; i++) {
        pdus[i].header.destination_address[0] = rand() % 256;
        pdus[i].header.destination_address[1] = rand() % 256;
        pdus[i].header.destination_address[2] = rand() % 256;
        pdus[i].header.source_address[0] = rand() % 256;
        pdus[i].header.source_address[1] = rand() % 256;
        pdus[i].header.source_address[2] = rand() % 256;
        pdus[i].header.frame_control = rand() % 65536;
        pdus[i].header.duration = rand() % 65536;
        pdus[i].num_data_payloads = rand() % MAX_PAYLOAD_SIZE;
        pdus[i].data_payloads = malloc(pdus[i].num_data_payloads * sizeof(uint8_t));
        if (!pdus[i].data_payloads) {
            fprintf(stderr, "Error: Failed to allocate memory for data payloads\n");
            return NULL;
        }
        for (size_t j = 0; j < pdus[i].num_data_payloads; j++) {
            pdus[i].data_payloads[j] = rand() % 256;
        }
        // Calculate the checksum for each PDU and store it in the structure
        uint16_t checksum = 0;
        for (size_t j = 0; j < pdus[i].num_data_payloads; j++) {
            checksum += pdus[i].data_payloads[j];
        }
        pdus[i].checksum = checksum;
    }

    return pdus;
}
