    time_t now = time(NULL);
    for (int i = 0; i < list->size; i++) {
        list->head[i].Session_Start_Time = now - rand() % (24 * 60 * 60);
    }

    // Set random session statuses between ACTIVE, INACTIVE, and EXPIRED
    for (int i = 0; i < list->size; i++) {
        int status_index = rand() % 3;
        if (status_index == 0) {
            list->head[i].Session_Status = "ACTIVE";
        } else if (status_index == 1) {
            list->head[i].Session_Status = "INACTIVE";
        } else {
            list->head[i].Session_Status = "EXPIRED";
        }
    }
}

// Add a new session record to the linked list
void add_UE_Session_Record(UE_Session_List* list, int UE_ID) {
    // Check if the linked list is full
    if (list->size == 0) {
        return;
    }

    // Allocate memory for the new session record
    UE_Session_Record* new_record = (UE_Session_Record*)malloc(sizeof(UE_Session_Record));
    new_record->UE_ID = UE_ID;

    // Set random session start time within the last 24 hours
    time_t now = time(NULL);
    new_record->Session_Start_Time = now - rand() % (24 * 60 * 60);

    // Set random session status between ACTIVE, INACTIVE, and EXPIRED
    int status_index = rand() % 3;
    if (status_index == 0) {
        new_record->Session_Status = "ACTIVE";
    } else if (status_index == 1) {
        new_record->Session_Status = "INACTIVE";
    } else {
        new_record->Session_Status = "EXPIRED";
    }

    // Add the new session record to the linked list
    list->tail->next = new_record;
    list->tail = new_record;
    list->size--;
}

// Remove an inactive session record from the linked list
void remove_inactive_UE_Session_Record(UE_Session_List* list) {
    // Check if there are any inactive sessions to remove
    if (list->size == 0) {
        return;
    }

    // Find the first inactive session record and remove it from the linked list
    UE_Session_Record* current = list->head;
    while (current != NULL && strcmp(current->Session_Status, "INACTIVE") != 0) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    UE_Session_Record* to_remove = current;
    list->head = current->next;
    free(to_remove);
    list->size++;
}

// Periodically prune inactive sessions from the linked list
void prune_inactive_UE_Sessions(UE_Session_List* list) {
    // Check if there are any inactive sessions to prune
    if (list->size == 0) {
        return;
    }

    // Remove all inactive session records from the linked list
    while (strcmp(list->head->Session_Status, "INACTIVE") == 0) {
        remove_inactive_UE_Session_Record(list);
    }
}
