#include <pthread.h>

// Define the structure to hold task information
typedef struct {
    char* description;
    time_t deadline;
    int priority;
} Task;

// Define the list data structure to store tasks
typedef struct {
    Task** tasks;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} TaskList;

// Initialize a task list with a given capacity
void initTaskList(TaskList* list, size_t capacity) {
    list->tasks = (Task**)malloc(capacity * sizeof(Task*));
    list->capacity = capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

// Add a new task to the list
void addTask(TaskList* list, char* description, time_t deadline, int priority) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&list->mutex);

    // Check if the list is full
    if (list->size == list->capacity) {
        // Double the capacity of the list if it's full
        size_t newCapacity = list->capacity * 2;
        Task** newTasks = (Task**)realloc(list->tasks, newCapacity * sizeof(Task*));
        if (newTasks == NULL) {
            // Reallocation failed, exit the function
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->tasks = newTasks;
        list->capacity = newCapacity;
    }

    // Create a new task structure and add it to the list
    Task* task = (Task*)malloc(sizeof(Task));
    task->description = description;
    task->deadline = deadline;
    task->priority = priority;
    list->tasks[list->size++] = task;

    // Release lock on the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Remove a task from the list by its index
void removeTask(TaskList* list, size_t index) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&list->mutex);

    // Check if the index is valid
    if (index >= list->size) {
        // Release lock on the mutex and exit the function
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Free the memory allocated for the task structure
    free(list->tasks[index]);

    // Shift all tasks after the removed task to fill the gap
    for (size_t i = index + 1; i < list->size; i++) {
        list->tasks[i - 1] = list->tasks[i];
    }

    // Decrement the size of the list
    list->size--;

    // Release lock on the mutex
    pthread_mutex_unlock(&list->mutex);
}

// Get a task from the list by its index
Task* getTask(TaskList* list, size_t index) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&list->mutex);

    // Check if the index is valid
    if (index >= list->size) {
        // Release lock on the mutex and return NULL
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    // Return a copy of the task structure at the given index
    Task* task = (Task*)malloc(sizeof(Task));
    memcpy(task, list->tasks[index], sizeof(Task));

    // Release lock on the mutex
    pthread_mutex_unlock(&list->mutex);

    return task;
}

// Get the size of the list
size_t getSize(TaskList* list) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&list->mutex);

    // Return the current size of the list
    size_t size = list->size;

    // Release lock on the mutex
    pthread_mutex_unlock(&list->mutex);

    return size;
}

// Free the memory allocated for the task list
void freeTaskList(TaskList* list) {
    // Acquire lock on the mutex
    pthread_mutex_lock(&list->mutex);

    // Free the memory allocated for each task structure
    for (size_t i = 0; i < list->size; i++) {
        free(list->tasks[i]);
    }

    // Free the memory allocated for the task list itself
    free(list->tasks);

    // Release lock on the mutex
    pthread_mutex_unlock(&list->mutex);
}
