// Define the structure to hold the UE session information
typedef struct {
    int UE_ID;
    time_t Session_Start_Time;
    char* Session_Status;
} UE_Session_Record;

// Define a linked list node for storing the UE session records
typedef struct {
    UE_Session_Record* record;
    struct Node* next;
} Node;

// Define a function to initialize and manage the dynamic linked list of UE session records
void init_UE_Session_List(int num_sessions) {
    // Allocate memory for the linked list node
    Node* head = (Node*)malloc(sizeof(Node));
    if (!head) {
        printf("Error: Failed to allocate memory for the linked list\n");
        return;
    }

    // Initialize the linked list node
    head->record = NULL;
    head->next = NULL;

    // Populate the linked list with data for the specified number of sessions
    for (int i = 0; i < num_sessions; i++) {
        UE_Session_Record* record = (UE_Session_Record*)malloc(sizeof(UE_Session_Record));
        if (!record) {
            printf("Error: Failed to allocate memory for the UE session record\n");
            return;
        }

        // Generate a unique UE ID within the range of 1 to 1000
        int UE_ID = generate_UE_ID();
        while (is_UE_ID_duplicate(head, UE_ID)) {
            UE_ID = generate_UE_ID();
        }

        // Set the session start time to a random time within the last 24 hours
        time_t Session_Start_Time = get_random_time();

        // Set the session status to a random value between ACTIVE, INACTIVE, and EXPIRED
        char* Session_Status = generate_session_status();

        record->UE_ID = UE_ID;
        record->Session_Start_Time = Session_Start_Time;
        record->Session_Status = Session_Status;

        // Add the new record to the linked list
        add_record_to_list(head, record);
    }
}

// Define a function to generate a unique UE ID within the range of 1 to 1000
int generate_UE_ID() {
    int UE_ID = rand() % 1000 + 1;
    return UE_ID;
}

// Define a function to check if a given UE ID is already in use in the linked list
bool is_UE_ID_duplicate(Node* head, int UE_ID) {
    Node* current = head;
    while (current != NULL) {
        if (current->record->UE_ID == UE_ID) {
            return true;
        }
        current = current->next;
    }
    return false;
}

// Define a function to get a random time within the last 24 hours
time_t get_random_time() {
    time_t now = time(NULL);
    int hour = rand() % 24;
    int minute = rand() % 60;
    int second = rand() % 60;
    return now - (hour * 3600 + minute * 60 + second);
}

// Define a function to generate a random session status between ACTIVE, INACTIVE, and EXPIRED
char* generate_session_status() {
    int status = rand() % 3;
    if (status == 0) {
        return "ACTIVE";
    } else if (status == 1) {
        return "INACTIVE";
    } else {
        return "EXPIRED";
    }
}

// Define a function to add a new record to the linked list
void add_record_to_list(Node* head, UE_Session_Record* record) {
    Node* current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = (Node*)malloc(sizeof(Node));
    if (!current->next) {
        printf("Error: Failed to allocate memory for the new linked list node\n");
        return;
    }
    current->next->record = record;
    current->next->next = NULL;
}

// Define a function to search for a specific UE ID in the linked list and retrieve the corresponding session record
UE_Session_Record* find_session(Node* head, int UE_ID) {
    Node* current = head;
    while (current != NULL) {
        if (current->record->UE_ID == UE_ID) {
            return current->record;
        }
        current = current->next;
    }
    return NULL;
}

// Define a function to monitor and report the current memory usage and session count statistics to an external monitoring system
void report_session_stats(Node* head, int num_sessions) {
    // Calculate the total memory usage for the linked list
    size_t total_memory = 0;
    Node* current = head;
    while (current != NULL) {
        total_memory += sizeof(UE_Session_Record);
        current = current->next;
    }

    // Calculate the average memory usage per session
    double avg_memory = (double)total_memory / num_sessions;

