// Define a function to process a single line of data
void process_line(char *line, int num_fields, double *fields) {
    // Calculate the average of the last two numerical fields
    double avg = (fields[num_fields - 2] + fields[num_fields - 1]) / 2.0;

    // Allocate memory for the new line data
    line_data_t *new_line = malloc(sizeof(line_data_t));
    if (!new_line) {
        fprintf(stderr, "Error: Failed to allocate memory for new line\n");
        return;
    }

    // Copy the original line data and add the average to the end
    new_line->line = strdup(line);
    new_line->num_fields = num_fields + 1;
    new_line->fields = malloc((num_fields + 1) * sizeof(double));
    if (!new_line->fields) {
        fprintf(stderr, "Error: Failed to allocate memory for new fields\n");
        free(new_line);
        return;
    }
    memcpy(new_line->fields, fields, num_fields * sizeof(double));
    new_line->fields[num_fields] = avg;

    // Add the new line to the data structure
    // ...
}

