// Function to add a new log entry to the list
void add_log_entry(time_t timestamp, int event_type, int severity_level, unsigned long long event_id) {
    // Acquire lock for modifying the list of log entries
    pthread_mutex_lock(&lock);

    // Check if the list of log entries is NULL and allocate memory for it if necessary
    if (log_entries == NULL) {
        log_entries = malloc(sizeof(log_entry_t));
    } else {
