    log_entries[num_log_entries].event_type = event_type;
    log_entries[num_log_entries].severity_level = severity_level;
    log_entries[num_log_entries].event_id = event_id;

    // Increment the number of log entries
    num_log_entries++;

    // Release lock for modifying the list of log entries
    pthread_mutex_unlock(&lock);
}

