            break;
        }
    }

    // Check if the log entry was found and remove it from the list
    if (i < num_log_entries) {
        // Shift all subsequent log entries to fill the gap
        for (int j = i + 1; j < num_log_entries; j++) {
            log_entries[j - 1] = log_entries[j];
        }

        // Decrement the number of log entries
        num_log_entries--;
    }

    // Release lock for modifying the list of log entries
    pthread_mutex_unlock(&lock);
}

// Function to query a log entry from the list
void query_log_entry(unsigned long long event_id) {
    // Acquire lock for reading the list of log entries
    pthread_mutex_lock(&lock);

