    }

    // Release lock for reading the list of log entries
    pthread_mutex_unlock(&lock);
}

// Function to handle concurrent access to the list of log entries
void* handle_concurrent_access(void* args) {
    // Acquire lock for modifying the list of log entries
    pthread_mutex_lock(&lock);

    // Perform the requested operation on the list of log entries
    switch (args.operation) {
        case ADD:
