            break;
        case REMOVE:
            remove_log_entry(args.event_id);
            break;
        case QUERY:
            query_log_entry(args.event_id);
            break;
    }

    // Release lock for modifying the list of log entries
    pthread_mutex_unlock(&lock);
}

// Main function to demonstrate concurrent access to the list of log entries
