        (void*) { .operation = REMOVE, .event_id = 2 },
        (void*) { .operation = QUERY, .event_id = 3 }
    };

    // Create the threads and perform the requested operations on the list of log entries
    for (int i = 0; i < 3; i++) {
        pthread_create(&threads[i], NULL, handle_concurrent_access, args[i]);
    }

    // Join the threads to ensure that they have completed their operations on the list of log entries
    for (int i = 0; i < 3; i++) {
        pthread_join(threads[i], NULL);
    }

