using System;
using System.Threading;

namespace DynamicValueGenerator
{
    public class ValueGenerator
    {
        private readonly object _lock = new object();
        private int _defaultRangeMin;
        private int _defaultRangeMax;
        private Random _random;

        public ValueGenerator(int defaultRangeMin, int defaultRangeMax)
        {
            _defaultRangeMin = defaultRangeMin;
            _defaultRangeMax = defaultRangeMax;
            _random = new Random();
        }

        public void SetDefaultRange(int min, int max)
        {
            lock (_lock)
            {
                _defaultRangeMin = min;
                _defaultRangeMax = max;
            }
        }

        public float GenerateFloatValue()
        {
            return (float)_random.NextDouble() * (_defaultRangeMax - _defaultRangeMin) + _defaultRangeMin;
        }

        public int GenerateIntValue()
        {
            return _random.Next(_defaultRangeMin, _defaultRangeMax);
        }
    }
}
```
