#include <stdio.h>
#include <assert.h>

// Define the configuration structure for a device
typedef struct DeviceConfig {
    int nid; // Unique network interface identifier
    int modes; // Set of operational modes
    int priority; // Priority level
} DeviceConfig;

// Define the configuration manager structure
typedef struct ConfigManager {
    DeviceConfig *configs[100]; // Array of device configurations
    int num_configs; // Number of device configurations
} ConfigManager;

// Initialize a configuration manager with a given number of devices
void init_config_manager(ConfigManager *cm, int num_devices) {
    assert(num_devices > 0 && num_devices <= 100);
    cm->num_configs = num_devices;
    for (int i = 0; i < num_devices; i++) {
        cm->configs[i] = malloc(sizeof(DeviceConfig));
        assert(cm->configs[i]);
    }
}

// Add a new device configuration to the manager
void add_device_config(ConfigManager *cm, int nid, int modes, int priority) {
    // Check if the NID is already in use
    for (int i = 0; i < cm->num_configs; i++) {
        if (cm->configs[i]->nid == nid) {
            printf("NID %d is already in use\n", nid);
            return;
        }
    }

    // Add the new configuration to the manager
    DeviceConfig *new_config = malloc(sizeof(DeviceConfig));
    assert(new_config);
    new_config->nid = nid;
    new_config->modes = modes;
    new_config->priority = priority;
    cm->configs[cm->num_configs++] = new_config;
}

// Remove a device configuration from the manager
void remove_device_config(ConfigManager *cm, int nid) {
    // Find the index of the configuration to be removed
    int i;
    for (i = 0; i < cm->num_configs; i++) {
        if (cm->configs[i]->nid == nid) {
            break;
        }
    }

    // Check if the configuration was found
    if (i == cm->num_configs) {
        printf("NID %d not found\n", nid);
        return;
    }

    // Remove the configuration from the manager
    DeviceConfig *removed_config = cm->configs[i];
    for (int j = i; j < cm->num_configs - 1; j++) {
        cm->configs[j] = cm->configs[j + 1];
    }
    cm->num_configs--;

    // Free the memory allocated to the removed configuration
    free(removed_config);
}

// Update a device configuration in the manager
void update_device_config(ConfigManager *cm, int nid, int modes, int priority) {
    // Find the index of the configuration to be updated
    int i;
    for (i = 0; i < cm->num_configs; i++) {
        if (cm->configs[i]->nid == nid) {
            break;
        }
    }

    // Check if the configuration was found
    if (i == cm->num_configs) {
        printf("NID %d not found\n", nid);
        return;
    }

    // Update the configuration in the manager
    DeviceConfig *updated_config = cm->configs[i];
    updated_config->modes = modes;
    updated_config->priority = priority;
}

// Get a device configuration from the manager
DeviceConfig* get_device_config(ConfigManager *cm, int nid) {
    // Find the index of the requested configuration
    int i;
    for (i = 0; i < cm->num_configs; i++) {
        if (cm->configs[i]->nid == nid) {
            break;
        }
    }

    // Check if the configuration was found
    if (i == cm->num_configs) {
        printf("NID %d not found\n", nid);
        return NULL;
    }

    // Return a pointer to the requested configuration
    return cm->configs[i];
}

// Free all memory allocated by the configuration manager
void free_config_manager(ConfigManager *cm) {
    for (int i = 0; i < cm->num_configs; i++) {
        free(cm->configs[i]);
    }
    free(cm);
}
```
This code defines a `DeviceConfig` structure to represent the configuration of a device, and a `ConfigManager` structure to manage multiple instances of this structure. The `init_config_manager()` function initializes a configuration manager with a given number of devices, and the `add_device_config()`, `remove_device_config()`, `update_device_config()`, and `get_device_config()` functions allow for adding, removing, updating, and retrieving device configurations. The `free_config_manager()` function frees all memory allocated by the configuration manager.

The code also includes a mechanism to log configuration changes and handle potential errors gracefully, as well as design considerations for ease of maintenance and future extensibility.']

