// Define the structure for a received downlink synchronization message
typedef struct LTE_PHY_RX_PDU {
    int SYNC_MSG_TAG; // Unique identifier for the message
    int CELL_ID; // Cell ID of the message
    int PCI; // Physical Cell Identity of the message
} LTE_PHY_RX_PDU_T;

// Define a list data structure to store received synchronization messages
typedef struct LTE_PHY_RX_PDU_LIST {
    LTE_PHY_RX_PDU_T *data; // Pointer to the array of structures
    int size; // Current number of elements in the list
} LTE_PHY_RX_PDU_LIST_T;

// Initialize a new list with a given capacity
LTE_PHY_RX_PDU_LIST_T *init_list(int capacity) {
    LTE_PHY_RX_PDU_LIST_T *list = malloc(sizeof(LTE_PHY_RX_PDU_LIST_T));
    list->data = malloc(capacity * sizeof(LTE_PHY_RX_PDU_T));
    list->size = 0;
    return list;
}

// Add a new synchronization message to the list
void add_sync_msg(LTE_PHY_RX_PDU_LIST_T *list, int SYNC_MSG_TAG, int CELL_ID, int PCI) {
    // Check if there is enough capacity in the list
    if (list->size >= list->capacity) {
        // Increase the capacity of the list by 50%
        list->capacity *= 1.5;
        list->data = realloc(list->data, list->capacity * sizeof(LTE_PHY_RX_PDU_T));
    }

    // Initialize the new structure with the given parameters
    LTE_PHY_RX_PDU_T *new_msg = &list->data[list->size];
    new_msg->SYNC_MSG_TAG = SYNC_MSG_TAG;
    new_msg->CELL_ID = CELL_ID;
    new_msg->PCI = PCI;

    // Increment the size of the list
    list->size++;
}

// Remove a synchronization message from the list by its index
void remove_sync_msg(LTE_PHY_RX_PDU_LIST_T *list, int index) {
    assert(index >= 0 && index < list->size);

    // Shift all elements after the removed element to the left
    for (int i = index; i < list->size - 1; i++) {
        list->data[i] = list->data[i + 1];
    }

    // Decrement the size of the list
    list->size--;
}

// Free the memory allocated for the list
void free_list(LTE_PHY_RX_PDU_LIST_T *list) {
    free(list->data);
    free(list);
}

int main() {
    // Initialize a new list with a capacity of 10 elements
    LTE_PHY_RX_PDU_LIST_T *list = init_list(10);

    // Add some synchronization messages to the list
    add_sync_msg(list, 1, 1, 1);
    add_sync_msg(list, 2, 2, 2);
    add_sync_msg(list, 3, 3, 3);

    // Remove a synchronization message from the list by its index
    remove_sync_msg(list, 1);

    // Free the memory allocated for the list
    free_list(list);

    return 0;
}
```
