    // Log the CRC indications
    for (int i = 0; i < num_uids; i++) {
        printf("CRC indication: RNTI=%d, CRC flag=%d\n", crc_indications[i].rnti, crc_indications[i].crc_flag);
    }

    // Free the memory for the CRC indications if necessary
    if (num_uids > PREALLOCATED_STRUCTURES) {
        free(crc_indications);
    }
}
