    *num_connections = 0;

    // Allocate memory for the dynamic array of WiFi AP connections
    *connections = (WIFI_AP_CONNECTION *)malloc(sizeof(WIFI_AP_CONNECTION) * (*num_connections));

    // Check if memory allocation was successful
    if (*connections == NULL) {
        printf("Error: Failed to allocate memory for WiFi AP connections\n");
        return;
    }

    // Initialize the thread-safe mutex for managing concurrent access to the connection data
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Loop through all available networks and add them to the dynamic array of WiFi AP connections
    for (int i = 0; i < num_networks; i++) {
        // Check if the network is a WiFi AP
        if (networks[i].type == WIFI) {
            // Lock the mutex to prevent race conditions during concurrent access to the connection data
            pthread_mutex_lock(&mutex);

            // Increment the number of connections and allocate memory for a new WiFi AP connection structure
            (*num_connections)++;
            *connections = (WIFI_AP_CONNECTION *)realloc(*connections, sizeof(WIFI_AP_CONNECTION) * (*num_connections));

            // Check if memory allocation was successful
            if (*connections == NULL) {
                printf("Error: Failed to allocate memory for WiFi AP connections\n");
                pthread_mutex_unlock(&mutex);
                return;
            }

            // Initialize the new WiFi AP connection structure with the network data
            (*connections)[*num_connections - 1].ssid = networks[i].ssid;
            (*connections)[*num_connections - 1].bssid = networks[i].bssid;
            (*connections)[*num_connections - 1].rssi = networks[i].rssi;
            (*connections)[*num_connections - 1].security_mode = networks[i].security_mode;

            // Calculate the security strength indicator based on encryption type and signal strength metrics
            if (networks[i].security_mode == WPA2) {
                (*connections)[*num_connections - 1].security_strength = 50 + networks[i].rssi / 2;
            } else if (networks[i].security_mode == WEP) {
                (*connections)[*num_connections - 1].security_strength = 30 + networks[i].rssi / 4;
            } else {
                (*connections)[*num_connections - 1].security_strength = 20 + networks[i].rssi / 8;
            }

            // Unlock the mutex to allow other threads to access the connection data
            pthread_mutex_unlock(&mutex);
        }
    }
}
