// Define the structure to store records
typedef struct {
    int key;
    long offset;
} Record;

// Define a hash table to store the records
static pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;
static Record* records = NULL;
static size_t num_records = 0;

// Initialize the hash table and allocate memory for the records
void init_records() {
    pthread_mutex_lock(&record_lock);
    if (records == NULL) {
        records = malloc(10000 * sizeof(Record));
        memset(records, 0, 10000 * sizeof(Record));
    }
    pthread_mutex_unlock(&record_lock);
}

// Add a new record to the hash table
void add_record(int key, long offset) {
    pthread_mutex_lock(&record_lock);
    if (records == NULL) {
        init_records();
    }
    // Check for duplicate keys and log an error if found
    for (size_t i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            fprintf(stderr, "Duplicate key value: %d\n", key);
            pthread_mutex_unlock(&record_lock);
            return;
        }
    }
    // Add the new record to the hash table
    records[num_records].key = key;
    records[num_records].offset = offset;
    num_records++;
    pthread_mutex_unlock(&record_lock);
}

// Get a record from the hash table by its key
Record* get_record(int key) {
    pthread_mutex_lock(&record_lock);
    for (size_t i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            Record* record = &records[i];
            pthread_mutex_unlock(&record_lock);
            return record;
        }
    }
    pthread_mutex_unlock(&record_lock);
    return NULL;
}

// Serialize the records to a binary file
void serialize_records(const char* filename) {
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    // Write the number of records to the file
    size_t num_records = 0;
    fwrite(&num_records, sizeof(size_t), 1, fp);
    // Write each record to the file
    for (size_t i = 0; i < num_records; i++) {
        Record* record = &records[i];
        fwrite(&record->key, sizeof(int), 1, fp);
        fwrite(&record->offset, sizeof(long), 1, fp);
    }
    // Close the file
    fclose(fp);
}

// Deserialize the records from a binary file
void deserialize_records(const char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    // Read the number of records from the file
    size_t num_records;
    fread(&num_records, sizeof(size_t), 1, fp);
    // Allocate memory for the records
    records = malloc(num_records * sizeof(Record));
    memset(records, 0, num_records * sizeof(Record));
    // Read each record from the file
    for (size_t i = 0; i < num_records; i++) {
        Record* record = &records[i];
        fread(&record->key, sizeof(int), 1, fp);
        fread(&record->offset, sizeof(long), 1, fp);
    }
    // Close the file
    fclose(fp);
}
```
