// Define the function to hash a given password using a default hash function
char* hash_password(char* password) {
    // Allocate memory for the hashed password
    char* hashed_password = (char*)malloc(SHA256_DIGEST_LENGTH * sizeof(char));
    if (!hashed_password) {
        printf("Error: Failed to allocate memory for the hashed password\n");
        return NULL;
    }

    // Hash the given password using a default hash function (SHA-256 in this case)
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, password, strlen(password));
    SHA256_Final(hashed_password, &ctx);

    // Return the hashed password
    return hashed_password;
}

