void allocateMemory(char **fileNames, int numFiles, long *numRecords, struct SensorReading ***data) {
    // Initialize variables
    int i, j;
    long totalNumRecords = 0;
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    FILE *file;

    // Loop through each file and determine the number of records
    for (i = 0; i < numFiles; i++) {
