            printf("Error: unable to open file %s\n", fileNames[i]);
            continue;
        }

        // Determine the number of records in the file
        while ((read = getline(&line, &len, file)) != -1) {
            totalNumRecords++;
        }

        // Close the file
        fclose(file);
    }

    // Allocate memory for the arrays
    *numRecords = totalNumRecords;
    *data = (struct SensorReading **)malloc(*numRecords * sizeof(struct SensorReading *));
    if (*data == NULL) {
        printf("Error: unable to allocate memory for data\n");
        return;
    }

    // Loop through each file and read the data into the arrays
    for (i = 0; i < numFiles; i++) {
        file = fopen(fileNames[i], "r");
        if (file == NULL) {
            printf("Error: unable to open file %s\n", fileNames[i]);
            continue;
        }

        // Read the data from the file into the arrays
        j = 0;
        while ((read = getline(&line, &len, file)) != -1) {
            char *token = strtok(line, ",");
            (*data)[j].temperature = atof(token);
            token = strtok(NULL, ",");
            (*data)[j].humidity = atof(token);
            token = strtok(NULL, ",");
            (*data)[j].pressure = atof(token);
            j++;
        }

        // Close the file
        fclose(file);
    }
}

// Function to deallocate memory for arrays of timestamp, data points, and sensor readings
void deallocateMemory(struct SensorReading **data, int numRecords) {
    free(data);
}
