// Define the function to initialize the dynamic linked list
void initDynamicLinkedList(NFAPI_LTE_PDU_T **head) {
    // Allocate memory for the head node
    *head = (NFAPI_LTE_PDU_T *)malloc(sizeof(NFAPI_LTE_PDU_T));
    if (*head == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the head node with random but realistic test data
    srand((unsigned int)time(NULL));
    (*head)->phyLayerRxData.rx_indication_rel8.tl.tag = PHY_LAYER_RX_DATA_TAG;
    (*head)->rachIndication.rach_indication_rel10.tl.tag = RACH_INDICATION_TAG;
    (*head)->srs.srs_indication_rel13.tl.tag = SRS_TAG;
    (*head)->phyLayerRxData.rx_indication_rel8.rnti = rand() % 65536;
    (*head)->rachIndication.rach_indication_rel10.preamble_index = rand() % 64;
    (*head)->srs.srs_indication_rel13.srs_present = (rand() % 2) ? 1 : 0;

    // Initialize the sequence number for each instance
    int seqNum = 0;
    NFAPI_LTE_PDU_T *currNode = *head;
    while (currNode != NULL) {
        currNode->phyLayerRxData.rx_indication_rel8.seq_number = seqNum++;
        currNode = currNode->next;
    }
}

// Define the function to add a new node to the dynamic linked list
void addNewNode(NFAPI_LTE_PDU_T **head) {
    // Allocate memory for the new node
    NFAPI_LTE_PDU_T *newNode = (NFAPI_LTE_PDU_T *)malloc(sizeof(NFAPI_LTE_PDU_T));
    if (newNode == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the new node with random but realistic test data
    srand((unsigned int)time(NULL));
    newNode->phyLayerRxData.rx_indication_rel8.tl.tag = PHY_LAYER_RX_DATA_TAG;
    newNode->rachIndication.rach_indication_rel10.tl.tag = RACH_INDICATION_TAG;
    newNode->srs.srs_indication_rel13.tl.tag = SRS_TAG;
    newNode->phyLayerRxData.rx_indication_rel8.rnti = rand() % 65536;
    newNode->rachIndication.rach_indication_rel10.preamble_index = rand() % 64;
    newNode->srs.srs_indication_rel13.srs_present = (rand() % 2) ? 1 : 0;

    // Initialize the sequence number for the new node
    int seqNum = 0;
    NFAPI_LTE_PDU_T *currNode = *head;
    while (currNode != NULL) {
        currNode->phyLayerRxData.rx_indication_rel8.seq_number = seqNum++;
        currNode = currNode->next;
    }

    // Add the new node to the end of the linked list
    NFAPI_LTE_PDU_T *prevNode = NULL;
    while ((*head) != NULL) {
        prevNode = (*head);
        (*head) = (*head)->next;
    }
    if (prevNode == NULL) {
        // The linked list is empty, so set the head node to the new node
        *head = newNode;
    } else {
        // Add the new node to the end of the linked list
        prevNode->next = newNode;
    }
}

// Define the function to remove a node from the dynamic linked list
void removeNode(NFAPI_LTE_PDU_T **head, int seqNum) {
    // Find the node with the specified sequence number
    NFAPI_LTE_PDU_T *currNode = *head;
    while (currNode != NULL && currNode->phyLayerRxData.rx_indication_rel8.seq_number != seqNum) {
        currNode = currNode->next;
    }

    // Remove the node from the linked list
    if (currNode == NULL) {
        printf("Sequence number %d not found\n", seqNum);
    } else {
        NFAPI_LTE_PDU_T *prevNode = NULL;
        while ((*head) != currNode && (*head)->next != currNode) {
            prevNode = (*head);
            (*head) = (*head)->next;
        }
        if (prevNode == NULL) {
            // The node to be removed is the head node, so set the new head node
            *head = (*head)->next;
        } else {
            // Remove the node from the linked list
            prevNode->next = currNode->next;
        }
    }
}
