#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include "nfadatabase_records.h"
#include "logging.h"

struct nfadatabaseRecord {
    RNTI rnti;
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    long offset;
    int key;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
};

struct nfadatabaseRecordList {
    struct nfadatabaseRecord *records;
    size_t numRecords;
    pthread_mutex_t mutex;
};

void initializeNfadatabaseRecords(struct nfadatabaseRecordList *list, const char *configFile) {
    FILE *fp = fopen(configFile, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return;
    }

    int initialKeyValue = 0;
    size_t maxNumRecords = 0;
    size_t numNFAs = 0;
    fscanf(fp, "%d %zu %zu", &initialKeyValue, &maxNumRecords, &numNFAs);
    if (ferror(fp)) {
        perror("Error reading config file");
        return;
    }

    list->records = malloc(sizeof(struct nfadatabaseRecord) * maxNumRecords);
    if (list->records == NULL) {
        perror("Error allocating memory for records");
        return;
    }

    list->numRecords = 0;
    pthread_mutex_init(&list->mutex, NULL);

    for (size_t i = 0; i < numNFAs; i++) {
        struct nfadatabaseRecord *record = &list->records[i];
        record->rnti = generateRandomRNTI();
        record->rx_ue_information_tag = generateRandomRX_UE_INFORMATION_TAG();
        record->offset = generateRandomOffset();
        record->key = initialKeyValue++;
        record->crc_indication_rel8_tag.CRCFLAG = generateRandomCRC_INDICATION_REL8_TAG();
    }

    qsort(list->records, list->numRecords, sizeof(struct nfadatabaseRecord), compareOffset);

    fclose(fp);
}

void destroyNfadatabaseRecords(struct nfadatabaseRecordList *list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->records);
}

int generateRandomRNTI() {
    // Generate a random RNTI value between 0 and 65535
    return rand() % 65536;
}

RX_UE_INFORMATION_TAG generateRandomRX_UE_INFORMATION_TAG() {
    // Generate a random RX_UE_INFORMATION_TAG value between 0 and 255
    return rand() % 256;
}

long generateRandomOffset() {
    // Generate a random offset value between 0 and 1000000000
    return rand() % 1000000000;
}

CRC_INDICATION_REL8_TAG generateRandomCRC_INDICATION_REL8_TAG() {
    // Generate a random CRC_INDICATION_REL8_TAG value between 0 and 255
    return rand() % 256;
}

int compareOffset(const void *a, const void *b) {
    struct nfadatabaseRecord *recordA = (struct nfadatabaseRecord *)a;
    struct nfadatabaseRecord *recordB = (struct nfadatabaseRecord *)b;
    return recordA->offset - recordB->offset;
}
