#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s command1;command2;...\n", argv[0]);
        return 1;
    }

    // Create a process group for the child processes
    pid_t pgid = getpid();
    setpgid(0, pgid);

    // Set up signal handling to terminate all child processes on SIGINT
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = SIG_IGN;
    sigaction(SIGINT, &sa, NULL);

    // Split the command string into individual commands
    char *cmds[argc - 1];
    for (int i = 1; i < argc; i++) {
        cmds[i - 1] = strdup(argv[i]);
    }

    // Execute each command in a separate subprocess
    int exit_statuses[argc - 1];
    for (int i = 0; i < argc - 1; i++) {
        pid_t pid = fork();
        if (pid == 0) {
            // Child process: execute the command and exit
            int status = system(cmds[i]);
            exit_statuses[i] = WEXITSTATUS(status);
            _exit(status);
        } else if (pid < 0) {
            perror("fork");
            return 1;
        }
    }

    // Wait for all child processes to terminate and collect their exit statuses
    int status = 0;
    for (int i = 0; i < argc - 1; i++) {
        waitpid(pgid, &status, WNOHANG);
        if (WIFEXITED(status)) {
            exit_statuses[i] = WEXITSTATUS(status);
        } else {
            // If a child process terminated abnormally, set its exit status to 0
            exit_statuses[i] = 0;
        }
    }

    // Return the array of exit statuses
    return exit_statuses;
}
```
