// Define the function to generate a random CRCFlag based on the seed
int generateCRCFlag(int seed) {
    srand(seed);
    return rand() % 10;
}

// Define the function to check if an integer is a duplicate in the dynamic array
bool isDuplicate(int *dynamicArray, int num) {
    for (int i = 0; i < dynamicArray->length; i++) {
        if (dynamicArray[i] == num) {
            return true;
        }
    }
    return false;
}

// Define the function to add an integer to the dynamic array and return a pointer to it
int *addToDynamicArray(int *dynamicArray, int num) {
    if (dynamicArray == NULL) {
        dynamicArray = (int *)malloc(sizeof(int));
        dynamicArray[0] = num;
        return dynamicArray;
    } else {
        int *newArray = (int *)realloc(dynamicArray, sizeof(int) * (dynamicArray->length + 1));
        newArray[dynamicArray->length] = num;
        return newArray;
    }
}

// Define the function to add a node to the linked list and return a pointer to it
NFAPI_CRC_INDICATION_PDU_T *addToLinkedList(NFAPI_CRC_INDICATION_PDU_T *linkedList, NFAPI_CRC_INDICATION_PDU_T *newNode) {
    if (linkedList == NULL) {
        linkedList = newNode;
        return linkedList;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *currentNode = linkedList;
        while (currentNode->next != NULL) {
            currentNode = currentNode->next;
        }
        currentNode->next = newNode;
        return linkedList;
    }
}

// Define the function to free the memory allocated for the linked list and dynamic array
void freeLinkedList(NFAPI_CRC_INDICATION_PDU_T *linkedList) {
    if (linkedList != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *currentNode = linkedList;
        while (currentNode->next != NULL) {
            currentNode = currentNode->next;
            free(currentNode);
        }
        free(linkedList);
    }
}

