// Define the structure to hold the PDU data
typedef struct {
    unsigned char *pdcp_pdu;
    unsigned int pdcp_pdu_len;
    S1AP_ENDRX_CONTEXT *s1ap_endrx_context;
} MAC_PDU_T;

// Define the function to manage the dynamic array of PDU structures
void manage_pdus(char *src_file, char *dst_file, int compression_level) {
    // Open the source file for reading
    FILE *src = fopen(src_file, "rb");
    if (src == NULL) {
        perror("fopen");
        return;
    }

    // Open the destination file for writing
    FILE *dst = fopen(dst_file, "wb");
    if (dst == NULL) {
        perror("fopen");
        fclose(src);
        return;
    }

    // Initialize the dynamic array of PDU structures
    MAC_PDU_T *pdus = malloc(sizeof(MAC_PDU_T));
    if (pdus == NULL) {
        perror("malloc");
        fclose(src);
        fclose(dst);
        return;
    }

    // Initialize the temporary file for JPEG conversion
    FILE *tmp = tmpfile();
    if (tmp == NULL) {
        perror("tmpfile");
        free(pdus);
        fclose(src);
        fclose(dst);
        return;
    }

    // Initialize the zlib decompression stream
    z_stream strm = {0};
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;
    strm.avail_in = 0;
    strm.next_in = NULL;
    int ret = inflateInit2(&strm, compression_level);
    if (ret != Z_OK) {
        fprintf(stderr, "inflateInit2 error: %s\n", strm.msg);
        free(pdus);
        fclose(src);
        fclose(dst);
        fclose(tmp);
        return;
    }

    // Initialize the JPEG conversion library
    struct jpeg_decompress_struct cinfo = {0};
    struct jpeg_error_mgr jerr = {0};
    cinfo.err = jpeg_std_error(&jerr);
    ret = jpeg_create_decompress(&cinfo);
    if (ret != JPEG_OK) {
        fprintf(stderr, "jpeg_create_decompress error: %s\n", cinfo.err->msg);
        free(pdus);
        fclose(src);
        fclose(dst);
        fclose(tmp);
        inflateEnd(&strm);
        return;
    }

    // Initialize the statistics counters
    int num_processed = 0;
    int num_failed = 0;

    // Read and process each PDU in the source file
    while (1) {
        // Read the next PDU from the source file
        MAC_PDU_T *pdu = malloc(sizeof(MAC_PDU_T));
        if (pdu == NULL) {
            perror("malloc");
            free(pdus);
            fclose(src);
            fclose(dst);
            fclose(tmp);
            inflateEnd(&strm);
            return;
        }
        pdu->pdcp_pdu = malloc(sizeof(unsigned char) * 1024);
        if (pdu->pdcp_pdu == NULL) {
            perror("malloc");
            free(pdu);
            free(pdus);
            fclose(src);
            fclose(dst);
            fclose(tmp);
            inflateEnd(&strm);
            return;
        }
        pdu->pdcp_pdu_len = fread(pdu->pdcp_pdu, 1, 1024, src);
        if (ferror(src)) {
            perror("fread");
            free(pdu->pdcp_pdu);
            free(pdu);
            free(pdus);
            fclose(src);
            fclose(dst);
            fclose(tmp);
            inflateEnd(&strm);
            return;
        }

        // Decompress the PDU using zlib
        strm.next_in = pdu->pdcp_pdu;
        strm.avail_in = pdu->pdcp_pdu_len;
        ret = inflate(&strm, Z_NO_FLUSH);
        if (ret != Z_OK && ret != Z_STREAM_END) {
            fprintf(stderr, "inflate error: %s\n", strm.msg);
            free(pdu->pdcp_pdu);
            free(pdu);
            free(pdus);
            fclose(src);
            fclose(dst);
            fclose(tmp);
            inflateEnd(&strm);
            return;
        }

        // Convert the decompressed PDU to a JPEG image using the JPEG conversion library
        cinfo.image_width = strm.total_out;
        cinfo.image_height = 1;
        cinfo.input_components = 3;
        cinfo.in_color_space = JCS_RGB;
        ret = jpeg_read_header(&cinfo, TRUE);
        if (ret != JPEG_OK) {
            fprintf(stderr, "jpeg_read_header error: %s\n", cinfo.err->msg);
            free(pdu->pdcp_pdu);
            free(pdu);
            free(pdus);
            fclose(src);
            fclose(dst);
            fclose(tmp);
            inflateEnd(&strm);
            return;
        }
        ret = jpeg_start_decompress(&cinfo);
        if (ret != JPEG_OK) {
            fprintf(stderr, "jpeg_start_decompress error: %s\n", cinfo.err->msg);
            free(pdu->pdcp_pdu);
            free(pdu);
            free(pdus);
            fclose(src);
            fclose(dst);
            fclose(tmp);
            inflateEnd(&strm);
            return;
        }
        while (cinfo.output_scanline < cinfo.image_height) {
            unsigned char *row = malloc(sizeof(unsigned char) * 3 * cinfo.image_width);
            if (row == NULL) {
                perror("malloc");
                free(pdu->pdcp_pdu);
                free(pdu);
                free(pdus);
                fclose(src);
                fclose(dst);
                fclose(tmp);
                inflateEnd(&strm);
                return;
            }
            ret = jpeg_read_scanlines(&cinfo, &row, 1);
            if (ret != JPEG_OK) {
                fprintf(stderr, "jpeg_read_scanlines error: %s\n", cinfo.err->msg);
                free(row);
                free(pdu->pdcp_pdu);
                free(pdu);
                free(pdus);
                fclose(src);
                fclose(dst);
                fclose(tmp);
                inflateEnd(&strm);
                return;
            }
            ret = fwrite(row, 1, 3 * cinfo.image_width, tmp);
            if (ret != 3 * cinfo.image_width) {
                perror("fwrite");
                free(row);
