// Structure to represent a Network Interface Control Block (NICB)
typedef struct NICB {
    char mac_addr[6]; // MAC address of the interface
    uint32_t ip_addr; // IP address of the interface
    uint32_t subnet_mask; // Subnet mask of the interface
    bool active; // Flag indicating whether the interface is active
    time_t last_seen; // Timestamp for the last seen network activity
} NICB;

// Function to initialize and populate a dynamic array of NICB structures
NICB** init_nicb_array(size_t initial_size) {
    // Allocate memory for the array of pointers to NICB structures
    NICB **nicb_array = (NICB **)malloc(initial_size * sizeof(NICB*));
    if (!nicb_array) {
        fprintf(stderr, "Error: Failed to allocate memory for the NICB array\n");
        return NULL;
    }

    // Initialize each pointer in the array to NULL
    size_t i;
    for (i = 0; i < initial_size; i++) {
        nicb_array[i] = NULL;
    }

    return nicb_array;
}

// Function to add a new NICB structure to the array
int add_nicb(NICB **nicb_array, size_t *size, size_t *capacity, const char *mac_addr, uint32_t ip_addr, uint32_t subnet_mask) {
    // Check if the array is full
    if (*size == *capacity) {
        // If the array is full, double its capacity
        size_t new_capacity = *capacity * 2;
        NICB **new_nicb_array = (NICB **)realloc(nicb_array, new_capacity * sizeof(NICB*));
        if (!new_nicb_array) {
            fprintf(stderr, "Error: Failed to reallocate memory for the NICB array\n");
            return -1;
        }
        nicb_array = new_nicb_array;
        *capacity = new_capacity;
    }

    // Allocate memory for the new NICB structure
    NICB *new_nicb = (NICB *)malloc(sizeof(NICB));
    if (!new_nicb) {
        fprintf(stderr, "Error: Failed to allocate memory for the new NICB\n");
        return -1;
    }

    // Initialize the new NICB structure
    memcpy(new_nicb->mac_addr, mac_addr, 6);
    new_nicb->ip_addr = ip_addr;
    new_nicb->subnet_mask = subnet_mask;
    new_nicb->active = true;
    new_nicb->last_seen = time(NULL);

    // Add the new NICB structure to the array
    nicb_array[*size] = new_nicb;
    (*size)++;

    return 0;
}

// Function to remove a NICB structure from the array
int remove_nicb(NICB **nicb_array, size_t *size, const char *mac_addr) {
    // Find the index of the NICB structure with the specified MAC address
    int i;
    for (i = 0; i < *size; i++) {
        if (!memcmp(nicb_array[i]->mac_addr, mac_addr, 6)) {
            break;
        }
    }

    // If the NICB structure was not found, return an error
    if (i == *size) {
        fprintf(stderr, "Error: NICB structure with MAC address %s not found\n", mac_addr);
        return -1;
    }

    // Remove the NICB structure from the array
    free(nicb_array[i]);
    nicb_array[i] = NULL;
    (*size)--;

    return 0;
}

// Function to update a NICB structure in the array
int update_nicb(NICB **nicb_array, size_t *size, const char *mac_addr, uint32_t ip_addr, uint32_t subnet_mask) {
    // Find the index of the NICB structure with the specified MAC address
    int i;
    for (i = 0; i < *size; i++) {
        if (!memcmp(nicb_array[i]->mac_addr, mac_addr, 6)) {
            break;
        }
    }

    // If the NICB structure was not found, return an error
    if (i == *size) {
        fprintf(stderr, "Error: NICB structure with MAC address %s not found\n", mac_addr);
        return -1;
    }

    // Update the IP address and subnet mask of the NICB structure
    nicb_array[i]->ip_addr = ip_addr;
    nicb_array[i]->subnet_mask = subnet_mask;

    return 0;
}

// Function to free up unused NICB structures and reclaim memory efficiently
void garbage_collect(NICB **nicb_array, size_t *size) {
    // Iterate over the array of NICB structures and remove any NULL pointers
    int i;
    for (i = 0; i < *size; i++) {
        if (!nicb_array[i]) {
            nicb_array[i] = nicb_array[*size - 1];
            (*size)--;
        }
    }
}
