struct Packet {
    struct Header header;
    char payload[];
    time_t timestamp;
};

struct Packet* allocatePackets(size_t numPackets) {
    // Allocate memory for the array of packets
    struct Packet** packets = malloc(numPackets * sizeof(struct Packet));
    if (packets == NULL) {
        // Log initialization failure to a separate error log
        fprintf(stderr, "Failed to allocate memory for %zu packets\n", numPackets);
        return NULL;
    }

    // Initialize each packet with random header fields and payload length
    size_t i;
    for (i = 0; i < numPackets; ++i) {
        struct Packet* packet = &packets[i];
        packet->header.srcPort = rand() % 65536;
        packet->header.dstPort = rand() % 65536;
        packet->header.seqNum = rand() % 4294967296;
        packet->payloadLen = rand() % 1024 + 1;
        packet->timestamp = time(NULL);
    }

    return packets;
}
