#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Define a custom memory pool for allocating NFAPI_CRC_INDICATION_PDU_T structures
struct nfaapi_crc_indication_pool {
    struct nfaapi_crc_indication_pool *next;
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T *elements[];
};

// Define a global variable to store the custom memory pool
static struct nfaapi_crc_indication_pool *nfaapi_crc_indication_pool = NULL;

// Define a mutex for synchronizing access to the custom memory pool
static pthread_mutex_t nfaapi_crc_indication_pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to allocate a new NFAPI_CRC_INDICATION_PDU_T structure from the custom memory pool
NFAPI_CRC_INDICATION_PDU_T *nfaapi_crc_indication_pool_alloc(size_t count) {
    // Acquire the mutex to prevent concurrent access to the custom memory pool
    pthread_mutex_lock(&nfaapi_crc_indication_pool_mutex);

    // Check if there is enough capacity in the custom memory pool to allocate the requested number of elements
    if (count > nfaapi_crc_indication_pool->capacity - nfaapi_crc_indication_pool->count) {
        // Release the mutex and return NULL if there is not enough capacity in the custom memory pool
        pthread_mutex_unlock(&nfaapi_crc_indication_pool_mutex);
        return NULL;
    }

    // Allocate a new NFAPI_CRC_INDICATION_PDU_T structure from the custom memory pool
    NFAPI_CRC_INDICATION_PDU_T *pdu = nfaapi_crc_indication_pool->elements[nfaapi_crc_indication_pool->count++];

    // Release the mutex and return the allocated NFAPI_CRC_INDICATION_PDU_T structure
    pthread_mutex_unlock(&nfaapi_crc_indication_pool_mutex);
    return pdu;
}

// Define a function to free an NFAPI_CRC_INDICATION_PDU_T structure from the custom memory pool
void nfaapi_crc_indication_pool_free(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire the mutex to prevent concurrent access to the custom memory pool
    pthread_mutex_lock(&nfaapi_crc_indication_pool_mutex);

    // Check if the NFAPI_CRC_INDICATION_PDU_T structure is in the custom memory pool
    if (pdu >= nfaapi_crc_indication_pool->elements && pdu < nfaapi_crc_indication_pool->elements + nfaapi_crc_indication_pool->capacity) {
        // Free the NFAPI_CRC_INDICATION_PDU_T structure from the custom memory pool
        nfaapi_crc_indication_pool->count--;
    } else {
        // Release the mutex and return if the NFAPI_CRC_INDICATION_PDU_T structure is not in the custom memory pool
        pthread_mutex_unlock(&nfaapi_crc_indication_pool_mutex);
        return;
    }

    // Release the mutex and return
    pthread_mutex_unlock(&nfaapi_crc_indication_pool_mutex);
}

// Define a function to populate a list of NFAPI_CRC_INDICATION_PDU_T structures based on user input N
NFAPI_CRC_INDICATION_PDU_T *populate_nfaapi_pdu_list(size_t n) {
    // Initialize the custom memory pool if it is not already initialized
    if (nfaapi_crc_indication_pool == NULL) {
        nfaapi_crc_indication_pool = malloc(sizeof(struct nfaapi_crc_indication_pool));
        if (nfaapi_crc_indication_pool == NULL) {
            return NULL;
        }
        nfaapi_crc_indication_pool->capacity = 1024; // Initial capacity of the custom memory pool
        nfaapi_crc_indication_pool->count = 0;
        nfaapi_crc_indication_pool->elements = malloc(nfaapi_crc_indication_pool->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (nfaapi_crc_indication_pool->elements == NULL) {
            free(nfaapi_crc_indication_pool);
            nfaapi_crc_indication_pool = NULL;
            return NULL;
        }
    }

    // Allocate a new NFAPI_CRC_INDICATION_PDU_T structure from the custom memory pool for each element in the list
    size_t i;
    for (i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = nfaapi_crc_indication_pool_alloc(1);
        if (pdu == NULL) {
            // If memory allocation fails, resize the custom memory pool to accommodate more elements and retry allocating the NFAPI_CRC_INDICATION_PDU_T structure
            size_t new_capacity = nfaapi_crc_indication_pool->capacity * 2;
            void *new_elements = realloc(nfaapi_crc_indication_pool->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (new_elements == NULL) {
                // If the resize fails, return NULL and an error code indicating memory allocation failure
                free(nfaapi_crc_indication_pool->elements);
                nfaapi_crc_indication_pool->capacity = 0;
                nfaapi_crc_indication_pool->count = 0;
                return NULL;
            }
            nfaapi_crc_indication_pool->elements = new_elements;
            nfaapi_crc_indication_pool->capacity = new_capacity;
            pdu = nfaapi_crc_indication_pool_alloc(1);
            if (pdu == NULL) {
                // If the resize fails, return NULL and an error code indicating memory allocation failure
                free(nfaapi_crc_indication_pool->elements);
                nfaapi_crc_indication_pool->capacity = 0;
                nfaapi_crc_indication_pool->count = 0;
                return NULL;
            }
        }
        // Initialize the NFAPI_CRC_INDICATION_PDU_T structure with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
        pdu->RX_UE_INFORMATION_TAG = 0; // Valid RX_UE_INFORMATION_TAG value
        pdu->RNTI = rand() % 1024 + 1; // Randomly generated RNTI value within the specified range
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly generated CRCFLAG value
    }

    // Return a pointer to the populated list and the total number of elements added, or NULL if memory allocation fails at any point
    return nfaapi_crc_indication_pool->elements;
}
