def parseAndAnalyzeLogs(log_file):
    # Initialize variables
    log_entries = []
    unique_identifiers = set()
    error_count = 0

    # Open the log file and read its contents
    with open(log_file, "r") as f:
        for line in f:
            # Parse the log entry from the line of text
            match = re.search(r"^(\d+)\s+(\w+)\s+(\d+)\s+(\d+)", line)
            if match:
                log_entries.append({
                    "timestamp": int(match.group(1)),
                    "identifier": match.group(2),
                    "value": int(match.group(3)),
                    "error": bool(int(match.group(4)))
                })

            # Add the identifier to the set of unique identifiers
            if match:
                unique_identifiers.add(match.group(2))

            # Increment the error count if an error is detected
            if match and match.group(4) == "1":
                error_count += 1

    # Sort the log entries by timestamp
    log_entries = sorted(log_entries, key=lambda x: x["timestamp"])

    # Analyze the log entries
    for entry in log_entries:
        print("Timestamp:", entry["timestamp"], "Identifier:", entry["identifier"], "Value:", entry["value"], "Error:", entry["error"])

    # Print a summary of the analysis
    print("Unique identifiers:", len(unique_identifiers))
    print("Total errors:", error_count)
