#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>

// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int valid;
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for a doubly linked list of NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
} NFAPI_CRC_INDICATION_PDU_LIST_T;

// Define the function to populate the list of PDUs
void populate_pdu_list(NFAPI_CRC_INDICATION_PDU_LIST_T *list, int num_pdus) {
    // Initialize the list with a sentinel node
    NFAPI_CRC_INDICATION_PDU_T sentinel;
    sentinel.valid = false;
    list->data = &sentinel;
    list->next = NULL;
    list->prev = NULL;

    // Populate the list with random PDUs
    for (int i = 0; i < num_pdus; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->valid = true;
        pdu->rx_ue_information_tag = rand() % 1000;
        pdu->rnti = rand() % 1000;
        pdu->crc_indication_rel8_tag = rand() % 1000;
        pdu->crcflag = (rand() % 2) == 0;

        // Add the PDU to the list
        if (list->next == NULL) {
            list->data = pdu;
            list->next = pdu;
            list->prev = pdu;
        } else {
            list->next->prev = pdu;
            pdu->next = list->next;
            list->next = pdu;
        }
    }
}

// Define the function to insert a new PDU into the list
void insert_pdu(NFAPI_CRC_INDICATION_PDU_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Check if the list is empty
    if (list->data == NULL) {
        list->data = pdu;
        list->next = pdu;
        list->prev = pdu;
    } else {
        // Find the position where the new PDU should be inserted
        NFAPI_CRC_INDICATION_PDU_T *current = list->data;
        while (current != NULL && current->rx_ue_information_tag < pdu->rx_ue_information_tag) {
            current = current->next;
        }

        // Insert the new PDU into the list
        if (current == NULL) {
            list->prev->next = pdu;
            pdu->prev = list->prev;
            list->prev = pdu;
        } else {
            current->prev->next = pdu;
            pdu->prev = current->prev;
            current->prev = pdu;
        }
    }
}

// Define the function to delete a PDU from the list
void delete_pdu(NFAPI_CRC_INDICATION_PDU_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Check if the list is empty
    if (list->data == NULL) {
        return;
    } else {
        // Find the position where the PDU should be deleted
        NFAPI_CRC_INDICATION_PDU_T *current = list->data;
        while (current != NULL && current != pdu) {
            current = current->next;
        }

        // Delete the PDU from the list
        if (current == NULL) {
            return;
        } else {
            current->prev->next = current->next;
            if (current->next != NULL) {
                current->next->prev = current->prev;
            }
            free(pdu);
        }
    }
}

// Define the function to handle external data source failures
void handle_data_source_failure(NFAPI_CRC_INDICATION_PDU_LIST_T *list) {
    // Retry logic goes here
}

// Define the function to log PDU creation events
void log_pdu_creation(NFAPI_CRC_INDICATION_PDU_T *pdu, FILE *log_file) {
    fprintf(log_file, "Created PDU with RX_UE_INFORMATION_TAG %d, RNTI %d, CRC_INDICATION_REL8_TAG %d, CRCFLAG %s\n", pdu->rx_ue_information_tag, pdu->rnti, pdu->crc_indication_rel8_tag, pdu->crcflag ? "true" : "false");
}
