#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>
#include <stdbool.h>

// Define the structure for the configuration system
typedef struct config_system {
    int num_modules;
    char **module_names;
    char **module_descriptions;
    char *version_info;
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdus;
} config_system_t;

// Define the structure for the cache entry
typedef struct cache_entry {
    int num_modules;
    char **module_names;
    char **module_descriptions;
    char *version_info;
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdus;
} cache_entry_t;

// Define the structure for the cache
typedef struct cache {
    int num_entries;
    cache_entry_t **entries;
} cache_t;

// Define the structure for the configuration file
typedef struct config_file {
    char *path;
    char *language;
    char *line_ending;
} config_file_t;

// Define the structure for the configuration filter
typedef struct config_filter {
    bool language_support;
    bool version_compatibility;
    bool module_type;
} config_filter_t;

// Define the function to load and process a large-scale configuration file system
config_system_t *load_and_process_config(const char *directory_path, const config_file_t *config_file, const config_filter_t *config_filter) {
    // Initialize the cache
    cache_t *cache = (cache_t *)malloc(sizeof(cache_t));
    cache->num_entries = 0;
    cache->entries = NULL;

    // Load the configuration files from the specified directory path
    int num_files = 0;
    char **file_paths = get_config_files(directory_path, &num_files);

    // Initialize the configuration system
    config_system_t *config_system = (config_system_t *)malloc(sizeof(config_system_t));
    config_system->num_modules = 0;
    config_system->module_names = NULL;
    config_system->module_descriptions = NULL;
    config_system->version_info = NULL;
    config_system->crc_indication_pdus = NULL;

    // Iterate over the configuration files and process them
    for (int i = 0; i < num_files; ++i) {
        // Load the configuration file
        FILE *file = fopen(file_paths[i], "r");
        if (!file) {
            continue;
        }

        // Parse the configuration file and update the cache
        cache_entry_t *cache_entry = parse_config_file(file, config_filter);
        if (cache_entry) {
            cache->num_entries++;
            cache->entries = realloc(cache->entries, sizeof(cache_entry_t *) * cache->num_entries);
            cache->entries[cache->num_entries - 1] = cache_entry;
        }

        // Close the configuration file
        fclose(file);
    }

    // Free the file paths array
    free(file_paths);

    // Filter the configurations based on the user-defined criteria
    filter_configurations(cache, config_filter);

    // Return the processed configuration system
    return config_system;
}

// Define the function to get the configuration files from a specified directory path
char **get_config_files(const char *directory_path, int *num_files) {
    // Initialize the file paths array
    char **file_paths = NULL;

    // Open the directory stream
    DIR *dir = opendir(directory_path);
    if (!dir) {
        return NULL;
    }

    // Iterate over the files in the directory and add them to the file paths array
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char *file_path = (char *)malloc(strlen(directory_path) + strlen(entry->d_name) + 2);
        sprintf(file_path, "%s/%s", directory_path, entry->d_name);
        file_paths = realloc(file_paths, sizeof(char *) * (*num_files + 1));
        file_paths[*num_files] = file_path;
        (*num_files)++;
    }

    // Close the directory stream
    closedir(dir);

    // Return the file paths array
    return file_paths;
}

// Define the function to parse a configuration file and update the cache
cache_entry_t *parse_config_file(FILE *file, const config_filter_t *config_filter) {
    // Initialize the cache entry
    cache_entry_t *cache_entry = (cache_entry_t *)malloc(sizeof(cache_entry_t));
    cache_entry->num_modules = 0;
    cache_entry->module_names = NULL;
    cache_entry->module_descriptions = NULL;
    cache_entry->version_info = NULL;
    cache_entry->crc_indication_pdus = NULL;

    // Load the configuration file and parse it line by line
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Skip empty lines and comments
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }

        // Parse the module name and description
        char *module_name = strtok(line, " ");
        char *module_description = strtok(NULL, "\n");
        if (module_name && module_description) {
            cache_entry->num_modules++;
            cache_entry->module_names = realloc(cache_entry->module_names, sizeof(char *) * cache_entry->num_modules);
            cache_entry->module_descriptions = realloc(cache_entry->module_descriptions, sizeof(char *) * cache_entry->num_modules);
            cache_entry->module_names[cache_entry->num_modules - 1] = module_name;
            cache_entry->module_descriptions[cache_entry->num_modules - 1] = module_description;
        }

        // Parse the version information
        char *version_info = strtok(NULL, "\n");
        if (version_info) {
            cache_entry->version_info = version_info;
        }

        // Parse the CRC indication PDUs
        NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu = parse_crc_indication_pdu(line);
        if (crc_indication_pdu) {
            cache_entry->crc_indication_pdus = realloc(cache_entry->crc_indication_pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * cache_entry->num_modules);
            cache_entry->crc_indication_pdus[cache_entry->num_modules - 1] = crc_indication_pdu;
        }
    }

    // Free the line buffer
    free(line);

    // Return the cache entry
    return cache_entry;
}

// Define the function to parse a CRC indication PDU from a configuration file
NFAPI_CRC_INDICATION_PDU_T *parse_crc_indication_pdu(const char *line) {
    // Initialize the CRC indication PDU
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    crc_indication_pdu->rx_ue_information.rx_ue_information_rel8.rnti = 0;
    crc_indication_pdu->rx_ue_information.rx_ue_information_rel8.crci = 0;
    crc_indication_pdu->rx_ue_information.rx_ue_information_rel8.crc_flag = false;

    // Parse the RX UE information
    char *token = strtok((char *)line, " ");
    while (token) {
        if (!strcmp(token, "RX_UE_INFORMATION")) {
            token = strtok(NULL, " ");
            if (!strcmp(token, "REL8")) {
                token = strtok(NULL, " ");
                crc_indication_pdu->rx_ue_information.rx_ue_information_rel8.rnti = atoi(token);
                token = strtok(NULL, " ");
                if (!strcmp(token, "CRCI")) {
                    token = strtok(NULL, " ");
                    crc_indication_pdu->rx_ue_information.rx_ue_information_rel8.crci = atoi(token);
                    token = strtok(NULL, " ");
                    if (!strcmp(token, "CRCFLAG")) {
                        token = strtok(NULL, " ");
                        crc_indication_pdu->rx_ue_information.rx_ue_information_rel8.crc_flag = atoi(token);
                    }
                }
            }
        }
        token = strtok(NULL, " ");
    }

    // Return the CRC indication PDU
    return crc_indication_pdu;
}

// Define the function to filter the configurations based on user-defined criteria
void filter_configurations(cache_t *cache, const config_filter_t *config_filter) {
    // Initialize the filtered cache entry array
    int num_filtered_entries = 0;
    cache_entry_t **filtered_entries = NULL;

    // Iterate over the cache entries and filter them based on the user-defined criteria
    for (int i = 0; i < cache->num_entries; ++i) {
        cache_entry_t *cache_entry = cache->entries[i];
        bool language_support = false;
        bool version_compatibility = false;
        bool module_type = false;

        // Check the language support
        if (config_filter->language_support) {
            for (int j = 0; j < cache_entry->num_modules; ++j) {
                char *module_name = cache_entry->module_names[j];
                char *module_description = cache_entry->module_descriptions[j];
                if (!strcmp(module_name, "language") && !strcmp(module_description, "C")) {
                    language_support = true;
                    break;
                }
            }
        } else {
            language_support = true;
        }

        // Check the version compatibility
        if (config_filter->version_compatibility) {
            char *version_info = cache_entry->version_info;
            if (!strcmp(version_info, "1.0")) {
                version_compatibility = true;
            }
        } else {
            version_compatibility = true;
        }

        // Check the module type
        if (config_filter->module_type) {
            for (int j = 0; j < cache_entry->num_modules; ++j) {
                char *module_name = cache_entry->module_names[j];
                char *module_description = cache_entry->module_descriptions[j];
                if (!strcmp(module_name, "type") && !strcmp(module_description, "UE")) {
                    module_type = true;
                    break;
                }
            }
        } else {
            module_type = true;
        }

        // Add the cache entry to the filtered array if it passes all filters
        if (language_support && version_compatibility && module_type) {
            num_filtered_entries++;
            filtered_entries = realloc(filtered_entries, sizeof(cache_entry_t *) * num_filtered_entries);
            filtered_entries[num_filtered_entries - 1] = cache_entry;
        }
    }

    // Free the original cache entries array and replace it with the filtered one
    free(cache->entries);
    cache->entries = filtered_entries;
}
