    int num_levels;
    int* level_counts;
} RSRP_HISTOGRAM_T;

// Function to manage a collection of LTE PHY RX frames
LTE_PHY_RX_FRAME_T* manage_frames(LTE_PHY_RX_FRAME_T** frame_list, int* num_frames, int max_num_frames) {
    // Check if the list is full and needs to be resized
    if (*num_frames == max_num_frames) {
        // Resize the list by doubling its capacity
        *frame_list = realloc(*frame_list, 2 * max_num_frames * sizeof(LTE_PHY_RX_FRAME_T));
        if (*frame_list == NULL) {
            printf("Error: Failed to resize frame list\n");
            return NULL;
        }
        // Update the maximum number of frames
        max_num_frames *= 2;
    }

    // Add a new frame to the list
    (*frame_list)[*num_frames].PCI = rand() % 100;
    (*frame_list)[*num_frames].RSRP_LEVEL = (float)rand() / RAND_MAX * 100.0f;
    (*num_frames)++;

    // Validate the PCI value and handle invalid values gracefully
    if ((*frame_list)[*num_frames - 1].PCI < 0 || (*frame_list)[*num_frames - 1].PCI > 79) {
        printf("Warning: Invalid PCI value detected\n");
        (*frame_list)[*num_frames - 1].PCI = 0;
    }

    // Update the total received signal power (RSRP) levels and provide a summary report
    RSRP_HISTOGRAM_T histogram = {0};
    for (int i = 0; i < *num_frames; i++) {
        int rsrp_level = (*frame_list)[i].RSRP_LEVEL;
        if (rsrp_level >= 0 && rsrp_level <= 100) {
            histogram.num_levels++;
            histogram.level_counts[rsrp_level]++;
        } else {
            printf("Warning: Invalid RSRP level detected\n");
        }
    }
    printf("RSRP levels:\n");
    for (int i = 0; i < histogram.num_levels; i++) {
        printf("%d: %d\n", i, histogram.level_counts[i]);
    }

    return *frame_list;
}
