#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>
#include <nfapi/nfapi_interface.h>

// Define the structure to hold the CRC indication data
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
} crc_indication_t;

// Function to read configuration parameters from JSON file
int read_config(const char *filename, json_object **config) {
    // Open the JSON file and check for errors
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: unable to open configuration file\n");
        return -1;
    }

    // Parse the JSON file and check for errors
    json_object *root = json_object_from_file(filename);
    if (root == NULL) {
        printf("Error: unable to parse configuration file\n");
        fclose(fp);
        return -1;
    }

    // Close the JSON file and return the root object
    fclose(fp);
    *config = root;
    return 0;
}

// Function to create and populate a list of CRC indication structures
int create_crc_indications(const char *filename, crc_indication_t **list) {
    // Read the configuration parameters from the JSON file
    json_object *config = NULL;
    if (read_config(filename, &config) != 0) {
        return -1;
    }

    // Get the number of CRC indications to create
    int num_indications = json_object_get_int(json_object_object_get(config, "num_indications"));

    // Allocate memory for the list of CRC indication structures
    *list = (crc_indication_t *)malloc(sizeof(crc_indication_t) * num_indications);
    if (*list == NULL) {
        printf("Error: unable to allocate memory for CRC indications\n");
        return -1;
    }

    // Populate the list of CRC indication structures with random data
    int i = 0;
    while (i < num_indications) {
        // Get a random RX UE information tag
        uint32_t rx_ue_information_tag = rand() % 1000000;

        // Get a random RNTI
        uint32_t rnti = rand() % 1000000;

        // Get a random CRC indication REL8 tag
        uint32_t crc_indication_rel8_tag = rand() % 1000000;

        // Set the CRCFLAG to a random value
        bool crcflag = (rand() % 2) == 0;

        // Create a new CRC indication structure and populate it with data
        (*list)[i].pdu.rx_ue_information_tag = rx_ue_information_tag;
        (*list)[i].pdu.rnti = rnti;
        (*list)[i].pdu.crc_indication_rel8_tag = crc_indication_rel8_tag;
        (*list)[i].pdu.crcflag = crcflag;

        // Increment the index and continue populating the list
        i++;
    }

    return 0;
}

// Function to free memory allocated for the list of CRC indication structures
void free_crc_indications(crc_indication_t **list) {
    // Check if the list is NULL before attempting to free it
    if (*list != NULL) {
