// Define the structure of a data point
typedef struct {
    double value;
    unsigned long id;
    struct data_point* next;
} data_point;

// Define the configuration parameters for memory management
#define MAX_NODES 10000
#define MIN_VALUE -1.0
#define MAX_VALUE 1.0

// Function to dynamically manage memory for an array of data points
data_point* allocate_nodes(int num_nodes) {
    // Check if the number of nodes is within the maximum limit
    if (num_nodes > MAX_NODES) {
        printf("Error: Number of nodes exceeds maximum limit\n");
        return NULL;
    }

    // Allocate memory for the array of data points
    data_point* nodes = malloc(sizeof(data_point) * num_nodes);
    if (nodes == NULL) {
        printf("Error: Memory allocation failed\n");
        return NULL;
    }

    // Initialize each node's double field with a random value within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_nodes; i++) {
        nodes[i].value = MIN_VALUE + ((double)rand() / RAND_MAX) * (MAX_VALUE - MIN_VALUE);
    }

    // Initialize each node's unsigned long field with a unique sequential ID
    for (int i = 0; i < num_nodes; i++) {
        nodes[i].id = i + 1;
    }

    // Set the next pointer of each node to point to the next node in the array
    for (int i = 0; i < num_nodes - 1; i++) {
        nodes[i].next = &nodes[i + 1];
    }

    return nodes;
}

// Function to deallocate memory for an array of data points
void free_nodes(data_point* nodes) {
    // Check if the input is a valid pointer
    if (nodes == NULL) {
        printf("Error: Invalid input\n");
        return;
    }

    // Deallocate memory for each node in the array
    for (int i = 0; i < MAX_NODES; i++) {
        free(nodes[i].next);
    }

    // Deallocate memory for the array of data points
    free(nodes);
}

// Function to access and modify a data point in the array
data_point* get_node(data_point* nodes, int index) {
    // Check if the input is a valid pointer and the index is within the range of the array
    if (nodes == NULL || index < 0 || index >= MAX_NODES) {
        printf("Error: Invalid input\n");
        return NULL;
    }

    return &nodes[index];
}

// Function to modify a data point in the array
void set_node(data_point* nodes, int index, double value) {
    // Check if the input is a valid pointer and the index is within the range of the array
    if (nodes == NULL || index < 0 || index >= MAX_NODES) {
        printf("Error: Invalid input\n");
        return;
    }

    nodes[index].value = value;
}
