// Define the maximum size of the linked list
#define MAX_LIST_SIZE 1024

// Define the maximum log file size per hour
#define LOG_FILE_SIZE_LIMIT (1024 * 1024) // 1 MB

// Define the LRU eviction policy
struct Node {
    struct Node* next;
    struct Node* prev;
    NFAPI_CRC_INDICATION_PDU_T data;
};

struct List {
    struct Node* head;
    struct Node* tail;
    size_t size;
};

// Initialize the linked list and log file
void initList(struct List* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
}

void initLogFile() {
    // Open the log file for writing
    FILE* log_file = fopen("crc_indication.log", "w");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        return;
    }

    // Set the log file size limit
    struct stat st;
    if (fstat(fileno(log_file), &st) != 0) {
        printf("Error getting log file size\n");
        fclose(log_file);
        return;
    }
    off_t max_size = st.st_size + LOG_FILE_SIZE_LIMIT;

    // Check if the log file is too large and needs to be rotated
    if (max_size > 0) {
        // Rotate the log file by renaming it with a timestamp suffix
        char* new_name = malloc(strlen("crc_indication.log") + 16);
        strcpy(new_name, "crc_indication.log");
        time_t t = time(NULL);
        struct tm* tm = localtime(&t);
        char* timestamp = asctime(tm);
        strcat(new_name, "_");
        strcat(new_name, timestamp);
        rename("crc_indication.log", new_name);
        free(new_name);
    }
}

// Add a new entry to the linked list and log file
void addEntry(struct List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    // Check if the list is full
    if (list->size >= MAX_LIST_SIZE) {
        // Evict the oldest entry using LRU policy
        struct Node* node = list->head;
        while (node->next != NULL) {
            node = node->next;
        }
        list->tail = node->prev;
        if (list->tail != NULL) {
            list->tail->next = NULL;
        } else {
            list->head = NULL;
        }
        free(node);
    }

    // Add the new entry to the linked list and log file
    struct Node* node = malloc(sizeof(struct Node));
    if (node == NULL) {
        printf("Error allocating memory for new node\n");
        return;
    }
    node->data = data;
    node->next = NULL;
    node->prev = list->tail;
    if (list->tail != NULL) {
        list->tail->next = node;
    } else {
        list->head = node;
    }
    list->tail = node;
    list->size++;

    // Write the entry to the log file
    FILE* log_file = fopen("crc_indication.log", "a");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        return;
    }
    fprintf(log_file, "%d %d %d\n", data.RX_UE_INFORMATION_TAG, data.RNTI, data.CRC_INDICATION_REL8_TAG);
    fclose(log_file);
}

// Iterate over the linked list in reverse order and print each entry to the log file
void iterateList(struct List* list) {
    struct Node* node = list->tail;
    while (node != NULL) {
        NFAPI_CRC_INDICATION_PDU_T data = node->data;
        FILE* log_file = fopen("crc_indication.log", "a");
        if (log_file == NULL) {
            printf("Error opening log file\n");
            return;
        }
        fprintf(log_file, "%d %d %d\n", data.RX_UE_INFORMATION_TAG, data.RNTI, data.CRC_INDICATION_REL8_TAG);
        fclose(log_file);
        node = node->prev;
    }
}

// Manage dependencies on the external CRC library and handle potential errors gracefully
void calculateCrc(NFAPI_CRC_INDICATION_PDU_T* data) {
    // Use an external library for efficient CRC calculation
    int crc = crc32(data->RX_UE_INFORMATION_TAG, data->RNTI, data->CRC_INDICATION_REL8_TAG);
    if (crc == -1) {
        printf("Error calculating CRC\n");
        return;
    }
    data->CRCFLAG = crc;
