void addEntry(LinkedList **head, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, bool CRCFLAG) {
    // Create a new node for the data
    LinkedList *newNode = malloc(sizeof(LinkedList));
    if (newNode == NULL) {
