void readIntegersFromSocket(int sockfd) {
    // Check if the socket is valid
    if (sockfd < 0) {
        printf("Invalid socket\n");
        return;
    }

    // Set the timeout for reading from the socket
    struct timeval tv;
    tv.tv_sec = SOCKET_TIMEOUT;
    tv.tv_usec = 0;
    setsockopt(sockfd, SOL_SOCKET, SO_RCVTIMEO, (const char*)&tv, sizeof(tv));

    // Read the integers from the socket
    while (true) {
        int integer = readIntFromSocket(sockfd);
        if (integer == -1) {
            break;
        }

        // Validate the integer to ensure it falls within the specified range
        if (integer < INTEGER_RANGE[0] || integer > INTEGER_RANGE[1]) {
            printf("Invalid integer: %d\n", integer);
            continue;
        }

        // Add the integer to the linked list
        addEntry(&head, integer, 0, 0, false);
    }
