// Define the function to read an integer from a high-speed network socket
int readIntFromSocket(int sockfd) {
    // Check if the socket is valid
    if (sockfd < 0) {
        printf("Invalid socket\n");
        return -1;
    }

    // Read the integer from the socket
    char buffer[1024];
    int bytesRead = recv(sockfd, buffer, sizeof(buffer), 0);
    if (bytesRead < 0) {
        perror("recv");
        return -1;
    }

    // Convert the integer from a string to an integer
    char *endptr;
    int integer = strtol(buffer, &endptr, 10);
    if (endptr == buffer || *endptr != '\0') {
        printf("Invalid integer: %s\n", buffer);
        return -1;
    }

    // Return the integer
    return integer;
}

