#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>

// Define the data structure for a record
typedef struct {
    long offset;
    int key;
    int value;
    char* buffer;
} Record;

// Define the data structure for the collection of records
typedef struct {
    Record** records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} RecordCollection;

// Initialize a new record collection with a given capacity
RecordCollection* init_record_collection(size_t capacity) {
    RecordCollection* collection = malloc(sizeof(RecordCollection));
    if (!collection) {
        fprintf(stderr, "Failed to allocate memory for record collection\n");
        return NULL;
    }

    // Initialize the mutex and lock it
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    if (pthread_mutex_init(&collection->mutex, &attr) != 0) {
        fprintf(stderr, "Failed to initialize mutex for record collection\n");
        free(collection);
        return NULL;
    }
    pthread_mutex_lock(&collection->mutex);

    // Allocate memory for the records array and set its capacity
    collection->records = malloc(capacity * sizeof(Record*));
    if (!collection->records) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        pthread_mutex_unlock(&collection->mutex);
        pthread_mutex_destroy(&collection->mutex);
        free(collection);
        return NULL;
    }
    collection->capacity = capacity;
    collection->count = 0;

    // Initialize the records with default values
    for (size_t i = 0; i < capacity; ++i) {
        Record* record = malloc(sizeof(Record));
        if (!record) {
            fprintf(stderr, "Failed to allocate memory for record %zu\n", i);
            pthread_mutex_unlock(&collection->mutex);
            pthread_mutex_destroy(&collection->mutex);
            free(collection->records);
            free(collection);
            return NULL;
        }
        record->offset = 0;
        record->key = 0;
        record->value = 0;
        record->buffer = NULL;
        collection->records[i] = record;
    }

    // Unlock the mutex and return the collection
    pthread_mutex_unlock(&collection->mutex);
    return collection;
}

// Add a new record to the collection with a given offset, key, and value
bool add_record(RecordCollection* collection, long offset, int key, int value) {
    if (!collection || !collection->records) {
        fprintf(stderr, "Invalid record collection\n");
        return false;
    }

    // Lock the mutex and check for capacity
    pthread_mutex_lock(&collection->mutex);
    if (collection->count >= collection->capacity) {
        fprintf(stderr, "Record collection is full\n");
        pthread_mutex_unlock(&collection->mutex);
        return false;
    }

    // Allocate memory for the new record and set its values
    Record* record = malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Failed to allocate memory for new record\n");
        pthread_mutex_unlock(&collection->mutex);
        return false;
    }
    record->offset = offset;
    record->key = key;
    record->value = value;
    collection->records[collection->count] = record;
    ++collection->count;

    // Unlock the mutex and return success
    pthread_mutex_unlock(&collection->mutex);
    return true;
}

// Remove a record from the collection with a given key
bool remove_record(RecordCollection* collection, int key) {
    if (!collection || !collection->records) {
        fprintf(stderr, "Invalid record collection\n");
        return false;
    }

    // Lock the mutex and find the index of the record to remove
    pthread_mutex_lock(&collection->mutex);
    size_t i = 0;
    while (i < collection->count && collection->records[i]->key != key) {
        ++i;
    }
    if (i == collection->count) {
        fprintf(stderr, "Record with key %d not found\n", key);
        pthread_mutex_unlock(&collection->mutex);
        return false;
    }

    // Remove the record and free its memory
    Record* record = collection->records[i];
    memmove(collection->records + i, collection->records + i + 1, (collection->count - i - 1) * sizeof(Record*));
    --collection->count;
    free(record);

    // Unlock the mutex and return success
    pthread_mutex_unlock(&collection->mutex);
    return true;
}

// Get a record from the collection with a given key
Record* get_record(RecordCollection* collection, int key) {
    if (!collection || !collection->records) {
        fprintf(stderr, "Invalid record collection\n");
        return NULL;
    }

    // Lock the mutex and find the index of the record to get
    pthread_mutex_lock(&collection->mutex);
    size_t i = 0;
    while (i < collection->count && collection->records[i]->key != key) {
        ++i;
    }
    if (i == collection->count) {
        fprintf(stderr, "Record with key %d not found\n", key);
        pthread_mutex_unlock(&collection->mutex);
        return NULL;
    }

    // Return the record and unlock the mutex
    Record* record = collection->records[i];
    pthread_mutex_unlock(&collection->mutex);
    return record;
}

// Free a record collection and its records
void free_record_collection(RecordCollection* collection) {
    if (!collection || !collection->records) {
        fprintf(stderr, "Invalid record collection\n");
        return;
    }

    // Lock the mutex and free each record in the collection
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->count; ++i) {
        Record* record = collection->records[i];
        if (record->buffer) {
            free(record->buffer);
        }
        free(record);
    }
    pthread_mutex_unlock(&collection->mutex);

    // Free the records array and mutex, then free the collection itself
    free(collection->records);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}
```
