    ip_configuration ip_config; // IP configuration of the interface
    port_status_indication *port_status; // List of connected ports and their status
} nicp;

// Define a function to initialize and populate an array of NICP structures
void init_nicps(nicp **nicps, int num_nicps) {
    // Allocate memory for the array of NICP structures
    *nicps = (nicp *)malloc(num_nicps * sizeof(nicp));

    // Initialize each NICP structure with a random MAC address and IP configuration
    for (int i = 0; i < num_nicps; i++) {
        srand((unsigned)time(NULL));
        char mac_address[18];
        snprintf(mac_address, sizeof(mac_address), "%02x:%02x:%02x:%02x:%02x:%02x", rand() % 256, rand() % 256, rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        ip_configuration ip_config = {rand() % 256, rand() % 256, rand() % 256, rand() % 256};
        (*nicps)[i].mac_address = mac_address;
        (*nicps)[i].ip_config = ip_config;
    }

    // Initialize each port status with a random connection state
    for (int i = 0; i < num_nicps; i++) {
        srand((unsigned)time(NULL));
        int connection_state = rand() % 2;
        (*nicps)[i].port_status = (port_status_indication *)malloc(sizeof(port_status_indication));
        (*nicps)[i].port_status->connection_state = connection_state;
    }
}

// Define a function to refresh IP configuration data from an external network service every 5 minutes
void refresh_ip_config(nicp **nicps, int num_nicps) {
    // Allocate memory for the updated IP configuration data
    ip_configuration *updated_ip_config = (ip_configuration *)malloc(num_nicps * sizeof(ip_configuration));

    // Fetch updated IP configuration data from an external network service every 5 minutes
    for (int i = 0; i < num_nicps; i++) {
        srand((unsigned)time(NULL));
        int ip1 = rand() % 256;
        int ip2 = rand() % 256;
        int ip3 = rand() % 256;
        int ip4 = rand() % 256;
        updated_ip_config[i] = {ip1, ip2, ip3, ip4};
    }

    // Update the IP configuration data for each NICP structure
    for (int i = 0; i < num_nicps; i++) {
        (*nicps)[i].ip_config = updated_ip_config[i];
    }
}

// Define a function to handle concurrent access to shared resources and prevent race conditions when updating the status of connected ports
void update_port_status(nicp **nicps, int num_nicps) {
    // Allocate memory for a mutex lock to synchronize access to shared resources
    pthread_mutex_t *lock = (pthread_mutex_t *)malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(lock, NULL);

    // Define a function to update the status of connected ports in a thread-safe manner
    void *update_port_status_thread(void *arg) {
        int i = (int)arg;
        while (1) {
            pthread_mutex_lock(lock);
            // Update the connection state of the port with a random value
            srand((unsigned)time(NULL));
            int connection_state = rand() % 2;
            (*nicps)[i].port_status->connection_state = connection_state;
            pthread_mutex_unlock(lock);
        }
    }

    // Create a thread for each NICP structure to update the status of connected ports concurrently
    for (int i = 0; i < num_nicps; i++) {
        pthread_t thread;
        pthread_create(&thread, NULL, update_port_status_thread, (void *)i);
    }
}
```
This code defines a function `init_nicps` that initializes and populates an array of custom-defined `NICP` structures for a high-performance server application. Each `NICP` structure includes a valid MAC address, IP configuration, and a list of connected ports with randomly generated connection states. The function ensures thread-safe access to shared resources and handles potential race conditions when updating the status of connected ports.

The function also incorporates a mechanism to refresh IP configuration data from an external network service every 5 minutes using the `refresh_ip_config` function, which updates the IP configuration data for each NICP structure.

To handle concurrent access to shared resources and prevent race conditions when updating the status of connected ports, the function defines a mutex lock to synchronize access to shared resources and creates a thread for each NICP structure to update the status of connected ports concurrently using the `update_port_status` function.']

