// Define the function to manage the dynamic list of custom message objects
void manage_messages(MessageArray* messages, int N) {
    // Initialize the array with a predefined number of elements
    messages->size = 0;
    messages->capacity = N;
    messages->messages = (Message**)malloc(sizeof(Message*) * N);

    // Define the mutex for thread-safe operations
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Define the function to add a new message
    void add_message(Message* message) {
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);

        // Check if there is enough space in the array for the new message
        if (messages->size == messages->capacity) {
            // Double the capacity of the array if it is full
            messages->capacity *= 2;
            messages->messages = (Message**)realloc(messages->messages, sizeof(Message*) * messages->capacity);
        }

        // Add the new message to the end of the array
        messages->messages[messages->size++] = message;

        // Release the lock on the mutex
        pthread_mutex_unlock(&mutex);
    }

    // Define the function to retrieve messages within a specified time range
    void get_messages(long start, long end) {
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);

        // Iterate over the array of messages and check if they are within the specified time range
        for (int i = 0; i < messages->size; i++) {
            Message* message = messages->messages[i];
            if (message->timestamp >= start && message->timestamp <= end) {
                // Print the message to the console
                printf("Message %d: sender_id=%d, timestamp=%ld, payload=%s\n", i, message->sender_id, message->timestamp, message->payload);
            }
        }

        // Release the lock on the mutex
        pthread_mutex_unlock(&mutex);
    }

    // Define the function to efficiently update the payload of existing messages
    void update_message(int index, char* new_payload) {
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);

        // Check if the index is valid
        if (index < 0 || index >= messages->size) {
            printf("Invalid index: %d\n", index);
            return;
        }

        // Update the payload of the message at the specified index
        Message* message = messages->messages[index];
        free(message->payload);
        message->payload = new_payload;

        // Release the lock on the mutex
        pthread_mutex_unlock(&mutex);
    }

    // Define the function to delete messages based on message ID
    void delete_messages(int* message_ids, int num_message_ids) {
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);

        // Iterate over the array of messages and check if they have the specified message IDs
        for (int i = 0; i < messages->size; i++) {
            Message* message = messages->messages[i];
            bool found = false;
            for (int j = 0; j < num_message_ids; j++) {
                if (message->message_id == message_ids[j]) {
                    found = true;
                    break;
                }
            }
            if (!found) continue;

            // Remove the message from the array
            messages->size--;
            for (int k = i; k < messages->size; k++) {
                messages->messages[k] = messages->messages[k + 1];
            }
        }

        // Release the lock on the mutex
        pthread_mutex_unlock(&mutex);
    }

    // Define the function to initialize the CRC flags based on a user-specified pattern
    void init_crc_flags(int* crc_indication) {
        // Acquire the lock on the mutex
        pthread_mutex_lock(&mutex);

        // Iterate over the array of messages and initialize the CRC flags based on the user-specified pattern
        for (int i = 0; i < messages->size; i++) {
