static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
static int list_size = 0;
static NFAPI_CRC_INDICATION_PDU_T *list = NULL;

// Function to add a new entry to the list
void add_entry(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, bool CRCFLAG) {
    // Lock the list before modifying it
    pthread_mutex_lock(&list_lock);

    // Check if the RNTI is already in the list
    for (int i = 0; i < list_size; i++) {
        if (list[i].RNTI == RNTI) {
            printf("Duplicate RNTI detected, ignoring entry\n");
            pthread_mutex_unlock(&list_lock);
            return;
        }
    }

    // If the list is full, resize it to accommodate more entries
    if (list_size == 10000) {
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * 20000);
        if (new_list == NULL) {
            printf("Failed to resize list, ignoring entry\n");
            pthread_mutex_unlock(&list_lock);
            return;
        }
        list = new_list;
    }

    // Add the new entry to the list
    list[list_size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list[list_size].RNTI = RNTI;
    list[list_size].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    list[list_size].CRCFLAG = CRCFLAG;
    list_size++;

    // Unlock the list after modifying it
    pthread_mutex_unlock(&list_lock);
