    // Lock the list before modifying it
    pthread_mutex_lock(&list_lock);

    // Find the entry in the list with the matching RNTI
    for (int i = 0; i < list_size; i++) {
        if (list[i].RNTI == RNTI) {
            list[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
            list[i].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
            list[i].CRCFLAG = CRCFLAG;
            break;
        }
    }

    // Unlock the list after modifying it
    pthread_mutex_unlock(&list_lock);
}

// Function to remove an entry from the list
void remove_entry(int RNTI) {
    // Lock the list before modifying it
    pthread_mutex_lock(&list_lock);

    // Find the entry in the list with the matching RNTI
    for (int i = 0; i < list_size; i++) {
        if (list[i].RNTI == RNTI) {
            // Shift all subsequent entries to fill the gap
            for (int j = i + 1; j < list_size; j++) {
                list[j - 1] = list[j];
            }
            list_size--;
            break;
        }
    }

    // Unlock the list after modifying it
    pthread_mutex_unlock(&list_lock);
}

// Function to retrieve an entry from the list by RNTI
