    // Lock the list before accessing it
    pthread_mutex_lock(&list_lock);

    // Find the entry in the list with the matching RNTI
    for (int i = 0; i < list_size; i++) {
        if (list[i].RNTI == RNTI) {
            NFAPI_CRC_INDICATION_PDU_T *entry = &list[i];
            pthread_mutex_unlock(&list_lock);
            return entry;
        }
    }

    // Unlock the list after accessing it
    pthread_mutex_unlock(&list_lock);
    return NULL;
}

// Function to handle incoming data updates from an external source
void update_data(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, bool CRCFLAG) {
    // Lock the list before modifying it
