#define MAX_INTERFACES 10
#define INTERFACE_NAME_LEN 16
#define MAC_ADDR_LEN 6
#define IP_ADDR_LEN 4
#define SUBNET_MASK_LEN 4
#define GATEWAY_IP_LEN 4

typedef struct {
    char name[INTERFACE_NAME_LEN];
    unsigned char mac_addr[MAC_ADDR_LEN];
    unsigned char ip_addr[IP_ADDR_LEN];
    unsigned char subnet_mask[SUBNET_MASK_LEN];
    unsigned char gateway_ip[GATEWAY_IP_LEN];
} interface_config;

interface_config interfaces[MAX_INTERFACES];
int num_interfaces = 0;
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

void init_network_stack() {
    // Initialize the network stack and configure the virtual interfaces
    for (int i = 0; i < num_interfaces; i++) {
        interface_config *interface = &interfaces[i];
        char iface_name[INTERFACE_NAME_LEN];
        snprintf(iface_name, INTERFACE_NAME_LEN, "veth%d", i);
        int sock = socket(AF_INET, SOCK_DGRAM, 0);
        if (sock < 0) {
            perror("socket");
            exit(1);
        }
        struct ifreq ifr;
        memset(&ifr, 0, sizeof(ifr));
        strncpy(ifr.ifr_name, iface_name, INTERFACE_NAME_LEN - 1);
        ifr.ifr_addr.sa_family = AF_INET;
        if (ioctl(sock, SIOCSIFFLAGS, &ifr) < 0) {
            perror("ioctl");
            exit(1);
        }
        close(sock);
    }
}

void configure_interface(int index, interface_config *config) {
    // Configure the specified virtual interface with the given configuration
    pthread_mutex_lock(&config_lock);
    if (index < 0 || index >= num_interfaces) {
        printf("Invalid interface index: %d\n", index);
        return;
    }
    interface_config *interface = &interfaces[index];
    strncpy(interface->name, config->name, INTERFACE_NAME_LEN - 1);
    memcpy(interface->mac_addr, config->mac_addr, MAC_ADDR_LEN);
    memcpy(interface->ip_addr, config->ip_addr, IP_ADDR_LEN);
    memcpy(interface->subnet_mask, config->subnet_mask, SUBNET_MASK_LEN);
    memcpy(interface->gateway_ip, config->gateway_ip, GATEWAY_IP_LEN);
    pthread_mutex_unlock(&config_lock);
}

void update_interface_config(int index, interface_config *config) {
    // Update the configuration of the specified virtual interface with the given configuration
    pthread_mutex_lock(&config_lock);
    if (index < 0 || index >= num_interfaces) {
        printf("Invalid interface index: %d\n", index);
        return;
    }
    interface_config *interface = &interfaces[index];
    strncpy(interface->name, config->name, INTERFACE_NAME_LEN - 1);
    memcpy(interface->mac_addr, config->mac_addr, MAC_ADDR_LEN);
    memcpy(interface->ip_addr, config->ip_addr, IP_ADDR_LEN);
    memcpy(interface->subnet_mask, config->subnet_mask, SUBNET_MASK_LEN);
    memcpy(interface->gateway_ip, config->gateway_ip, GATEWAY_IP_LEN);
    pthread_mutex_unlock(&config_lock);
}

void* configure_interfaces() {
    // Configure the virtual interfaces with their corresponding configurations
    for (int i = 0; i < num_interfaces; i++) {
        interface_config *interface = &interfaces[i];
        char iface_name[INTERFACE_NAME_LEN];
        snprintf(iface_name, INTERFACE_NAME_LEN, "veth%d", i);
        int sock = socket(AF_INET, SOCK_DGRAM, 0);
        if (sock < 0) {
            perror("socket");
            exit(1);
        }
        struct ifreq ifr;
        memset(&ifr, 0, sizeof(ifr));
        strncpy(ifr.ifr_name, iface_name, INTERFACE_NAME_LEN - 1);
        ifr.ifr_addr.sa_family = AF_INET;
        // Set the MAC address of the interface
        memcpy(ifr.ifr_hwaddr.sa_data, interface->mac_addr, MAC_ADDR_LEN);
        if (ioctl(sock, SIOCSIFHWADDR, &ifr) < 0) {
            perror("ioctl");
            exit(1);
        }
        // Set the IP address of the interface
        memcpy(&ifr.ifr_addr.sa_data[2], interface->ip_addr, IP_ADDR_LEN);
        if (ioctl(sock, SIOCSIFADDR, &ifr) < 0) {
            perror("ioctl");
            exit(1);
        }
        // Set the subnet mask of the interface
        memcpy(&ifr.ifr_addr.sa_data[6], interface->subnet_mask, SUBNET_MASK_LEN);
        if (ioctl(sock, SIOCSIFNETMASK, &ifr) < 0) {
            perror("ioctl");
            exit(1);
        }
        // Set the default gateway of the interface
        memcpy(&ifr.ifr_addr.sa_data[10], interface->gateway_ip, GATEWAY_IP_LEN);
        if (ioctl(sock, SIOCSIFDSTADDR, &ifr) < 0) {
            perror("ioctl");
            exit(1);
        }
        close(sock);
    }
}

void* update_interface_configs() {
    // Update the configurations of all virtual interfaces with their corresponding configurations
    for (int i = 0; i < num_interfaces; i++) {
        interface_config *interface = &interfaces[i];
        char iface_name[INTERFACE_NAME_LEN];
        snprintf(iface_name, INTERFACE_NAME_LEN, "veth%d", i);
        int sock = socket(AF_INET, SOCK_DGRAM, 0);
        if (sock < 0) {
            perror("socket");
            exit(1);
        }
