        strncpy(ifr.ifr_name, iface_name, INTERFACE_NAME_LEN - 1);
        ifr.ifr_addr.sa_family = AF_INET;
        // Set the MAC address of the interface
        memcpy(ifr.ifr_hwaddr.sa_data, interface->mac_addr, MAC_ADDR_LEN);
        if (ioctl(sock, SIOCSIFHWADDR, &ifr) < 0) {
            perror("ioctl");
            exit(1);
        }
        // Set the IP address of the interface
        memcpy(&ifr.ifr_addr.sa_data[2], interface->ip_addr, IP_ADDR_LEN);
        if (ioctl(sock, SIOCSIFADDR, &ifr) < 0) {
            perror("ioctl");
            exit(1);
        }
        // Set the subnet mask of the interface
        memcpy(&ifr.ifr_addr.sa_data[6], interface->subnet_mask, SUBNET_MASK_LEN);
        if (ioctl(sock, SIOCSIFNETMASK, &ifr) < 0) {
            perror("ioctl");
            exit(1);
        }
        // Set the default gateway of the interface
        memcpy(&ifr.ifr_addr.sa_data[10], interface->gateway_ip, GATEWAY_IP_LEN);
        if (ioctl(sock, SIOCSIFDSTADDR, &ifr) < 0) {
            perror("ioctl");
            exit(1);
        }
        close(sock);
    }
}

void* handle_external_config() {
    // Handle external network configuration updates by updating the configurations of all virtual interfaces
    while (true) {
        update_interface_configs();
        sleep(10);
    }
}

int main() {
    // Initialize the network stack and configure the virtual interfaces
    init_network_stack();
    configure_interfaces();
    // Handle external network configuration updates in a separate thread
    pthread_t handle_config_thread;
    if (pthread_create(&handle_config_thread, NULL, handle_external_config, NULL) < 0) {
        perror("pthread_create");
        exit(1);
    }
    // Update the configurations of all virtual interfaces in a separate thread
    pthread_t update_config_thread;
    if (pthread_create(&update_config_thread, NULL, update_interface_configs, NULL) < 0) {
        perror("pthread_create");
        exit(1);
    }
    // Join the threads to ensure proper termination
    pthread_join(handle_config_thread, NULL);
    pthread_join(update_config_thread, NULL);
    return 0;
}
