// Function to generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void generate_crc_indication_pdu_list(int n, int *rnti_array) {
    // Initialize the list with NULL pointers
    NFAPI_CRC_INDICATION_PDU_T **list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < n; i++) {
