        pdu->rx_ue_information_tag = rnti_array[i];
        pdu->rnti = rnti_array[i];
        list[i] = pdu;
    }

    // Randomly set the CRCFLAG for each structure
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        int crcflag = rand() % 2;
        list[i]->crc_indication_rel8_tag.crcflag = crcflag;
    }

    // Check the integrity of each structure before adding it to the list
    for (int i = 0; i < n; i++) {
