// Define the function to manage the dynamic linked list
void manage_list(LIST_NODE_T **head, int size) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Check if the list is full and needs to be resized
    if (size > MAX_SIZE) {
        // Resize the list by half
        size = size / 2;

        // Iterate over the list and remove the last node
        LIST_NODE_T *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        free(current);
    }

    // Add a new node to the end of the list
    LIST_NODE_T *new_node = malloc(sizeof(LIST_NODE_T));
    new_node->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = NULL;

    // Iterate over the list and add the new node to the end
    LIST_NODE_T *current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_node;

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

