    if (add_entry) {
        bool duplicate = false;
        uint8_t crc_flag = rand() % 256;
        for (size_t i = 0; i < array->num_entries; i++) {
            if (array->entries[i].RNTI == RNTI) {
                duplicate = true;
                break;
            }
        }
        if (!duplicate) {
            NFAPI_CRC_INDICATION_PDU_T new_entry = {0};
