    // Initialize a dynamically allocated array to store the unique integers
    int *unique_integers = (int *)malloc(size * sizeof(int));
    if (!unique_integers) {
        fprintf(stderr, "Error: Failed to allocate memory for unique integers\n");
        return;
    }

    // Initialize a variable to store the number of unique integers found
