        bool is_unique = true;
        for (int j = 0; j < num_unique; j++) {
            if (input[i] == unique_integers[j]) {
                is_unique = false;
                break;
            }
        }
        if (is_unique) {
            unique_integers[num_unique++] = input[i];
        }
    }

    // Allocate and populate a variable number of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_unique * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indication_pdus) {
        fprintf(stderr, "Error: Failed to allocate memory for CRC indication PDUs\n");
        free(unique_integers);
        return;
    }

    // Iterate through the unique integers and create a NFAPI_CRC_INDICATION_PDU_T structure for each one
