    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file for CRC indication PDUs\n");
        free(unique_integers);
        free(crc_indication_pdus);
        return;
    }
    for (int i = 0; i < num_unique; i++) {
        fprintf(log_file, "CRC indication PDU %d: tag=%d, rnti=%d, crcflag=%d\n", i + 1, crc_indication_pdus[i].tag, crc_indication_pdus[i].rnti, crc_indication_pdus[i].crc_indication_rel8.crcflag);
    }
    fclose(log_file);

    // Free the allocated resources
    free(unique_integers);
    free(crc_indication_pdus);
}
