#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Structures for nodes and records
struct node {
    int value;
    struct node* next;
};

struct record {
    int id;
    double value;
};

// Function to dynamically allocate memory for a singly linked list of nodes
struct node* create_node(int value) {
    struct node* new_node = malloc(sizeof(struct node));
    if (new_node == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for node\n");
        return NULL;
    }
    new_node->value = value;
    new_node->next = NULL;
    return new_node;
}

// Function to dynamically allocate memory for a two-dimensional array of records
struct record** create_records(int num_records) {
    struct record** records = malloc(num_records * sizeof(struct record*));
    if (records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        return NULL;
    }
    for (int i = 0; i < num_records; i++) {
        records[i] = malloc(sizeof(struct record));
        if (records[i] == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for record %d\n", i);
            return NULL;
        }
    }
    return records;
}

// Function to read input from the user and populate the linked list and two-dimensional array of records
void populate_data(struct node** head, struct record*** records) {
    int num_records = 0;
    printf("Enter the number of records: ");
    scanf("%d", &num_records);
    *records = create_records(num_records);
    if (*records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        return;
    }
    for (int i = 0; i < num_records; i++) {
        printf("Enter the value and id of record %d: ", i);
        scanf("%d%lf", &(*records)[i]->id, &(*records)[i]->value);
    }
    *head = NULL;
    for (int i = 0; i < num_records; i++) {
        struct node* new_node = create_node((*records)[i]->id);
        if (new_node == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for node\n");
            return;
        }
        new_node->next = *head;
        *head = new_node;
    }
}

// Function to free the memory allocated by create_node and create_records
void free_data(struct node* head, struct record** records) {
    while (head != NULL) {
        struct node* temp = head->next;
        free(head);
        head = temp;
    }
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }
    free(records);
}

int main() {
    struct node* head = NULL;
    struct record** records = NULL;
    populate_data(&head, &records);
    // Use the linked list and two-dimensional array of records here
    free_data(head, records);
    return 0;
}
```
