        crc_indications[i].crc_indication.crc_indication_rel8.crc_flag = rand() % 2;
    }

    return crc_indications;
}

// Define a function to populate a linked list of CRC indication structures
CrcIndicationNode* allocate_crc_indications_linked_list(int num_users) {
    // Allocate memory for the head node of the linked list
    CrcIndicationNode *head = (CrcIndicationNode*)malloc(sizeof(CrcIndicationNode));
    head->data = NULL;
    head->next = NULL;

    // Initialize the RX UE information tag and RNTI for each structure
    for (int i = 0; i < num_users; i++) {
        CrcIndicationData *data = (CrcIndicationData*)malloc(sizeof(CrcIndicationData));
        data->crc_indication.rx_ue_information.tag = RX_UE_INFORMATION_TAG;
        data->crc_indication.rx_ue_information.rnti = i + 1;
        data->crc_indication.crc_indication_rel8.crc_flag = rand() % 2;

        // Add the structure to the linked list
        CrcIndicationNode *node = (CrcIndicationNode*)malloc(sizeof(CrcIndicationNode));
        node->data = data;
        node->next = NULL;

        if (head->data == NULL) {
            head->data = data;
        } else {
            CrcIndicationNode *current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = node;
        }
    }

    return head;
}

// Define a function to free the memory allocated for an array of CRC indication structures
void free_crc_indications(CrcIndicationData *crc_indications, int num_users) {
    // Free the memory allocated for each structure in the array
    for (int i = 0; i < num_users; i++) {
        free(crc_indications[i].crc_indication.rx_ue_information.rnti);
