    free(crc_indications);
}

// Define a function to free the memory allocated for a linked list of CRC indication structures
void free_crc_indications_linked_list(CrcIndicationNode *head) {
    // Free the memory allocated for each structure in the linked list
    while (head != NULL) {
        CrcIndicationData *data = head->data;
        free(data->crc_indication.rx_ue_information.rnti);
        head = head->next;
    }

    // Free the memory allocated for the linked list
    free(head);
}

// Define a function to handle concurrent access to shared resources
void synchronized_access(CrcIndicationData *crc_indications, int num_users) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Lock the mutex before accessing shared resources
    pthread_mutex_lock(&mutex);

    // Perform the operation that requires synchronized access to shared resources
    for (int i = 0; i < num_users; i++) {
        crc_indications[i].crc_indication.rx_ue_information.tag = RX_UE_INFORMATION_TAG;
        crc_indications[i].crc_indication.rx_ue_information.rnti = i + 1;
    }

    // Unlock the mutex after accessing shared resources
    pthread_mutex_unlock(&mutex);
}

// Define a function to handle concurrent access to shared resources in a linked list
void synchronized_access_linked_list(CrcIndicationNode *head) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Lock the mutex before accessing shared resources
    pthread_mutex_lock(&mutex);

    // Perform the operation that requires synchronized access to shared resources
    while (head != NULL) {
        CrcIndicationData *data = head->data;
        data->crc_indication.rx_ue_information.tag = RX_UE_INFORMATION_TAG;
        data->crc_indication.rx_ue_information.rnti = head->next->data->crc_indication.rx_ue_information.rnti + 1;
        head = head->next;
    }

    // Unlock the mutex after accessing shared resources
    pthread_mutex_unlock(&mutex);
}

