#include <semaphore.h>

// Define the structure for the linked list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct NFAPI_CRC_INDICATION_PDU {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU *next;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list head pointer
NFAPI_CRC_INDICATION_PDU_T *head = NULL;

// Define the mutex and semaphore for synchronization
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
semaphore_t semaphore = SEMAPHORE_INITIALIZER;

// Function to add a new structure to the linked list
void add_structure(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    // Create a new structure and allocate memory for it
    NFAPI_CRC_INDICATION_PDU_T *new_structure = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_structure->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_structure->RNTI = RNTI;
    new_structure->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_structure->CRCFLAG = CRCFLAG;

    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Check if the RNTI value is already present in the list
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        if (current->RNTI == RNTI) {
            // If the RNTI value is already present, free the new structure and return
            free(new_structure);
            pthread_mutex_unlock(&mutex);
            return;
        }
        current = current->next;
    }

    // Add the new structure to the linked list
    new_structure->next = head;
    head = new_structure;

    // Unlock the mutex and signal the semaphore to release waiting threads
    pthread_mutex_unlock(&mutex);
    semaphore_signal(&semaphore);
}

// Function to remove a structure from the linked list
void remove_structure(int RNTI) {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Find the structure with the matching RNTI value and remove it from the linked list
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        if (current->RNTI == RNTI) {
            // Remove the structure from the linked list
            NFAPI_CRC_INDICATION_PDU_T *temp = current;
            current = current->next;
            free(temp);
            break;
        }
        current = current->next;
    }

    // Unlock the mutex and signal the semaphore to release waiting threads
    pthread_mutex_unlock(&mutex);
    semaphore_signal(&semaphore);
}

// Function to validate the CRC flag values in the linked list
void validate_crc_flags() {
    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Iterate through the linked list and validate the CRC flag values
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        if (current->CRCFLAG < 0 || current->CRCFLAG > 127) {
            // If the CRC flag value is outside the specified range, log an error and remove the structure from the linked list
            printf("Error: Invalid CRC flag value %d for RNTI %d\n", current->CRCFLAG, current->RNTI);
