// Define a structure to represent an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int crc;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list node to store the CRC indications
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

// Define a global variable to keep track of the head of the linked list
Node *head = NULL;

// Define a semaphore to synchronize access to the linked list
sem_t sem;

// Function to add a new CRC indication to the linked list
void addCrcIndication(NFAPI_CRC_INDICATION_PDU_T *crc) {
    // Lock the semaphore to prevent concurrent access to the linked list
    sem_wait(&sem);

    // Create a new node for the CRC indication
    Node *newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the data field of the new node with the given CRC indication
    newNode->data = crc;

    // If the linked list is empty, set the head to point to the new node
    if (head == NULL) {
        head = newNode;
    } else {
        // Otherwise, add the new node to the end of the linked list
        Node *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    // Unlock the semaphore and return
    sem_post(&sem);
}

// Function to process a CRC indication
void processCrcIndication(NFAPI_CRC_INDICATION_PDU_T *crc) {
    // Lock the semaphore to prevent concurrent access to the linked list
    sem_wait(&sem);

    // If the linked list is empty, log an error and return
    if (head == NULL) {
        printf("Linked list is empty\n");
        sem_post(&sem);
        return;
    }

    // Otherwise, process each CRC indication in the linked list
    Node *current = head;
    while (current != NULL) {
        // Process the current CRC indication
        printf("Processing CRC indication: %d\n", current->data->crc);

        // Remove the current node from the linked list
        Node *next = current->next;
        free(current);
        current = next;
    }

    // Reset the head of the linked list to NULL
    head = NULL;

    // Unlock the semaphore and return
    sem_post(&sem);
}

// Function to log the number of processed CRC indications per second
void logCrcIndications() {
    // Lock the semaphore to prevent concurrent access to the linked list
    sem_wait(&sem);

    // If the linked list is empty, log an error and return
    if (head == NULL) {
        printf("Linked list is empty\n");
        sem_post(&sem);
        return;
    }

    // Otherwise, count the number of CRC indications in the linked list
    int numCrcIndications = 0;
    Node *current = head;
    while (current != NULL) {
        numCrcIndications++;
        current = current->next;
    }

    // Log the number of processed CRC indications per second
    printf("Processed %d CRC indications per second\n", numCrcIndications);

    // Reset the head of the linked list to NULL
    head = NULL;

    // Unlock the semaphore and return
    sem_post(&sem);
}

// Function to reset the counter for processed CRC indications per second
void resetCrcIndicationCounter() {
    // Lock the semaphore to prevent concurrent access to the linked list
    sem_wait(&sem);

    // If the linked list is empty, log an error and return
    if (head == NULL) {
        printf("Linked list is empty\n");
        sem_post(&sem);
        return;
    }

    // Otherwise, reset the head of the linked list to NULL
    head = NULL;

    // Unlock the semaphore and return
    sem_post(&sem);
}
