// Define the maximum size of the list
#define MAX_LIST_SIZE 1024

// Define the maximum file size for the log file
#define LOG_FILE_MAX_SIZE (1024 * 1024) // 1 MB

// Define the seed for the random number generator
#define RANDOM_SEED 123456789

// Define the structure for the cell configuration
typedef struct {
    int cell_id;
    PHY_LAYER_PARAMETERS phy_layer_parameters;
    NFAPI_CRC_INDICATION_PDU_T crc_indication_pdu;
} NR_CELL_CONFIG_S_T;

// Define the structure for the list of cell configurations
typedef struct {
    int size;
    NR_CELL_CONFIG_S_T *cells[MAX_LIST_SIZE];
} CELL_CONFIG_LIST_T;

// Define the function to initialize and manage the list of cell configurations
void init_cell_config_list(CELL_CONFIG_LIST_T *list) {
    // Initialize the list size to 0
    list->size = 0;

    // Initialize the cells array to NULL
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        list->cells[i] = NULL;
    }
}

// Define the function to add a new cell configuration to the list
void add_cell_config(CELL_CONFIG_LIST_T *list, int cell_id, PHY_LAYER_PARAMETERS phy_layer_parameters) {
    // Check if the list is full
    if (list->size == MAX_LIST_SIZE) {
        printf("List is full\n");
        return;
    }

    // Create a new cell configuration structure
    NR_CELL_CONFIG_S_T *cell = malloc(sizeof(NR_CELL_CONFIG_S_T));
    if (cell == NULL) {
        printf("Failed to allocate memory for cell configuration\n");
        return;
    }

    // Initialize the cell configuration structure
    cell->cell_id = cell_id;
    cell->phy_layer_parameters = phy_layer_parameters;
    cell->crc_indication_pdu.rx_ue_information_tag = RX_UE_INFORMATION_TAG;
    cell->crc_indication_pdu.rnti = RNTI;
    cell->crc_indication_pdu.crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG;
    cell->crc_indication_pdu.crflag = (rand() % 2) ? 1 : 0;

    // Add the new cell configuration to the list
    list->cells[list->size++] = cell;
}

// Define the function to remove a cell configuration from the list
void remove_cell_config(CELL_CONFIG_LIST_T *list, int cell_id) {
    // Find the index of the cell configuration to be removed
    int i;
    for (i = 0; i < list->size; i++) {
        if (list->cells[i]->cell_id == cell_id) {
            break;
        }
    }

    // Check if the cell configuration was found
    if (i == list->size) {
        printf("Cell configuration not found\n");
        return;
    }

    // Remove the cell configuration from the list
    free(list->cells[i]);
    list->cells[i] = NULL;
    list->size--;
}

// Define the function to update a cell configuration in the list
void update_cell_config(CELL_CONFIG_LIST_T *list, int cell_id, PHY_LAYER_PARAMETERS phy_layer_parameters) {
    // Find the index of the cell configuration to be updated
    int i;
    for (i = 0; i < list->size; i++) {
        if (list->cells[i]->cell_id == cell_id) {
            break;
        }
    }

    // Check if the cell configuration was found
    if (i == list->size) {
        printf("Cell configuration not found\n");
        return;
    }

    // Update the cell configuration in the list
    list->cells[i]->phy_layer_parameters = phy_layer_parameters;
}

// Define the function to retrieve a cell configuration from the list
NR_CELL_CONFIG_S_T *get_cell_config(CELL_CONFIG_LIST_T *list, int cell_id) {
    // Find the index of the cell configuration to be retrieved
    int i;
    for (i = 0; i < list->size; i++) {
        if (list->cells[i]->cell_id == cell_id) {
            break;
        }
    }

    // Check if the cell configuration was found
    if (i == list->size) {
        printf("Cell configuration not found\n");
        return NULL;
    }

    // Return the cell configuration from the list
    return list->cells[i];
}

// Define the function to retrieve all cell configurations from the list
NR_CELL_CONFIG_S_T **get_all_cell_configs(CELL_CONFIG_LIST_T *list) {
    // Create an array of pointers to NR_CELL_CONFIG_S_T structures
    NR_CELL_CONFIG_S_T **cells = malloc(sizeof(NR_CELL_CONFIG_S_T *) * list->size);
    if (cells == NULL) {
        printf("Failed to allocate memory for cell configurations\n");
        return NULL;
    }

    // Copy the cell configurations from the list to the array
    for (int i = 0; i < list->size; i++) {
        cells[i] = list->cells[i];
    }

    // Return the array of pointers to NR_CELL_CONFIG_S_T structures
    return cells;
}

// Define the function to clear the cell configuration list
void clear_cell_config_list(CELL_CONFIG_LIST_T *list) {
    // Free the memory allocated for the cells array
    free(list->cells);

    // Reset the list size to 0
    list->size = 0;
}

// Define the function to log cell configuration changes to a file
void log_cell_config_changes(CELL_CONFIG_LIST_T *list, char *filename) {
    // Open the log file for writing
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        printf("Failed to open log file\n");
        return;
