    // Write the cell configuration changes to the log file
    for (int i = 0; i < list->size; i++) {
        NR_CELL_CONFIG_S_T *cell = list->cells[i];
        char buffer[1024];
        sprintf(buffer, "%d %d %d %d %d\n", cell->cell_id, cell->phy_layer_parameters.dl_carrier_bandwidth, cell->phy_layer_parameters.ul_carrier_bandwidth, cell->crc_indication_pdu.rx_ue_information_tag, cell->crc_indication_pdu.rnti);
        write(fd, buffer, strlen(buffer));
    }

    // Close the log file
    close(fd);
}

// Define the function to archive older entries in the log file
void archive_log_file(char *filename) {
    // Open the log file for reading and writing
    int fd = open(filename, O_RDWR | O_CREAT, 0644);
    if (fd == -1) {
        printf("Failed to open log file\n");
        return;
    }

    // Read the contents of the log file into a buffer
    char *buffer = malloc(LOG_FILE_MAX_SIZE);
    read(fd, buffer, LOG_FILE_MAX_SIZE);

    // Close the log file
    close(fd);

    // Create a new log file with a timestamp suffix
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char *timestamp = asctime(tm);
    strtok(timestamp, "\n");
    char new_filename[1024];
    sprintf(new_filename, "%s-%s.log", filename, timestamp);
    fd = open(new_filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        printf("Failed to create new log file\n");
        return;
    }

    // Write the contents of the buffer to the new log file
    write(fd, buffer, LOG_FILE_MAX_SIZE);

    // Close the new log file
    close(fd);
}

// Define the function to overwrite older entries in the log file
void overwrite_log_file(char *filename) {
    // Open the log file for reading and writing
