// Define the maximum number of structures in the array
#define MAX_STRUCTURES 1024

// Function to populate the CRC indication array with new data
void populate_crc_indication_array(NFAPI_CRC_INDICATION_PDU_T *new_data) {
    // Check if the array is already allocated and has space for more structures
    if (crc_indication_array == NULL || crc_indication_array->num_structures < MAX_STRUCTURES) {
        // Allocate memory for the new structure
        NFAPI_CRC_INDICATION_PDU_T *new_structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_structure == NULL) {
            printf("Error: Out of memory\n");
            return;
        }

        // Copy the new data into the new structure
        memcpy(new_structure, new_data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Add the new structure to the array
        crc_indication_array->num_structures++;
        crc_indication_array = realloc(crc_indication_array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * crc_indication_array->num_structures);
        if (crc_indication_array == NULL) {
            printf("Error: Out of memory\n");
            return;
        }
        crc_indication_array[crc_indication_array->num_structures - 1] = *new_structure;
    } else {
        // The array is full, so we need to shuffle the data and add the new structure at the end
        for (int i = 0; i < crc_indication_array->num_structures - 1; i++) {
            crc_indication_array[i] = crc_indication_array[i + 1];
        }
        memcpy(crc_indication_array[MAX_STRUCTURES - 1], new_data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
}

// Function to check for duplicate RNTIs in the array and log an error if found
void validate_crc_indication_array() {
    // Iterate through the array and check for duplicate RNTIs
    for (int i = 0; i < crc_indication_array->num_structures - 1; i++) {
        for (int j = i + 1; j < crc_indication_array->num_structures; j++) {
            if (crc_indication_array[i].rnti == crc_indication_array[j].rnti) {
                printf("Error: Duplicate RNTI value found in CRC indication array\n");
                return;
            }
        }
    }
}

// Function to handle memory allocation failures gracefully
void handle_memory_allocation_failure() {
