    printf("Error: Out of memory\n");
    exit(1);
}

// Function to shuffle the array after population to ensure data randomness for testing purposes
void shuffle_crc_indication_array() {
    // Implement a Fisher-Yates shuffle algorithm to shuffle the array
    for (int i = crc_indication_array->num_structures - 1; i > 0; i--) {
        int j = rand() % (i + 1);
