pthread_mutex_t crc_indication_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the array with a given size
void init_crc_indication_array(size_t size) {
    // Allocate memory for the array
    crc_indication_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    if (!crc_indication_array) {
