    for (size_t i = 0; i < size; i++) {
        crc_indication_array[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        crc_indication_array[i].RNTI = rand() % 1000000000;
        crc_indication_array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }
    // Set the size of the array
    crc_indication_array_size = size;
}

// Function to add a new entry to the array
void add_crc_indication(NFAPI_CRC_INDICATION_PDU_T *new_entry) {
    // Lock the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&crc_indication_lock);
    // Check if the array is full
    if (crc_indication_array_size == 0) {
        printf("Error: crc_indication_array is full\n");
        pthread_mutex_unlock(&crc_indication_lock);
        return;
    }
    // Add the new entry to the array
    crc_indication_array[crc_indication_array_size] = *new_entry;
    // Increment the size of the array
    crc_indication_array_size++;
    pthread_mutex_unlock(&crc_indication_lock);
}

// Function to remove an entry from the array
void remove_crc_indication(NFAPI_CRC_INDICATION_PDU_T *entry) {
    // Lock the mutex to ensure thread-safe access to the array
    pthread_mutex_lock(&crc_indication_lock);
    // Find the index of the entry in the array
    size_t index = 0;
    for (size_t i = 0; i < crc_indication_array_size; i++) {
        if (crc_indication_array[i].RX_UE_INFORMATION_TAG == entry->RX_UE_INFORMATION_TAG &&
            crc_indication_array[i].RNTI == entry->RNTI &&
            crc_indication_array[i].CRC_INDICATION_REL8_TAG == entry->CRC_INDICATION_REL8_TAG) {
            index = i;
            break;
        }
    }
    // Check if the entry was found in the array
    if (index == 0) {
        printf("Error: Entry not found in crc_indication_array\n");
        pthread_mutex_unlock(&crc_indication_lock);
        return;
    }
    // Remove the entry from the array
    for (size_t i = index; i < crc_indication_array_size - 1; i++) {
        crc_indication_array[i] = crc_indication_array[i + 1];
    }
    // Decrement the size of the array
    crc_indication_array_size--;
    pthread_mutex_unlock(&crc_indication_lock);
}

