// Define a struct to represent a network statistic
typedef struct {
    int cell_id;
    double throughput;
    double packet_loss_rate;
    double error_rate;
} NetworkStat;

// Define a dynamic array to store the network statistics
NetworkStat *stats = NULL;
int stats_size = 0;
int stats_capacity = 0;

// Function to initialize and manage the dynamic list of network statistics
void init_network_statistics(int cell_id, int time_interval) {
    // Allocate memory for the dynamic array
    stats_capacity = time_interval * 10; // Arbitrary multiplier for initial capacity
    stats = (NetworkStat *)malloc(stats_capacity * sizeof(NetworkStat));
    if (!stats) {
        printf("Error: Failed to allocate memory for network statistics\n");
        exit(1);
    }

    // Initialize the dynamic array with default values
    for (int i = 0; i < stats_capacity; i++) {
        stats[i].cell_id = cell_id;
        stats[i].throughput = 0.0;
        stats[i].packet_loss_rate = 0.0;
        stats[i].error_rate = 0.0;
    }
}

// Function to add a new network statistic to the dynamic list
void add_network_statistic(int cell_id, double throughput, double packet_loss_rate, double error_rate) {
    // Check if the dynamic array needs to be resized
    if (stats_size == stats_capacity) {
        stats_capacity *= 2; // Double the capacity of the dynamic array
        NetworkStat *new_stats = (NetworkStat *)realloc(stats, stats_capacity * sizeof(NetworkStat));
        if (!new_stats) {
            printf("Error: Failed to resize network statistics\n");
            exit(1);
        }
        stats = new_stats;
    }

    // Add the new statistic to the dynamic array
    stats[stats_size].cell_id = cell_id;
    stats[stats_size].throughput = throughput;
    stats[stats_size].packet_loss_rate = packet_loss_rate;
    stats[stats_size].error_rate = error_rate;
    stats_size++;
}

// Function to remove a network statistic from the dynamic list
void remove_network_statistic(int index) {
    // Check if the index is valid
    if (index < 0 || index >= stats_size) {
        printf("Error: Invalid index for removing network statistic\n");
        exit(1);
    }

    // Shift all elements after the removed element to the left
    for (int i = index; i < stats_size - 1; i++) {
        stats[i] = stats[i + 1];
    }
    stats_size--;
}

// Function to update a network statistic in the dynamic list
void update_network_statistic(int index, double throughput, double packet_loss_rate, double error_rate) {
    // Check if the index is valid
    if (index < 0 || index >= stats_size) {
        printf("Error: Invalid index for updating network statistic\n");
        exit(1);
    }

    // Update the statistic at the given index
    stats[index].throughput = throughput;
    stats[index].packet_loss_rate = packet_loss_rate;
    stats[index].error_rate = error_rate;
}

// Function to retrieve a network statistic from the dynamic list
NetworkStat get_network_statistic(int index) {
    // Check if the index is valid
    if (index < 0 || index >= stats_size) {
        printf("Error: Invalid index for retrieving network statistic\n");
        exit(1);
    }

    return stats[index];
}

// Function to retrieve all network statistics from the dynamic list
NetworkStat *get_all_network_statistics() {
    // Return a copy of the dynamic array
    NetworkStat *copy = (NetworkStat *)malloc(stats_size * sizeof(NetworkStat));
    if (!copy) {
        printf("Error: Failed to allocate memory for network statistics\n");
        exit(1);
    }
    memcpy(copy, stats, stats_size * sizeof(NetworkStat));
    return copy;
}
```
