    uint8_t pid;
    uint8_t mac_control_element[];
} MAC_PDU_T;

// Define a linked list node for the dynamic list of structures
typedef struct {
    MAC_PDU_T *data;
    struct node *next;
} LIST_NODE_T;

// Define a linked list for the dynamic list of structures
typedef struct {
    LIST_NODE_T *head;
    LIST_NODE_T *tail;
} LIST_T;

// Define a function to initialize a new structure with random values
void init_structure(MAC_PDU_T *structure) {
    // Generate a random logical channel ID and PID
    structure->logical_channel_id = rand() % 1024;
    structure->pid = rand() % 256;

    // Initialize the MAC control element with a randomly generated type and payload size
    uint8_t mac_control_element[rand() % 1024];
    memset(mac_control_element, 0, sizeof(mac_control_element));
    structure->mac_control_element = mac_control_element;
}

// Define a function to add a new structure to the list
void add_structure(LIST_T *list, MAC_PDU_T *structure) {
    // Allocate memory for the new node
    LIST_NODE_T *new_node = malloc(sizeof(LIST_NODE_T));
    if (new_node == NULL) {
        printf("Error: unable to allocate memory for new node\n");
        return;
    }

    // Initialize the new node with the given structure
    new_node->data = structure;

    // Add the new node to the end of the list
    if (list->tail == NULL) {
        list->head = new_node;
    } else {
        list->tail->next = new_node;
    }
    list->tail = new_node;
}

// Define a function to update an existing structure in the list
void update_structure(LIST_T *list, MAC_PDU_T *structure) {
    // Find the node containing the given structure
    LIST_NODE_T *node = list->head;
    while (node != NULL && node->data != structure) {
        node = node->next;
    }

    // If the node was found, update its data
    if (node != NULL) {
        node->data = structure;
    } else {
        printf("Error: unable to find structure in list\n");
    }
}

// Define a function to retrieve an existing structure from the list
MAC_PDU_T *get_structure(LIST_T *list, uint16_t logical_channel_id, uint8_t pid) {
    // Find the node containing the given structure
    LIST_NODE_T *node = list->head;
    while (node != NULL && node->data->logical_channel_id != logical_channel_id || node->data->pid != pid) {
        node = node->next;
    }

    // If the node was found, return its data
    if (node != NULL) {
        return node->data;
    } else {
        printf("Error: unable to find structure in list\n");
        return NULL;
    }
}

// Define a function to remove an existing structure from the list
void remove_structure(LIST_T *list, MAC_PDU_T *structure) {
    // Find the node containing the given structure
    LIST_NODE_T *node = list->head;
    while (node != NULL && node->data != structure) {
        node = node->next;
    }

    // If the node was found, remove it from the list
    if (node != NULL) {
        LIST_NODE_T *prev_node = node->prev;
        LIST_NODE_T *next_node = node->next;
        if (prev_node == NULL) {
            list->head = next_node;
        } else {
            prev_node->next = next_node;
        }
        if (next_node == NULL) {
            list->tail = prev_node;
        } else {
            next_node->prev = prev_node;
        }
        free(node);
    } else {
        printf("Error: unable to find structure in list\n");
    }
}

// Define a function to iterate over the structures in the list
void iterate_structures(LIST_T *list, void (*callback)(MAC_PDU_T *)) {
    // Iterate over the nodes in the list and call the callback function for each structure
    LIST_NODE_T *node = list->head;
    while (node != NULL) {
        callback(node->data);
        node = node->next;
    }
}
