// Define the maximum allowed memory usage percentage
#define MAX_MEMORY_USAGE_PERCENTAGE 90

// Define the function to dynamically allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu(size_t n) {
    // Check if the provided value of N exceeds the system's available memory
    if (n > SIZE_MAX / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        fprintf(stderr, "Error: Provided value of N exceeds the system's available memory\n");
        return NULL;
    }

    // Calculate the required memory size for the array
    size_t mem_size = n * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    // Check if the maximum allowed memory usage percentage is exceeded
    if (mem_size > MAX_MEMORY_USAGE_PERCENTAGE) {
        fprintf(stderr, "Error: Maximum allowed memory usage percentage is exceeded\n");
        return NULL;
    }

    // Dynamically allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(mem_size);

    // Check if memory allocation failed
    if (pdu == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return NULL;
    }

    // Initialize the array of NFAPI_CRC_INDICATION_PDU_T structures
    for (size_t i = 0; i < n; i++) {
        pdu[i].RX_UE_INFORMATION_TAG = 0;
        pdu[i].RNTI = 0;
        pdu[i].CRC_INDICATION_REL8_TAG = 0;
        pdu[i].CRCFLAG = false;
    }

    // Initialize the secondary array of previously used RNTI values
    size_t num_rnti = 0;
    uint32_t* rnti_array = malloc(n * sizeof(uint32_t));

    if (rnti_array == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free(pdu);
        return NULL;
    }

    // Generate random RNTI values for each structure in the array
    srand(time(NULL));
    for (size_t i = 0; i < n; i++) {
        uint32_t rnti = rand() % 1000000000 + 1;

        // Check if the RNTI value is already used in the array
        bool duplicate = false;
        for (size_t j = 0; j < num_rnti; j++) {
            if (rnti == rnti_array[j]) {
                duplicate = true;
                break;
            }
        }

        // If the RNTI value is a duplicate, generate a new one
        while (duplicate) {
            rnti = rand() % 1000000000 + 1;
            for (size_t j = 0; j < num_rnti; j++) {
                if (rnti == rnti_array[j]) {
                    duplicate = true;
                    break;
                } else {
                    duplicate = false;
                }
            }
        }

        // Add the RNTI value to the secondary array of previously used RNTI values
        rnti_array[num_rnti++] = rnti;

        // Set the RNTI value in the current structure
        pdu[i].RNTI = rnti;
    }

    // Free the secondary array of previously used RNTI values if it is no longer needed
    if (num_rnti < n) {
        free(rnti_array);
    }

    return pdu;
}

// Define the function to release memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
void deallocate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu, size_t n) {
    // Check if the provided pointer is NULL
    if (pdu == NULL) {
        fprintf(stderr, "Error: Provided pointer is NULL\n");
        return;
    }

    // Free the memory allocated for the array of NFAPI_CRC_INDICATION_PDU_T structures
    free(pdu);
}
