// Define the structure to store network interface status reports
typedef struct {
    char id[16]; // Unique identifier for each report
    int link_layer_stats; // Link layer statistics
    int packet_loss_events; // List of recent packet loss events
} Report;

// Define the structure to store the summary report
typedef struct {
    float average_packet_loss_percentage; // Average packet loss percentage
    long total_packet_count; // Total number of packets received
} SummaryReport;

// Define the function to initialize and manage the distributed network monitoring system
void init_network_monitoring_system() {
    // Initialize the report list and summary report
    Report *reports = malloc(sizeof(Report) * 10); // Initial capacity of 10 reports
    SummaryReport *summary_report = malloc(sizeof(SummaryReport));

    // Initialize the semaphore for synchronizing access to the report list
    sem_t *sem = sem_open("network_monitoring_sem", O_CREAT, 0644, 1);

    // Start the thread that handles incoming reports
    pthread_create(&report_handler_thread, NULL, handle_incoming_reports, (void *)&reports);

    // Start the thread that generates the summary report
    pthread_create(&summary_report_thread, NULL, generate_summary_report, (void *)&summary_report);
}

// Define the function to handle incoming reports
void *handle_incoming_reports(void *args) {
    Report **reports = args;

    // Loop indefinitely until a shutdown signal is received
    while (1) {
        // Acquire the semaphore to synchronize access to the report list
        sem_wait(sem);

        // Check if there are any incoming reports
        if (reports->size > 0) {
            // Update the report list with the new report
            Report *new_report = malloc(sizeof(Report));
            memcpy(new_report, &reports[0], sizeof(Report));
            reports = realloc(reports, (reports.size + 1) * sizeof(Report));
            reports[reports.size - 1] = new_report;
        }

        // Release the semaphore to allow other threads to access the report list
        sem_post(sem);
    }
}

// Define the function to generate the summary report
void *generate_summary_report(void *args) {
    SummaryReport **summary_report = args;

    // Loop indefinitely until a shutdown signal is received
    while (1) {
        // Acquire the semaphore to synchronize access to the report list
        sem_wait(sem);

        // Calculate the average packet loss percentage and total packet count
        float average_packet_loss_percentage = 0;
        long total_packet_count = 0;
        for (int i = 0; i < reports.size; i++) {
            average_packet_loss_percentage += reports[i].link_layer_stats * reports[i].packet_loss_events;
            total_packet_count += reports[i].packet_loss_events;
        }
        average_packet_loss_percentage /= total_packet_count;

        // Update the summary report with the new values
        SummaryReport *new_summary_report = malloc(sizeof(SummaryReport));
        memcpy(new_summary_report, &summary_report[0], sizeof(SummaryReport));
        summary_report = realloc(summary_report, (summary_report.size + 1) * sizeof(SummaryReport));
        summary_report[summary_report.size - 1] = new_summary_report;

        // Release the semaphore to allow other threads to access the report list
        sem_post(sem);
    }
}
```
