    // Initialize each structure in the array with random data
    srand(time(NULL));
    for (int i = 0; i < num_events; i++) {
        pdu_array[i].EventTag = rand() % 1000;
        pdu_array[i].SequenceNumber = rand() % 1000;
        memset(pdu_array[i].DataPayload, 'a', sizeof(pdu_array[i].DataPayload));
    }

    // Validate the integrity of the DataPayload before returning the array
    for (int i = 0; i < num_events; i++) {
        if (!validate_data_payload(&pdu_array[i])) {
            printf("Invalid data payload detected in PDU %d\n", i);
            free(pdu_array);
            return NULL;
        }
