#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>

// Define the structure for session information
struct Session {
    int id;
    int auth_level;
    time_t last_activity;
    char* history[10];
};

// Define the shared memory segment for storing sessions
static struct Session* sessions = NULL;

// Define the semaphore for protecting access to the shared memory segment
static sem_t* session_sem = NULL;

// Initialize the shared memory segment and semaphore
void init_sessions() {
    // Create a new shared memory segment
    int shmid = shmget(IPC_PRIVATE, sizeof(struct Session) * 100, IPC_CREAT | 0644);
    if (shmid < 0) {
        perror("Error creating shared memory segment");
        exit(1);
    }

    // Attach the shared memory segment to this process
    sessions = shmat(shmid, NULL, 0);
    if (sessions == (void*)-1) {
        perror("Error attaching shared memory segment");
        exit(1);
    }

    // Create a new semaphore for protecting access to the shared memory segment
    session_sem = sem_open("/session_sem", O_CREAT, 0644, 1);
    if (session_sem == SEM_FAILED) {
        perror("Error creating semaphore");
        exit(1);
    }
}

// Add a new session to the shared memory segment
void add_session(int id, int auth_level, time_t last_activity) {
    // Lock the semaphore to prevent concurrent access to the shared memory segment
    if (sem_wait(session_sem) == -1) {
        perror("Error waiting for semaphore");
        exit(1);
    }

    // Find an empty slot in the shared memory segment for the new session
    int i;
    for (i = 0; i < 100; i++) {
        if (sessions[i].id == 0) {
            break;
        }
    }

    // If no empty slot was found, return an error
    if (i == 100) {
        perror("Error adding session: shared memory segment is full");
        exit(1);
    }

    // Add the new session to the shared memory segment
    sessions[i].id = id;
    sessions[i].auth_level = auth_level;
    sessions[i].last_activity = last_activity;

    // Unlock the semaphore and return
    if (sem_post(session_sem) == -1) {
        perror("Error posting to semaphore");
        exit(1);
    }
}

// Update an existing session in the shared memory segment
void update_session(int id, int auth_level, time_t last_activity) {
    // Lock the semaphore to prevent concurrent access to the shared memory segment
    if (sem_wait(session_sem) == -1) {
        perror("Error waiting for semaphore");
        exit(1);
    }

    // Find the session in the shared memory segment and update it
    int i;
    for (i = 0; i < 100; i++) {
        if (sessions[i].id == id) {
            sessions[i].auth_level = auth_level;
            sessions[i].last_activity = last_activity;
            break;
        }
    }

    // If the session was not found, return an error
    if (i == 100) {
        perror("Error updating session: session not found");
        exit(1);
    }

    // Unlock the semaphore and return
    if (sem_post(session_sem) == -1) {
        perror("Error posting to semaphore");
        exit(1);
    }
}

// Query a session from the shared memory segment
struct Session* query_session(int id) {
    // Lock the semaphore to prevent concurrent access to the shared memory segment
    if (sem_wait(session_sem) == -1) {
        perror("Error waiting for semaphore");
        exit(1);
    }

    // Find the session in the shared memory segment and return it
    int i;
    for (i = 0; i < 100; i++) {
        if (sessions[i].id == id) {
            break;
        }
    }

    // If the session was not found, return NULL
    if (i == 100) {
        perror("Error querying session: session not found");
        exit(1);
    }

    // Unlock the semaphore and return the session
    if (sem_post(session_sem) == -1) {
        perror("Error posting to semaphore");
        exit(1);
    }

    return &sessions[i];
}

// Expire sessions that have been inactive for a specified period of time
void expire_sessions() {
    // Lock the semaphore to prevent concurrent access to the shared memory segment
