#include <stdbool.h>

// Define the structure for a TCP connection record
typedef struct {
    int id;
    char ip[INET_ADDRSTRLEN];
    uint16_t port;
} TCP_CONNECTION_RECORD;

// Define the array of TCP connection records
TCP_CONNECTION_RECORD *connections = NULL;
size_t connections_count = 0;
size_t connections_capacity = 0;

// Function to initialize and populate the array of TCP connection records with data from a network interface statistics dump
void init_connections(const char *interface) {
    // Get the IP address and port number of the interface
    struct ifreq ifr;
    strncpy(ifr.ifr_name, interface, IFNAMSIZ - 1);
    ioctl(sock, SIOCGIFADDR, &ifr);
    inet_ntop(AF_INET, &((struct sockaddr_in *)&ifr.ifr_addr)->sin_addr, ifr.ifr_name, IFNAMSIZ - 1);
    uint16_t port = ntohs(((struct sockaddr_in *)&ifr.ifr_addr)->sin_port);

    // Create a socket for the interface
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        exit(1);
    }

    // Set the socket options to receive broadcast messages
    int optval = 1;
    setsockopt(sock, SOL_SOCKET, SO_BROADCAST, &optval, sizeof(int));

    // Bind the socket to the interface and port number
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    inet_pton(AF_INET, ifr.ifr_name, &addr.sin_addr);
    if (bind(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        exit(1);
    }

    // Receive the network interface statistics dump and populate the array of TCP connection records
    char buffer[4096];
    while (true) {
        ssize_t len = recvfrom(sock, buffer, sizeof(buffer), 0, NULL, NULL);
        if (len < 0) {
            perror("recvfrom");
            exit(1);
        }
        struct ndmsg *ndm = (struct ndmsg *)buffer;
        if (ndm->ndm_family != AF_INET || ndm->ndm_state == NUD_REACHABLE) {
            continue;
        }
        struct rtattr *rta = (struct rtattr *)(ndm + 1);
        while (RTA_OK(rta, len)) {
            if (rta->rta_type == NDA_DST) {
                struct in_addr *dst = RTA_DATA(rta);
                char ip[INET_ADDRSTRLEN];
                inet_ntop(AF_INET, dst, ip, INET_ADDRSTRLEN);
                uint16_t port = ntohs(((struct sockaddr_in *)&rta->rta_data)->sin_port);
                // Check if the connection is already in the array of TCP connection records
                bool found = false;
                for (size_t i = 0; i < connections_count; i++) {
                    if (strcmp(ip, connections[i].ip) == 0 && port == connections[i].port) {
                        found = true;
                        break;
                    }
                }
                // Add the connection to the array of TCP connection records if it is not already in it
                if (!found) {
                    if (connections_count >= connections_capacity) {
                        connections_capacity *= 2;
                        connections = realloc(connections, connections_capacity * sizeof(TCP_CONNECTION_RECORD));
                    }
                    connections[connections_count].id = connections_count + 1;
                    strcpy(connections[connections_count].ip, ip);
                    connections[connections_count].port = port;
                    connections_count++;
                }
            }
            rta = RTA_NEXT(rta, len);
        }
    }
}

// Function to remove a connection from the array of TCP connection records by its ID
void remove_connection(int id) {
    // Find the index of the connection in the array of TCP connection records
    size_t i = 0;
    for (; i < connections_count; i++) {
        if (connections[i].id == id) {
            break;
        }
    }
    // Remove the connection from the array of TCP connection records
    if (i < connections_count) {
        memmove(&connections[i], &connections[i + 1], (connections_count - i - 1) * sizeof(TCP_CONNECTION_RECORD));
        connections_count--;
    }
}

// Function to update the connection status based on received heartbeat signals
void update_connection_status() {
    // Iterate over the array of TCP connection records and check if any connections have been lost or gained
    for (size_t i = 0; i < connections_count; i++) {
        struct sockaddr_in addr;
        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        inet_pton(AF_INET, connections[i].ip, &addr.sin_addr);
        addr.sin_port = htons(connections[i].port);
        int sock = socket(AF_INET, SOCK_DGRAM, 0);
        if (sock < 0) {
            perror("socket");
            exit(1);
        }
        // Send a heartbeat signal to the connection and check if it is still alive
        char buffer[4096];
        ssize_t len = sendto(sock, buffer, sizeof(buffer), 0, (struct sockaddr *)&addr, sizeof(addr));
        if (len < 0) {
            perror("sendto");
            exit(1);
        }
        // If the connection is no longer alive, remove it from the array of TCP connection records
        if (len == 0) {
            remove_connection(connections[i].id);
        }
    }
}
