#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// Custom hash table implementation for quick lookups during connection management
struct HashTable {
    int size;
    struct ConnectionRecord **buckets;
};

struct ConnectionRecord {
    uint32_t id;
    char ip[16];
    uint16_t port;
    bool active;
};

// Initialize and populate the dynamic array of TCP connection records
void initializeConnections(struct HashTable *ht) {
    // Load network interface statistics dump from external data source
    FILE *fp = fopen("network_stats.txt", "r");
    if (fp == NULL) {
        perror("fopen");
        exit(1);
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Parse connection ID, IP address, and port number from each line
        uint32_t id;
        char ip[16];
        uint16_t port;
        sscanf(line, "%d %s %hu", &id, ip, &port);

        // Add connection to the hash table if it doesn't already exist
        struct ConnectionRecord *rec = (struct ConnectionRecord *)malloc(sizeof(struct ConnectionRecord));
        rec->id = id;
        strcpy(rec->ip, ip);
        rec->port = port;
        rec->active = true;
        ht_add(ht, rec);
    }

    fclose(fp);
}

// Add a new connection to the hash table if it doesn't already exist
void ht_add(struct HashTable *ht, struct ConnectionRecord *rec) {
    // Calculate the hash value for the connection ID
    uint32_t hash = rec->id % ht->size;

    // Check if the connection already exists in the hash table
    struct ConnectionRecord *existing = ht->buckets[hash];
    while (existing != NULL) {
        if (existing->id == rec->id) {
            return;
        }
        existing = existing->next;
    }

    // Add the new connection to the hash table
    rec->next = ht->buckets[hash];
    ht->buckets[hash] = rec;
}

// Remove a connection from the hash table by its ID
void ht_remove(struct HashTable *ht, uint32_t id) {
    // Calculate the hash value for the connection ID
    uint32_t hash = id % ht->size;

    // Check if the connection exists in the hash table
    struct ConnectionRecord *existing = ht->buckets[hash];
    while (existing != NULL) {
        if (existing->id == id) {
            break;
        }
        existing = existing->next;
    }

    // Remove the connection from the hash table
    if (existing != NULL) {
        struct ConnectionRecord *prev = ht->buckets[hash];
        while (prev->next != existing) {
            prev = prev->next;
        }
        prev->next = existing->next;
        free(existing);
    }
}

// Update the connection status based on received heartbeat signals
void updateConnections(struct HashTable *ht, uint32_t id) {
    // Calculate the hash value for the connection ID
    uint32_t hash = id % ht->size;

    // Check if the connection exists in the hash table
    struct ConnectionRecord *existing = ht->buckets[hash];
    while (existing != NULL) {
        if (existing->id == id) {
            break;
        }
        existing = existing->next;
    }

    // Update the connection status based on received heartbeat signals
    if (existing != NULL) {
        existing->active = true;
    }
}

// Handle concurrent access from multiple threads without causing data races or inconsistent states
void *connectionManager(void *arg) {
    struct HashTable *ht = (struct HashTable *)arg;

    while (1) {
        // Load network interface statistics dump from external data source
        FILE *fp = fopen("network_stats.txt", "r");
        if (fp == NULL) {
            perror("fopen");
            exit(1);
        }

        char line[256];
        while (fgets(line, sizeof(line), fp)) {
            // Parse connection ID, IP address, and port number from each line
            uint32_t id;
            char ip[16];
            uint16_t port;
            sscanf(line, "%d %s %hu", &id, ip, &port);

            // Add connection to the hash table if it doesn't already exist
            struct ConnectionRecord *rec = (struct ConnectionRecord *)malloc(sizeof(struct ConnectionRecord));
            rec->id = id;
            strcpy(rec->ip, ip);
            rec->port = port;
            rec->active = true;
            ht_add(ht, rec);
        }

        fclose(fp);
    }
}

// Handle periodic batch processing of updates
void *batchProcessor(void *arg) {
    struct HashTable *ht = (struct HashTable *)arg;

    while (1) {
        // Load network interface statistics dump from external data source
        FILE *fp = fopen("network_stats.txt", "r");
        if (fp == NULL) {
            perror("fopen");
            exit(1);
        }

        char line[256];
        while (fgets(line, sizeof(line), fp)) {
            // Parse connection ID, IP address, and port number from each line
            uint32_t id;
            char ip[16];
            uint16_t port;
            sscanf(line, "%d %s %hu", &id, ip, &port);

            // Update the connection status based on received heartbeat signals
            updateConnections(ht, id);
        }

        fclose(fp);
    }
}

int main() {
    struct HashTable *ht = (struct HashTable *)malloc(sizeof(struct HashTable));
    ht->size = 1024;
    ht->buckets = (struct ConnectionRecord **)malloc(sizeof(struct ConnectionRecord *) * ht->size);
    memset(ht->buckets, 0, sizeof(struct ConnectionRecord *) * ht->size);

    // Initialize and populate the dynamic array of TCP connection records
    initializeConnections(ht);

    // Handle concurrent access from multiple threads without causing data races or inconsistent states
    pthread_t thread1;
    pthread_create(&thread1, NULL, connectionManager, ht);

