NFAPI_CRC_INDICATION_PDU_T* allocateCrcIndicationPduArray(int n) {
    // Check if the input is valid
    if (n <= 0 || n > 10000) {
        printf("Invalid input: %d\n", n);
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* pduArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (!pduArray) {
        printf("Failed to allocate memory for the array of structures\n");
        return NULL;
    }

    // Initialize each structure in the array with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < n; i++) {
        pduArray[i].rxUeInformationTag = RX_UE_INFORMATION_TAG_INIT;
        pduArray[i].rnti = RNTI_INIT;
        pduArray[i].crcIndicationRel8Tag = CRC_INDICATION_REL8_TAG_INIT;
    }

    // Set a random value for the CRCFLAG in each structure
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
