public class NFapiCRCGenerator {
    private static final int DEFAULT_RANDOM_SEED = 42; // default random seed for reproducibility
    private static final int DEFAULT_N = 10; // default number of UE entries to generate
    private static final int DEFAULT_RX_UE_INFORMATION_TAG = 1; // default RX_UE_INFORMATION_TAG value
    private static final int DEFAULT_RNTI = 1234567890; // default RNTI value
    private static final int DEFAULT_CRC_INDICATION_REL8_TAG = 1; // default CRC_INDICATION_REL8_TAG value

    public List<NFAPI_CRC_INDICATION_PDU_T> generateUEList(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Invalid number of UE entries: " + n);
        }

        Random random = new Random(DEFAULT_RANDOM_SEED); // create a new random instance with the default seed
        List<NFAPI_CRC_INDICATION_PDU_T> ueList = new ArrayList<>(); // create an empty list to store the UE entries

        for (int i = 0; i < n; i++) {
            NFAPI_CRC_INDICATION_PDU_T ueEntry = new NFAPI_CRC_INDICATION_PDU_T(); // create a new UE entry structure
            ueEntry.RX_UE_INFORMATION_TAG = random.nextInt(10); // set the RX_UE_INFORMATION_TAG value randomly
