#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>
#include <pthread.h>

// Custom data structure for linked list nodes
typedef struct CustomDataStructure {
    long timestamp;
    char* string;
    int* integers;
} CustomDataStructure;

// Linked list node
struct Node {
    CustomDataStructure data;
    struct Node* next;
};

// Linked list head
struct Node* head = NULL;

// Memory pool for dynamic allocation of linked list nodes
struct Node** memory_pool = NULL;

// Number of available slots in the memory pool
int num_available_slots = 0;

// Maximum number of nodes that can be allocated
#define MAX_NODES 10000

// Current number of nodes allocated
int current_num_nodes = 0;

// Lock for synchronizing access to the linked list and memory pool
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically manage memory allocation and initialization for a linked list of custom data structures
void createCustomDataStructureList(int num_nodes, int batch_size) {
    // Validate input parameters
    if (num_nodes <= 0 || batch_size <= 0) {
        printf("Invalid input parameters\n");
        return;
    }

    // Ensure that the number of nodes does not exceed the maximum limit
    if (num_nodes > MAX_NODES) {
        printf("Number of nodes exceeds maximum limit\n");
        return;
    }

    // Acquire lock for synchronizing access to the linked list and memory pool
    pthread_mutex_lock(&lock);

    // Allocate memory for the linked list nodes
    struct Node** new_memory_pool = (struct Node**)malloc(sizeof(struct Node*) * num_nodes);
    if (!new_memory_pool) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    // Initialize the linked list head
    struct Node* new_head = NULL;

    // Iterate over the batches of nodes to be allocated
    for (int i = 0; i < num_nodes; i += batch_size) {
        int current_batch_size = min(batch_size, num_nodes - i);

        // Allocate memory for the current batch of nodes
        struct Node* new_node = (struct Node*)malloc(sizeof(struct Node) * current_batch_size);
        if (!new_node) {
            printf("Memory allocation failed\n");
            pthread_mutex_unlock(&lock);
            return;
        }

        // Initialize the linked list nodes
        for (int j = 0; j < current_batch_size; j++) {
            new_node[j].data.timestamp = i + j;
            new_node[j].data.string = malloc(sizeof(char) * 10);
            sprintf(new_node[j].data.string, "String %d", i + j);
            new_node[j].data.integers = (int*)malloc(sizeof(int) * 5);
            for (int k = 0; k < 5; k++) {
                new_node[j].data.integers[k] = i + j + k;
            }
            new_node[j].next = NULL;
        }

        // Add the current batch of nodes to the linked list
        if (new_head == NULL) {
            new_head = new_node;
        } else {
            struct Node* temp = new_head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = new_node;
        }
    }

    // Update the memory pool and linked list head
    if (memory_pool == NULL) {
        memory_pool = new_memory_pool;
        head = new_head;
    } else {
        struct Node** temp = memory_pool;
        while (*temp != NULL) {
            temp++;
        }
        *temp = new_memory_pool;
        head = new_head;
    }

    // Release lock for synchronizing access to the linked list and memory pool
    pthread_mutex_unlock(&lock);
}

