// Function to recalculate the CRC flag based on a parity check of the combined bits of the UE information tag and RNTI
void update_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Calculate the parity check of the combined bits of the UE information tag and RNTI
    uint16_t parity = 0;
    for (int i = 0; i < 16; i++) {
        parity ^= ((pdu->rx_ue_information_tag >> i) & 1) + ((pdu->rnti >> i) & 1);
    }

    // Set the CRC flag based on the result of the parity check
    pdu->crcflag = (parity % 2 == 0);
}

