typedef struct {
    NFAPI_MESSAGE_T *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} CACHE_T;

// Function to add a new entry to the cache
void add_entry(CACHE_T *cache, NFAPI_MESSAGE_T *entry) {
    // Acquire the lock on the cache
    pthread_mutex_lock(&cache->mutex);

    // Check if the cache is full
    if (cache->count == cache->capacity) {
        // If the cache is full, remove the oldest entry
        NFAPI_MESSAGE_T *oldest = cache->data + 0;
        for (size_t i = 1; i < cache->count; i++) {
            if (cache->data[i].rnti < oldest->rnti) {
                oldest = cache->data + i;
            }
        }
        // Remove the oldest entry from the cache
        free(oldest);
        cache->count--;
    }

    // Add the new entry to the cache
    cache->data[cache->count++] = *entry;

    // Release the lock on the cache
    pthread_mutex_unlock(&cache->mutex);
}

// Function to remove an existing entry from the cache by RNTI
void remove_entry(CACHE_T *cache, RNTI rnti) {
    // Acquire the lock on the cache
    pthread_mutex_lock(&cache->mutex);

    // Find the index of the entry to be removed
    size_t i = 0;
    while (i < cache->count && cache->data[i].rnti != rnti) {
        i++;
    }

    // If the entry was found, remove it from the cache
    if (i < cache->count) {
        NFAPI_MESSAGE_T *entry = cache->data + i;
        free(entry);
        cache->count--;
    }

    // Release the lock on the cache
    pthread_mutex_unlock(&cache->mutex);
}

// Function to retrieve all entries that match a specific RNTI from the cache
NFAPI_MESSAGE_T *get_entries(CACHE_T *cache, RNTI rnti) {
    // Acquire the lock on the cache
    pthread_mutex_lock(&cache->mutex);

    // Find all entries that match the specified RNTI
    size_t count = 0;
    for (size_t i = 0; i < cache->count; i++) {
        if (cache->data[i].rnti == rnti) {
            count++;
        }
    }

    // If no entries were found, return NULL
    if (count == 0) {
        pthread_mutex_unlock(&cache->mutex);
        return NULL;
    }

    // Allocate memory for the retrieved entries
    NFAPI_MESSAGE_T *entries = malloc(sizeof(NFAPI_MESSAGE_T) * count);

    // Copy the retrieved entries to the allocated memory
    size_t j = 0;
    for (size_t i = 0; i < cache->count; i++) {
        if (cache->data[i].rnti == rnti) {
            entries[j++] = cache->data[i];
        }
    }

    // Release the lock on the cache
    pthread_mutex_unlock(&cache->mutex);

    return entries;
}

// Function to periodically clean up inactive entries from the cache
void cleanup(CACHE_T *cache) {
    // Acquire the lock on the cache
    pthread_mutex_lock(&cache->mutex);

    // Find the oldest entry in the cache
    NFAPI_MESSAGE_T *oldest = cache->data + 0;
    for (size_t i = 1; i < cache->count; i++) {
        if (cache->data[i].rnti < oldest->rnti) {
            oldest = cache->data + i;
        }
    }

    // If the oldest entry is inactive, remove it from the cache
    time_t current_time = time(NULL);
    if (current_time - oldest->rx_ue_information.timestamp > INACTIVE_DURATION) {
        free(oldest);
        cache->count--;
    }

    // Release the lock on the cache
    pthread_mutex_unlock(&cache->mutex);
}

// Function to serialize and deserialize the entire data structure to disk
void serialize(CACHE_T *cache, FILE *file) {
    // Acquire the lock on the cache
    pthread_mutex_lock(&cache->mutex);

    // Write the number of entries in the cache to the file
    fwrite(&cache->count, sizeof(size_t), 1, file);

    // Write each entry in the cache to the file
    for (size_t i = 0; i < cache->count; i++) {
        NFAPI_MESSAGE_T *entry = cache->data + i;
        fwrite(entry, sizeof(NFAPI_MESSAGE_T), 1, file);
    }

    // Release the lock on the cache
    pthread_mutex_unlock(&cache->mutex);
}

void deserialize(CACHE_T *cache, FILE *file) {
    // Acquire the lock on the cache
    pthread_mutex_lock(&cache->mutex);

    // Read the number of entries in the cache from the file
    fread(&cache->count, sizeof(size_t), 1, file);

    // Allocate memory for the deserialized entries
    cache->data = malloc(sizeof(NFAPI_MESSAGE_T) * cache->count);

    // Read each entry in the cache from the file
    for (size_t i = 0; i < cache->count; i++) {
        NFAPI_MESSAGE_T *entry = cache->data + i;
        fread(entry, sizeof(NFAPI_MESSAGE_T), 1, file);
    }

    // Release the lock on the cache
    pthread_mutex_unlock(&cache->mutex);
}
