    // Allocate memory for the linked list and two-dimensional array
    linked_list = (struct node*)malloc(sizeof(struct node) * n);
    two_dimensional_array = (struct record**)malloc(sizeof(struct record*) * n);

    // Initialize the linked list and two-dimensional array
    for (int i = 0; i < n; i++) {
        linked_list[i].value = i + 1;
        linked_list[i].next = &linked_list[i + 1];
        two_dimensional_array[i] = (struct record*)malloc(sizeof(struct record));
        two_dimensional_array[i]->id = i + 1;
        two_dimensional_array[i]->value = (double)i / 2.0;
