// Define a global variable to store the head of the linked list
LIST_NODE_T *head = NULL;

// Define a function to add a new node to the linked list
void add_node(PHY_STATISTICS_T *data) {
    // Create a new node and allocate memory for it
    LIST_NODE_T *new_node = (LIST_NODE_T *)malloc(sizeof(LIST_NODE_T));
    if (!new_node) {
        printf("Error: Failed to allocate memory for new node\n");
        return;
    }

    // Set the data field of the new node to the given data
    new_node->data = data;

    // If the head is NULL, set the head to the new node and return
    if (!head) {
        head = new_node;
        return;
    }

    // Otherwise, add the new node to the end of the linked list
    LIST_NODE_T *current = head;
    while (current->next) {
        current = current->next;
    }
    current->next = new_node;
}

// Define a function to remove a node from the linked list
void remove_node(PHY_STATISTICS_T *data) {
    // If the head is NULL, return
    if (!head) {
        return;
    }

    // Otherwise, search for the node with the given data and remove it
    LIST_NODE_T *current = head;
    while (current->next) {
        if (current->data == data) {
            LIST_NODE_T *previous = current;
            current = current->next;
            previous->next = current->next;
            free(current);
            return;
        }
        current = current->next;
    }
}

