    // Iterate through the linked list and write each node's data to the CSV file
    LIST_NODE_T *current = head;
    while (current) {
        fprintf(output, "%ld,%d,%d,%d\n", current->data->timestamp, current->data->cell_id, current->data->rssi, current->data->snr);
        current = current->next;
    }

    // Close the output file
    fclose(output);
}

