} NFAPI_CRC_INDICATION_PDU_T;

void manage_nfapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Generate MD5 hash of RX_UE_INFORMATION_TAG and RNTI
    char md5_hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char *)&pdu->rx_ue_information_tag, sizeof(uint16_t), (unsigned char *)md5_hash);
    memcpy(&md5_hash[MD5_DIGEST_LENGTH], &pdu->rnti, sizeof(uint32_t));
    MD5((unsigned char *)&md5_hash, MD5_DIGEST_LENGTH + sizeof(uint32_t), (unsigned char *)md5_hash);

    // Set CRCFLAG to a randomly set value
    pdu->crc_indication_rel8_tag = rand() % 256;

    // Ensure uniqueness of MD5 hash
    for (int i = 0; i < 10; i++) {
        if (memcmp(md5_hash, &pdu->crc_indication_rel8_tag, sizeof(uint8_t)) != 0) {
            break;
        } else {
            pdu->crc_indication_rel8_tag = rand() % 256;
        }
    }
}
