    uint8_t CRC_INDICATION_REL8_TAG;
}

void initializeAndPopulateNfadlIndications(int numStructures, FILE *logFile) {
    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T *indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        fprintf(logFile, "Error: Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T structures\n");
        return;
    }

    // Initialize the RX_UE_INFORMATION_TAG field of each structure
    for (int i = 0; i < numStructures; i++) {
        indications[i].RX_UE_INFORMATION_TAG = i + 1;
    }

    // Generate a random CRC flag for each structure
    srand(time(NULL));
    for (int i = 0; i < numStructures; i++) {
        indications[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    // Populate the RNTI field of each structure with a random value
    for (int i = 0; i < numStructures; i++) {
        indications[i].RNTI = rand() % 1000000000 + 1;
    }

    // Free the memory allocated for the array of structures
    free(indications);
}
