// Function to initialize a dynamic array of TCP segments
void init_segments(size_t count) {
    // Allocate memory for the dynamic array
    segments = malloc(sizeof(tcp_segment_t) * count);
    if (!segments) {
        fprintf(stderr, "Failed to allocate memory for TCP segments\n");
        return;
    }

    // Initialize each segment with a valid TCP header and payload
    for (size_t i = 0; i < count; i++) {
        tcp_segment_t *seg = &segments[i];
        seg->seq_number = i + 1;
        seg->ack_number = 0;
        seg->flags = false;
        memset(seg->payload, 0, MAX_PAYLOAD_SIZE);
    }
}

