// Define the structure for a UE measurement record
typedef struct {
    int ue_id;
    long timestamp;
    float signal_strength;
    char* frequency_bands[10]; // Maximum of 10 frequency bands supported
} UeMeasurementRecord;

// Define the dynamic array for storing UE measurement records
typedef struct {
    int size;
    int capacity;
    UeMeasurementRecord** records;
} UeMeasurementArray;

// Initialize a new empty dynamic array
UeMeasurementArray* ue_measurement_array_init() {
    UeMeasurementArray* arr = malloc(sizeof(UeMeasurementArray));
    arr->size = 0;
    arr->capacity = 10; // Initial capacity of 10 records
    arr->records = malloc(arr->capacity * sizeof(UeMeasurementRecord*));
    return arr;
}

// Add a new UE measurement record to the dynamic array
void ue_measurement_array_add(UeMeasurementArray* arr, UeMeasurementRecord* record) {
    if (arr->size == arr->capacity) { // If capacity is reached, double it
        arr->capacity *= 2;
        arr->records = realloc(arr->records, arr->capacity * sizeof(UeMeasurementRecord*));
    }
    arr->records[arr->size++] = record;
}

// Retrieve a UE measurement record from the dynamic array based on its UE identifier
UeMeasurementRecord* ue_measurement_array_get(UeMeasurementArray* arr, int ue_id) {
    for (int i = 0; i < arr->size; i++) {
        if (arr->records[i]->ue_id == ue_id) {
            return arr->records[i];
        }
    }
    return NULL; // Return NULL if UE identifier is not found
}

// Free the memory allocated for the dynamic array and its records
void ue_measurement_array_free(UeMeasurementArray* arr) {
    free(arr->records);
    free(arr);
}
