    size_t count;
    NFAPI_CRC_INDICATION_PDU_T *data;
} NFAPI_CRC_INDICATION_LIST_T;

// Define a function to dynamically populate the list of CRC indication data structures
void populate_crc_indication_list(NFAPI_UE_INFORMATION_TAG *ue_info, size_t num_ues) {
    // Create a new list with the required capacity
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    list->capacity = num_ues;
    list->count = 0;
    list->data = malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Iterate over the UE information and populate the list with CRC indication data structures
    for (size_t i = 0; i < num_ues; i++) {
        NFAPI_UE_INFORMATION_TAG *ue = &ue_info[i];
        NFAPI_CRC_INDICATION_PDU_T *crc_indication = &list->data[i];

        // Set the RX UE information tag and RNTI
        crc_indication->rx_ue_info.rnti = ue->rnti;
        crc_indication->rx_ue_info.tag = ue->tag;

        // Set the CRC indication REL8 tag and randomly set the CRCFLAG
        crc_indication->crc_indication.tag = ue->crc_indication.tag;
        crc_indication->crcflag = rand() % 2;
    }

    // Validate the populated list to ensure integrity of the structures
    validate_crc_indication_list(list);

    return list;
}

// Define a function to validate the integrity of the CRC indication data structures in the list
void validate_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Iterate over the list and validate each structure
    for (size_t i = 0; i < list->count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *crc_indication = &list->data[i];

        // Validate the RX UE information tag and RNTI
        if (crc_indication->rx_ue_info.tag != RX_UE_INFORMATION_TAG) {
            printf("Invalid RX UE information tag in CRC indication structure\n");
            return;
        }
        if (crc_indication->rx_ue_info.rnti == 0) {
            printf("Invalid RNTI in CRC indication structure\n");
            return;
        }

        // Validate the CRC indication REL8 tag and CRCFLAG
        if (crc_indication->crc_indication.tag != CRC_INDICATION_REL8_TAG) {
            printf("Invalid CRC indication REL8 tag in CRC indication structure\n");
            return;
        }
