#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <dirent.h>
#include <jpeglib.h>
#include <pdflib.h>

// Define constants for the output directory and compression level
#define OUTPUT_DIR "output"
#define COMPRESSION_LEVEL 90

// Define a structure to hold information about each task
typedef struct {
    char *input_file;
    char *output_file;
    int status;
} task_t;

// Define a queue data structure for holding tasks
typedef struct {
    task_t *tasks;
    size_t capacity;
    size_t size;
} queue_t;

// Define a function to initialize the queue
void init_queue(queue_t *q) {
    q->tasks = malloc(sizeof(task_t) * 10);
    q->capacity = 10;
    q->size = 0;
}

// Define a function to add a task to the queue
void enqueue(queue_t *q, char *input_file, char *output_file) {
    if (q->size == q->capacity) {
        // Reallocate memory for the tasks array if necessary
        q->tasks = realloc(q->tasks, sizeof(task_t) * (q->capacity + 10));
        q->capacity += 10;
    }
    task_t *task = &q->tasks[q->size++];
    task->input_file = input_file;
    task->output_file = output_file;
}

// Define a function to remove a task from the queue
void dequeue(queue_t *q) {
    if (q->size == 0) return;
    q->tasks[--q->size] = NULL;
}

// Define a function to process a directory of JPEG images
int process_directory(char *input_dir, char *output_dir, int compression_level, int metadata_inclusion) {
    // Initialize the queue for holding tasks
    queue_t q;
    init_queue(&q);

    // Iterate over the files in the input directory
    DIR *dir = opendir(input_dir);
    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char *file_name = entry->d_name;
        if (strcmp(file_name, ".") == 0 || strcmp(file_name, "..") == 0) continue;

        // Create a task for each JPEG file and add it to the queue
        char *input_file = malloc(strlen(input_dir) + strlen(file_name) + 2);
        sprintf(input_file, "%s/%s", input_dir, file_name);
        char *output_file = malloc(strlen(output_dir) + strlen(file_name) + 4);
        sprintf(output_file, "%s/%s.pdf", output_dir, file_name);
        enqueue(&q, input_file, output_file);
    }
    closedir(dir);

    // Initialize the number of threads to use for processing tasks
    int num_threads = 4;

    // Create a thread pool for concurrently processing tasks
    pthread_t *threads = malloc(sizeof(pthread_t) * num_threads);
    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, process_task, &q);
    }

    // Wait for all threads to complete and check for any errors
    for (int i = 0; i < num_threads; ++i) {
        void *status;
        pthread_join(threads[i], &status);
        if (status != NULL) {
            printf("Error: %s\n", (char *)status);
            return 1;
        }
    }

    // Clean up the queue and thread pool
    free(q.tasks);
    free(threads);

    return 0;
}

// Define a function to process a task in a separate thread
void *process_task(void *arg) {
    queue_t *q = (queue_t *)arg;
    while (q->size > 0) {
        // Dequeue the next task and process it
        task_t *task = &q->tasks[--q->size];
        char *input_file = task->input_file;
        char *output_file = task->output_file;
        int status = 0;

        // Open the input file and create a JPEG decompressor object
        FILE *in = fopen(input_file, "rb");
        if (in == NULL) {
            printf("Error: failed to open input file %s\n", input_file);
            status = 1;
            goto cleanup;
        }
        jpeg_decompress_struct cinfo;
        jpeg_error_mgr jerr;
        cinfo.err = jpeg_std_error(&jerr);
        if (jpeg_create_decompress(&cinfo, in) != JPEG_OK) {
            printf("Error: failed to create decompressor for %s\n", input_file);
            status = 1;
            goto cleanup;
        }

        // Open the output file and create a PDF writer object
        FILE *out = fopen(output_file, "wb");
        if (out == NULL) {
            printf("Error: failed to open output file %s\n", output_file);
            status = 1;
            goto cleanup;
        }
        pdf_writer writer;
        if (pdf_create_writer(&writer, out) != PDF_OK) {
            printf("Error: failed to create PDF writer for %s\n", output_file);
            status = 1;
            goto cleanup;
        }

        // Set the compression level and metadata inclusion options
        pdf_set_compression_level(&writer, compression_level);
        pdf_set_metadata_inclusion(&writer, metadata_inclusion);

        // Decode the JPEG image and write it to the PDF file
        jpeg_start_decompress(&cinfo);
        while (cinfo.output_scanline < cinfo.output_height) {
            JSAMPROW row = (JSAMPROW)malloc(sizeof(JSAMPLE) * cinfo.output_width * 3);
            jpeg_read_scanlines(&cinfo, &row, 1);
            pdf_write_image(&writer, row, cinfo.output_width, cinfo.output_height);
            free(row);
        }
        jpeg_finish_decompress(&cinfo);

    cleanup:
        // Clean up the decompressor and writer objects
        if (in != NULL) fclose(in);
        if (out != NULL) fclose(out);
        if (cinfo.src != NULL) jpeg_destroy_decompress(&cinfo);
        if (writer.pdf != NULL) pdf_destroy_writer(&writer);

        // Update the task status and log a detailed message
        task->status = status;
        printf("Task %s: %s\n", input_file, status == 0 ? "success" : "failure");
    }
    return NULL;
}
```
This code defines a function `process_directory` that takes an input directory of JPEG images and an output directory as parameters. It initializes a queue for holding tasks and iterates over the files in the input directory, creating a task for each JPEG file and adding it to the queue. The function then creates a thread pool for concurrently processing tasks using the `pthread` library. Each task is processed by the `process_task` function, which opens the input file, creates a JPEG decompressor object, and writes the decoded image to a PDF file using the `pdflib` library. The function updates the task status and logs a detailed message for each operation. If any error occurs during processing, the function returns 1 and prints an error message. Otherwise, it returns 0.']

