// Define the structure for a MAC PDU
typedef struct mac_pdu {
    unsigned char header[14]; // MAC header (14 bytes)
    unsigned char payload[1024]; // MAC payload (up to 1024 bytes)
    int sequence_number; // Sequence number for the packet
} mac_pdu_t;

// Define the linked list structure
typedef struct mac_list {
    mac_pdu_t *head; // Pointer to the head of the list
    mac_pdu_t *tail; // Pointer to the tail of the list
    int size; // Size of the list (number of elements)
} mac_list_t;

// Define the function to add a new element to the linked list
void add_element(mac_list_t *list, mac_pdu_t *new_element) {
    pthread_mutex_lock(&list->mutex); // Lock the list for writing
    if (list->size == 10000) { // Check if the list is full
        printf("List is full\n");
        pthread_mutex_unlock(&list->mutex); // Unlock the list
        return;
    }
    new_element->next = NULL; // Set the next pointer to NULL
    if (list->tail == NULL) { // Check if the tail is NULL
        list->head = new_element; // Set the head to the new element
    } else {
        list->tail->next = new_element; // Set the next pointer of the tail to the new element
    }
    list->tail = new_element; // Update the tail to the new element
    list->size++; // Increment the size of the list
    pthread_mutex_unlock(&list->mutex); // Unlock the list
}

// Define the function to retrieve the total number of elements in the linked list
int get_element_count(mac_list_t *list) {
    return list->size;
}

// Define the function to serialize the linked list to a binary file
void serialize_list(mac_list_t *list, char *filename) {
    FILE *file = fopen(filename, "wb"); // Open the file in write mode
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }
    mac_pdu_t *current = list->head; // Set the current element to the head of the list
    while (current != NULL) {
        fwrite(current, sizeof(mac_pdu_t), 1, file); // Write the current element to the file
        current = current->next; // Move to the next element in the list
    }
    fclose(file); // Close the file
}

// Define the function to deserialize the linked list from a binary file
void deserialize_list(mac_list_t *list, char *filename) {
    FILE *file = fopen(filename, "rb"); // Open the file in read mode
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }
    mac_pdu_t *current = list->head; // Set the current element to the head of the list
    while (!feof(file)) {
        fread(current, sizeof(mac_pdu_t), 1, file); // Read the next element from the file
        current = current->next; // Move to the next element in the list
    }
    fclose(file); // Close the file
}
```
