    Record *new_record = alloc_record(key, value);
    if (new_record == NULL) {
        // Handle memory allocation failure
        return;
    }
    if (list->head == NULL) {
        list->head = new_record;
        list->tail = new_record;
    } else {
        list->tail->next = new_record;
        list->tail = new_record;
    }
}

