void populateList(NFAPI_CRC_INDICATION_PDU_T *list, int numEntries) {
    // Lock the mutex to ensure thread-safe access to shared resources
    pthread_mutex_lock(&mutex);

    // Check if the maximum number of entries has been reached
    if (entryCount >= MAX_ENTRIES) {
        // Signal the condition variable to wait for the maximum number of entries to be released
        pthread_cond_wait(&cond, &mutex);
