        // Set the timestamp to the current time
        data->timestamp = time(NULL);

        // Create a new node and link it to the head node
        Node *new_node = malloc(sizeof(Node));
        new_node->data = data;
        new_node->next = head;
        head = new_node;
    }
}

// Define a function to iterate over the linked list and print each node's details
