        printf("CRC_INDICATION_REL8_TAG: %d\n", current->data->crc_indication_rel8.crflag);
        printf("Timestamp: %ld\n", current->data->timestamp);
    }
}

// Define a function to clear the linked list and free all allocated memory
void clear_linked_list() {
    // Iterate over the nodes in the linked list and free each node's data
    for (Node *current = head; current != NULL;) {
        Node *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
}
