    while (current != NULL) {
        printf("Node ID: %d\n", current->unique_id);
        printf("Timestamp: %s\n", ctime(&(current->timestamp)));
        printf("PHY Context: %p\n", current->phy_context);
        printf("RX PDU Type: %d\n", current->rx_pdu.type);
        printf("Status Flag: %d\n", current->status.flag);
        current = current->next;
    }
}

// Define the function to retrieve a node from the linked list by its unique identifier
NFAPI_RX_MESSAGE_T* nfapi_rx_message_list_get(NFAPI_RX_MESSAGE_LIST_T* list, int unique_id) {
    NFAPI_RX_MESSAGE_T* current = list->head;
    while (current != NULL) {
        if (current->unique_id == unique_id) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Define the function to clear the linked list and free all allocated memory
void nfapi_rx_message_list_clear(NFAPI_RX_MESSAGE_LIST_T* list) {
    NFAPI_RX_MESSAGE_T* current = list->head;
    while (current != NULL) {
        NFAPI_RX_MESSAGE_T* next = current->next;
        free(current);
        current = next;
    }
}
