    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to generate the array of structures
NFAPI_CRC_INDICATION_PDU_T* generateNfadpPduList(const char* configFilePath) {
    // Initialize variables
    int N = 0;
    FILE* configFile = NULL;
    bool isConfigFileValid = false;
    NFAPI_CRC_INDICATION_PDU_T* pduList = NULL;
    size_t numEntries = 0;

    // Open the configuration file and check for errors
    configFile = fopen(configFilePath, "r");
    if (configFile == NULL) {
        perror("Error opening configuration file");
        return NULL;
    }

    // Read the number of entries from the configuration file
    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, configFile)) != -1) {
        if (strncmp(line, "N=", 2) == 0) {
            N = atoi(line + 2);
            isConfigFileValid = true;
            break;
        }
    }

    // Close the configuration file and check for errors
    if (fclose(configFile) != 0) {
        perror("Error closing configuration file");
        return NULL;
    }

    // Check if the configuration file is valid
    if (!isConfigFileValid) {
        fprintf(stderr, "Invalid configuration file\n");
        return NULL;
    }

    // Allocate memory for the array of structures
    pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (pduList == NULL) {
        perror("Error allocating memory for the array of structures");
        return NULL;
    }

    // Initialize each structure with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < N; i++) {
        pduList[i].RX_UE_INFORMATION_TAG = i + 1;
        pduList[i].RNTI = rand();
        pduList[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        pduList[i].CRCFLAG = (rand() % 2) == 0 ? true : false;
    }

    // Return the pointer to the populated array of structures and the number of successfully created entries
    return pduList;
}
