    if (list == NULL || list->size == 0) {
        return NULL;
    }

    // Iterate over each structure in the list
    for (size_t i = 0; i < list->size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &list->data[i];

        // Check if the RNTI value matches the specified value
        if (pdu->rnti == rnti) {
            return pdu;
        }
    }

    // Return NULL if no matching structure is found
    return NULL;
}
