    uint8_t crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to dynamically create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(int num_elements) {
    // Allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        printf("Out of memory\n");
        return NULL;
    }

    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < num_elements; i++) {
        pdu_list[i].rx_ue_information_tag = 0;
        pdu_list[i].rnti = 0;
        pdu_list[i].crc_indication_rel8_tag = 0;
        pdu_list[i].crcflag = 0;
    }

    // Read the configuration parameters from an external JSON file
    json_object *root = json_object_from_file("config.json");
    if (!root) {
        printf("Error reading configuration file\n");
        free(pdu_list);
        return NULL;
    }

    // Get the number of elements in the list from the JSON file
    int num_elements = json_object_get_int(json_object_object_get(root, "num_elements"));

    // Populate the list of NFAPI_CRC_INDICATION_PDU_T structures with random values
    for (int i = 0; i < num_elements; i++) {
        pdu_list[i].rx_ue_information_tag = rand() % 65536;
        pdu_list[i].rnti = rand() % 4294967296;
        pdu_list[i].crc_indication_rel8_tag = rand() % 256;
        pdu_list[i].crcflag = rand() % 2 ? 1 : 0;
    }

    // Free the JSON object and return the list of NFAPI_CRC_INDICATION_PDU_T structures
    json_object_put(root);
    return pdu_list;
}

// Define a thread-safe function to handle concurrent access to the list of NFAPI_CRC_INDICATION_PDU_T structures
void* crc_indication_pdu_thread_func(void *arg) {
