    NFAPI_CRC_INDICATION_PDU_T *pdu_list = create_crc_indication_pdu_list(10);
    if (!pdu_list) {
        printf("Error creating list of CRC indication PDUs\n");
        return NULL;
    }

    // Populate the list with random values for this thread
