} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocateNfapiCrcIndicationPdu(int numElements) {
    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* pduArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pduArray) {
        return NULL;
    }

    // Initialize the structures with random values for CRCFLAG
    for (int i = 0; i < numElements; i++) {
        pduArray[i].rxUeInformationTag = RX_UE_INFORMATION_TAG_RANDOM;
        pduArray[i].rnti = RNTI_RANDOM;
        pduArray[i].crcIndicationRel8Tag = CRC_INDICATION_REL8_TAG_RANDOM;
    }

    // Add thread-safe mechanisms to ensure data integrity during concurrent access
    pthread_mutex_t* mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    if (!mutex) {
        free(pduArray);
        return NULL;
    }
    pthread_mutex_init(mutex, NULL);
    pthread_mutex_lock(mutex);

    // Add a pool of structures to allow efficient reuse and deallocation
    struct Pool {
        NFAPI_CRC_INDICATION_PDU_T* pduArray;
        int numElements;
        pthread_mutex_t* mutex;
    };
    static struct Pool pool = {pduArray, numElements, mutex};

    // Implement a strategy for efficiently reusing and deallocating memory to minimize overhead and maximize throughput
    if (pool.numElements < numElements) {
        free(pool.pduArray);
        pool.pduArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pool.pduArray) {
            pthread_mutex_unlock(mutex);
            return NULL;
        }
        pool.numElements = numElements;
    }

    // Return the allocated memory
    NFAPI_CRC_INDICATION_PDU_T* pduArray = pool.pduArray;
    pthread_mutex_unlock(mutex);
    return pduArray;
}
