        {
            int consumption = (int)(_currentCapacityLevel * _defaultGrowthRate * _degradationFactor);
            if (consumption > 0)
            {
                _currentCapacityLevel -= consumption;
            }
            else
            {
                _currentCapacityLevel += consumption;
            }
        }
    }

    public void ResetCapacityLevel()
    {
        lock (_lock)
        {
            _currentCapacityLevel = _minCapacityLevel;
        }
