void delete_end(list_t *list) {
    assert(list != NULL);

    pthread_mutex_lock(&list->mutex);

    if (list->tail == NULL) {
        // List is empty, do nothing
        return;
    }

    list_node_t *old_node = list->tail;
    list->tail = old_node->prev;

    if (list->tail == NULL) {
        // Old node was the only element in the list, set head to NULL
        list->head = NULL;
    } else {
        // Update the next pointer of the new tail
        list->tail->next = NULL;
