#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure to represent an UE context
typedef struct {
    int ueId;
    RRCConnection *connection;
    List *messages;
} UEContext;

// Define a list data structure to store the UE contexts
typedef struct {
    UEContext **contexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} UEContextList;

// Initialize an empty UE context list
void ueContextListInit(UEContextList *list) {
    list->capacity = 0;
    list->count = 0;
    list->contexts = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

// Add a new UE context to the list
void ueContextListAdd(UEContextList *list, int ueId, RRCConnection *connection) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Check if the list needs to be resized
    if (list->count == list->capacity) {
        list->capacity = list->capacity ? list->capacity * 2 : 16;
        UEContext **newContexts = realloc(list->contexts, list->capacity * sizeof(UEContext));
        if (!newContexts) {
            // Reallocation failed, unlock the mutex and return
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->contexts = newContexts;
    }

    // Create a new UE context and add it to the list
    UEContext *newContext = malloc(sizeof(UEContext));
    if (!newContext) {
        // Allocation failed, unlock the mutex and return
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    newContext->ueId = ueId;
    newContext->connection = connection;
    newContext->messages = NULL;
    list->contexts[list->count++] = newContext;

    // Unlock the mutex and return
    pthread_mutex_unlock(&list->mutex);
}

// Retrieve an existing UE context from the list by ueId
UEContext *ueContextListGet(UEContextList *list, int ueId) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Search for the UE context in the list
    for (size_t i = 0; i < list->count; i++) {
        if (list->contexts[i]->ueId == ueId) {
            // Found the UE context, unlock the mutex and return it
            pthread_mutex_unlock(&list->mutex);
            return list->contexts[i];
        }
    }

    // Did not find the UE context, unlock the mutex and return NULL
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Free all allocated resources in the UE context list
void ueContextListFree(UEContextList *list) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);

    // Iterate over the list and free each UE context
    for (size_t i = 0; i < list->count; i++) {
        UEContext *context = list->contexts[i];
        if (context) {
            free(context->messages);
            free(context->connection);
            free(context);
        }
    }

    // Free the context array and unlock the mutex
    free(list->contexts);
    pthread_mutex_unlock(&list->mutex);
}
```
This code defines a `UEContext` structure to represent an UE context, which contains a unique `ueId`, a pointer to a dynamically allocated `RRCConnection` structure, and a list of `RRCMessage` pointers. It also defines a `UEContextList` data structure to store the UE contexts in a dynamic array, with locking mechanisms to prevent concurrent access from multiple threads.

The `ueContextListInit()` function initializes an empty UE context list by allocating memory for the dynamic array and setting up the mutex. The `ueContextListAdd()` function adds a new UE context to the list by creating a new `UEContext` structure, adding it to the end of the dynamic array, and updating the count. The `ueContextListGet()` function retrieves an existing UE context from the list by searching for the matching `ueId`. The `ueContextListFree()` function frees all allocated resources in the UE context list by iterating over the list and freeing each `UEContext` structure, then freeing the dynamic array and unlocking the mutex.

The code uses a pthread mutex to ensure that concurrent access from multiple threads is safe and does not result in deadlocks or race conditions. The mutex is used to lock the list during updates and retrieval operations to prevent simultaneous access to the list by multiple threads.']

