// Define the function to generate NFAPI_CRC_INDICATION_PDU_T structures
void generateNfadlIndications(int numIndications) {
    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numIndications * sizeof(NFAPI_CRC_INDICATION_PDU_T));

