// Define the maximum number of RNTIs that can be stored in the list
#define MAX_RNTIS 1024

// Define the maximum memory budget for the list, in bytes
#define MEMORY_BUDGET (1024 * 1024) // 1 MB

// Define the LRU eviction policy parameters
#define EVICTION_THRESHOLD 0.75 // Evict items when the list is 75% full
#define EVICTION_INTERVAL 30 // Evict items every 30 seconds

// Define the data structure for storing RNTIs and their corresponding CRC indications
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *crc_ind;
    uint16_t rnti;
} rnti_entry_t;

// Define the data structure for storing the list of RNTIs and their corresponding CRC indications
typedef struct {
    rnti_entry_t *entries;
    size_t num_entries;
    size_t max_entries;
} rnti_list_t;

// Define the data structure for storing the list of RNTIs and their corresponding CRC indications, along with the LRU eviction policy parameters
typedef struct {
    rnti_list_t *rntis;
    size_t num_rntis;
    size_t max_rntis;
    double eviction_threshold;
    uint32_t eviction_interval;
} rnti_manager_t;

// Define the function for managing the list of RNTIs and their corresponding CRC indications
void manage_rntis(rnti_manager_t *manager, NFAPI_CRC_INDICATION_PDU_T *crc_ind) {
    // Validate that the RNTI is unique within the list
    if (find_rnti(manager->rntis, crc_ind->rx_ue_information.rnti)) {
        return;
    }

    // Ensure the total size of the list does not exceed the memory budget
    if (manager->num_entries >= manager->max_entries) {
        evict_lru(manager);
    }

    // Add the new RNTI and CRC indication to the list
    rnti_entry_t *new_entry = malloc(sizeof(rnti_entry_t));
    new_entry->crc_ind = crc_ind;
    new_entry->rnti = crc_ind->rx_ue_information.rnti;
    manager->entries[manager->num_entries++] = new_entry;

    // Update the LRU eviction policy parameters
    if (manager->num_entries >= EVICTION_THRESHOLD * manager->max_entries) {
        manager->eviction_interval = EVICTION_INTERVAL;
    }
}

// Define the function for finding a RNTI in the list
bool find_rnti(rnti_list_t *rntis, uint16_t rnti) {
    for (size_t i = 0; i < rntis->num_entries; i++) {
        if (rntis->entries[i]->rnti == rnti) {
            return true;
        }
    }
    return false;
}

// Define the function for evicting the least recently used item from the list
void evict_lru(rnti_manager_t *manager) {
    // Find the least recently used item in the list
    size_t lru_index = 0;
    uint32_t lru_timestamp = manager->entries[0]->crc_ind->rx_ue_information.timestamp;
    for (size_t i = 1; i < manager->num_entries; i++) {
        if (manager->entries[i]->crc_ind->rx_ue_information.timestamp < lru_timestamp) {
            lru_index = i;
            lru_timestamp = manager->entries[i]->crc_ind->rx_ue_information.timestamp;
        }
    }

    // Remove the least recently used item from the list
    free(manager->entries[lru_index]);
    memmove(&manager->entries[lru_index], &manager->entries[lru_index + 1], (manager->num_entries - lru_index - 1) * sizeof(rnti_entry_t));
    manager->num_entries--;
}

// Define the function for handling concurrent access to the list
void manage_concurrent_access(rnti_manager_t *manager, NFAPI_CRC_INDICATION_PDU_T *crc_ind) {
    // Lock the list before accessing it
    pthread_mutex_lock(&manager->mutex);

    // Add the new RNTI and CRC indication to the list
    manage_rntis(manager, crc_ind);

    // Unlock the list after accessing it
    pthread_mutex_unlock(&manager->mutex);
}
