// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the memory pool for the structures
#define MEMORY_POOL_SIZE 1024 * 1024 // 1 MB
static char memory_pool[MEMORY_POOL_SIZE];
static size_t memory_pool_used = 0;

// Define the function to manage the pool of structures
NFAPI_CRC_INDICATION_PDU_T* allocate_structure(uint32_t RNTI) {
    // Check if the RNTI is already in use
    for (size_t i = 0; i < memory_pool_used; i++) {
        NFAPI_CRC_INDICATION_PDU_T* structure = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool + i;
        if (structure->RNTI == RNTI) {
            return NULL; // Return NULL if the RNTI is already in use
        }
    }

    // Check if there is enough memory available to allocate a new structure
    size_t required_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (memory_pool_used + required_size > MEMORY_POOL_SIZE) {
        return NULL; // Return NULL if there is not enough memory available
    }

    // Allocate a new structure from the pool
    NFAPI_CRC_INDICATION_PDU_T* structure = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool + memory_pool_used;
    memory_pool_used += required_size;

    // Initialize the structure with the given RNTI value
    structure->RX_UE_INFORMATION_TAG = 0;
    structure->RNTI = RNTI;
    structure->CRCFLAG = 0;

    return structure; // Return the allocated structure
}

// Define the function to validate the uniqueness of an RNTI value
bool is_rnti_unique(uint32_t RNTI) {
    for (size_t i = 0; i < memory_pool_used; i++) {
        NFAPI_CRC_INDICATION_PDU_T* structure = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool + i;
        if (structure->RNTI == RNTI) {
            return false; // Return false if the RNTI is already in use
        }
    }
    return true; // Return true if the RNTI is unique
}

// Define the function to generate a new RNTI value
uint32_t generate_rnti() {
    uint32_t new_rnti = 0;
    while (!is_rnti_unique(new_rnti)) {
        new_rnti++; // Increment the RNTI until a unique value is found
    }
    return new_rnti; // Return the generated RNTI value
}

// Define the function to set the CRCFLAG based on parity check
void set_crcflag(NFAPI_CRC_INDICATION_PDU_T* structure) {
    uint16_t rx_ue_information_tag = structure->RX_UE_INFORMATION_TAG;
    uint32_t rnti = structure->RNTI;
    uint8_t crcflag = 0;

    // Perform the parity check over the concatenated binary representation of the RX_UE_INFORMATION_TAG and RNTI values
    for (size_t i = 0; i < sizeof(rx_ue_information_tag) + sizeof(rnti); i++) {
        crcflag ^= ((uint8_t*)&rx_ue_information_tag)[i] ^ ((uint8_t*)&rnti)[i];
    }

    // Set the CRCFLAG based on the result of the parity check
    structure->CRCFLAG = crcflag;
}

// Define the function to handle potential integer overflow during the parity check process
void handle_integer_overflow(NFAPI_CRC_INDICATION_PDU_T* structure) {
    // Check if the CRCFLAG is outside of the valid range of the tag
    if (structure->CRCFLAG > UINT8_MAX) {
        // If the CRCFLAG is outside of the valid range, set it to 0
        structure->CRCFLAG = 0;
    }
}

// Define the function to validate all input parameters before processing
void validate_input(NFAPI_CRC_INDICATION_PDU_T* structure) {
    // Check if the RX_UE_INFORMATION_TAG is valid
    if (structure->RX_UE_INFORMATION_TAG > UINT16_MAX) {
        return; // Return if the RX_UE_INFORMATION_TAG is invalid
    }

    // Check if the RNTI is valid
    if (structure->RNTI > UINT32_MAX) {
        return; // Return if the RNTI is invalid
    }
}

