// Define the memory pool for efficient allocation and deallocation of NFAPI_CRC_INDICATION_PDU_T structures
#define POOL_SIZE 1024
static NFAPI_CRC_INDICATION_PDU_T *pool = NULL;

// Function to initialize the memory pool
void init_memory_pool() {
    if (pool == NULL) {
        pool = malloc(POOL_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pool == NULL) {
            printf("Error: Memory allocation failed\n");
            return;
        }
    }
}

// Function to allocate a new NFAPI_CRC_INDICATION_PDU_T structure from the memory pool
NFAPI_CRC_INDICATION_PDU_T *allocate_structure() {
    if (pool == NULL) {
        init_memory_pool();
    }
    for (int i = 0; i < POOL_SIZE; i++) {
        if (pool[i].RX_UE_INFORMATION_TAG == 0 && pool[i].RNTI == 0) {
            return &pool[i];
        }
    }
    printf("Error: Memory allocation failed\n");
    return NULL;
}

// Function to deallocate a NFAPI_CRC_INDICATION_PDU_T structure from the memory pool
void deallocate_structure(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pool == NULL || pdu == NULL) {
        return;
    }
    for (int i = 0; i < POOL_SIZE; i++) {
        if (&pool[i] == pdu) {
            pool[i].RX_UE_INFORMATION_TAG = 0;
            pool[i].RNTI = 0;
            return;
        }
    }
}

// Function to calculate the CRCFLAG based on a parity check over the concatenated binary representation of RX_UE_INFORMATION_TAG and RNTI
uint8_t calculate_crcflag(uint16_t RX_UE_INFORMATION_TAG, uint32_t RNTI) {
    // Calculate the parity check over the concatenated binary representation of RX_UE_INFORMATION_TAG and RNTI
    uint8_t crcflag = 0;
    for (int i = 0; i < sizeof(RX_UE_INFORMATION_TAG); i++) {
        crcflag ^= ((uint8_t *)&RX_UE_INFORMATION_TAG)[i];
    }
    for (int i = 0; i < sizeof(RNTI); i++) {
        crcflag ^= ((uint8_t *)&RNTI)[i];
    }
    return crcflag;
}

// Function to manage a dynamic list of NFAPI_CRC_INDICATION_PDU_T structures, each containing a valid RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG
void manage_list(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Initialize the memory pool if it has not been initialized yet
    init_memory_pool();

    // Allocate a new NFAPI_CRC_INDICATION_PDU_T structure from the memory pool
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = allocate_structure();
    if (new_pdu == NULL) {
        return;
    }

    // Set the RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG for the new structure
    new_pdu->RX_UE_INFORMATION_TAG = pdu->RX_UE_INFORMATION_TAG;
    new_pdu->RNTI = pdu->RNTI;
    new_pdu->CRCFLAG = calculate_crcflag(new_pdu->RX_UE_INFORMATION_TAG, new_pdu->RNTI);

    // Check if the RNTI is already in the list
    bool found = false;
    for (int i = 0; i < POOL_SIZE; i++) {
        if (pool[i].RNTI == new_pdu->RNTI) {
            found = true;
            break;
        }
    }

    // If the RNTI is not in the list, add it to the list and return
    if (!found) {
        pool[i] = *new_pdu;
        deallocate_structure(new_pdu);
        return;
    }

    // If the RNTI is already in the list, check for duplicates and generate a new RNTI until uniqueness is achieved
    while (found) {
        new_pdu->RNTI++;
        new_pdu->CRCFLAG = calculate_crcflag(new_pdu->RX_UE_INFORMATION_TAG, new_pdu->RNTI);
        found = false;
        for (int i = 0; i < POOL_SIZE; i++) {
            if (pool[i].RNTI == new_pdu->RNTI) {
                found = true;
                break;
            }
        }
    }

    // Add the new structure to the list and return
    pool[i] = *new_pdu;
    deallocate_structure(new_pdu);
}

// Function to track the time taken for each disjoint pair check
void measure_time(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Initialize a timer variable
    clock_t start = clock();

    // Perform the disjoint pair check
    manage_list(pdu);

    // Calculate the time taken for the disjoint pair check
    double time_taken = (double)(clock() - start) / CLOCKS_PER_SEC;

    // Print the time taken for the disjoint pair check
    printf("Time taken for disjoint pair check: %f ms\n", time_taken * 1000);
}

// Function to integrate a Union-Find data structure to efficiently manage disjoint pairs
void union_find(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Initialize the Union-Find data structure
    int *parent = malloc(POOL_SIZE * sizeof(int));
    for (int i = 0; i < POOL_SIZE; i++) {
        parent[i] = i;
    }

    // Perform the disjoint pair check using the Union-Find data structure
    manage_list(pdu);

    // Free the memory allocated for the Union-Find data structure
    free(parent);
}

