// Define the structure to hold the RX_FRAME_PDU data
typedef struct {
    NFAPI_RX_FRAME_PDU_T rx_frame;
    NFAPI_RX_TX_DUP_IND_PDU_T dup_ind;
} frame_data_t;

// Define the array to hold the RX_FRAME_PDU data
static frame_data_t *rx_frames = NULL;

// Define the mutex for protecting the rx_frames array from concurrent access
static pthread_mutex_t rx_frames_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function to initialize and populate the rx_frames array
void init_rx_frames(int num_frames) {
    // Allocate memory for the rx_frames array
    rx_frames = (frame_data_t *)malloc(num_frames * sizeof(frame_data_t));

    // Initialize the sequence number and timestamp for each frame
    for (int i = 0; i < num_frames; i++) {
        rx_frames[i].rx_frame.sequence_number = i + 1;
        rx_frames[i].dup_ind.timestamp = time(NULL);
        rx_frames[i].dup_ind.is_duplicate = false;
    }
}

// Define the function to add a new RX_FRAME_PDU to the rx_frames array
void add_rx_frame(NFAPI_RX_FRAME_PDU_T *rx_frame) {
    // Lock the mutex to protect the rx_frames array from concurrent access
    pthread_mutex_lock(&rx_frames_mutex);

    // Find the next available slot in the rx_frames array
    int i = 0;
    while (i < num_frames && rx_frames[i].rx_frame.sequence_number != 0) {
        i++;
    }

    // If no slots are available, resize the array and add a new slot
    if (i == num_frames) {
        num_frames += 100;
        rx_frames = (frame_data_t *)realloc(rx_frames, num_frames * sizeof(frame_data_t));
    }

    // Copy the new RX_FRAME_PDU data into the next available slot
    memcpy(&rx_frames[i].rx_frame, rx_frame, sizeof(NFAPI_RX_FRAME_PDU_T));
    rx_frames[i].dup_ind.timestamp = time(NULL);
    rx_frames[i].dup_ind.is_duplicate = false;

    // Unlock the mutex and return
    pthread_mutex_unlock(&rx_frames_mutex);
}

// Define the function to check if a frame is a duplicate
bool is_duplicate(NFAPI_RX_FRAME_PDU_T *rx_frame) {
    // Lock the mutex to protect the rx_frames array from concurrent access
    pthread_mutex_lock(&rx_frames_mutex);

    // Check if the frame is a duplicate by comparing its sequence number and timestamp with those in the rx_frames array
    for (int i = 0; i < num_frames; i++) {
        if (rx_frame->sequence_number == rx_frames[i].rx_frame.sequence_number &&
            rx_frame->timestamp == rx_frames[i].dup_ind.timestamp) {
