void initializePacketList(NetworkPacket *packets, int num_packets) {
    // Initialize shared memory cache for repeated calls with the same number of packets
    static char* ip_cache = NULL;
    if (ip_cache == NULL) {
        ip_cache = malloc(sizeof(char) * 16);
    }

    // Populate array of NetworkPacket structures with specified number of packets
    for (int i = 0; i < num_packets; i++) {
        // Generate random IP addresses using shared memory cache
        char* source_ip = ip_cache + (i % 16);
        char* destination_ip = ip_cache + ((i + 1) % 16);
        if (source_ip == destination_ip) {
            // Handle duplicate IP addresses by generating a new one
            do {
                source_ip = generateIPAddress();
                destination_ip = generateIPAddress();
            } while (source_ip == destination_ip);
        }

        // Set packet size and transmission delay
        packets[i].SourceIP = source_ip;
        packets[i].DestinationIP = destination_ip;
        packets[i].PacketSize = rand() % 1024 + 512;
        packets[i].TransmissionDelay = (double)rand() / RAND_MAX * 10.0;
    }
}

char* generateIPAddress() {
    // Generate random IP address using shared memory cache
    char* ip = ip_cache + rand() % 16;
    if (*ip == '\0') {
        // Handle duplicate IP addresses by generating a new one
