NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu(int num_users, int rnti_start, int rnti_end, bool enable_logging, pthread_mutex_t *mutex) {
    // Check if the number of users is within the valid range
    if (num_users < 0 || num_users > MAX_USERS) {
        printf("Error: Invalid number of users specified\n");
        return NULL;
    }

    // Check if the RNTI range is within the valid range
    if (rnti_start < 0x0000 || rnti_end > 0xFFFF) {
        printf("Error: Invalid RNTI range specified\n");
        return NULL;
    }

    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_users * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        printf("Error: Failed to allocate memory for CRC indication PDU\n");
        return NULL;
    }

    // Initialize the RX_UE_INFORMATION_TAG and CRCFLAG fields of each structure
    for (int i = 0; i < num_users; i++) {
        pdu[i].RX_UE_INFORMATION_TAG = 0x1234;
        pdu[i].CRCFLAG = rand() % 256;
    }

    // Generate a random RNTI value for each structure
    for (int i = 0; i < num_users; i++) {
        pdu[i].RNTI = rnti_start + (rand() % (rnti_end - rnti_start));
    }

    // Check for duplicate RNTI values and handle them appropriately
    for (int i = 0; i < num_users; i++) {
        for (int j = i + 1; j < num_users; j++) {
            if (pdu[i].RNTI == pdu[j].RNTI) {
                // If a duplicate RNTI value is found, regenerate the RNTI value for that structure
                pdu[i].RNTI = rnti_start + (rand() % (rnti_end - rnti_start));
            }
        }
    }

    // Log the allocation and validation steps if enabled
    if (enable_logging) {
        printf("Allocated CRC indication PDU with %d users\n", num_users);
        for (int i = 0; i < num_users; i++) {
            printf("User %d: RNTI=0x%X, CRCFLAG=%d\n", i, pdu[i].RNTI, pdu[i].CRCFLAG);
        }
    }

    // Return the pointer to the allocated array of NFAPI_CRC_INDICATION_PDU_T structures
    return pdu;
}
