typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the linked list head pointer
Node* head = NULL;

// Define the mutex for thread-safe operations
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function to add an element to the linked list
void addElement(NFAPI_CRC_INDICATION_PDU_T data) {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&mutex);

    // Create a new node and initialize it with the given data
    Node* newNode = malloc(sizeof(Node));
    newNode->data = data;

    // If the head is NULL, set the new node as the head
    if (head == NULL) {
        head = newNode;
    } else {
        // Otherwise, add the new node to the end of the linked list
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    // Unlock the mutex after modifying the linked list
    pthread_mutex_unlock(&mutex);
}

// Define the function to remove an element from the linked list
void removeElement(NFAPI_CRC_INDICATION_PDU_T data) {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&mutex);

    // If the head is NULL, do nothing
    if (head == NULL) {
        return;
    }

    // Otherwise, find the node with the given data and remove it from the linked list
    Node* current = head;
    while (current != NULL && current->data.rx_ue_information != data.rx_ue_information) {
        current = current->next;
    }
    if (current == NULL) {
        return;
    }
    if (current == head) {
        head = head->next;
    } else {
        Node* previous = head;
        while (previous->next != current) {
            previous = previous->next;
        }
        previous->next = current->next;
    }

    // Unlock the mutex after modifying the linked list
    pthread_mutex_unlock(&mutex);
}

// Define the function to get an element from the linked list
NFAPI_CRC_INDICATION_PDU_T* getElement(RX_UE_INFORMATION_TAG rx_ue_information) {
    // Lock the mutex before accessing the linked list
    pthread_mutex_lock(&mutex);

    // If the head is NULL, return NULL
    if (head == NULL) {
        return NULL;
    }

    // Otherwise, find the node with the given data and return its data
    Node* current = head;
    while (current != NULL && current->data.rx_ue_information != rx_ue_information) {
        current = current->next;
    }
    if (current == NULL) {
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* data = &(current->data);

    // Unlock the mutex after accessing the linked list
    pthread_mutex_unlock(&mutex);

    return data;
}

// Define the function to get the size of the linked list
int getSize() {
    int size = 0;

    // Lock the mutex before accessing the linked list
    pthread_mutex_lock(&mutex);

    // If the head is NULL, return 0
    if (head == NULL) {
        size = 0;
    } else {
        // Otherwise, count the number of nodes in the linked list
        Node* current = head;
        while (current != NULL) {
            size++;
            current = current->next;
        }
    }

    // Unlock the mutex after accessing the linked list
    pthread_mutex_unlock(&mutex);

    return size;
}

// Define the function to clear the linked list
void clear() {
    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&mutex);

    // If the head is NULL, do nothing
    if (head == NULL) {
        return;
    }

    // Otherwise, free all nodes in the linked list and set the head to NULL
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    head = NULL;

    // Unlock the mutex after modifying the linked list
    pthread_mutex_unlock(&mutex);
}
