#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>

// Define the structure for frame information
typedef struct FrameInfo {
    long timestamp;
    int session_id;
    PacketMetadata *packets;
} FrameInfo;

// Define the structure for packet metadata
typedef struct PacketMetadata {
    int length;
    char source_ip[16];
    char dest_ip[16];
    bool tcp_flag;
} PacketMetadata;

// Function to initialize and populate a dynamic array of FrameInfo structures
void init_frame_info(FrameInfo **frames, int num_frames) {
    // Allocate memory for the frames
    *frames = (FrameInfo *)malloc(num_frames * sizeof(FrameInfo));
    if (*frames == NULL) {
        printf("Error: Failed to allocate memory for frames\n");
        return;
    }

    // Initialize each frame with a timestamp, session ID, and empty packet list
    for (int i = 0; i < num_frames; i++) {
        (*frames)[i].timestamp = time(NULL);
        (*frames)[i].session_id = i + 1;
        (*frames)[i].packets = NULL;
    }
}

// Function to add a packet to the frame information
void add_packet(FrameInfo *frame, PacketMetadata *packet) {
    // Check if the frame has an empty packet list
    if (frame->packets == NULL) {
        // Allocate memory for the packet list
        frame->packets = (PacketMetadata *)malloc(sizeof(PacketMetadata));
        if (frame->packets == NULL) {
            printf("Error: Failed to allocate memory for packet list\n");
            return;
        }
    } else {
        // Reallocate the packet list with additional space for the new packet
        frame->packets = (PacketMetadata *)realloc(frame->packets, (frame->num_packets + 1) * sizeof(PacketMetadata));
        if (frame->packets == NULL) {
            printf("Error: Failed to reallocate memory for packet list\n");
            return;
        }
    }

    // Add the new packet to the list
    frame->packets[frame->num_packets++] = *packet;
}

// Function to handle a single frame of data
void handle_frame(FrameInfo *frame) {
    // Iterate over each packet in the frame
    for (int i = 0; i < frame->num_packets; i++) {
        PacketMetadata *packet = &frame->packets[i];

        // Handle the packet as needed
        handle_packet(packet);
    }
}

// Function to handle a single packet of data
void handle_packet(PacketMetadata *packet) {
    // Process the packet as needed
    printf("Received packet with length %d, source IP %s, destination IP %s, and TCP flag %d\n", packet->length, packet->source_ip, packet->dest_ip, packet->tcp_flag);
}

// Function to clean up memory for a frame
void free_frame(FrameInfo *frame) {
    // Free the packet list if it exists
    if (frame->packets != NULL) {
        free(frame->packets);
    }

    // Free the frame structure itself
    free(frame);
}
```
