// Define the structure to hold the CRC indication data
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to manage the dynamically allocated array of structures
void manage_crc_indications(NFAPI_CRC_INDICATION_PDU_T **pdu, uint16_t num_pdus, uint16_t rnti_range) {
    // Initialize variables for tracking statistics
    int processed = 0;
    int errors = 0;

    // Allocate memory for the array of structures
    *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_pdus * sizeof(**pdu));
    if (*pdu == NULL) {
        printf("Error: Failed to allocate memory for CRC indication PDUs\n");
        return;
    }

    // Initialize the structures with random values and timestamps
    srand(time(NULL));
    for (int i = 0; i < num_pdus; i++) {
        (*pdu)[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        (*pdu)[i].RNTI = rand() % rnti_range;
        (*pdu)[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        (*pdu)[i].timestamp = time(NULL);
    }

    // Filter the structures based on the specified RNTI range
    for (int i = 0; i < num_pdus; i++) {
        if ((*pdu)[i].RNTI >= rnti_range) {
            continue;
        }
        processed++;
    }

    // Print statistics on the number of structures processed and any errors encountered
    printf("Processed %d CRC indications, with %d errors\n", processed, errors);

    // Free memory allocated for the array of structures
    free(*pdu);
}
