#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for LTE_DL_FRAMEINFO
typedef struct {
    MAC_PDU *mac_pdu;
    RRC_CAUSE rrc_cause;
    NAS_CAUSE nas_cause;
} LTE_DL_FRAMEINFO;

// Define the dynamic array for storing LTE_DL_FRAMEINFO structures
typedef struct {
    LTE_DL_FRAMEINFO **frames;
    size_t capacity;
    size_t count;
} LTE_DL_FRAMEARRAY;

// Define the function for initializing and populating the dynamic array
void init_and_populate_framearray(LTE_DL_FRAMEARRAY *framearray, size_t capacity) {
    // Allocate memory for the frames array
    framearray->frames = (LTE_DL_FRAMEINFO **)malloc(capacity * sizeof(LTE_DL_FRAMEINFO *));
    if (!framearray->frames) {
        // Handle error: out of memory
        return;
    }

    // Initialize the frames array with NULL pointers
    for (size_t i = 0; i < capacity; i++) {
        framearray->frames[i] = NULL;
    }

    // Set the initial capacity and count to zero
    framearray->capacity = capacity;
    framearray->count = 0;
}

// Define the function for adding a new frame to the dynamic array
void add_frame(LTE_DL_FRAMEARRAY *framearray, MAC_PDU *mac_pdu, RRC_CAUSE rrc_cause, NAS_CAUSE nas_cause) {
    // Check if the capacity of the frames array needs to be increased
    if (framearray->count == framearray->capacity) {
        // Increase the capacity by 50%
        size_t new_capacity = framearray->capacity * 1.5;
        LTE_DL_FRAMEINFO **new_frames = (LTE_DL_FRAMEINFO **)realloc(framearray->frames, new_capacity * sizeof(LTE_DL_FRAMEINFO *));
        if (!new_frames) {
            // Handle error: out of memory
            return;
        }
        framearray->frames = new_frames;
        framearray->capacity = new_capacity;
    }

    // Allocate memory for the new frame and populate it with the given data
    LTE_DL_FRAMEINFO *new_frame = (LTE_DL_FRAMEINFO *)malloc(sizeof(LTE_DL_FRAMEINFO));
    if (!new_frame) {
        // Handle error: out of memory
        return;
    }
    new_frame->mac_pdu = mac_pdu;
    new_frame->rrc_cause = rrc_cause;
    new_frame->nas_cause = nas_cause;

    // Add the new frame to the end of the frames array
    framearray->frames[framearray->count++] = new_frame;
}

// Define the function for removing a frame from the dynamic array
void remove_frame(LTE_DL_FRAMEARRAY *framearray, size_t index) {
    // Check if the given index is valid
    if (index >= framearray->count) {
        return;
    }

    // Free the memory for the removed frame
    free(framearray->frames[index]);

    // Shift all frames after the removed frame to fill the gap
    for (size_t i = index + 1; i < framearray->count; i++) {
        framearray->frames[i - 1] = framearray->frames[i];
    }

    // Decrement the count of frames in the array
    framearray->count--;
}

// Define the function for accessing a frame from the dynamic array
LTE_DL_FRAMEINFO *get_frame(LTE_DL_FRAMEARRAY *framearray, size_t index) {
    // Check if the given index is valid
    if (index >= framearray->count) {
        return NULL;
    }

    // Return a pointer to the requested frame
    return framearray->frames[index];
}

// Define the function for logging errors and debugging information to a file
void log_error(const char *message, ...) {
    // Open the log file in append mode
    FILE *log_file = fopen("log.txt", "a");
    if (!log_file) {
        return;
    }

    // Write the error message to the log file
    va_list args;
    va_start(args, message);
    vfprintf(log_file, message, args);
    va_end(args);

    // Close the log file
    fclose(log_file);
}
