void manage_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Lock the list for thread-safe access
    pthread_mutex_lock(&list->mutex);

    // Check if the list is full and needs to be resized
    if (list->size == list->capacity) {
        // Double the capacity of the list
        list->capacity *= 2;

        // Reallocate memory for the list
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            // Log the error and return
            printf("Error: Failed to allocate memory for CRC indication list\n");
            pthread_mutex_unlock(&list->mutex);
            return;
        }

        // Update the data pointer and size of the list
        list->data = new_data;
        list->size++;
    }

    // Add a new element to the list
    NFAPI_CRC_INDICATION_PDU_T *new_element = &list->data[list->size++];

    // Initialize the fields of the new element
    new_element->RX_UE_INFORMATION_TAG = 0;
    new_element->RNTI = 0;
    new_element->CRC_INDICATION_REL8_TAG = 0;
