    // Lock the list for thread-safe access
    pthread_mutex_lock(&list->mutex);

    // Check if the index is valid
    if (index < 0 || index >= list->size) {
        // Log the error and return
        printf("Error: Invalid index %d for CRC indication element\n", index);
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Update the fields of the element at the specified index
    NFAPI_CRC_INDICATION_PDU_T *element = &list->data[index];
    element->RX_UE_INFORMATION_TAG = new_data->RX_UE_INFORMATION_TAG;
    element->RNTI = new_data->RNTI;
    element->CRC_INDICATION_REL8_TAG = new_data->CRC_INDICATION_REL8_TAG;
    element->CRCFLAG = new_data->CRCFLAG;

    // Unlock the list for thread-safe access
    pthread_mutex_unlock(&list->mutex);
}

// Define the function to retrieve an element from the list
NFAPI_CRC_INDICATION_PDU_T *get_crc_indication_element(NFAPI_CRC_INDICATION_LIST_T *list, int index) {
    // Lock the list for thread-safe access
    pthread_mutex_lock(&list->mutex);

    // Check if the index is valid
    if (index < 0 || index >= list->size) {
        // Log the error and return NULL
        printf("Error: Invalid index %d for CRC indication element\n", index);
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    // Return a pointer to the element at the specified index
    NFAPI_CRC_INDICATION_PDU_T *element = &list->data[index];

    // Unlock the list for thread-safe access
    pthread_mutex_unlock(&list->mutex);

    return element;
}

// Define the function to remove an element from the list
void remove_crc_indication_element(NFAPI_CRC_INDICATION_LIST_T *list, int index) {
    // Lock the list for thread-safe access
    pthread_mutex_lock(&list->mutex);

    // Check if the index is valid
    if (index < 0 || index >= list->size) {
        // Log the error and return
        printf("Error: Invalid index %d for CRC indication element\n", index);
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Shift all elements after the specified index to fill the gap
    for (int i = index + 1; i < list->size; i++) {
        list->data[i - 1] = list->data[i];
