// Define the structure for a data packet
typedef struct {
    int packetID;
    time_t timestamp;
    char* payload;
} DataPacket;

// Function to initialize and populate a dynamic array of DataPacket structures
void initDataPackets(int numPackets, DataPacket** packets) {
    // Allocate memory for the array of pointers
    *packets = (DataPacket*)malloc(numPackets * sizeof(DataPacket));

    // Initialize each packet with a unique ID and timestamp
    for (int i = 0; i < numPackets; i++) {
        (*packets)[i].packetID = i + 1;
        (*packets)[i].timestamp = time(NULL);

        // Generate a random byte array of length between 100 and 1000 bytes
        int payloadSize = rand() % 900 + 100;
        char* payload = (char*)malloc(payloadSize * sizeof(char));
        for (int j = 0; j < payloadSize; j++) {
            payload[j] = rand() % 256;
        }
        (*packets)[i].payload = payload;
    }
}

// Function to compress the payload of a DataPacket structure using zlib
void compressPayload(DataPacket* packet) {
    // Compress the payload using zlib
    int compressedSize = compressBound(strlen(packet->payload));
    char* compressedPayload = (char*)malloc(compressedSize * sizeof(char));
    compress2(compressedPayload, &compressedSize, packet->payload, strlen(packet->payload), Z_DEFAULT_COMPRESSION);

    // Free the original payload and replace it with the compressed one
    free(packet->payload);
    packet->payload = compressedPayload;
}

// Function to serialize a DataPacket structure into a binary format
void serializeDataPacket(DataPacket* packet, char** serializedPacket) {
    // Allocate memory for the serialized packet
    *serializedPacket = (char*)malloc(sizeof(DataPacket));

    // Serialize the packet ID and timestamp
    memcpy(*serializedPacket, &packet->packetID, sizeof(int));
    memcpy(*serializedPacket + sizeof(int), &packet->timestamp, sizeof(time_t));

    // Serialize the payload using zlib
    int compressedSize = compressBound(strlen(packet->payload));
    char* compressedPayload = (char*)malloc(compressedSize * sizeof(char));
    compress2(compressedPayload, &compressedSize, packet->payload, strlen(packet->payload), Z_DEFAULT_COMPRESSION);

    // Serialize the compressed payload and free the original one
    memcpy(*serializedPacket + 2 * sizeof(int), compressedPayload, compressedSize);
    free(compressedPayload);
}

// Function to deserialize a DataPacket structure from a binary format
void deserializeDataPacket(char* serializedPacket, int serializedPacketSize, DataPacket** packet) {
    // Allocate memory for the deserialized packet
    *packet = (DataPacket*)malloc(sizeof(DataPacket));

    // Deserialize the packet ID and timestamp
    memcpy(&(*packet)->packetID, serializedPacket, sizeof(int));
    memcpy(&(*packet)->timestamp, serializedPacket + sizeof(int), sizeof(time_t));

    // Deserialize the payload using zlib
    int decompressedSize = decompressBound(serializedPacketSize - 2 * sizeof(int));
    char* decompressedPayload = (char*)malloc(decompressedSize * sizeof(char));
    uncompress(decompressedPayload, &decompressedSize, serializedPacket + 2 * sizeof(int), serializedPacketSize - 2 * sizeof(int));

    // Free the original payload and replace it with the decompressed one
    free((*packet)->payload);
    (*packet)->payload = decompressedPayload;
}
