    // Wait for all threads to complete before returning the list of CRC indications
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
    return indications;
}

void *generate_crc_indication_thread(void *arg) {
