        return;
    }

    // Lock the list to prevent concurrent access
    semaphore_lock(&list->semaphore);

    // Calculate the average load of the list
    double average_load = (double)list->size / (double)list->capacity;

    // Adjust the capacity of the list based on the average load
    if (average_load > 0.75) {
        list->capacity *= 2;
    } else if (average_load < 0.25) {
        list->capacity /= 2;
    }

    // Unlock the list and return
    semaphore_unlock(&list->semaphore);
}

