#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <math.h>

// Define the LTE_PHY_FRAME_T structure
typedef struct {
    int frame_number;
    double rssi;
    double snr;
} LTE_PHY_FRAME_T;

// Function to generate and populate LTE_PHY_FRAME_T structures from simulated radio signals
LTE_PHY_FRAME_T* generate_phy_frames(int num_frames, double *rssi, double *snr) {
    // Allocate memory for the LTE_PHY_FRAME_T structures
    LTE_PHY_FRAME_T *frames = (LTE_PHY_FRAME_T*)malloc(num_frames * sizeof(LTE_PHY_FRAME_T));
    if (!frames) {
        printf("Error: Failed to allocate memory for LTE_PHY_FRAME_T structures\n");
        return NULL;
    }

    // Populate the LTE_PHY_FRAME_T structures with simulated radio signal data
    for (int i = 0; i < num_frames; i++) {
        frames[i].frame_number = i + 1;
        frames[i].rssi = rssi[i];
        frames[i].snr = snr[i];
    }

    return frames;
}
```
This function takes in the number of frames to generate, a pointer to an array of RSSI values, and a pointer to an array of SNR values. It allocates memory for the LTE_PHY_FRAME_T structures using `malloc()`, and then populates the structures with the simulated radio signal data. If there is an error in allocating memory or populating the structures, it returns NULL. Otherwise, it returns a pointer to the first element of the allocated array of LTE_PHY_FRAME_T structures.

