// Define a structure to represent an LTE UE context
typedef struct {
    int ue_id;
    int num_bwp_configs;
    int *bwp_configs;
    int num_meas_reports;
    int *meas_reports;
} lte_ue_context_t;

// Define a function to initialize and configure an LTE UE context
void init_lte_ue_context(lte_ue_context_t *ctx, int ue_id) {
    ctx->ue_id = ue_id;
    ctx->num_bwp_configs = 0;
    ctx->bwp_configs = NULL;
    ctx->num_meas_reports = 0;
    ctx->meas_reports = NULL;
}

// Define a function to add a BWP configuration to an LTE UE context
void add_bwp_config(lte_ue_context_t *ctx, int bwp_id) {
    // Check if the BWP configuration already exists in the list
    for (int i = 0; i < ctx->num_bwp_configs; i++) {
        if (ctx->bwp_configs[i] == bwp_id) {
            return;
        }
    }

    // Allocate memory for the new BWP configuration
    int *new_bwp_configs = realloc(ctx->bwp_configs, (ctx->num_bwp_configs + 1) * sizeof(int));
    if (!new_bwp_configs) {
        printf("Error: Failed to allocate memory for BWP configuration\n");
        return;
    }
    ctx->bwp_configs = new_bwp_configs;

    // Add the new BWP configuration to the list
    ctx->bwp_configs[ctx->num_bwp_configs++] = bwp_id;
}

// Define a function to add a measurement report to an LTE UE context
void add_meas_report(lte_ue_context_t *ctx, int meas_report) {
    // Check if the measurement report already exists in the list
    for (int i = 0; i < ctx->num_meas_reports; i++) {
        if (ctx->meas_reports[i] == meas_report) {
            return;
        }
    }

    // Allocate memory for the new measurement report
    int *new_meas_reports = realloc(ctx->meas_reports, (ctx->num_meas_reports + 1) * sizeof(int));
    if (!new_meas_reports) {
        printf("Error: Failed to allocate memory for measurement report\n");
        return;
    }
    ctx->meas_reports = new_meas_reports;

    // Add the new measurement report to the list
    ctx->meas_reports[ctx->num_meas_reports++] = meas_report;
}

// Define a function to free the memory allocated for an LTE UE context
void free_lte_ue_context(lte_ue_context_t *ctx) {
    if (ctx->bwp_configs) {
        free(ctx->bwp_configs);
    }
    if (ctx->meas_reports) {
        free(ctx->meas_reports);
    }
