// Custom data structure for user sessions
typedef struct Session {
    int session_id;
    char* user_attributes;
    time_t last_activity;
} Session;

// Global variable to store the number of active sessions
int num_sessions = 0;

// Mutex for thread-safe access to the global variable
pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize a new session structure
Session* init_session(int session_id, char* user_attributes) {
    Session* session = malloc(sizeof(Session));
    if (session == NULL) {
        // Handle allocation failure gracefully
        printf("Error: Failed to allocate memory for session %d\n", session_id);
        return NULL;
    }

    session->session_id = session_id;
    session->user_attributes = user_attributes;
    session->last_activity = time(NULL);

    // Acquire lock to update the global variable safely
    pthread_mutex_lock(&session_lock);
    num_sessions++;
    pthread_mutex_unlock(&session_lock);

    return session;
}

// Function to free a session structure
void free_session(Session* session) {
    // Acquire lock to update the global variable safely
    pthread_mutex_lock(&session_lock);
    num_sessions--;
    pthread_mutex_unlock(&session_lock);

    free(session->user_attributes);
    free(session);
}

// Function to retrieve a session structure by ID
Session* get_session(int session_id) {
    // Acquire lock to access the global variable safely
    pthread_mutex_lock(&session_lock);

    Session* session = NULL;
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i].session_id == session_id) {
            session = &sessions[i];
            break;
        }
    }

    pthread_mutex_unlock(&session_lock);

    return session;
}

// Function to update the last activity timestamp for a session structure
void update_last_activity(Session* session) {
    // Acquire lock to access the global variable safely
    pthread_mutex_lock(&session_lock);

    session->last_activity = time(NULL);

    pthread_mutex_unlock(&session_lock);
}
