    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to dynamically generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void generate_nfapi_crc_indication_pdu_list(int n, int *rnti_list) {
    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (!nfapi_crc_indication_pdu_list) {
        printf("Error: Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T list\n");
        return;
    }

    // Populate the list of NFAPI_CRC_INDICATION_PDU_T structures with valid RX_UE_INFORMATION_TAG and RNTI values
    for (int i = 0; i < n; i++) {
        nfapi_crc_indication_pdu_list[i].rx_ue_information_tag = i + 1;
        nfapi_crc_indication_pdu_list[i].rnti = rnti_list[i];
        nfapi_crc_indication_pdu_list[i].crc_indication_rel8_tag = rand() % 256; // Randomly set CRCFLAG
    }

