// Define a structure to hold configuration parameters
typedef struct {
    int tile_size;
    int width;
    int height;
    float camera_speed;
} config_t;

// Define a function to read the configuration file and populate the config structure
int read_config(const char *filename, config_t *config) {
    // Open the JSON file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open configuration file\n");
        return -1;
    }

    // Parse the JSON data and populate the config structure
    json_object *root = json_object_from_file(filename);
    if (root == NULL) {
        printf("Error: unable to parse configuration file\n");
        fclose(file);
        return -1;
    }

    // Read the tile size parameter
    json_object *tile_size = json_object_object_get(root, "tile_size");
    if (tile_size == NULL) {
        printf("Error: unable to read tile size from configuration file\n");
        fclose(file);
        return -1;
    }
    config->tile_size = json_object_get_int(tile_size);

    // Read the world dimensions (width and height) parameters
    json_object *width = json_object_object_get(root, "width");
    if (width == NULL) {
        printf("Error: unable to read width from configuration file\n");
        fclose(file);
        return -1;
    }
    config->width = json_object_get_int(width);

    json_object *height = json_object_object_get(root, "height");
    if (height == NULL) {
        printf("Error: unable to read height from configuration file\n");
        fclose(file);
        return -1;
    }
    config->height = json_object_get_int(height);

    // Read the camera movement speed parameter
    json_object *camera_speed = json_object_object_get(root, "camera_speed");
    if (camera_speed == NULL) {
        printf("Error: unable to read camera speed from configuration file\n");
        fclose(file);
        return -1;
    }
    config->camera_speed = json_object_get_float(camera_speed);

    // Close the JSON file
    fclose(file);

    return 0;
}

