#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <sys/socket.h>
#include <resolv.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void initialize_array(NFAPI_CRC_INDICATION_PDU_T *arr, int n) {
    for (int i = 0; i < n; i++) {
        arr[i].RX_UE_INFORMATION_TAG = rand() % 65535;
        arr[i].RNTI = rand() % 4294967295;
        arr[i].CRCFLAG = rand() % 256;
        arr[i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }
}

void resolve_hostnames(char **hostnames, int n, u_char *ip_addrs) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_DGRAM;

    for (int i = 0; i < n; i++) {
        status = getaddrinfo(hostnames[i], NULL, &hints, &res);
        if (status != 0) {
            printf("DNS resolution failed for %s: %s\n", hostnames[i], gai_strerror(status));
            continue;
        }

        struct in_addr *addr = &((struct sockaddr_in *)res->ai_addr)->sin_addr;
        ip_addrs[i] = addr->s_addr;

        freeaddrinfo(res);
    }
}

void populate_array(NFAPI_CRC_INDICATION_PDU_T *arr, int n) {
    char *hostnames[] = {"example.com", "google.com", "yahoo.com"};
    u_char ip_addrs[3];

    resolve_hostnames(hostnames, 3, ip_addrs);

    for (int i = 0; i < n; i++) {
        arr[i].RX_UE_INFORMATION_TAG = rand() % 65535;
        arr[i].RNTI = rand() % 4294967295;
        arr[i].CRCFLAG = rand() % 256;
        arr[i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }
}
