} nfapi_crc_indication_pdu_t;

void populate_nfapi_crc_indication_pdus(const char *json_file, size_t num_pdus) {
    json_error_t error;
    json_t *root = json_load_file(json_file, 0, &error);
    if (!root) {
        fprintf(stderr, "Failed to load JSON file: %s\n", error.text);
        return;
    }

    size_t i;
    nfapi_crc_indication_pdu_t *pdus = malloc(num_pdus * sizeof(*pdus));
    if (!pdus) {
        fprintf(stderr, "Failed to allocate memory for NFAPI CRC indication PDUs\n");
        return;
    }

    json_t *pdu_array = json_object_get(root, "pdus");
    if (!json_is_array(pdu_array)) {
        fprintf(stderr, "Invalid JSON format: 'pdus' is not an array\n");
        return;
    }

    size_t pdu_count = json_array_size(pdu_array);
    if (pdu_count > num_pdus) {
        fprintf(stderr, "Too many PDUs in JSON file: %zu\n", pdu_count);
        return;
    }

    for (i = 0; i < pdu_count; ++i) {
        json_t *pdu = json_array_get(pdu_array, i);
        if (!json_is_object(pdu)) {
            fprintf(stderr, "Invalid JSON format: PDU %zu is not an object\n", i);
            return;
        }

        json_t *rx_ue_information_tag = json_object_get(pdu, "rx_ue_information_tag");
        if (!json_is_integer(rx_ue_information_tag)) {
            fprintf(stderr, "Invalid JSON format: 'rx_ue_information_tag' is not an integer\n");
            return;
        }

        json_t *rnti = json_object_get(pdu, "rnti");
        if (!json_is_integer(rnti)) {
            fprintf(stderr, "Invalid JSON format: 'rnti' is not an integer\n");
            return;
        }

        json_t *crc_indication_rel8_tag = json_object_get(pdu, "crc_indication_rel8_tag");
        if (!json_is_integer(crc_indication_rel8_tag)) {
            fprintf(stderr, "Invalid JSON format: 'crc_indication_rel8_tag' is not an integer\n");
            return;
        }

        json_t *crcflag = json_object_get(pdu, "crcflag");
        if (!json_is_boolean(crcflag)) {
            fprintf(stderr, "Invalid JSON format: 'crcflag' is not a boolean\n");
            return;
        }

        pdus[i].rx_ue_information_tag = json_integer_value(rx_ue_information_tag);
        pdus[i].rnti = json_integer_value(rnti);
        pdus[i].crc_indication_rel8_tag = json_integer_value(crc_indication_rel8_tag);
        pdus[i].crcflag = json_is_true(crcflag);
    }

    // Free the JSON data structure
    json_decref(root);

    return pdus;
}
