        headers = NULL;

        *response = json_tokener_parse(curl_easy_strerror(res));
    }
}

void retry_http_request(const char *url, json_object **response) {
    int attempt = 0;
    while (attempt < HTTP_REQUEST_RETRY_COUNT) {
