        if (*response != NULL) {
            break;
        } else {
            fprintf(stderr, "Failed to fetch JSON data: retrying in %d seconds\n", HTTP_REQUEST_RETRY_DELAY * (attempt + 1));
            sleep(HTTP_REQUEST_RETRY_DELAY * (attempt + 1));
            attempt++;
        }
    }
}

